/* ContentLevelToggle.module.css - 3-Level Content Toggle Styles */

.toggleContainer {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  padding: 1rem;
  margin: 0 auto 2rem;
  max-width: 28rem;
}

@media (min-width: 640px) {
  .toggleContainer {
    flex-direction: row;
    justify-content: center;
  }
}

.toggleLabel {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--sacred-charcoal, #3a3a3a);
  opacity: 0.7;
}

.toggleGroup {
  display: inline-flex;
  background: rgba(143, 191, 159, 0.1);
  border-radius: 9999px;
  padding: 0.25rem;
  gap: 0.25rem;
}

.toggleButton {
  padding: 0.5rem 1rem;
  border-radius: 9999px;
  border: none;
  background: transparent;
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--sacred-charcoal, #3a3a3a);
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease, transform 0.1s ease;
}

.toggleButton:hover {
  background: rgba(143, 191, 159, 0.2);
}

.toggleButton:focus-visible {
  outline: 2px solid var(--sacred-teal, #2f5d5d);
  outline-offset: 2px;
}

.toggleButton.active {
  background: linear-gradient(135deg, var(--sacred-sage, #8fbf9f), var(--sacred-teal, #2f5d5d));
  color: white;
  box-shadow: 0 2px 8px rgba(47, 93, 93, 0.2);
}

.toggleButton:active {
  transform: scale(0.98);
}

@media (prefers-reduced-motion: reduce) {
  .toggleButton {
    transition: none;
  }

  .toggleButton:active {
    transform: none;
  }
}

/* Level Content Styles */
.levelContent {
  animation: fadeIn 0.3s ease-out;
}

@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .levelContent {
    animation: none;
  }
}

.summary {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 1.125rem;
  font-weight: 400;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.7;
  max-width: 42rem;
  margin: 0 auto 1.5rem;
  text-align: center;
}

.reassurance {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 1rem;
  font-weight: 400;
  font-style: italic;
  color: var(--sacred-teal, #2f5d5d);
  max-width: 36rem;
  margin: 0 auto 2rem;
  text-align: center;
  padding: 1rem;
  background: rgba(143, 191, 159, 0.08);
  border-radius: 1rem;
  border-left: 4px solid var(--sacred-sage, #8fbf9f);
}

/* Steps List (Beginner) */
.stepsList {
  list-style: none;
  padding: 0;
  margin: 0 auto 2rem;
  max-width: 36rem;
  counter-reset: step-counter;
}

.stepItem {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 1rem 1.25rem;
  margin-bottom: 0.75rem;
  background: var(--sacred-cream, #faf9f7);
  border: 1px solid rgba(143, 191, 159, 0.2);
  border-radius: 1rem;
}

.stepNumber {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  flex-shrink: 0;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--sacred-sage, #8fbf9f), var(--sacred-teal, #2f5d5d));
  color: white;
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.875rem;
  font-weight: 600;
}

.stepText {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 1rem;
  font-weight: 400;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.6;
  padding-top: 0.25rem;
}

/* Guidance List (Intermediate) */
.guidanceList {
  list-style: none;
  padding: 0;
  margin: 0 auto 2rem;
  max-width: 42rem;
}

.guidanceItem {
  position: relative;
  padding: 0.75rem 0 0.75rem 1.5rem;
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 1rem;
  font-weight: 400;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.6;
  border-bottom: 1px solid rgba(143, 191, 159, 0.1);
}

.guidanceItem::before {
  content: '';
  position: absolute;
  left: 0;
  top: 1rem;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--sacred-sage, #8fbf9f);
}

/* Examples Section (Intermediate) */
.examplesSection {
  max-width: 42rem;
  margin: 0 auto 2rem;
  padding: 1.5rem;
  background: rgba(234, 195, 59, 0.08);
  border-radius: 1rem;
  border-left: 4px solid var(--sacred-gold, #eac33b);
}

.examplesTitle {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--sacred-charcoal, #3a3a3a);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin: 0 0 1rem;
}

.examplesList {
  list-style: none;
  padding: 0;
  margin: 0;
}

.exampleItem {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.9375rem;
  font-weight: 400;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.6;
  padding: 0.5rem 0;
  border-bottom: 1px dashed rgba(234, 195, 59, 0.3);
}

.exampleItem:last-child {
  border-bottom: none;
}

/* Deeper Dive Section (Advanced) */
.deeperSection {
  max-width: 42rem;
  margin: 0 auto 2rem;
  padding: 1.5rem;
  background: rgba(47, 93, 93, 0.05);
  border-radius: 1rem;
  border-left: 4px solid var(--sacred-teal, #2f5d5d);
}

.deeperTitle {
  font-family: var(--font-sacred, 'Playfair Display', serif);
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--sacred-teal, #2f5d5d);
  margin: 0 0 1rem;
}

.deeperList {
  list-style: none;
  padding: 0;
  margin: 0;
}

.deeperItem {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 1rem;
  font-weight: 400;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.7;
  padding: 0.5rem 0;
}

/* References Section (Advanced) */
.referencesSection {
  max-width: 42rem;
  margin: 0 auto 2rem;
  padding: 1rem 1.5rem;
  background: var(--sacred-cream, #faf9f7);
  border-radius: 0.75rem;
  border: 1px solid rgba(143, 191, 159, 0.15);
}

.referencesTitle {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--sacred-charcoal, #3a3a3a);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  opacity: 0.6;
  margin: 0 0 0.75rem;
}

.referencesList {
  list-style: none;
  padding: 0;
  margin: 0;
}

.referenceItem {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.875rem;
  font-weight: 400;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.5;
  opacity: 0.7;
  padding: 0.25rem 0;
}

/* Mobile Adjustments */
@media (max-width: 768px) {
  .summary {
    font-size: 1rem;
    padding: 0 1rem;
  }

  .stepItem {
    padding: 0.875rem 1rem;
  }

  .stepNumber {
    width: 1.75rem;
    height: 1.75rem;
    font-size: 0.75rem;
  }

  .examplesSection,
  .deeperSection,
  .referencesSection {
    margin-left: 1rem;
    margin-right: 1rem;
  }
}

/* ContentStudio.module.css - Social Media Content Developer Tool Styles */

.studio {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem 1rem;
}

@media (min-width: 1024px) {
  .studio {
    grid-template-columns: 400px 1fr;
    gap: 3rem;
    padding: 2rem;
  }
}

/* Form Section */
.formSection {
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.formGroup {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.label {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--sacred-charcoal, #3a3a3a);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.hint {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.8125rem;
  color: var(--sacred-charcoal, #3a3a3a);
  opacity: 0.6;
  margin: 0;
}

/* Content Type Buttons */
.buttonGroup {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.75rem;
}

.typeButton {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem;
  background: var(--sacred-cream, #faf9f7);
  border: 2px solid transparent;
  border-radius: 1rem;
  cursor: pointer;
  transition: all 0.2s ease;
}

.typeButton:hover {
  background: rgba(143, 191, 159, 0.1);
  border-color: rgba(143, 191, 159, 0.3);
}

.typeButton:focus-visible {
  outline: 2px solid var(--sacred-teal, #2f5d5d);
  outline-offset: 2px;
}

.typeButton.active {
  background: linear-gradient(135deg, rgba(143, 191, 159, 0.15), rgba(47, 93, 93, 0.1));
  border-color: var(--sacred-sage, #8fbf9f);
}

.typeIcon {
  width: 1.5rem;
  height: 1.5rem;
  color: var(--sacred-teal, #2f5d5d);
}

.typeLabel {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--sacred-charcoal, #3a3a3a);
  text-align: center;
}

/* Topic Grid */
.topicGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 0.5rem;
}

@media (min-width: 480px) {
  .topicGrid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.topicButton {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem;
  background: var(--sacred-cream, #faf9f7);
  border: 2px solid transparent;
  border-radius: 0.75rem;
  cursor: pointer;
  transition: all 0.2s ease;
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--sacred-charcoal, #3a3a3a);
  text-align: left;
}

.topicButton:hover {
  background: rgba(143, 191, 159, 0.1);
  border-color: rgba(143, 191, 159, 0.3);
}

.topicButton:focus-visible {
  outline: 2px solid var(--sacred-teal, #2f5d5d);
  outline-offset: 2px;
}

.topicButton.active {
  background: linear-gradient(135deg, rgba(143, 191, 159, 0.15), rgba(47, 93, 93, 0.1));
  border-color: var(--sacred-sage, #8fbf9f);
}

.topicIcon {
  width: 1rem;
  height: 1rem;
  color: var(--sacred-teal, #2f5d5d);
  flex-shrink: 0;
}

/* Level Buttons */
.levelGroup {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.levelButton {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.25rem;
  padding: 0.875rem 1rem;
  background: var(--sacred-cream, #faf9f7);
  border: 2px solid transparent;
  border-radius: 0.75rem;
  cursor: pointer;
  transition: all 0.2s ease;
  text-align: left;
}

.levelButton:hover {
  background: rgba(143, 191, 159, 0.1);
  border-color: rgba(143, 191, 159, 0.3);
}

.levelButton:focus-visible {
  outline: 2px solid var(--sacred-teal, #2f5d5d);
  outline-offset: 2px;
}

.levelButton.active {
  background: linear-gradient(135deg, rgba(143, 191, 159, 0.15), rgba(47, 93, 93, 0.1));
  border-color: var(--sacred-sage, #8fbf9f);
}

.levelLabel {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--sacred-charcoal, #3a3a3a);
}

.levelDesc {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.75rem;
  color: var(--sacred-charcoal, #3a3a3a);
  opacity: 0.6;
}

/* Preview Section */
.previewSection {
  background: white;
  border-radius: 1.5rem;
  padding: 1.5rem;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.05);
  border: 1px solid rgba(143, 191, 159, 0.15);
}

.previewHeader {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.5rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid rgba(143, 191, 159, 0.15);
}

.previewTitle {
  font-family: var(--font-sacred, 'Playfair Display', serif);
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--sacred-charcoal, #3a3a3a);
