}

.copyAllButton {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  background: linear-gradient(135deg, var(--sacred-sage, #8fbf9f), var(--sacred-teal, #2f5d5d));
  border: none;
  border-radius: 2rem;
  color: white;
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.875rem;
  font-weight: 500;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.copyAllButton:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(47, 93, 93, 0.2);
}

.copyAllButton:focus-visible {
  outline: 2px solid var(--sacred-teal, #2f5d5d);
  outline-offset: 2px;
}

.copyAllButton svg {
  width: 1rem;
  height: 1rem;
}

/* Output Fields */
.outputField {
  margin-bottom: 1.25rem;
}

.outputHeader {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 0.5rem;
}

.outputLabel {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--sacred-teal, #2f5d5d);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.copyButton {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2rem;
  height: 2rem;
  background: rgba(143, 191, 159, 0.1);
  border: none;
  border-radius: 0.5rem;
  color: var(--sacred-teal, #2f5d5d);
  cursor: pointer;
  transition: background 0.2s ease;
}

.copyButton:hover {
  background: rgba(143, 191, 159, 0.2);
}

.copyButton:focus-visible {
  outline: 2px solid var(--sacred-teal, #2f5d5d);
  outline-offset: 2px;
}

.copyButton svg {
  width: 1rem;
  height: 1rem;
}

.outputText {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.9375rem;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.6;
  margin: 0;
  padding: 1rem;
  background: var(--sacred-cream, #faf9f7);
  border-radius: 0.75rem;
  border: 1px solid rgba(143, 191, 159, 0.1);
}

.outputTextarea {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.9375rem;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.7;
  padding: 1rem;
  background: var(--sacred-cream, #faf9f7);
  border-radius: 0.75rem;
  border: 1px solid rgba(143, 191, 159, 0.1);
  white-space: pre-wrap;
}

/* Meta Section */
.metaSection {
  margin-top: 1.5rem;
  padding-top: 1.5rem;
  border-top: 1px solid rgba(143, 191, 159, 0.15);
}

.safetyNotice {
  display: flex;
  gap: 1rem;
  padding: 1rem;
  background: rgba(234, 195, 59, 0.1);
