  margin-bottom: 1.25rem;
}

.safetyIcon {
  width: 1.25rem;
  height: 1.25rem;
  color: var(--sacred-gold, #eac33b);
  flex-shrink: 0;
  margin-top: 0.125rem;
}

.safetyTitle {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--sacred-charcoal, #3a3a3a);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin: 0 0 0.5rem;
}

.safetyText {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.875rem;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.5;
  margin: 0;
