/* Crisis Banner */
.crisisBanner {
  margin-top: 1.5rem;
  padding: 1rem;
  background: rgba(47, 93, 93, 0.05);
  border-radius: 0.75rem;
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.8125rem;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.5;
  text-align: center;
}

.crisisBanner a {
