}

/* Carousel Preview */
.carouselPreview {
  margin-bottom: 1.5rem;
}

.slidesContainer {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.slide {
  padding: 1.25rem;
  background: var(--sacred-cream, #faf9f7);
  border-radius: 1rem;
  border: 1px solid rgba(143, 191, 159, 0.15);
}

.slideNumber {
  display: inline-block;
