  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.75rem;
  font-weight: 600;
  color: white;
}

.threadText {
  font-family: var(--font-body, 'Inter', sans-serif);
  font-size: 0.9375rem;
  color: var(--sacred-charcoal, #3a3a3a);
  line-height: 1.6;
  margin: 0;
