/* BuddyAvatar.css — visual-only styles. State + motion classes drive feel.
   v1.1: motion vocabulary aligned with healing-domain semantics.
   All animations gated by prefers-reduced-motion. */

.buddy {
  display: inline-block;
  position: relative;
  line-height: 0;
  user-select: none;
}
.buddy__svg {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
  /* v1.13 visible-presence — soft dimensional drop-shadow so Buddy reads
     as "floating" on any page background. Without this, the body fills
     blend into near-white surfaces and the figure feels flat. The shadow
     is layered: a tight contact shadow + a soft cast shadow. Keeps Buddy
     visible against light AND dark surfaces.
     v1.13.1 — softened cast shadow (12/.14 → 10/.10) so smaller companion
     renders (~80px on Journal/Mood/Onboarding panels per BUDDY_PANEL_COPY)
     don't get a "cloudy" haze beneath them at tiny sizes. */
  filter:
    drop-shadow(0 3px 5px rgba(20, 30, 25, 0.09))
    drop-shadow(0 10px 22px rgba(20, 30, 25, 0.10));
}

/* ---------- Heart pulse (cadence varies via --buddy-heart-pulse) ---------- */
.buddy__heart-shape,
.buddy__heart-glow {
  transform-origin: center;
  transform-box: fill-box;
  animation: buddyHeartBeat var(--buddy-heart-pulse, 5200ms) ease-in-out infinite;
  filter: drop-shadow(0 0 6px var(--buddy-heart-color, #7FD8A8));
}
.buddy__heart-glow {
  animation-duration: calc(var(--buddy-heart-pulse, 5200ms) * 1.05);
  opacity: 0.7;
}
.buddy__heart-core {
  transform-origin: center;
  transform-box: fill-box;
  animation: buddyHeartCore var(--buddy-heart-pulse, 5200ms) ease-in-out infinite;
}

@keyframes buddyHeartBeat {
  0%, 100% { transform: scale(1.00); }
  35%      { transform: scale(1.08); }
  55%      { transform: scale(0.97); }
}
@keyframes buddyHeartCore {
  0%, 100% { opacity: 0.85; transform: scale(1); }
  50%      { opacity: 1.00; transform: scale(1.15); }
}

/* ---------- Eyes ---------- */
/* v1.14 — eye blink is now gated to NON-steady motion states.  Crisis
   uses motion=steady, so crisis inherits a motionless, present gaze
   (safety contract: "calm, unbroken presence" during distress).  All
   other states blink gently every ~9s for living-presence feel.  Right
   eye is staggered by 200ms so the two eyes feel like one organic
   motion, not synchronized robotics.  Globally disabled by the
   prefers-reduced-motion block at end of file. */
.buddy__eye {
  transform-origin: center;
  transform-box: fill-box;
  filter: drop-shadow(0 0 4px var(--buddy-eye-color, #6FE3B0));
}
.buddy:not(.buddy--motion-steady) .buddy__eye {
  animation: buddyEyeBlink 9s ease-in-out infinite;
}
.buddy:not(.buddy--motion-steady) .buddy__eye--right {
  animation-delay: 200ms;
}
@keyframes buddyEyeBlink {
  0%, 92%, 100% { transform: scaleY(1); }
  94%, 96%      { transform: scaleY(0.1); }
}

/* ---------- Body micro-motion (motion class driven, v1.1 vocab) ---------- */
.buddy__body, .buddy__head {
  transform-origin: center bottom;
  transform-box: fill-box;
}

/* idle — gentle baseline breath (calm).
   v1.14: amplitude bumped from 1.5px → 4px and scale 1.015 → 1.025 so
   Buddy visibly "breathes" instead of looking static. v1.13's micro-motion
   was too subtle on light page surfaces — users read it as plain/flat.
   The cadence (5200ms) is still well within calm-presence range and is
   gentler than the anxious-state breathing animation (4200ms / -3px). */
.buddy--motion-idle .buddy__body,
.buddy--motion-idle .buddy__head {
  animation: buddyIdle 5200ms ease-in-out infinite;
}
@keyframes buddyIdle {
  0%, 100% { transform: translateY(0) scale(1); }
  50%      { transform: translateY(-4px) scale(1.025); }
}

/* v1.14 — Aura breathing pulse. Decorative outer halo softly expands +
   contracts with a slower cadence than the body so the two motions
   layer instead of locking. Gated to NON-steady states so crisis
   stays motionless (safety contract preserved). */
.buddy:not(.buddy--motion-steady) .buddy__aura {
  transform-origin: center;
  transform-box: fill-box;
  animation: buddyAuraBreathe 6400ms ease-in-out infinite;
}
@keyframes buddyAuraBreathe {
  0%, 100% { transform: scale(1);    opacity: 0.55; }
  50%      { transform: scale(1.04); opacity: 0.72; }
}

/* v1.14 — Floor glow gentle pulse. Synced with aura so the "halo" and
   the "floor pool" feel like one breathing system. Crisis: motionless. */
.buddy:not(.buddy--motion-steady) .buddy__floor {
  transform-origin: center;
  transform-box: fill-box;
  animation: buddyFloorBreathe 6400ms ease-in-out infinite;
}
@keyframes buddyFloorBreathe {
  0%, 100% { transform: scaleX(1);    opacity: 0.65; }
  50%      { transform: scaleX(1.06); opacity: 0.85; }
}

/* v1.14 — Antenna outer halo "ping". The first <circle> in
   .buddy__antenna is the outer fuzzy halo (r=14, see BuddyAvatar.tsx
   v1.13 comment). It gently expands + fades on a 2.6s cadence so
   Buddy's antenna feels like an alive sensor, not a static prop.
   Gated to NON-steady states. */
.buddy:not(.buddy--motion-steady) .buddy__antenna circle:nth-of-type(1) {
  transform-origin: center;
  transform-box: fill-box;
  animation: buddyAntennaPing 2600ms ease-out infinite;
}
@keyframes buddyAntennaPing {
  0%       { transform: scale(0.85); opacity: 0.85; }
  70%      { transform: scale(1.35); opacity: 0.20; }
  100%     { transform: scale(1.55); opacity: 0;    }
}

/* slow_glow — gentle sway with deepened heart glow (sad) */
.buddy--motion-slow_glow .buddy__head {
  animation: buddySlowSway 5800ms ease-in-out infinite;
}
.buddy--motion-slow_glow .buddy__heart-shape,
.buddy--motion-slow_glow .buddy__heart-glow {
  filter: drop-shadow(0 0 12px var(--buddy-heart-color, #5DA3C9));
}
@keyframes buddySlowSway {
  0%, 100% { transform: rotate(-2deg); }
  50%      { transform: rotate(2deg); }
}

/* breathing — pronounced slow inhale/exhale (anxious) */
.buddy--motion-breathing .buddy__body,
.buddy--motion-breathing .buddy__head {
  animation: buddyBreathing 4200ms ease-in-out infinite;
}
@keyframes buddyBreathing {
  0%, 100% { transform: translateY(0) scale(1); }
  50%      { transform: translateY(-3px) scale(1.025); }
}

/* grounding — long, deliberate pulse (overwhelmed) */
.buddy--motion-grounding .buddy__body,
.buddy--motion-grounding .buddy__head {
  animation: buddyGrounding 3200ms ease-in-out infinite;
}
@keyframes buddyGrounding {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.022); }
}

/* warm_glow — subtle rise + warm halo + gentle head tilt (encouraged).
   The head tilts a couple degrees while the body rises — reads as a
   compassionate, listening posture. */
.buddy--motion-warm_glow .buddy__body {
  animation: buddyWarmRise 3600ms ease-in-out infinite;
}
.buddy--motion-warm_glow .buddy__head {
  animation: buddyWarmTilt 3600ms ease-in-out infinite;
}
.buddy--motion-warm_glow .buddy__heart-shape {
  filter: drop-shadow(0 0 10px var(--buddy-heart-color, #5DDB94))
          drop-shadow(0 0 4px #FFD75A);
}
@keyframes buddyWarmRise {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-3px); }
}
@keyframes buddyWarmTilt {
  0%, 100% { transform: translateY(0) rotate(-1.4deg); }
  50%      { transform: translateY(-3px) rotate(1.4deg); }
}

/* steady — motionless presence (crisis) */
.buddy--motion-steady .buddy__body,
.buddy--motion-steady .buddy__head {
  animation: none;
}

/* sparkle — joyful bounce + shimmer + floating particles (celebrate) */
.buddy--motion-sparkle .buddy__body,
.buddy--motion-sparkle .buddy__head {
  animation: buddySparkleBounce 1400ms cubic-bezier(.34,1.56,.64,1) infinite;
}
.buddy--motion-sparkle .buddy__heart-shape {
  filter: drop-shadow(0 0 14px var(--buddy-heart-color, #FFD75A))
          drop-shadow(0 0 6px #A78BFA);
}
@keyframes buddySparkleBounce {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  35%      { transform: translateY(-7px) rotate(-1.5deg); }
  65%      { transform: translateY(-2px) rotate(1.5deg); }
}

/* v1.12 sparkle particles — two soft floating dots that orbit upward
   during celebration. Pure CSS pseudo-elements so they cost zero DOM. */
.buddy--motion-sparkle::before,
.buddy--motion-sparkle::after {
  content: '';
  position: absolute;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--buddy-heart-color, #FFD75A);
  box-shadow: 0 0 10px var(--buddy-heart-color, #FFD75A);
  pointer-events: none;
  opacity: 0.85;
}
.buddy--motion-sparkle::before {
  top: 8%;
  left: 6%;
  animation: buddySparkleFloatA 1900ms ease-in-out infinite;
}
.buddy--motion-sparkle::after {
  top: 14%;
  right: 6%;
  animation: buddySparkleFloatB 1900ms ease-in-out infinite 650ms;
}
@keyframes buddySparkleFloatA {
  0%, 100% { transform: translateY(2px) scale(0.85); opacity: 0.40; }
  50%      { transform: translateY(-12px) scale(1.25); opacity: 0.95; }
}
@keyframes buddySparkleFloatB {
  0%, 100% { transform: translateY(2px) scale(0.85); opacity: 0.40; }
  50%      { transform: translateY(-15px) scale(1.20); opacity: 0.95; }
}

/* v1.14 — gentle warm-glow sparkles for the encouraged state. Softer
   than celebrate (smaller dots, slower float, lower opacity ceiling)
   so encouragement reads as supportive warmth rather than a party.
   Crisis (.buddy--motion-steady) is excluded by selector. */
.buddy--motion-warm_glow::before,
.buddy--motion-warm_glow::after {
  content: '';
  position: absolute;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--buddy-heart-color, #5DDB94);
  box-shadow: 0 0 8px var(--buddy-heart-color, #5DDB94);
  pointer-events: none;
  opacity: 0.55;
}
.buddy--motion-warm_glow::before {
  top: 12%;
  left: 8%;
  animation: buddyWarmSparkleA 3200ms ease-in-out infinite;
}
.buddy--motion-warm_glow::after {
  top: 18%;
  right: 8%;
  animation: buddyWarmSparkleB 3200ms ease-in-out infinite 1100ms;
}
@keyframes buddyWarmSparkleA {
  0%, 100% { transform: translateY(2px) scale(0.7);  opacity: 0.20; }
  50%      { transform: translateY(-10px) scale(1.05); opacity: 0.70; }
}
@keyframes buddyWarmSparkleB {
  0%, 100% { transform: translateY(2px) scale(0.7);  opacity: 0.20; }
  50%      { transform: translateY(-12px) scale(1.05); opacity: 0.70; }
}

/* v1.14 — antenna ping replaces the v1.12 buddyAntennaPulse rule that
   was state-agnostic and would have animated the antenna in crisis
   (motion: steady) too — a subtle but real safety-contract violation
   on a mental-health surface. The replacement is gated to non-steady
   states (see "Antenna outer halo ping" earlier in this file). Crisis
   stays motionless. */

/* ---------- Mouth — v1.16 expression vocabulary ----------
   Default `d` is set in BuddyAvatar.tsx as a calm gentle line. State
   rules below override `d:` to morph the expression. Geometry note:
   eyes sit at y≈78–92, screen ends at y=112, so mouth lives at y≈96–110.
   Crisis rule keeps the mouth a NEUTRAL grounded line — never frowny,
   never smiley — to honor the crisis safety contract. Reduced-motion
   branch below disables the smooth d-morph transition. */
.buddy__mouth {
  transform-origin: center;
  transform-box: fill-box;
  transition: d 700ms ease, opacity 600ms ease, stroke 600ms ease;
}
.buddy--calm .buddy__mouth        { d: path("M 86 100 Q 100 102 114 100"); opacity: 0.70; }
.buddy--sad .buddy__mouth         { d: path("M 84 96 Q 100 106 116 96");  opacity: 0.65; }
.buddy--anxious .buddy__mouth     { d: path("M 84 100 L 116 100");         opacity: 0.60; }
.buddy--overwhelmed .buddy__mouth { d: path("M 86 102 L 114 102");         opacity: 0.55; }
.buddy--encouraged .buddy__mouth  { d: path("M 82 98 Q 100 108 118 98");  opacity: 0.85; }
.buddy--celebrate .buddy__mouth   { d: path("M 78 96 Q 100 112 122 96");  opacity: 0.92; }
.buddy--crisis .buddy__mouth      { d: path("M 84 100 L 116 100");         opacity: 0.70; }

/* Anxious mouth softly breathes with the body so the slit visibly
   inhales/exhales — coaches the user toward a slow breath. Crisis
   exclusion is implicit (different state class). */
.buddy--anxious .buddy__mouth {
  animation: buddyMouthBreathe 4200ms ease-in-out infinite;
}
@keyframes buddyMouthBreathe {
  0%, 100% { transform: scaleX(1.00); }
  50%      { transform: scaleX(0.86); }
}
/* Celebrate mouth softly opens + closes like a giggle. */
.buddy--celebrate .buddy__mouth {
  animation: buddyMouthGiggle 1400ms ease-in-out infinite;
}
@keyframes buddyMouthGiggle {
  0%, 100% { transform: scale(1, 1);   }
  50%      { transform: scale(1.04, 1.18); }
}

/* ---------- Arms — v1.16 movable arms with palms ----------
   Each arm is a <g> wrapping the pad + palm pip. Transform-origin is
   set to the shoulder pivot (top center of each arm pad in user-space
   coords) so they swing from the shoulder rather than spinning around
   their own center. Motion is per-state and STRICTLY motionless under
   crisis (steady) — same safety contract as body/head. */
.buddy__arm {
  transform-origin: 33px 158px;
  transform-box: view-box;
  transition: transform 600ms ease;
}
.buddy__arm--right {
  transform-origin: 167px 158px;
}
.buddy__palm {
  transition: fill 600ms ease, stroke 600ms ease;
}

/* idle (calm) — arms barely sway, like resting breath. */
.buddy--motion-idle .buddy__arm--left {
  animation: buddyArmIdleLeft 5200ms ease-in-out infinite;
}
.buddy--motion-idle .buddy__arm--right {
  animation: buddyArmIdleRight 5200ms ease-in-out infinite;
}
@keyframes buddyArmIdleLeft {
  0%, 100% { transform: rotate(0deg); }
  50%      { transform: rotate(-2deg); }
}
@keyframes buddyArmIdleRight {
  0%, 100% { transform: rotate(0deg); }
  50%      { transform: rotate(2deg); }
}

/* breathing (anxious) — arms gently press in toward the body on
   the exhale, easing back out on the inhale. */
.buddy--motion-breathing .buddy__arm--left {
  animation: buddyArmBreatheLeft 4200ms ease-in-out infinite;
}
.buddy--motion-breathing .buddy__arm--right {
  animation: buddyArmBreatheRight 4200ms ease-in-out infinite;
}
@keyframes buddyArmBreatheLeft {
  0%, 100% { transform: rotate(0deg) translateX(0); }
  50%      { transform: rotate(-3deg) translateX(2px); }
}
@keyframes buddyArmBreatheRight {
  0%, 100% { transform: rotate(0deg) translateX(0); }
  50%      { transform: rotate(3deg) translateX(-2px); }
}

/* slow_glow (sad) — arms hang slightly heavier, sway slowly. */
.buddy--motion-slow_glow .buddy__arm--left {
  animation: buddyArmSadLeft 5800ms ease-in-out infinite;
}
.buddy--motion-slow_glow .buddy__arm--right {
  animation: buddyArmSadRight 5800ms ease-in-out infinite;
}
@keyframes buddyArmSadLeft {
  0%, 100% { transform: rotate(2deg)  translateY(2px); }
  50%      { transform: rotate(-1deg) translateY(0); }
}
@keyframes buddyArmSadRight {
  0%, 100% { transform: rotate(-2deg) translateY(2px); }
  50%      { transform: rotate(1deg)  translateY(0); }
}

/* grounding (overwhelmed) — arms barely move, settled. */
.buddy--motion-grounding .buddy__arm--left,
.buddy--motion-grounding .buddy__arm--right {
  animation: buddyArmGround 3200ms ease-in-out infinite;
}
@keyframes buddyArmGround {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.012); }
}

/* warm_glow (encouraged) — arms reach forward + slightly up in a
   compassionate "I see you" gesture. */
.buddy--motion-warm_glow .buddy__arm--left {
  animation: buddyArmWarmLeft 3600ms ease-in-out infinite;
}
.buddy--motion-warm_glow .buddy__arm--right {
  animation: buddyArmWarmRight 3600ms ease-in-out infinite;
}
@keyframes buddyArmWarmLeft {
  0%, 100% { transform: rotate(0deg)  translateY(0); }
  50%      { transform: rotate(-6deg) translateY(-2px); }
}
@keyframes buddyArmWarmRight {
  0%, 100% { transform: rotate(0deg) translateY(0); }
  50%      { transform: rotate(6deg) translateY(-2px); }
}

/* sparkle (celebrate) — joyful asymmetric wave, arms swing up high. */
.buddy--motion-sparkle .buddy__arm--left {
  animation: buddyArmWaveLeft 1400ms cubic-bezier(.34,1.56,.64,1) infinite;
}
.buddy--motion-sparkle .buddy__arm--right {
  animation: buddyArmWaveRight 1400ms cubic-bezier(.34,1.56,.64,1) infinite 250ms;
}
@keyframes buddyArmWaveLeft {
  0%, 100% { transform: rotate(0deg)   translateY(0); }
  35%      { transform: rotate(-22deg) translateY(-6px); }
  65%      { transform: rotate(-8deg)  translateY(-2px); }
}
@keyframes buddyArmWaveRight {
  0%, 100% { transform: rotate(0deg)  translateY(0); }
  35%      { transform: rotate(22deg) translateY(-6px); }
  65%      { transform: rotate(8deg)  translateY(-2px); }
}

/* steady (crisis) — arms are MOTIONLESS. Safety contract: crisis must
   never animate. This rule explicitly overrides any inherited motion. */
.buddy--motion-steady .buddy__arm,
.buddy--motion-steady .buddy__arm--left,
.buddy--motion-steady .buddy__arm--right {
  animation: none !important;
  transform: none !important;
}

/* v1.2 safety: crisis must NEVER pulse fast or use a red fallback.
   No animation-duration override here — cadence stays slow (5800ms) from
   VISUAL_MAP. Fallback color is green, not red. Steady, grounded presence. */
.buddy--crisis .buddy__heart-shape,
.buddy--crisis .buddy__heart-glow {
  filter: drop-shadow(0 0 10px var(--buddy-heart-color, #7FD8A8));
}

/* v1.3 transition polish: smooth color shift between buddy states.
   Only `fill` transitions (filter is keyframe-driven, leave it alone).
   Disabled under prefers-reduced-motion below. */
.buddy__eye,
.buddy__heart-shape,
.buddy__heart-glow {
  transition: fill 600ms ease;
}

.buddy__shadow {
  animation: buddyShadow var(--buddy-heart-pulse, 5200ms) ease-in-out infinite;
}
@keyframes buddyShadow {
  0%, 100% { transform: scale(1, 1); opacity: 0.10; }
  50%      { transform: scale(0.94, 1); opacity: 0.13; }
}

/* ---------- V6 cuteness overlay (opt-in via prop `overlay`) ----------
   Layered DOM on top of the v4 PNG. Position values are %-based against
   the .buddy wrapper square so the overlay scales correctly across the
   sm / md-header / md / lg / xl size tokens.

   Layer stack (bottom → top):
     img.buddy__svg       (the PNG)
     .buddy__v6-face-pad  (soft cream radial — mutes underlying PNG face)
     .buddy__v6-eye(s)    (dark kawaii dots; gentle blink on non-steady)
     .buddy__v6-mouth     (emotion-gated; no mouth in calm = Hello Kitty rule)
     .buddy__v6-heart     (warm amber chest glow + slow pulse)

   Crisis (.buddy--motion-steady) MUST NOT animate any V6 layer. Existing
   safety contract preserved by selector gates. */

.buddy__v6 {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
/* Per the V6 spec: when the overlay is active, hide the PNG's painted face
   region with a CSS mask so the new dot eyes / mouth / heart sit on a clean
   surface (no double-face show-through). Mask is a radial ellipse over the
   upper-mid third of the body — fully transparent (cuts out) at the face
   center, fading to opaque (keeps PNG) by ~85% radius so the body silhouette
   stays intact. The face-pad below provides a soft cream fill inside the cut
   so the cutout doesn't read as a hole. */
.buddy.buddy--v6 .buddy__svg {
  -webkit-mask-image: radial-gradient(
    ellipse 26% 17% at 50% 38%,
    transparent 0%,
    transparent 55%,
    black 88%,
    black 100%
  );
          mask-image: radial-gradient(
    ellipse 26% 17% at 50% 38%,
    transparent 0%,
    transparent 55%,
    black 88%,
    black 100%
  );
  -webkit-mask-repeat: no-repeat;
          mask-repeat: no-repeat;
}
.buddy__v6-face-pad {
  position: absolute;
  /* Face region of the v4 PNG — upper-mid third, slightly off-center vertically.
     With the mask above cutting the PNG, the pad now serves as a soft cream
     fill so the eyes/mouth sit on warm skin tone, not a transparent hole. */
  left: 22%;
  top: 22%;
  width: 56%;
  height: 36%;
  background: radial-gradient(
    ellipse at center,
    rgba(255, 247, 232, 0.95) 0%,
    rgba(255, 247, 232, 0.80) 45%,
    rgba(255, 247, 232, 0.20) 78%,
    transparent 100%
  );
  border-radius: 50%;
  /* Soften the edge so the pad doesn't read as a sticker. */
  filter: blur(3px);
}
/* Kawaii dot eyes — small, dark warm brown for premium matte feel.
   Positioned per the v4 PNG face geometry. */
.buddy__v6-eye {
  position: absolute;
  width: 8.5%;
  height: 11%;
  background: #2d1810;
  border-radius: 50%;
  /* Subtle highlight on top — gives the dot a "wet" kawaii sparkle. */
  box-shadow: inset 0.5px 1.5px 0 rgba(255, 255, 255, 0.55);
  top: 32%;
  transform-origin: center;
}
.buddy__v6-eye--left  { left: 33%; }
.buddy__v6-eye--right { left: 58.5%; }
.buddy:not(.buddy--motion-steady) .buddy__v6-eye {
  animation: buddyV6EyeBlink 9s ease-in-out infinite;
}
.buddy:not(.buddy--motion-steady) .buddy__v6-eye--right {
  animation-delay: 220ms;
}
@keyframes buddyV6EyeBlink {
  0%, 92%, 100% { transform: scaleY(1); }
  94%, 96%      { transform: scaleY(0.08); }
}
/* Emotion-gated mouth. Geometry: small subtle curve under the eyes. */
.buddy__v6-mouth {
  position: absolute;
  left: 42%;
  top: 47%;
  width: 16%;
  height: 6%;
  border-bottom: 2.5px solid #2d1810;
  border-radius: 0 0 50% 50% / 0 0 100% 100%;
  opacity: 0.85;
}
.buddy--celebrate .buddy__v6-mouth {
  /* Wider, deeper smile during joy. */
  left: 38%;
  width: 24%;
  height: 9%;
  border-bottom-width: 3px;
}
.buddy--sad .buddy__v6-mouth {
  /* Inverted curve = gentle frown. */
  border-bottom: none;
  border-top: 2.5px solid #2d1810;
  border-radius: 50% 50% 0 0 / 100% 100% 0 0;
  top: 49%;
}
/* Warm amber heart on chest — soft glow pulse, signature element.
   Shape comes from the inline <svg> child (viewBox-scaled) so geometry
   stays crisp at every size token. The wrapper is just a positioning
   box; pulse animation runs on the wrapper so glow + shape pulse together. */
.buddy__v6-heart {
  position: absolute;
  left: 42%;
  top: 60%;
  width: 16%;
  height: 14%;
  transform-origin: center;
}
.buddy__v6-heart-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  filter: drop-shadow(0 1px 2px rgba(255, 140, 66, 0.45));
}
.buddy__v6-heart-glow {
  position: absolute;
  inset: -30%;
  background: radial-gradient(
    circle at center,
    rgba(255, 178, 71, 0.55) 0%,
    rgba(255, 140, 66, 0.25) 50%,
    transparent 80%
  );
  border-radius: 50%;
  filter: blur(4px);
}
.buddy:not(.buddy--motion-steady) .buddy__v6-heart {
  animation: buddyV6HeartPulse var(--buddy-heart-pulse, 5200ms) ease-in-out infinite;
}
.buddy:not(.buddy--motion-steady) .buddy__v6-heart-glow {
  animation: buddyV6HeartGlowPulse calc(var(--buddy-heart-pulse, 5200ms) * 1.05) ease-in-out infinite;
}
@keyframes buddyV6HeartPulse {
  0%, 100% { transform: scale(1.00); }
  35%      { transform: scale(1.10); }
  55%      { transform: scale(0.96); }
}
@keyframes buddyV6HeartGlowPulse {
  0%, 100% { opacity: 0.55; transform: scale(1.00); }
  50%      { opacity: 0.85; transform: scale(1.12); }
}

/* When V6 overlay is active, suppress legacy sparkle pseudo-element particles
   (.buddy--motion-sparkle::before/::after). They predated V6 and now visually
   clash with the V6 heart pulse — leaving stray green/yellow dots in the
   upper-right corner on celebrate/encouraged states. The V6 heart already
   carries the joy signal cleanly. */
.buddy--v6.buddy--motion-sparkle::before,
.buddy--v6.buddy--motion-sparkle::after,
.buddy--v6.buddy--motion-warm_glow::before,
.buddy--v6.buddy--motion-warm_glow::after {
  content: none !important;
  display: none !important;
}

/* ---------- Reduced motion ----------
   v1.12: pseudo-elements (::before, ::after) are NOT selected by `*`
   in CSS, so they need their own explicit reset to fully respect the
   user's motion preference. Sparkle particles also fade to invisible
   under reduced-motion (they're decorative joy, not info). */
@media (prefers-reduced-motion: reduce) {
  .buddy *,
  .buddy {
    animation: none !important;
    /* Also disable transitions so state-driven property animations
       (e.g. mouth `d:` morph, arm transform swing) are instant — not
       just the keyframed loops. Required for full WCAG SC 2.3.3
       compliance on the new mouth + arm visuals. */
    transition: none !important;
  }
  .buddy--motion-sparkle::before,
  .buddy--motion-sparkle::after {
    animation: none !important;
    opacity: 0 !important;
    transition: none !important;
  }
  .buddy__heart-shape,
  .buddy__heart-glow {
    filter: drop-shadow(0 0 4px var(--buddy-heart-color, #7FD8A8));
  }
  /* V6 overlay also respects reduced motion. */
  .buddy__v6-eye,
  .buddy__v6-heart,
  .buddy__v6-heart-glow {
    animation: none !important;
    transform: none !important;
  }
}

:root {
  --mmhb-coherence-cream: #fff9f2;
  --mmhb-coherence-cream-2: #f7f0e8;
  --mmhb-coherence-sage: #afc6a1;
  --mmhb-coherence-sage-deep: #5f7f55;
  --mmhb-coherence-gold: #f6c14b;
  --mmhb-coherence-rose: #ffd6da;
  --mmhb-coherence-sky: #aee9ff;
  --mmhb-coherence-ink: #263326;
  --mmhb-coherence-muted: #556455;
}

.mmhb-content-coherence-layer {
  position: fixed;
  left: clamp(0.75rem, 2vw, 1.25rem);
  bottom: clamp(0.75rem, 2vw, 1.25rem);
  z-index: 42;
  width: min(29rem, calc(100vw - 1.5rem));
  pointer-events: none;
}

.mmhb-content-coherence-card {
  pointer-events: auto;
  color: var(--mmhb-coherence-ink);
  border: 1px solid rgba(95, 127, 85, 0.22);
  border-radius: 1.35rem;
  padding: 1rem;
  background:
    radial-gradient(circle at top left, rgba(255, 212, 107, 0.25), transparent 34%),
    radial-gradient(circle at top right, rgba(174, 233, 255, 0.24), transparent 36%),
    linear-gradient(135deg, rgba(255, 249, 242, 0.97), rgba(247, 240, 232, 0.94));
  box-shadow:
    0 18px 48px rgba(38, 51, 38, 0.14),
    0 0 0 1px rgba(255, 255, 255, 0.64) inset;
  backdrop-filter: blur(16px);
}

.mmhb-content-coherence-kicker {
  display: inline-flex;
  width: fit-content;
  margin-bottom: 0.45rem;
  padding: 0.28rem 0.62rem;
  border-radius: 999px;
  background: rgba(175, 198, 161, 0.25);
  color: var(--mmhb-coherence-sage-deep);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mmhb-content-coherence-card h2 {
  margin: 0;
  color: var(--mmhb-coherence-ink);
  font-size: clamp(1rem, 2vw, 1.18rem);
  line-height: 1.25;
  font-weight: 850;
}

.mmhb-content-coherence-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.65rem;
  margin-top: 0.75rem;
}

.mmhb-content-coherence-grid div {
  border-radius: 1rem;
  padding: 0.72rem;
  background: rgba(255, 255, 255, 0.58);
  border: 1px solid rgba(175, 198, 161, 0.18);
}

.mmhb-content-coherence-grid span {
  display: block;
  margin-bottom: 0.25rem;
  color: var(--mmhb-coherence-sage-deep);
  font-size: 0.72rem;
  font-weight: 850;
}

.mmhb-content-coherence-grid p,
.mmhb-content-coherence-boundary {
  margin: 0;
  color: var(--mmhb-coherence-muted);
  font-size: 0.82rem;
  line-height: 1.45;
}

.mmhb-content-coherence-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin-top: 0.85rem;
}

.mmhb-content-coherence-actions a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.45rem;
  border-radius: 999px;
  padding: 0.62rem 0.9rem;
  font-size: 0.84rem;
  font-weight: 850;
  text-decoration: none;
  transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
}

.mmhb-content-coherence-actions a:hover {
  transform: translateY(-1px);
}

.mmhb-content-coherence-primary {
  color: #243024;
  background: linear-gradient(135deg, var(--mmhb-coherence-gold), #ffd46b);
  box-shadow: 0 10px 24px rgba(246, 193, 75, 0.28);
}

.mmhb-content-coherence-secondary {
  color: #243024;
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid rgba(95, 127, 85, 0.24);
}

.mmhb-content-coherence-boundary {
  margin-top: 0.7rem;
  padding-top: 0.65rem;
  border-top: 1px solid rgba(95, 127, 85, 0.14);
  font-size: 0.76rem;
}

@media (max-width: 720px) {
  .mmhb-content-coherence-layer {
    position: static;
    width: auto;
    margin: 1rem;
  }

  .mmhb-content-coherence-grid {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mmhb-content-coherence-actions a {
    transition: none;
  }

  .mmhb-content-coherence-actions a:hover {
    transform: none;
  }
}

/*
 * FloatIdleAnimated styles — MMHB_FLOAT_IDLE_UNIT_v1 Phase 4-6 motion.
 *
 * All keyframes use INDIVIDUAL transform properties (scale, translate)
 * per CSS Transforms Level 2 so they compose with each other and with
 * any inline `transform` set on the rig layers. This is the same
 * pattern LumiV7 uses for pupil dilation + RAF gaze tracking.
 *
 * Composition rules:
 *   - Body container: translate (floating)
 *   - Torso:          scale (breathing)
 *   - Eyes:           translate (settling) + scale (blink, JS-toggled)
 *   - Mouth:          scale (softness, breath-synced)
 *   - Shadow:         opacity + filter:blur + scale (synced with float)
 *
 * Crisis + reduced-motion blanket: animations paused. Shadow pinned.
 */

/* ─── Phase 4: Breathing (torso scale 1.0→1.02 over 7.1s) ─── */
/* Inhale 0-39.4% (2.8s rise), Hold 39.4-44.9% (~0.4s), Exhale 44.9-100% (3.9s decay) */
@keyframes float-idle-breathing {
  0%    { scale: 1; }
  39.4% { scale: 1.02; }
  44.9% { scale: 1.02; }
  100%  { scale: 1; }
}

/* ─── Phase 4: Floating (body translateY 0→-10px over 9.3s, ease) ─── */
@keyframes float-idle-floating {
  0%, 100% { translate: 0 0; }
  /* Amplitude scales with state (--float-amplitude: 0.4-1.2) AND with
   * Phase 9 interaction multiplier (--interaction-amplitude-mult: 0.85-1)
   * so hover/proximity gently settle the bob without changing its shape. */
  50%      { translate: 0 calc(-10px * var(--float-amplitude, 1) * var(--interaction-amplitude-mult, 1)); }
}

/* ─── Phase 4: Shadow (synced with floating, 9.3s) ─── */
/* When body is UP (peak), shadow expands + blurs + fades.
   When body is DOWN (rest), shadow contracts + sharpens + darkens. */
@keyframes float-idle-shadow {
  0%, 100% {
    opacity: 0.55;
    filter: blur(3px);
    scale: 1;
  }
  50% {
    opacity: 0.28;
    filter: blur(7px);
    scale: 1.15;
  }
}

/* ─── Phase 5: Eye settling (translate ±0.5-1.5px over 8.7s) ─── */
/* Asymmetric waypoints so the wander feels organic, not metronomic */
@keyframes float-idle-eye-settling {
  0%   { translate: 0 0; }
  25%  { translate: 1px 0.5px; }
  50%  { translate: -0.5px 1.5px; }
  75%  { translate: -1px -0.5px; }
  100% { translate: 0 0; }
}

/* ─── Phase 5: Blink (JS-toggled .float-idle-blinking class) ─── */
/* Subtle eye-soften compression — NOT a full eyelid close (manifest's
   full 0.1 blink is reserved for the controlled rig's blinkScaleY prop).
 *
 * Implementation note: instead of layering a second @keyframes onto the
 * same animation list (which would reset eye-settling's timeline every
 * time the class toggled), we drive blink purely via the `scale`
 * individual transform property + a CSS transition. Eye-settling
 * (which uses `translate`) keeps running on its own infinite loop with
 * zero restart. Both compose per CSS Transforms Level 2.
 */

/* ─── Phase 7: Arm settling (rotate ±2°, water-float feel) ─── */
/* Asymmetric waypoints so each arm wanders independently. Slightly
 * different cycle period from the other arm (10.3s vs 10.7s) so the
 * two arms never lock into visual sync — feels organic, not mirror.
 * Pivots are set by FloatIdleRig.css per-zone transform-origin
 * (arm-l 24.9%/50.3%, arm-r 74.7%/50.3% — shoulder anchor points). */
@keyframes float-idle-arm-l-settling {
  0%   { rotate: 0deg; }
  30%  { rotate: 1.5deg; }
  55%  { rotate: -1deg; }
  80%  { rotate: 2deg; }
  100% { rotate: 0deg; }
}

@keyframes float-idle-arm-r-settling {
  0%   { rotate: 0deg; }
  25%  { rotate: -1.8deg; }
  50%  { rotate: 1.2deg; }
  75%  { rotate: -0.5deg; }
  100% { rotate: 0deg; }
}

/* ─── Phase 7: Leg settling (translateY ±3px, inertia support) ─── */
/* Legs drift slightly out of sync with each other AND with the body
 * floating cycle (9.3s) so the inertia feels like soft trailing
 * motion, not a tight follow. Different periods (9.7s, 10.1s). */
@keyframes float-idle-leg-l-settling {
  0%   { translate: 0 0; }
  35%  { translate: 0 2px; }
  65%  { translate: 0 -3px; }
  100% { translate: 0 0; }
}

@keyframes float-idle-leg-r-settling {
  0%   { translate: 0 0; }
  40%  { translate: 0 -2.5px; }
  70%  { translate: 0 2px; }
  100% { translate: 0 0; }
}

/* ─── Phase 6: Mouth softness (synced with breathing 7.1s) ─── */
/* Max 0.6% vertical, 0.4% horizontal — sub-pixel. Mouth NEVER speaks. */
@keyframes float-idle-mouth-softness {
  0%    { scale: 1 1; }
  39.4% { scale: 1.004 1.006; }
  44.9% { scale: 1.004 1.006; }
  100%  { scale: 1 1; }
}

/* ─── Phase 8: Emotional state orchestration ─── */
/* Each state shifts cycle durations + float amplitude + glow color/opacity
 * via CSS custom properties consumed by the keyframes/halo below.
 * The avatar itself never changes — only its emotional weather does. */
.float-idle-animated {
  --breath-cycle: 7.1s;
  --float-cycle: 9.3s;
  --float-amplitude: 1;
  --glow-color: 168, 201, 160;
  --glow-opacity: 0.15;
  /* NOTE: cycle vars are not @property-registered, so they snap rather
   * than interpolate on state change. Visible as a brief retime jump
   * mid-cycle; acceptable for QA lab. Pre-production wiring should
   * register them via @property (or interpolate via JS) for smoothness. */

  /* Phase 9 — Interaction multipliers. Default to identity (1 / 0) so
   * the avatar at rest behaves exactly like Phase 8 did. Interaction
   * state blocks below override these to gently shift cycles, amplitude,
   * and glow when the pointer hovers, lingers nearby, or clicks.
   * Each multiplier is a SCALAR layered on top of the state-supplied
   * base values, so emotional state and interaction state compose. */
  --interaction-breath-mult: 1;
  --interaction-float-mult: 1;
  --interaction-amplitude-mult: 1;
  --interaction-eye-settle-mult: 1;
  --interaction-glow-boost: 0;
}

.float-idle-animated[data-state="grounding"] {
  --breath-cycle: 9.94s;
  --float-cycle: 12.09s;
  --float-amplitude: 0.6;
  --glow-color: 116, 192, 252;
  --glow-opacity: 0.12;
}
.float-idle-animated[data-state="reflective"] {
  --breath-cycle: 8.52s;
  --float-cycle: 13.02s;
  --float-amplitude: 0.7;
  --glow-color: 200, 182, 255;
  --glow-opacity: 0.10;
}
.float-idle-animated[data-state="sleepy"] {
  --breath-cycle: 11.36s;
  --float-cycle: 16.74s;
  --float-amplitude: 0.4;
  --glow-color: 168, 213, 186;
  --glow-opacity: 0.08;
}
.float-idle-animated[data-state="comforting"] {
  --breath-cycle: 7.81s;
  --float-cycle: 11.16s;
  --float-amplitude: 0.8;
  --glow-color: 255, 154, 139;
  --glow-opacity: 0.18;
}
.float-idle-animated[data-state="peacefulJoy"] {
  --breath-cycle: 6.39s;
  --float-cycle: 7.91s;
  --float-amplitude: 1.2;
  --glow-color: 255, 217, 61;
  --glow-opacity: 0.14;
}

/* Crisis pins glow + cycles to calmIdle baseline regardless of state */
.float-idle-animated[data-crisis="true"] {
  --breath-cycle: 7.1s;
  --float-cycle: 9.3s;
  --float-amplitude: 1;
  --glow-color: 168, 201, 160;
  --glow-opacity: 0.15;
}

/* ─── Glow halo (Phase 8) ─── */
/* Rendered as a sibling div behind shadow + rig. Radial gradient fades
 * from state-tinted RGBA at center to transparent at the edge.
 * Static (no pulse) so it reads as ambient atmosphere, not animation. */
.float-idle-animated__glow {
  position: absolute;
  inset: -10%;
  width: 120%;
  height: 120%;
  pointer-events: none;
  z-index: 0;
  border-radius: 50%;
  background: radial-gradient(
    circle at 50% 60%,
    rgba(var(--glow-color), calc(var(--glow-opacity) + var(--interaction-glow-boost, 0))) 0%,
    rgba(var(--glow-color), 0) 65%
  );
  /* NOTE: gradient interpolation is engine-dependent and may step
   * rather than cross-fade on some browsers. Acceptable for QA lab;
   * pre-production wiring should refactor to a 2-layer opacity
   * cross-fade (render previous + current glow, fade between them).
   *
   * Phase 8 baseline transition is 1.2s (v5.8.45 contract); Phase 9
   * extends to 3s ONLY when interactive is on (data-interactive="true"
   * on wrapper) so non-interactive surfaces — including the v5.8.46
   * hero — keep their original feel. Click pulse decays via the same
   * 3s ease under interactive mode so it feels like a soft
   * acknowledgment, not a button press. */
  transition: background 1.2s ease-in-out;
}

.float-idle-animated[data-interactive="true"] .float-idle-animated__glow {
  transition: background 3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Phase 8: explicit z-index contract so stacking is deterministic
 * regardless of browser default paint order. */
.float-idle-animated__shadow { z-index: 1; }
.float-idle-animated .float-idle-rig { z-index: 2; }

/* ─── Activation: only when wrapper is animating ─── */
/* Phase 9 — All cycle durations multiplied by interaction multipliers
 * (default 1 = identity). Hover/proximity gently shift these to
 * change the felt rhythm without changing motion shape. */
.float-idle-animated.is-animating .float-idle-rig[data-animated="true"] {
  animation: float-idle-floating calc(var(--float-cycle, 9.3s) * var(--interaction-float-mult, 1)) ease-in-out infinite;
  will-change: translate;
}

.float-idle-animated.is-animating .float-idle-rig[data-animated="true"] [data-rig-zone="torso"] {
  animation: float-idle-breathing calc(var(--breath-cycle, 7.1s) * var(--interaction-breath-mult, 1)) ease-in-out infinite;
  will-change: scale;
}

.float-idle-animated.is-animating .float-idle-rig[data-animated="true"] [data-rig-zone="eyes"] {
  animation: float-idle-eye-settling calc(8.7s * var(--interaction-eye-settle-mult, 1)) ease-in-out infinite;
  /* Override controlled-rig's transform-only transition so `scale`
     gets its own ease for the JS-driven blink (translate stays on the
     settling animation, untouched). */
  transition: transform 150ms cubic-bezier(0.4, 0, 0.2, 1),
              scale 100ms ease-in-out;
  will-change: translate, scale;
}

/* Blink: pure `scale` override + transition — does NOT touch the
 * `animation` list, so eye-settling never restarts its timeline. */
.float-idle-animated.is-animating
  .float-idle-rig[data-animated="true"]
  [data-rig-zone="eyes"].float-idle-blinking {
  scale: 1 0.92;
}

.float-idle-animated.is-animating .float-idle-rig[data-animated="true"] [data-rig-zone="mouth"] {
  /* Mouth softness stays breath-synced: same combined var as torso breathing */
  animation: float-idle-mouth-softness calc(var(--breath-cycle, 7.1s) * var(--interaction-breath-mult, 1)) ease-in-out infinite;
  will-change: scale;
}

/* Phase 7: arm + leg settling. Composes with FloatIdleRig's inline
 * `transform` (controlled mode props default to 0 so transform is
 * identity here) because we use individual `rotate`/`translate`
 * properties per CSS Transforms Level 2. */
.float-idle-animated.is-animating .float-idle-rig[data-animated="true"] [data-rig-zone="arm-l"] {
  animation: float-idle-arm-l-settling 10.3s ease-in-out infinite;
  will-change: rotate;
}

.float-idle-animated.is-animating .float-idle-rig[data-animated="true"] [data-rig-zone="arm-r"] {
  animation: float-idle-arm-r-settling 10.7s ease-in-out infinite;
  will-change: rotate;
}

.float-idle-animated.is-animating .float-idle-rig[data-animated="true"] [data-rig-zone="leg-l"] {
  animation: float-idle-leg-l-settling 9.7s ease-in-out infinite;
  will-change: translate;
}

.float-idle-animated.is-animating .float-idle-rig[data-animated="true"] [data-rig-zone="leg-r"] {
  animation: float-idle-leg-r-settling 10.1s ease-in-out infinite;
  will-change: translate;
}

.float-idle-animated.is-animating .float-idle-animated__shadow {
  /* Shadow stays float-synced: same combined var as body floating */
  animation: float-idle-shadow calc(var(--float-cycle, 9.3s) * var(--interaction-float-mult, 1)) ease-in-out infinite;
  transform-origin: center 86%; /* shadow ellipse y=860/1024 ≈ 86% */
  will-change: opacity, filter, scale;
}

/* ─── Phase 9 — Interaction state blocks ─── */
/* Each block layers ON TOP of the active emotional state by overriding
 * the multiplier vars only. Order matters: hover < proximity < clicked.
 * When multiple are active simultaneously, the deeper interaction
 * (proximity > hover) wins for shared multipliers, and clicked stacks
 * its glow boost on top of whichever is current.
 *
 * Spec values from MMHB_FLOAT_IDLE_UNIT_v1 Phase 9 verification report:
 *   Hover     — float settle 0.5px (≈5% of 10px), breath -0.5s on 7.1s
 *               (≈-7% = 0.93×), eye soften 20% (1.25× duration), glow
 *               +8% intensity (0.012 boost on baseline 0.15).
 *   Proximity — float drift -25% (1.25× duration so each oscillation is
 *               longer/calmer), breathing +40% rhythmic sync (deepen
 *               cycle to 0.85× = faster sync), amplitude -15%, glow
 *               +4% intensity (0.006 boost).
 *   Clicked   — gentle glow pulse +0.05 boost decaying via 3s ease.
 *               Sub-percent body motion intentionally NOT changed —
 *               no "button press" feel; this is acknowledgment, not
 *               feedback. */
.float-idle-animated[data-hover="true"] {
  --interaction-breath-mult: 0.93;
  --interaction-amplitude-mult: 0.95;
  --interaction-eye-settle-mult: 1.25;
  --interaction-glow-boost: 0.012;
}

.float-idle-animated[data-proximity="true"] {
  --interaction-breath-mult: 0.85;
  --interaction-float-mult: 1.25;
  --interaction-amplitude-mult: 0.85;
  --interaction-eye-settle-mult: 1.25;
  --interaction-glow-boost: 0.006;
}

/* When BOTH hover AND proximity are true, proximity already wins above
 * for shared multipliers (later in source). For glow we want the
 * stronger of the two — proximity's 0.006 < hover's 0.012, so use
 * a combined block to keep hover's glow when proximity adds depth. */
.float-idle-animated[data-hover="true"][data-proximity="true"] {
  --interaction-glow-boost: 0.012;
}

/* Click acknowledgment: brief +0.05 glow pulse over 600ms. Stacks on
 * top of whichever interaction state is active by overriding the boost
 * with the hover/proximity boost PLUS the pulse. */
.float-idle-animated[data-clicked="true"] {
  --interaction-glow-boost: 0.05;
}
.float-idle-animated[data-clicked="true"][data-hover="true"] {
  --interaction-glow-boost: 0.062;
}
.float-idle-animated[data-clicked="true"][data-proximity="true"] {
  --interaction-glow-boost: 0.056;
}
/* Triple combinator — when clicked AND both hover+proximity are active,
 * use hover's stronger base (0.012) + click pulse (0.05) = 0.062 so the
 * "presence settle" glow precedence (hover wins) carries through to the
 * click pulse layer. Without this rule, source order would let
 * [data-clicked][data-proximity]=0.056 win over [data-clicked][data-hover]=0.062. */
.float-idle-animated[data-clicked="true"][data-hover="true"][data-proximity="true"] {
  --interaction-glow-boost: 0.062;
}

/* ─── Crisis override: pin shadow to rest, kill all animations,
 *     and force all interaction multipliers back to identity so
 *     hover/proximity/click cannot color or destabilize the avatar
 *     during a crisis routing path (asymmetric-risk safety). ─── */
.float-idle-animated[data-crisis="true"] {
  --interaction-breath-mult: 1 !important;
  --interaction-float-mult: 1 !important;
  --interaction-amplitude-mult: 1 !important;
  --interaction-eye-settle-mult: 1 !important;
  --interaction-glow-boost: 0 !important;
}
.float-idle-animated[data-crisis="true"] .float-idle-animated__shadow,
.float-idle-animated[data-crisis="true"].is-animating .float-idle-animated__shadow {
  animation: none !important;
  opacity: 0.55;
  filter: blur(3px);
  scale: 1;
}

/* ─── Reduced-motion blanket ─── */
/* Per Phase 9 spec: hover/proximity → static glow only (no cycle/
 * amplitude shifts); click → static glow pulse; idle return → instant.
 * Implementation: pin all cycle + amplitude multipliers to 1 so the
 * paused base motion stays paused, but ALLOW --interaction-glow-boost
 * to keep responding so the static glow can soften/warm/pulse. */
@media (prefers-reduced-motion: reduce) {
  .float-idle-animated .float-idle-rig,
  .float-idle-animated .float-idle-rig [data-rig-zone],
  .float-idle-animated .float-idle-animated__shadow {
    animation: none !important;
  }
  .float-idle-animated .float-idle-animated__shadow {
    opacity: 0.55;
    filter: blur(3px);
    scale: 1;
  }
  /* Pin cycle/amplitude multipliers; let glow boost still respond. */
  .float-idle-animated[data-hover="true"],
  .float-idle-animated[data-proximity="true"],
  .float-idle-animated[data-clicked="true"] {
    --interaction-breath-mult: 1 !important;
    --interaction-float-mult: 1 !important;
    --interaction-amplitude-mult: 1 !important;
    --interaction-eye-settle-mult: 1 !important;
  }
  /* Idle return = instant under reduced motion (per spec). Scoped to
   * interactive surfaces only so the v5.8.45 baseline 1.2s glow
   * cross-fade for state changes is preserved on non-interactive
   * surfaces (e.g. the v5.8.46 hero). */
  .float-idle-animated[data-interactive="true"] .float-idle-animated__glow {
    transition: none;
  }
}

/*
 * FloatIdleRig styles — MMHB_FLOAT_IDLE_UNIT_v1 Phase 3.
 *
 * Scoped under .float-idle-rig — zero leak risk per universal contract.
 * Layers stack absolutely, each filling the full container so the
 * regions self-position via their internal pixel placement.
 */

.float-idle-rig {
  position: relative;
  display: inline-block;
  isolation: isolate;
  user-select: none;
  -webkit-user-select: none;
  /* Smooth body-wide float bob */
  transition: transform 600ms cubic-bezier(0.4, 0, 0.2, 1);
  will-change: transform;
}

.float-idle-rig__layer {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  /* Smooth rig transitions per V32 cadence (eyes lead, others follow) */
  transition:
    transform 200ms cubic-bezier(0.4, 0, 0.2, 1),
    opacity 600ms ease-out;
  will-change: transform, opacity;
  /* Keep alpha edges crisp; avoid blurring from subpixel rounding */
  image-rendering: auto;
}

/* v5.8.46 — <picture> wrapper carries the layer class; the inner <img>
 * must fill its parent so the WebP/PNG source covers the full container.
 * Block display avoids the inline-image baseline gap. */
.float-idle-rig__layer > img {
  display: block;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

/* Eye blink is faster per manifest (150ms ScaleY 0.1) */
.float-idle-rig__layer[data-rig-zone="eyes"] {
  transition: transform 150ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* Breathing scale uses the slower V32 cadence */
.float-idle-rig__layer[data-rig-zone="torso"] {
  transition: transform 1200ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* BHCE crisis override — pin every layer + the container to identity.
 * Asymmetric risk: under crisis, no motion of any kind. */
.float-idle-rig[data-crisis="true"],
.float-idle-rig[data-crisis="true"] .float-idle-rig__layer {
  transform: none !important;
  animation: none !important;
  transition: none !important;
}

/* Reduced-motion blanket — universal contract from polish history */
@media (prefers-reduced-motion: reduce) {
  .float-idle-rig,
  .float-idle-rig .float-idle-rig__layer {
    transform: none !important;
    animation: none !important;
    transition: none !important;
  }
  .float-idle-rig .float-idle-rig__layer[data-rig-zone="sparkles"] {
    opacity: 0.6 !important;
  }
}

.lumi-brand-avatar {
  --lumi-avatar-size: 188px;
  position: relative;
  width: var(--lumi-avatar-size);
  height: calc(var(--lumi-avatar-size) * 1.16);
  display: inline-grid;
  place-items: center;
  isolation: isolate;
  filter: drop-shadow(0 24px 34px rgba(36, 58, 34, 0.2));
}

.lumi-brand-avatar--sm { --lumi-avatar-size: 92px; }
.lumi-brand-avatar--md { --lumi-avatar-size: 132px; }
.lumi-brand-avatar--lg { --lumi-avatar-size: 188px; }
.lumi-brand-avatar--xl { --lumi-avatar-size: 248px; }

.lumi-brand-avatar__aura {
  position: absolute;
  border-radius: 999px;
  pointer-events: none;
  z-index: -2;
}

.lumi-brand-avatar__aura-one {
  inset: 5%;
  background:
    radial-gradient(circle at 48% 44%, rgba(255, 212, 107, 0.44), transparent 56%),
    radial-gradient(circle at 56% 58%, rgba(174, 233, 255, 0.24), transparent 64%);
  animation: lumi-aura-pulse 4.6s ease-in-out infinite;
}

.lumi-brand-avatar__aura-two {
  inset: -10%;
  background:
    radial-gradient(circle at 38% 30%, rgba(255, 214, 218, 0.28), transparent 42%),
    radial-gradient(circle at 72% 70%, rgba(221, 231, 213, 0.44), transparent 54%);
  animation: lumi-aura-float 7s ease-in-out infinite;
}

.lumi-brand-avatar__stage {
  position: relative;
  width: 100%;
  height: 100%;
  animation: lumi-official-breathe 4.8s ease-in-out infinite;
  transform-origin: 50% 58%;
}

.lumi-official-layer {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  user-select: none;
  pointer-events: none;
  transform-origin: 50% 50%;
  will-change: transform, opacity, filter;
}

.lumi-official-shadow {
  opacity: 0.45;
  transform-origin: 50% 84%;
  animation: lumi-shadow-breathe 4.8s ease-in-out infinite;
  z-index: 0;
}

.lumi-official-body {
  z-index: 2;
  animation: lumi-body-soft-sway 6.8s ease-in-out infinite;
}

.lumi-official-torso {
  z-index: 3;
  animation: lumi-torso-breathe 4.8s ease-in-out infinite;
}

.lumi-official-arm-left {
  z-index: 4;
  transform-origin: 36% 44%;
  animation: lumi-arm-left-wave 4.4s ease-in-out infinite;
}

.lumi-official-arm-right {
  z-index: 4;
  transform-origin: 64% 44%;
  animation: lumi-arm-right-wave 4.4s ease-in-out infinite;
}

.lumi-official-leg-left {
  z-index: 1;
  transform-origin: 44% 68%;
  animation: lumi-leg-left-sway 5.2s ease-in-out infinite;
}

.lumi-official-leg-right {
  z-index: 1;
  transform-origin: 56% 68%;
  animation: lumi-leg-right-sway 5.2s ease-in-out infinite;
}

.lumi-official-face {
  z-index: 5;
  transform-origin: 50% 38%;
  animation: lumi-face-tilt 7.2s ease-in-out infinite;
}

.lumi-official-eyes {
  z-index: 6;
  transform-origin: 50% 38%;
  animation: lumi-eye-blink 5.1s ease-in-out infinite;
}

.lumi-official-mouth {
  z-index: 7;
  transform-origin: 50% 48%;
  animation: lumi-mouth-talk 5.8s ease-in-out infinite;
}

.lumi-official-top-leaf {
  z-index: 8;
  transform-origin: 50% 18%;
  animation: lumi-leaf-wiggle 5.7s ease-in-out infinite;
}

.lumi-official-sparkles {
  z-index: 9;
  opacity: 0.88;
  animation: lumi-sparkle-twinkle 3.8s ease-in-out infinite;
}

.lumi-brand-avatar--calm .lumi-official-arm-left,
.lumi-brand-avatar--calm .lumi-official-arm-right,
.lumi-brand-avatar--listening .lumi-official-arm-left,
.lumi-brand-avatar--listening .lumi-official-arm-right {
  animation-duration: 7s;
}

.lumi-brand-avatar--celebrate .lumi-official-arm-left,
.lumi-brand-avatar--celebrate .lumi-official-arm-right,
.lumi-brand-avatar--celebrate .lumi-official-sparkles {
  animation-duration: 2.2s;
  filter: saturate(1.08) brightness(1.04);
}

.lumi-brand-avatar--reflect .lumi-official-face,
.lumi-brand-avatar--reflect .lumi-official-eyes {
  animation-duration: 8.8s;
}

.lumi-brand-avatar--guide .lumi-brand-avatar__aura-one {
  opacity: 0.9;
}

@keyframes lumi-official-breathe {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-2.8%) scale(1.022); }
}

@keyframes lumi-aura-pulse {
  0%, 100% { transform: scale(0.95); opacity: 0.48; }
  50% { transform: scale(1.09); opacity: 0.78; }
}

@keyframes lumi-aura-float {
  0%, 100% { transform: translate3d(0, 0, 0) rotate(-1deg); opacity: 0.58; }
  50% { transform: translate3d(0, -7%, 0) rotate(2deg); opacity: 0.86; }
}

@keyframes lumi-shadow-breathe {
  0%, 100% { transform: translateY(2%) scaleX(1); opacity: 0.34; }
  50% { transform: translateY(5%) scaleX(0.88); opacity: 0.22; }
}

@keyframes lumi-body-soft-sway {
  0%, 100% { transform: rotate(-0.7deg); }
  50% { transform: rotate(0.9deg); }
}

@keyframes lumi-torso-breathe {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.018); }
}

