.lumi-living-avatar {
  --lumi-avatar-size: clamp(220px, 32vw, 440px);
  position: relative;
  isolation: isolate;
  display: grid;
  place-items: center;
  inline-size: var(--lumi-avatar-size);
  max-inline-size: 100%;
  margin: 0 auto;
}

.lumi-living-avatar--sm { --lumi-avatar-size: clamp(120px, 18vw, 180px); }
.lumi-living-avatar--md { --lumi-avatar-size: clamp(180px, 25vw, 280px); }
.lumi-living-avatar--lg { --lumi-avatar-size: clamp(240px, 34vw, 430px); }
.lumi-living-avatar--xl { --lumi-avatar-size: clamp(300px, 42vw, 560px); }

.lumi-living-avatar__image,
.lumi-living-avatar__fallback {
  inline-size: 100%;
