/*
 * LumiMascot — Body-part animations for the interactive Buddy.
 * State-driven via [data-emotion] attribute on .lumi-mascot wrapper.
 */

.lumi-mascot {
  display: inline-block;
  position: relative;
  line-height: 0;
  isolation: isolate;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.lumi-mascot__svg {
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}

/* ── Body breathing & floating ─────────────────────────────────── */
.lumi-mascot__body {
  transform-origin: 50% 60%;
  animation: lumi-mascot-breathe 4.2s ease-in-out infinite;
  transition: filter 600ms var(--lumi-ease);
}
.lumi-mascot__floater {
  animation: lumi-mascot-float 6.5s ease-in-out infinite;
  transform-origin: center;
}
@keyframes lumi-mascot-breathe {
  0%, 100% { transform: scale(1.0); }
  50%      { transform: scale(1.03); }
}
@keyframes lumi-mascot-float {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-4px); }
}

/* ── Head tilt by emotion ──────────────────────────────────────── */
.lumi-mascot__head {
  transform-origin: 50% 100%;
  transition: transform 700ms var(--lumi-ease-out);
}
.lumi-mascot[data-emotion="empathy"]     .lumi-mascot__head { transform: rotate(-5deg); }
.lumi-mascot[data-emotion="reflection"]  .lumi-mascot__head { transform: rotate(4deg); }
.lumi-mascot[data-emotion="surprise"]    .lumi-mascot__head { transform: rotate(-2deg) translateY(-2px); }
.lumi-mascot[data-emotion="sleepy"]      .lumi-mascot__head { transform: rotate(8deg) translateY(2px); }
.lumi-mascot[data-emotion="celebration"] .lumi-mascot__head { animation: lumi-head-bob 700ms ease-in-out infinite; }
@keyframes lumi-head-bob {
  0%, 100% { transform: rotate(-2deg); }
  50%      { transform: rotate(2deg); }
}

/* ── Eyes / pupils ─────────────────────────────────────────────── */
.lumi-mascot__eyelid {
  transform-origin: center;
  animation: lumi-mascot-blink 5.5s infinite;
}
.lumi-mascot__eyelid--right { animation-delay: 30ms; }
@keyframes lumi-mascot-blink {
  0%, 92%, 100% { transform: scaleY(0.05); opacity: 0; }
  94%, 96%      { transform: scaleY(1); opacity: 1; }
}
.lumi-mascot[data-emotion="sleepy"] .lumi-mascot__eyelid {
  animation: none; transform: scaleY(0.85); opacity: 0.85;
}
.lumi-mascot[data-emotion="surprise"] .lumi-mascot__pupil {
  r: 4.5;
}

.lumi-mascot__pupil {
  transition: cx 240ms var(--lumi-ease), cy 240ms var(--lumi-ease), r 300ms var(--lumi-ease);
}

/* ── Arms ──────────────────────────────────────────────────────── */
.lumi-mascot__arm--left  { transform-origin: 35% 0%; transition: transform 600ms var(--lumi-ease-out); }
.lumi-mascot__arm--right { transform-origin: 65% 0%; transition: transform 600ms var(--lumi-ease-out); }

.lumi-mascot[data-emotion="joy"]         .lumi-mascot__arm--left  { animation: lumi-wave 1.6s ease-in-out infinite; }
.lumi-mascot[data-emotion="celebration"] .lumi-mascot__arm--left  { transform: rotate(-45deg) translateY(-8px); }
.lumi-mascot[data-emotion="celebration"] .lumi-mascot__arm--right { transform: rotate(45deg)  translateY(-8px); }
.lumi-mascot[data-emotion="comfort"]     .lumi-mascot__arm--left  { transform: rotate(-22deg) translateY(2px); }
.lumi-mascot[data-emotion="comfort"]     .lumi-mascot__arm--right { transform: rotate(22deg)  translateY(2px); }
.lumi-mascot[data-emotion="reflection"]  .lumi-mascot__arm--left  { transform: rotate(-12deg) translateY(-4px); }
.lumi-mascot[data-emotion="reflection"]  .lumi-mascot__arm--right { transform: rotate(12deg)  translateY(-4px); }
@keyframes lumi-wave {
  0%, 100% { transform: rotate(-30deg); }
  50%      { transform: rotate(-55deg); }
}

/* ── Heart glow ───────────────────────────────────────────────── */
.lumi-mascot__heart {
  transform-origin: center;
  animation: lumi-heart-pulse 3s ease-in-out infinite;
  transition: filter 400ms var(--lumi-ease);
}
.lumi-mascot[data-emotion="celebration"] .lumi-mascot__heart {
  animation-duration: 0.9s;
  filter: drop-shadow(0 0 18px var(--lumi-amber-500));
}
.lumi-mascot[data-emotion="empathy"] .lumi-mascot__heart,
.lumi-mascot[data-emotion="comfort"] .lumi-mascot__heart {
  filter: drop-shadow(0 0 12px hsl(350, 80%, 65%));
}
.lumi-mascot[data-emotion="concern"] .lumi-mascot__heart {
  animation-duration: 5s;
  filter: drop-shadow(0 0 6px var(--lumi-amber-300));
}
.lumi-mascot[data-emotion="sleepy"] .lumi-mascot__heart {
  animation-duration: 6s;
  filter: drop-shadow(0 0 4px hsl(218, 30%, 60%));
}
.lumi-mascot[data-flash="true"] .lumi-mascot__heart {
  animation: lumi-heart-flash 600ms ease-out 1;
}
@keyframes lumi-heart-flash {
  0%   { transform: scale(1); filter: drop-shadow(0 0 4px var(--lumi-amber-400)); }
  40%  { transform: scale(1.4); filter: drop-shadow(0 0 28px var(--lumi-amber-500)); }
  100% { transform: scale(1); filter: drop-shadow(0 0 4px var(--lumi-amber-400)); }
}

/* ── Body color tint by emotion ───────────────────────────────── */
.lumi-mascot[data-emotion="joy"]         .lumi-mascot__body { filter: hue-rotate(-12deg) saturate(1.1); }
.lumi-mascot[data-emotion="celebration"] .lumi-mascot__body { filter: hue-rotate(-20deg) saturate(1.2) brightness(1.05); }
.lumi-mascot[data-emotion="empathy"]     .lumi-mascot__body { filter: hue-rotate(8deg); }
.lumi-mascot[data-emotion="comfort"]     .lumi-mascot__body { filter: hue-rotate(15deg); }
.lumi-mascot[data-emotion="concern"]     .lumi-mascot__body { filter: saturate(0.85); }
.lumi-mascot[data-emotion="sleepy"]      .lumi-mascot__body { filter: saturate(0.7) brightness(0.95); }

/* ── Ambient glow halo ────────────────────────────────────────── */
.lumi-mascot__halo {
  opacity: 0.55;
  transition: opacity 700ms var(--lumi-ease);
}
.lumi-mascot[data-emotion="celebration"] .lumi-mascot__halo { opacity: 0.95; }
.lumi-mascot[data-emotion="sleepy"]      .lumi-mascot__halo { opacity: 0.25; }

/* ── Reduced motion ───────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .lumi-mascot__body,
  .lumi-mascot__floater,
  .lumi-mascot__eyelid,
  .lumi-mascot__heart,
  .lumi-mascot__arm--left,
  .lumi-mascot__arm--right,
  .lumi-mascot__head { animation: none !important; }
  .lumi-mascot__eyelid { transform: scaleY(0.05); opacity: 0; }
}

/* ════════════════════════════════════════════════════════════════
 * PNG MASCOT ANIMATIONS (additive)
 *
 * The brand owners replaced the original hand-built SVG mascot with a
 * single canonical PNG, which collapsed the JSX to one <img> and made
 * the body-part-targeting rules above (`.lumi-mascot__body`,
 * `.lumi-mascot__head`, `.lumi-mascot__arm--left`, etc.) inert.
 *
 * The rules below restore visible motion by animating the wrapper +
 * <img> + a chest-positioned ::after-style heart-glow span. Per-emotion
 * variations adjust speed, rotation, scale, and the heart-glow tint so
 * the same flat artwork still feels expressive across all 10 states.
 *
 * Compact instances (size ≤ 80px, e.g. logo badges in nav/footer) get
 * smaller motion amplitudes so the breathing scale + float don't
 * overflow tight overflow-hidden container clip regions.
 *
 * All motion respects prefers-reduced-motion at the bottom.
 * ════════════════════════════════════════════════════════════════ */

.lumi-mascot--png {
  display: inline-block;
  position: relative;
  overflow: visible;
  animation: lumi-png-float 6.5s ease-in-out infinite;
  will-change: transform;
}

.lumi-mascot--png[data-compact="true"] {
  animation: lumi-png-float-compact 6.5s ease-in-out infinite;
}

.lumi-mascot--png .lumi-mascot__img {
  display: block;
  position: relative;
  z-index: 0;
  transform-origin: 50% 60%;
  animation: lumi-png-breathe 4.2s ease-in-out infinite;
  transition: filter 600ms ease-out, transform 600ms ease-out;
  will-change: transform, filter;
}

.lumi-mascot--png[data-compact="true"] .lumi-mascot__img {
  animation: lumi-png-breathe-compact 4.2s ease-in-out infinite;
}

/* Heart-glow halo pinned over the mascot's chest */
.lumi-mascot__heart-glow {
  position: absolute;
  left: 50%;
  top: 56%;
  width: 36%;
  height: 36%;
  transform: translate(-50%, -50%) scale(1);
  border-radius: 50%;
  background: radial-gradient(
    circle,
    rgba(255, 170, 80, 0.55) 0%,
    rgba(255, 170, 80, 0.20) 45%,
    rgba(255, 170, 80, 0) 75%
  );
  filter: blur(6px);
  pointer-events: none;
  mix-blend-mode: screen;
  z-index: 1;
  animation: lumi-png-heart-pulse 3s ease-in-out infinite;
  opacity: 0.7;
}

/* Tiny logo badges hide the heart glow — too small to read as a heart */
.lumi-mascot--png[data-compact="true"] .lumi-mascot__heart-glow {
  display: none;
}

/* ── Base keyframes ─────────────────────────────────────────────── */
@keyframes lumi-png-float {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-6px); }
}
@keyframes lumi-png-float-compact {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-2px); }
}
@keyframes lumi-png-breathe {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.035); }
}
@keyframes lumi-png-breathe-compact {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.02); }
}
@keyframes lumi-png-heart-pulse {
  0%, 100% { opacity: 0.45; transform: translate(-50%, -50%) scale(0.92); }
  50%      { opacity: 0.85; transform: translate(-50%, -50%) scale(1.10); }
}

/* ── Per-emotion overrides (img layer) ──────────────────────────── */
.lumi-mascot--png[data-emotion="joy"] .lumi-mascot__img {
  animation: lumi-png-joy 1.8s ease-in-out infinite;
  filter: saturate(1.1) brightness(1.03);
}
@keyframes lumi-png-joy {
  0%, 100% { transform: scale(1.02) rotate(-3deg); }
  50%      { transform: scale(1.05) rotate(3deg); }
}

.lumi-mascot--png[data-emotion="celebration"] .lumi-mascot__img {
  animation: lumi-png-celebrate 0.9s ease-in-out infinite;
  filter: saturate(1.15) brightness(1.05);
}
@keyframes lumi-png-celebrate {
  0%, 100% { transform: scale(1.04) rotate(-5deg) translateY(0); }
  50%      { transform: scale(1.08) rotate(5deg) translateY(-4px); }
}

.lumi-mascot--png[data-emotion="empathy"] .lumi-mascot__img {
  animation: lumi-png-empathy 5s ease-in-out infinite;
}
@keyframes lumi-png-empathy {
  0%, 100% { transform: scale(1.01) rotate(-4deg); }
  50%      { transform: scale(1.03) rotate(-2deg); }
}

.lumi-mascot--png[data-emotion="comfort"] .lumi-mascot__img {
  animation: lumi-png-comfort 5.5s ease-in-out infinite;
}
@keyframes lumi-png-comfort {
  0%, 100% { transform: scale(1) rotate(0); }
  50%      { transform: scale(1.025) rotate(1deg); }
}

.lumi-mascot--png[data-emotion="reflection"] .lumi-mascot__img {
  animation: lumi-png-reflect 5.5s ease-in-out infinite;
}
@keyframes lumi-png-reflect {
  0%, 100% { transform: scale(1.01) rotate(3deg); }
  50%      { transform: scale(1.025) rotate(5deg); }
}

.lumi-mascot--png[data-emotion="concern"] .lumi-mascot__img {
  animation: lumi-png-concern 6s ease-in-out infinite;
  filter: saturate(0.9);
}
@keyframes lumi-png-concern {
  0%, 100% { transform: scale(0.99); }
  50%      { transform: scale(1.015); }
}

.lumi-mascot--png[data-emotion="sleepy"] .lumi-mascot__img {
  animation: lumi-png-sleepy 7s ease-in-out infinite;
  filter: saturate(0.85) brightness(0.97);
}
@keyframes lumi-png-sleepy {
  0%, 100% { transform: scale(1) rotate(2deg); }
  50%      { transform: scale(1.012) rotate(4deg); }
}

.lumi-mascot--png[data-emotion="surprise"] .lumi-mascot__img {
  animation: lumi-png-surprise 1.4s ease-in-out infinite;
  filter: brightness(1.04);
}
@keyframes lumi-png-surprise {
  0%, 100% { transform: scale(1.03) translateY(-2px); }
  50%      { transform: scale(1.06) translateY(-4px); }
}

.lumi-mascot--png[data-emotion="listening"] .lumi-mascot__img {
  animation: lumi-png-listen 4.2s ease-in-out infinite;
}
@keyframes lumi-png-listen {
  0%, 100% { transform: scale(1.01) rotate(-1deg); }
  50%      { transform: scale(1.025) rotate(1deg); }
}

/* ── Per-emotion heart-glow tint/intensity ──────────────────────── */
.lumi-mascot--png[data-emotion="celebration"] .lumi-mascot__heart-glow {
  animation-duration: 0.9s;
  background: radial-gradient(
    circle,
    rgba(255, 180, 90, 0.85) 0%,
    rgba(255, 180, 90, 0.30) 45%,
    rgba(255, 180, 90, 0) 75%
  );
}
.lumi-mascot--png[data-emotion="joy"] .lumi-mascot__heart-glow {
  animation-duration: 1.6s;
  opacity: 0.85;
}
.lumi-mascot--png[data-emotion="empathy"] .lumi-mascot__heart-glow,
.lumi-mascot--png[data-emotion="comfort"] .lumi-mascot__heart-glow {
  background: radial-gradient(
    circle,
    rgba(244, 114, 182, 0.55) 0%,
    rgba(244, 114, 182, 0.18) 45%,
    rgba(244, 114, 182, 0) 75%
  );
}
.lumi-mascot--png[data-emotion="concern"] .lumi-mascot__heart-glow {
  animation-duration: 5s;
  opacity: 0.40;
}
.lumi-mascot--png[data-emotion="sleepy"] .lumi-mascot__heart-glow {
  animation-duration: 6s;
  opacity: 0.25;
}

/* ── Click flash (full-mascot pop) ─────────────────────────────── */
.lumi-mascot--png[data-flash="true"] .lumi-mascot__img {
  animation: lumi-png-flash 700ms ease-out 1;
  filter: brightness(1.15) drop-shadow(0 0 20px rgba(255, 180, 90, 0.8));
}
.lumi-mascot--png[data-flash="true"] .lumi-mascot__heart-glow {
  animation: lumi-png-heart-flash 700ms ease-out 1;
}
@keyframes lumi-png-flash {
  0%   { transform: scale(1); }
  40%  { transform: scale(1.18); }
  100% { transform: scale(1); }
}
@keyframes lumi-png-heart-flash {
  0%   { opacity: 0.5; transform: translate(-50%, -50%) scale(0.95); }
  40%  { opacity: 1;   transform: translate(-50%, -50%) scale(1.6); }
  100% { opacity: 0.5; transform: translate(-50%, -50%) scale(1); }
}

/* ── Hover (interactive only) ───────────────────────────────────── */
.lumi-mascot--png[role="button"] { cursor: pointer; }
.lumi-mascot--png[role="button"]:hover .lumi-mascot__img {
  filter: brightness(1.06);
}
.lumi-mascot--png[role="button"]:focus-visible {
  outline: 2px solid var(--lumi-amber-500, #f59e0b);
  outline-offset: 4px;
  border-radius: 12px;
}

/* ── Reduced motion override ────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .lumi-mascot--png,
  .lumi-mascot--png .lumi-mascot__img,
  .lumi-mascot--png .lumi-mascot__heart-glow {
    animation: none !important;
  }
  .lumi-mascot--png .lumi-mascot__heart-glow {
    opacity: 0.4;
  }
}

/* PHASE116G_LEGACY_LUMI_MASCOT_TRANSPARENT_SHELL_PATCH
   Legacy LumiMascot shell: remove visible square/panel artifacts while
   preserving BuddyAvatar animation, sizing API, and compact logo behavior.
*/
.lumi-mascot,
.lumi-mascot--png,
.lumi-mascot__img {
  background: transparent !important;
  background-color: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  outline-color: color-mix(in srgb, var(--glp-sage) 46%, transparent);
  overflow: visible !important;
}

.lumi-mascot {
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
}

.lumi-mascot__img {
  display: grid !important;
  place-items: center !important;
  border-radius: 999px;
  isolation: isolate;
}

.lumi-mascot__img img,
.lumi-mascot__img svg,
.lumi-mascot svg,
.lumi-mascot img {
  display: block;
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
  background: transparent !important;
  background-color: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
  overflow: visible;
}

.lumi-mascot__heart-glow {
  background:
    radial-gradient(
      circle,
      color-mix(in srgb, var(--glp-gold) 34%, transparent) 0%,
      color-mix(in srgb, var(--glp-blossom) 22%, transparent) 44%,
      transparent 76%
    ) !important;
  filter: blur(7px);
  mix-blend-mode: screen;
}

.lumi-mascot[data-compact="true"] .lumi-mascot__heart-glow {
  opacity: 0.46;
  filter: blur(4px);
}

.lumi-presence-layer {
  position: fixed;
  right: clamp(14px, 2vw, 28px);
  bottom: clamp(14px, 2vw, 28px);
  z-index: 40;
  display: grid;
  justify-items: center;
  gap: 0.35rem;
  pointer-events: none;
}

.lumi-presence-caption {
  max-width: 12rem;
  border-radius: 999px;
  padding: 0.42rem 0.72rem;
  background: rgba(255, 249, 242, 0.9);
  color: var(--lumi-ink, #17312D);
  border: 1px solid rgba(144, 175, 133, 0.32);
  box-shadow: 0 12px 32px rgba(36, 58, 34, 0.12);
  font-size: 0.72rem;
  line-height: 1.25;
  text-align: center;
  backdrop-filter: blur(14px);
}

@media (max-width: 720px) {
  .lumi-presence-layer {
    transform: scale(0.78);
    transform-origin: bottom right;
  }

  .lumi-presence-caption {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .lumi-presence-layer {
    transform: none;
  }
}

/* ===== Phase 74: Lumi Presence Pastel Scene Polish ===== */
.lumi-presence-layer,
.lumi-presence-shell,
.lumi-presence-orb,
.lumi-presence-card {
  --lumi-presence-cream: var(--lumi-eternal-cream-100, #fff9f2);
  --lumi-presence-sage: var(--lumi-serenity-sage-200, #dde7d5);
  --lumi-presence-gold: var(--lumi-healing-gold-300, #ffd46b);
  --lumi-presence-rose: var(--lumi-compassion-rose-200, #ffd6da);
  --lumi-presence-sky: var(--lumi-hope-sky-200, #aee9ff);
}

.lumi-presence-layer {
  pointer-events: none;
}

.lumi-presence-card,
.lumi-presence-shell {
  background:
    radial-gradient(circle at 22% 18%, rgba(255, 214, 218, 0.34), transparent 32%),
    radial-gradient(circle at 82% 16%, rgba(174, 233, 255, 0.28), transparent 34%),
    linear-gradient(145deg, rgba(255, 249, 242, 0.94), rgba(233, 242, 225, 0.82));
  border: 1px solid rgba(36, 48, 36, 0.12);
  box-shadow:
    0 22px 70px rgba(144, 175, 133, 0.22),
    0 12px 36px rgba(255, 212, 107, 0.18);
  backdrop-filter: blur(18px);
}

.lumi-presence-card *,
.lumi-presence-shell * {
  color: var(--lumi-readable-ink, #243024);
}

.lumi-presence-glow,
.lumi-aura,
.lumi-orb-glow {
  background:
    radial-gradient(circle, rgba(255, 212, 107, 0.38), transparent 52%),
    radial-gradient(circle, rgba(174, 233, 255, 0.22), transparent 64%);
  filter: blur(10px);
}

/* LumiV6.css — Living Lumi multi-layer avatar.
   Scoped under .lumiv6 so it cannot collide with .buddy* (BuddyAvatar). */

.lumiv6 {
  position: relative;
  display: inline-block;
  user-select: none;
  /* CSS vars driven by JS for mouse-tracking pupil drift. */
  --lumiv6-eye-x: 0%;
  --lumiv6-eye-y: 0%;
  /* Subtle dimensional float so Lumi reads off any background. */
  filter:
    drop-shadow(0 3px 5px rgba(20, 30, 25, 0.09))
    drop-shadow(0 10px 22px rgba(20, 30, 25, 0.10));
  transition: transform 280ms ease;
}
.lumiv6.lumiv6--interactive.lumiv6--hovered {
  transform: translateY(-3px) scale(1.03);
}

/* ---------- BODY ---------- */
.lumiv6__body {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
  pointer-events: none;
}
/* Breathe duration + depth driven by CSS vars so V8 can vary them at runtime
   (procedural breathing — every 15s the pattern shifts a touch). The default
   values reproduce the V6/V7 fixed cadence so existing callers don't change. */
.lumiv6.lumiv6--animated .lumiv6__body {
  animation: lumiv6Breathe var(--lumiv6-breath-duration, 5200ms) ease-in-out infinite;
  transform-origin: 50% 70%;
}
@keyframes lumiv6Breathe {
  0%, 100% { transform: translateY(0) scale(1); }
  50%      { transform: translateY(-3px) scale(var(--lumiv6-breath-depth, 1.025)); }
}

/* ---------- FACE PAD (mutes PNG face) ---------- */
.lumiv6__face-pad {
  position: absolute;
  left: 22%;
  top: 22%;
  width: 56%;
  height: 36%;
  background: radial-gradient(
    ellipse at center,
    rgba(255, 247, 232, 0.78) 0%,
    rgba(255, 247, 232, 0.55) 45%,
    rgba(255, 247, 232, 0.10) 78%,
    transparent 100%
  );
  border-radius: 50%;
  filter: blur(3px);
  pointer-events: none;
}

/* ---------- EYES ---------- */
.lumiv6__eye {
  position: absolute;
  width: 9.5%;
  height: 12%;
  background: #fff8ee;
  border-radius: 50%;
  box-shadow: inset 0 1px 2px rgba(80, 50, 30, 0.18);
  top: 31%;
  overflow: hidden;
  pointer-events: none;
}
.lumiv6__eye--left  { left: 32.5%; }
.lumiv6__eye--right { left: 58%; }
.lumiv6__pupil {
  position: absolute;
  left: 18%;
  top: 18%;
  width: 64%;
  height: 64%;
  background: #2d1810;
  border-radius: 50%;
  /* Wet kawaii sparkle. */
  box-shadow: inset 0.5px 1.5px 0 rgba(255, 255, 255, 0.55);
  /* Eye-tracking: vars set by JS on mousemove (when interactive). */
  transform: translate(var(--lumiv6-eye-x), var(--lumiv6-eye-y));
  transition: transform 180ms ease-out;
}
/* Blink loop — only when animated. */
.lumiv6.lumiv6--animated .lumiv6__eye {
  animation: lumiv6EyeBlink 9s ease-in-out infinite;
  transform-origin: center;
}
.lumiv6.lumiv6--animated .lumiv6__eye--right {
  animation-delay: 220ms;
}
@keyframes lumiv6EyeBlink {
  0%, 92%, 100% { transform: scaleY(1); }
  94%, 96%      { transform: scaleY(0.08); }
}
/* Sleepy → eyes are closed slits (override the round shape). */
.lumiv6__eye--closed {
  height: 2%;
  top: 38%;
  background: #2d1810;
  border-radius: 2px;
  box-shadow: none;
}
.lumiv6__eye--closed .lumiv6__pupil { display: none; }
.lumiv6.lumiv6--animated .lumiv6__eye--closed { animation: none; }
/* Surprise → wider eyes. */
.lumiv6__eye--wide {
  width: 11%;
  height: 14%;
  top: 30%;
}

/* ---------- MOUTH (emotion-gated) ----------
   Default geometry sits just below the eyes. Each emotion modifier
   tweaks shape/position. `calm` never renders (Hello Kitty rule). */
.lumiv6__mouth {
  position: absolute;
  left: 42%;
  top: 47%;
  width: 16%;
  height: 6%;
  border-bottom: 2.5px solid #2d1810;
  border-radius: 0 0 50% 50% / 0 0 100% 100%;
  opacity: 0.85;
  pointer-events: none;
}
.lumiv6__mouth--joy {
  /* Big open smile. */
  left: 38%;
  width: 24%;
  height: 9%;
  border-bottom-width: 3px;
}
.lumiv6__mouth--love {
  /* Subtle warm smile. */
  width: 14%;
  left: 43%;
}
.lumiv6__mouth--greeting {
  /* Friendly small smile. */
  left: 41%;
  width: 18%;
}
.lumiv6__mouth--empathy {
  /* Neutral soft line. */
  border-bottom: none;
  border-top: 2px solid #2d1810;
  border-radius: 0;
  height: 2%;
  top: 49%;
  opacity: 0.7;
}
.lumiv6__mouth--sleepy {
  /* Tiny "z"-line. */
  border-bottom: none;
  border-top: 1.5px solid #2d1810;
  border-radius: 0;
  height: 0;
  width: 8%;
  left: 46%;
  top: 49%;
  opacity: 0.6;
}
.lumiv6__mouth--surprise {
  /* Small round "o". */
  border: 2px solid #2d1810;
  border-radius: 50%;
  height: 8%;
  width: 8%;
  left: 46%;
  top: 47%;
}

/* ---------- HEART ---------- */
.lumiv6__heart {
  position: absolute;
  left: 42%;
  top: 60%;
  width: 16%;
  height: 14%;
  pointer-events: none;
  transform-origin: center;
}
.lumiv6__heart-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  filter: drop-shadow(0 1px 2px rgba(255, 140, 66, 0.45));
}
.lumiv6__heart-glow {
  position: absolute;
  inset: -30%;
  background: radial-gradient(
    circle at center,
    rgba(255, 178, 71, 0.55) 0%,
    rgba(255, 140, 66, 0.25) 50%,
    transparent 80%
  );
  border-radius: 50%;
  filter: blur(4px);
}
.lumiv6.lumiv6--animated .lumiv6__heart {
  animation: lumiv6HeartPulse 5200ms ease-in-out infinite;
}
.lumiv6.lumiv6--animated .lumiv6__heart-glow {
  animation: lumiv6HeartGlow 5460ms ease-in-out infinite;
}
@keyframes lumiv6HeartPulse {
  0%, 100% { transform: scale(1.00); }
  35%      { transform: scale(1.10); }
  55%      { transform: scale(0.96); }
}
@keyframes lumiv6HeartGlow {
  0%, 100% { opacity: 0.55; transform: scale(1.00); }
  50%      { opacity: 0.85; transform: scale(1.12); }
}

/* ---------- POSE micro-tilts (no PNG for thinking/listening yet → CSS hint).
   IMPORTANT: applied to the .lumiv6 wrapper, NOT .lumiv6__body, because the
   body element runs the breathing keyframes which set `transform` themselves
   and would otherwise overwrite the rotate. Wrapping the rotate on the
   parent lets both transforms compose without conflict. */
.lumiv6--pose-thinking  { transform: rotate(-4deg); }
.lumiv6--pose-listening { transform: rotate(2deg); }
/* Hover bounce should still apply on top of the pose tilt. */
.lumiv6--pose-thinking.lumiv6--interactive.lumiv6--hovered  { transform: rotate(-4deg) translateY(-3px) scale(1.03); }
.lumiv6--pose-listening.lumiv6--interactive.lumiv6--hovered { transform: rotate(2deg)  translateY(-3px) scale(1.03); }

/* ---------- SPEECH BUBBLE ---------- */
.lumiv6__bubble {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 10px);
  transform: translateX(-50%);
  background: #fff;
  color: #1a1917;
  border: 1px solid #ead7b9;
  border-radius: 14px;
  padding: 8px 12px;
  font-size: 13px;
  font-weight: 500;
  white-space: nowrap;
  max-width: 220px;
  box-shadow: 0 4px 14px rgba(60, 40, 20, 0.10);
  animation: lumiv6BubbleIn 320ms ease-out;
  z-index: 5;
}
.lumiv6__bubble-text {
  display: inline-block;
  white-space: normal;
  line-height: 1.35;
}
.lumiv6__bubble-tail {
  position: absolute;
  left: 50%;
  bottom: -7px;
  transform: translateX(-50%) rotate(45deg);
  width: 12px;
  height: 12px;
  background: #fff;
  border-right: 1px solid #ead7b9;
  border-bottom: 1px solid #ead7b9;
}
@keyframes lumiv6BubbleIn {
  0%   { opacity: 0; transform: translate(-50%, 6px) scale(0.92); }
  100% { opacity: 1; transform: translate(-50%, 0) scale(1); }
}

/* =============================================================
   V7 "EXPRESSIVE SOUL" — additive: 5 new mouth shapes, 2 new eye
   variants, 5 body postures, smooth 600ms expression morphs, and
   per-emotion heart rate (--lumiv6-heart-period CSS var driven
   by JS). All scoped under .lumiv6 — zero collision risk with
   .buddy* / .buddy__v6-* (BuddyAvatar overlay system).
   ============================================================= */

/* ----- Per-emotion heart rate (set inline by JS via --lumiv6-heart-period) */
.lumiv6 {
  --lumiv6-heart-period: 5200ms;
}
.lumiv6.lumiv6--animated .lumiv6__heart {
  animation-duration: var(--lumiv6-heart-period);
}
.lumiv6.lumiv6--animated .lumiv6__heart-glow {
  animation-duration: var(--lumiv6-heart-period);
}

/* ----- New mouth shapes (V7) -------------------------------------------- */
/* Worried — empathy/concern. Inverted curve. */
.lumiv6__mouth--worried {
  border-bottom: none;
  border-top: 3px solid #2d1810;
  border-radius: 50% 50% 0 0 / 100% 100% 0 0;
  background: transparent;
  height: 6%;
  width: 14%;
  left: 43%;
  top: 49%;
  opacity: 0.85;
}
/* Excited wide smile — joy/celebration. Filled, with subtle tremble. */
.lumiv6__mouth--excited {
  background: #d4546a;
  border: 2px solid #2d1810;
  border-radius: 0 0 50% 50% / 0 0 100% 100%;
  height: 11%;
  width: 20%;
  left: 40%;
  top: 47%;
  opacity: 1;
}
.lumiv6.lumiv6--animated .lumiv6__mouth--excited {
  animation: lumiv6MouthTremble 0.3s ease-in-out infinite alternate;
}
@keyframes lumiv6MouthTremble {
  from { transform: translateX(0); }
  to   { transform: translateX(0.6px); }
}
/* Loving — gentle warm crescent. */
.lumiv6__mouth--loving {
  border-bottom: 2px solid #2d1810;
  border-top: none;
  border-radius: 0 0 50% 50% / 0 0 100% 100%;
  background: transparent;
  height: 7%;
  width: 13%;
  left: 43.5%;
  top: 48%;
  opacity: 0.85;
}
/* Focused — concentrated thin line. */
.lumiv6__mouth--focused {
  background: #2d1810;
  border: none;
  border-radius: 1px;
  height: 1.2%;
  width: 9%;
  left: 45.5%;
  top: 49.5%;
  opacity: 0.9;
}
/* Breathing — gentle parting; subtle expand/contract. */
.lumiv6__mouth--breathing {
  background: #2d1810;
  border: none;
  border-radius: 50%;
  height: 2%;
  width: 7%;
  left: 46.5%;
  top: 49%;
  opacity: 0.5;
}
.lumiv6.lumiv6--animated .lumiv6__mouth--breathing {
  animation: lumiv6MouthBreathe 4s ease-in-out infinite;
}
@keyframes lumiv6MouthBreathe {
  0%, 100% { height: 1.5%; opacity: 0.4; }
  50%      { height: 3.2%; opacity: 0.65; }
}

/* ----- New eye expression variants (V7; --wide already exists) ---------- */
.lumiv6__eye--soft {
  width: 8%;
  height: 11%;
  opacity: 0.88;
}
.lumiv6__eye--happy {
  width: 9.5%;
  height: 7%;
  border-radius: 50% 50% 45% 45%;
  top: 33%;
}
/* Happy-eye pupils sit slightly higher (smiling crescent feel). */
.lumiv6__eye--happy .lumiv6__pupil {
  top: 8%;
  height: 50%;
}

/* ----- Body posture wrapper (V7) ----------------------------------------
   Posture transforms live on a dedicated wrapper between root and body img,
   so they compose cleanly with the body's own breathing keyframes (which
   set transform on the inner img). Posture transitions over 800ms ease-out
   per spec section 2.3. */
.lumiv6__posture {
  position: absolute;
  inset: 0;
  display: block;
  transform-origin: 50% 70%;
  transition: transform 800ms ease-out;
}
.lumiv6--posture-upright  .lumiv6__posture { transform: rotate(0deg); }
.lumiv6--posture-curious  .lumiv6__posture { transform: rotate(-3deg); }
.lumiv6--posture-leaning  .lumiv6__posture { transform: rotate(2deg) scaleX(1.02); }
.lumiv6--posture-relaxed  .lumiv6__posture { transform: scaleY(0.98); }
.lumiv6.lumiv6--animated.lumiv6--posture-bouncy .lumiv6__posture {
  animation: lumiv6PostureBounce 0.8s ease-in-out infinite;
}
@keyframes lumiv6PostureBounce {
  0%, 100% { transform: translateY(0)    rotate(0deg); }
  50%      { transform: translateY(-4px) rotate(-1deg); }
}

/* ----- 600ms emotion morph ----------------------------------------------
   Mouth and eye-box geometry/colour transition over 600ms when the emotion
   changes. Pupil keeps its 180ms tracking transition (don't slow that down
   or mouse-follow feels laggy). */
.lumiv6__mouth,
.lumiv6__eye {
  transition-property: width, height, top, left, border-radius, opacity, background-color, border-color, border-width;
  transition-duration: 600ms;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}
/* During the transitioning window eyes briefly close — gives the morph a
   soft "blink-into-new-expression" beat per spec section 3.1. Implemented
   as a keyframe animation (NOT a transition override) so the 600ms eye-box
   geometry morph defined above runs unimpeded alongside the blink beat. */
.lumiv6.lumiv6--animated.lumiv6--transitioning .lumiv6__eye {
  animation: lumiv6BlinkBeat 600ms ease-in-out;
}
@keyframes lumiv6BlinkBeat {
  0%   { transform: scaleY(1); }
  16%  { transform: scaleY(0.1); }
  33%  { transform: scaleY(1); }
  100% { transform: scaleY(1); }
}

/* =============================================================
   V8 "HEART, MIND & SOUL" — additive layer on top of V7. All
   subsystems gated by additional class flags so V6/V7 callers
   render identically when the V8 props are not used.

   Gates:
     .lumiv6--v8           umbrella (auto-applied when v8 prop set)
     .lumiv6--idle         JS-set after 10s of no activity
     .lumiv6--blink-once   JS-toggled briefly to fire one blink
     .lumiv6--heart-burst  JS-toggled for ~800ms after heart click
     .lumiv6--head-tilt    JS-toggled for ~1500ms after head click
     .lumiv6--body-bounce  JS-toggled for ~2000ms after body click
     .lumiv6--recognizing  JS-toggled for ~800ms on memory recall
   ============================================================= */

/* When V8 mode is on, suppress the V7 auto-blink CSS loop — JS schedules
   blinks at natural irregular intervals via .lumiv6--blink-once. */
.lumiv6.lumiv6--v8.lumiv6--animated .lumiv6__eye           { animation: none; }
.lumiv6.lumiv6--v8.lumiv6--animated .lumiv6__eye--right    { animation-delay: 0; }
.lumiv6.lumiv6--v8.lumiv6--animated.lumiv6--blink-once .lumiv6__eye {
  animation: lumiv6BlinkOnce 220ms ease-in-out;
}
@keyframes lumiv6BlinkOnce {
  0%, 100% { transform: scaleY(1); }
  50%      { transform: scaleY(0.08); }
}

/* ----- Aura: soft radial halo behind the body, color per emotion --------- */
.lumiv6__aura {
  position: absolute;
  inset: -22%;
  border-radius: 50%;
  pointer-events: none;
  z-index: 0;
  background: radial-gradient(
    ellipse at 50% 55%,
    var(--lumiv6-aura-color, rgba(168, 201, 160, 0.18)) 0%,
    transparent 70%
  );
  opacity: var(--lumiv6-aura-opacity, 0.6);
}
.lumiv6.lumiv6--animated .lumiv6__aura {
  animation: lumiv6AuraPulse var(--lumiv6-aura-period, 4200ms) ease-in-out infinite;
}
@keyframes lumiv6AuraPulse {
  0%, 100% { transform: scale(1.00); }
  50%      { transform: scale(1.08); }
}

/* ----- Ground shadow: subtle ellipse below the body, posture-aware ------- */
.lumiv6__shadow {
  position: absolute;
  bottom: -8%;
  left: 50%;
  width: 58%;
  height: 9%;
  background: radial-gradient(ellipse, rgba(0, 0, 0, 0.10) 0%, transparent 70%);
  border-radius: 50%;
  transform: translateX(-50%);
  transition: transform 800ms ease-out, opacity 800ms ease-out;
  pointer-events: none;
  z-index: 0;
}
.lumiv6--posture-leaning .lumiv6__shadow { transform: translateX(-44%); }
.lumiv6--posture-curious .lumiv6__shadow { transform: translateX(-56%); }
.lumiv6.lumiv6--animated.lumiv6--posture-bouncy .lumiv6__shadow {
  animation: lumiv6ShadowBounce 800ms ease-in-out infinite;
}
@keyframes lumiv6ShadowBounce {
  0%, 100% { transform: translateX(-50%) scale(1.00); opacity: 1; }
  50%      { transform: translateX(-50%) scale(0.88); opacity: 0.7; }
}

/* ----- Click zones (only rendered when `clickable` prop is true) ---------
   Sit above visual layers so clicks register, but pointer-events: none on the
   wrapper child elements means the visual layers are passive (we set
   pointer-events: auto only on the zones themselves). */
.lumiv6__zone {
  position: absolute;
  cursor: pointer;
  z-index: 30;
  background: transparent;
  border: 0;
  padding: 0;
}
.lumiv6__zone:focus-visible {
  outline: 2px dashed rgba(255, 178, 71, 0.9);
  outline-offset: 2px;
  border-radius: 12px;
}
.lumiv6__zone--head  { top: 12%; left: 32%; width: 36%; height: 28%; border-radius: 50%; }
.lumiv6__zone--heart { top: 56%; left: 40%; width: 20%; height: 16%; border-radius: 50%; }
.lumiv6__zone--body  { top: 38%; left: 25%; width: 50%; height: 42%; border-radius: 40%; z-index: 25; }

/* ----- Heart burst (after heart-zone click) ----------------------------- */
.lumiv6.lumiv6--heart-burst::after {
  content: "";
  position: absolute;
  top: 56%;
  left: 50%;
  width: 30%;
  height: 24%;
  transform: translate(-50%, 0) scale(0.4);
  background: radial-gradient(ellipse, rgba(255, 178, 71, 0.65) 0%, rgba(255, 140, 66, 0.0) 70%);
  border-radius: 50%;
  pointer-events: none;
  z-index: 4;
  animation: lumiv6HeartBurst 800ms ease-out forwards;
}
@keyframes lumiv6HeartBurst {
  0%   { transform: translate(-50%, 0) scale(0.4); opacity: 0.0; }
  30%  { transform: translate(-50%, 0) scale(1.6); opacity: 1.0; }
  100% { transform: translate(-50%, 0) scale(2.4); opacity: 0.0; }
}

/* ----- Head tilt (after head-zone click) -------------------------------- */
.lumiv6--head-tilt .lumiv6__posture {
  animation: lumiv6HeadTilt 1500ms ease-in-out;
}
@keyframes lumiv6HeadTilt {
  0%   { transform: rotate(0deg); }
  30%  { transform: rotate(-6deg); }
  60%  { transform: rotate(2deg); }
  100% { transform: rotate(0deg); }
}

/* ----- Body bounce (after body-zone click) ------------------------------ */
.lumiv6--body-bounce .lumiv6__posture {
  animation: lumiv6BodyBounce 2000ms cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes lumiv6BodyBounce {
  0%   { transform: translateY(0)     scale(1); }
  20%  { transform: translateY(-12px) scale(1.03); }
  40%  { transform: translateY(0)     scale(0.97); }
  60%  { transform: translateY(-6px)  scale(1.01); }
  100% { transform: translateY(0)     scale(1); }
}

/* ----- Recognition micro-expression (returning user) -------------------- */
.lumiv6--recognizing .lumiv6__heart {
  animation: lumiv6Recognize 800ms ease-out !important;
}
@keyframes lumiv6Recognize {
  0%   { transform: scale(1.00); filter: brightness(1.0); }
  30%  { transform: scale(1.18); filter: brightness(1.25); }
  60%  { transform: scale(1.06); filter: brightness(1.10); }
  100% { transform: scale(1.00); filter: brightness(1.0); }
}

/* ----- Idle behaviors: subtle gaze drift + occasional weight shift ------ */
.lumiv6.lumiv6--v8.lumiv6--animated.lumiv6--idle .lumiv6__pupil {
  animation: lumiv6IdleDrift 9s ease-in-out infinite;
}
@keyframes lumiv6IdleDrift {
  0%, 100% { transform: translate(0, 0); }
  25%      { transform: translate(2px, -1px); }
  50%      { transform: translate(-2px, 1px); }
  75%      { transform: translate(1px, 2px); }
}
.lumiv6.lumiv6--v8.lumiv6--animated.lumiv6--idle .lumiv6__posture {
  animation-name: lumiv6IdleShift;
  animation-duration: 14s;
  animation-iteration-count: infinite;
  animation-timing-function: ease-in-out;
}
@keyframes lumiv6IdleShift {
  0%, 88%, 100% { transform: rotate(0deg); }
  92%           { transform: rotate(1.2deg); }
  96%           { transform: rotate(-0.8deg); }
}

/* ---------- Reduced motion ---------- */
@media (prefers-reduced-motion: reduce) {
  .lumiv6 *,
  .lumiv6,
  .lumiv6::before,
  .lumiv6::after,
  .lumiv6 *::before,
  .lumiv6 *::after {
    animation: none !important;
    transition: none !important;
  }
}

/* ======================================================================
   V9 "SOUL CAPTURE" — entrance · attention · escalation · mirroring · goodbye
   All V9 modifiers use the lumiv6--v9-* convention so the existing
   reduced-motion blanket (.lumiv6 *) AND any animated=false crisis
   surface automatically suppress these animations.
   ====================================================================== */

/* ----- 2.1 Entrance: one-shot 800ms birth sequence -------------------- */
.lumiv6--animated.lumiv6--v9-entering .lumiv6__posture {
  animation: lumiv9Entrance 800ms ease-out;
  transform-origin: 50% 75%;
}
@keyframes lumiv9Entrance {
  0% {
    transform: scale(0.3) rotate(-10deg);
    opacity: 0;
    filter: blur(8px);
  }
  40% {
    transform: scale(1.05) rotate(2deg);
    opacity: 0.8;
    filter: blur(2px);
  }
  60% {
    transform: scale(0.98) rotate(-1deg);
    opacity: 1;
    filter: blur(0);
  }
  100% {
    transform: scale(1) rotate(0deg);
    opacity: 1;
    filter: blur(0);
  }
}

/* ----- 2.2 Attention capture: "Lumi notices you" wobble (600ms) ------- */
.lumiv6--animated.lumiv6--v9-attention .lumiv6__posture {
  animation: lumiv9AttentionCapture 600ms ease-in-out;
}
@keyframes lumiv9AttentionCapture {
  0%   { transform: scale(1)    rotate(0deg); }
  15%  { transform: scale(1.08) rotate(-2deg); }
  30%  { transform: scale(1.04) rotate(1deg); }
  45%  { transform: scale(1.06) rotate(-1deg); }
  60%  { transform: scale(1.02) rotate(0.5deg); }
  100% { transform: scale(1)    rotate(0deg); }
}
/* Gaze-lock window (3s after capture): subtle aura intensification so the
   user feels Lumi looking back. The actual eye tracking is already handled
   by the V8 lerp loop. */
.lumiv6--animated.lumiv6--v9-gaze-lock .lumiv6__aura {
  opacity: calc(var(--lumiv6-aura-opacity, 0.6) * 1.4);
  transition: opacity 300ms ease-out;
}

/* ----- 2.3 Emotional escalation levels -------------------------------- */
/* Level 1: warmer aura + slightly faster heart */
.lumiv6--v9-escalation-1 {
  --lumiv6-heart-period: 600ms;
}
.lumiv6--v9-escalation-1 .lumiv6__aura {
  opacity: calc(var(--lumiv6-aura-opacity, 0.6) * 1.2);
}
/* Level 2: excited bounce + wider eyes + faster heart */
.lumiv6--v9-escalation-2 {
  --lumiv6-heart-period: 450ms;
}
.lumiv6--animated.lumiv6--v9-escalation-2 .lumiv6__posture {
  animation: lumiv9EscalateBounce 1200ms ease-in-out infinite;
}
.lumiv6--animated.lumiv6--v9-escalation-2 .lumiv6__pupil {
  transform: scale(1.15);
  transition: transform 300ms ease-out;
}
@keyframes lumiv9EscalateBounce {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-5px); }
}
/* Level 3: full celebration — sparkle burst + rapid heart pulse */
.lumiv6--v9-escalation-3 {
  --lumiv6-heart-period: 300ms;
}
.lumiv6--animated.lumiv6--v9-escalation-3 .lumiv6__pupil {
  transform: scale(1.2);
  transition: transform 300ms ease-out;
}
.lumiv6--animated.lumiv6--v9-escalation-3::before {
  content: "";
  position: absolute;
  inset: -10%;
  background:
    radial-gradient(circle at 20% 30%, rgba(255, 217, 61, 0.55) 0%, transparent 8%),
    radial-gradient(circle at 80% 25%, rgba(255, 184, 140, 0.50) 0%, transparent 8%),
    radial-gradient(circle at 25% 75%, rgba(255, 154, 139, 0.50) 0%, transparent 8%),
    radial-gradient(circle at 75% 80%, rgba(168, 213, 186, 0.50) 0%, transparent 8%),
    radial-gradient(circle at 50% 15%, rgba(200, 182, 255, 0.50) 0%, transparent 7%);
  pointer-events: none;
  z-index: 5;
  animation: lumiv9CelebrationSparkle 1400ms ease-out infinite;
  border-radius: 50%;
}
@keyframes lumiv9CelebrationSparkle {
  0%, 100% { opacity: 0; transform: scale(0.85) rotate(0deg); }
  20%      { opacity: 1; transform: scale(1.05) rotate(15deg); }
  60%      { opacity: 0.6; transform: scale(1.1) rotate(-10deg); }
}

/* ----- 2.4 Mirroring micro-expression flash (1.5s) -------------------- */
.lumiv6--animated.lumiv6--v9-mirroring .lumiv6__heart {
  animation: lumiv9MirrorFlash 1500ms ease-out;
}
@keyframes lumiv9MirrorFlash {
  0%   { filter: brightness(1.0); transform: scale(1); }
  20%  { filter: brightness(1.3) saturate(1.2); transform: scale(1.12); }
  50%  { filter: brightness(1.15); transform: scale(1.05); }
  100% { filter: brightness(1.0); transform: scale(1); }
}

/* ----- 2.5 Goodbye sequence: wave + fade-out (1s) --------------------- */
.lumiv6--animated.lumiv6--v9-goodbye .lumiv6__posture {
  animation: lumiv9GoodbyeWave 1000ms ease-in-out forwards;
}
.lumiv6--animated.lumiv6--v9-goodbye {
  animation: lumiv9GoodbyeFade 1000ms ease-out forwards;
}
.lumiv6--animated.lumiv6--v9-goodbye .lumiv6__heart {
  animation: lumiv9GoodbyeHeart 1000ms ease-in-out;
}
@keyframes lumiv9GoodbyeWave {
  0%   { transform: rotate(0deg); }
  20%  { transform: rotate(8deg); }
  40%  { transform: rotate(-6deg); }
  60%  { transform: rotate(4deg); }
  80%  { transform: rotate(-2deg); }
  100% { transform: rotate(0deg); }
}
@keyframes lumiv9GoodbyeFade {
  0%   { opacity: 1; transform: scale(1); }
  50%  { opacity: 0.8; transform: scale(0.95); }
  100% { opacity: 0; transform: scale(0.9); }
}
@keyframes lumiv9GoodbyeHeart {
  0%, 100% { transform: scale(1); opacity: 0.9; }
  33%      { transform: scale(1.1); opacity: 1; }
  66%      { transform: scale(0.95); opacity: 0.6; }
}

/* ---------------------------------------------------------------------------
   V9.7 — Visceral Glow ("The Warmth Engine")  — declared FIRST so transient
   states (recognition / mirroring / goodbye / heart-burst), declared AFTER
   this rule, win on the CSS cascade for `.lumiv6__heart` during their brief
   windows. Period syncs to the existing --lumiv6-heart-period custom
   property already set by the heart-rate driver in LumiV6.tsx (and overridden
   by escalation levels 600/450/300ms), so visceral glow inherits emotion +
   escalation cadence automatically. Scoped under `.lumiv6--animated` so
   crisis surfaces (animated=false) are completely unaffected.
   --------------------------------------------------------------------------- */
.lumiv6--animated.lumiv6--v9-visceral-glow .lumiv6__heart {
  animation: lumiv9VisceralGlow var(--lumiv6-heart-period, 2000ms) ease-in-out infinite;
  will-change: transform, filter;
}
@keyframes lumiv9VisceralGlow {
  0%, 100% {
    transform: scale(1);
    filter: brightness(1) drop-shadow(0 0 2px rgba(232,145,58,0.35));
  }
  30% {
    transform: scale(1.14);
    filter: brightness(1.3) drop-shadow(0 0 10px rgba(232,145,58,0.85));
  }
  60% {
    transform: scale(1.06);
    filter: brightness(1.1) drop-shadow(0 0 6px rgba(232,145,58,0.55));
  }
}

/* ---------------------------------------------------------------------------
   V9.6 — Recognition micro-expression ("Welcome Back")
   600ms flash on mount when previous-session emotion differs from current.
   Eyes widen + heart pulses bright once, then settles into base behavior.
   Declared AFTER visceral-glow so the cascade gives this rule the heart
   element during the 600ms recognition window (equal specificity, last wins).
   Scoped under .lumiv6--animated so crisis (animated=false) is unaffected;
   reduced-motion blanket already disables it via the .lumiv6 namespace rule.
   --------------------------------------------------------------------------- */
.lumiv6--animated.lumiv6--v9-recognition .lumiv6__pupil {
  animation: lumiv9RecognitionEyes 600ms ease-out;
}
.lumiv6--animated.lumiv6--v9-recognition .lumiv6__heart {
  animation: lumiv9RecognitionHeart 600ms ease-out;
}
@keyframes lumiv9RecognitionEyes {
  0%   { transform: scaleY(1); }
  35%  { transform: scaleY(1.18); }
  70%  { transform: scaleY(1.06); }
  100% { transform: scaleY(1); }
}
@keyframes lumiv9RecognitionHeart {
  0%   { transform: scale(1);    filter: brightness(1)   drop-shadow(0 0 0 rgba(232,145,58,0)); }
  40%  { transform: scale(1.22); filter: brightness(1.4) drop-shadow(0 0 8px rgba(232,145,58,0.7)); }
  100% { transform: scale(1);    filter: brightness(1)   drop-shadow(0 0 0 rgba(232,145,58,0)); }
}

/* ======================================================================
   V20 — Visual effects (sparkles · floating particles · 3-level blush)
   Additive, gated by .lumiv6--v20. JSX never renders these when
   animated=false (crisis), and the existing .lumiv6 reduced-motion
   blanket already kills their keyframes; the rules below add
   display:none for sparkles/particles under reduced-motion so we don't
   leave a frozen sparkle stuck mid-cycle. PNG/WebP image is untouched.
   ====================================================================== */

/* ----- Sparkles (joy · escalation level 3) ---------------------------- */
.lumiv6__sparkle-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 22;
}
.lumiv6__sparkle {
  position: absolute;
  width: 8px;
  height: 8px;
  background: linear-gradient(135deg, #FFD93D 0%, #FFC857 100%);
  clip-path: polygon(50% 0%, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%);
  opacity: 0;
  transform: scale(0) rotate(0deg);
  filter: drop-shadow(0 0 4px rgba(255, 217, 61, 0.6));
}
.lumiv6--v20.lumiv6--animated .lumiv6__sparkle {
  animation: lumiv20Sparkle 2s ease-in-out infinite;
}
.lumiv6__sparkle--1 { top: 10%;  left: 80%;  animation-delay: 0s !important; }
.lumiv6__sparkle--2 { top: 20%;  right: 15%; animation-delay: 0.5s !important; }
.lumiv6__sparkle--3 { top: 5%;   left: 60%;  animation-delay: 1s !important; }
@keyframes lumiv20Sparkle {
  0%, 100% { opacity: 0; transform: scale(0) rotate(0deg); }
  50%      { opacity: 1; transform: scale(1) rotate(180deg); }
}

/* ----- Floating particles (calm · sleepy · empathy) ------------------- */
.lumiv6__particle-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
}
.lumiv6__particle {
  position: absolute;
  width: 3px;
  height: 3px;
  bottom: 20%;
  border-radius: 50%;
  background: rgba(168, 201, 160, 0.6);
  opacity: 0;
}
.lumiv6--v20.lumiv6--animated .lumiv6__particle {
  animation: lumiv20FloatParticle 4s ease-in-out infinite;
}
.lumiv6__particle--1 { left: 20%; animation-delay: 0s !important;  animation-duration: 3.5s !important; }
.lumiv6__particle--2 { left: 50%; animation-delay: 1s !important;  animation-duration: 4.2s !important; }
.lumiv6__particle--3 { left: 70%; animation-delay: 2s !important;  animation-duration: 5s !important; }
.lumiv6--emotion-calm    .lumiv6__particle { background: rgba(116, 192, 252, 0.55); }
.lumiv6--emotion-empathy .lumiv6__particle { background: rgba(200, 182, 255, 0.55); }
.lumiv6--emotion-sleepy  .lumiv6__particle { background: rgba(168, 213, 186, 0.5); }
@keyframes lumiv20FloatParticle {
  0%   { transform: translate(0, 0);        opacity: 0; }
  20%  {                                    opacity: 0.6; }
  80%  {                                    opacity: 0.4; }
  100% { transform: translate(10px, -40px); opacity: 0; }
}

/* ----- Blush (3 escalation levels, interaction-driven only) ----------
   The V17 plush PNGs already ship with subtle baked-in cheek blush, so
   the V20 overlay layers an additional radial wash on top — only when
   the user has actively interacted with click zones (V9 escalation
   level >= 1). Never auto-derived from emotion alone. */
.lumiv6__blush {
  position: absolute;
  width: 18%;
  height: 10%;
  top: 45%;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
  z-index: 14;
  transition: opacity 400ms ease-in-out, background 400ms ease-in-out;
  background: radial-gradient(ellipse at center, rgba(255, 154, 139, 0.5) 0%, rgba(255, 154, 139, 0) 70%);
}
.lumiv6__blush--left  { left:  15%; }
.lumiv6__blush--right { right: 15%; }
.lumiv6--blush-level-1 .lumiv6__blush { opacity: 0.2; }
.lumiv6--blush-level-2 .lumiv6__blush { opacity: 0.4; }
.lumiv6--blush-level-3 .lumiv6__blush { opacity: 0.6; }
.lumiv6--emotion-joy     .lumiv6__blush { background: radial-gradient(ellipse at center, rgba(255, 217, 61, 0.5) 0%,  rgba(255, 217, 61, 0)  70%); }
.lumiv6--emotion-love    .lumiv6__blush { background: radial-gradient(ellipse at center, rgba(255, 154, 139, 0.55) 0%, rgba(255, 154, 139, 0) 70%); }
.lumiv6--emotion-empathy .lumiv6__blush { background: radial-gradient(ellipse at center, rgba(200, 182, 255, 0.5) 0%,  rgba(200, 182, 255, 0) 70%); }
.lumiv6--emotion-calm    .lumiv6__blush { background: radial-gradient(ellipse at center, rgba(168, 201, 160, 0.45) 0%, rgba(168, 201, 160, 0) 70%); }

/* ----- Crisis stillness (animated=false) — belt-and-braces ----------- */
.lumiv6--still .lumiv6__sparkle,
.lumiv6--still .lumiv6__particle { display: none; }

/* ----- Reduced motion: hide moving effects, freeze blush ------------- */
@media (prefers-reduced-motion: reduce) {
  .lumiv6 .lumiv6__sparkle,
  .lumiv6 .lumiv6__particle { display: none; }
  .lumiv6 .lumiv6__blush    { transition: none !important; }
}

/* ======================================================================
   V20 Phase 2 — coordination transitions · bounce physics · tear-drop
   Additive on top of v5.8.8. All effects gated by .lumiv6--v20 +
   .lumiv6--animated; PNG/WebP image untouched. Ear wiggle from the
   blueprint is intentionally NOT implemented — the V17 plush PNG has
   no separate ear sprites (V21 3D-preservation rule).
   ====================================================================== */

/* ----- Coordination transitions (eyes lead, mouth +100ms, posture +50ms) */
.lumiv6--v20.lumiv6--animated .lumiv6__eye {
  transition: top 600ms cubic-bezier(0.4, 0, 0.2, 1),
              left 600ms cubic-bezier(0.4, 0, 0.2, 1),
              width 600ms cubic-bezier(0.4, 0, 0.2, 1),
              height 600ms cubic-bezier(0.4, 0, 0.2, 1),
              opacity 600ms cubic-bezier(0.4, 0, 0.2, 1);
}
.lumiv6--v20.lumiv6--animated .lumiv6__mouth {
  transition: width 600ms cubic-bezier(0.4, 0, 0.2, 1) 100ms,
              height 600ms cubic-bezier(0.4, 0, 0.2, 1) 100ms,
              border-radius 600ms cubic-bezier(0.4, 0, 0.2, 1) 100ms,
              background-color 600ms cubic-bezier(0.4, 0, 0.2, 1) 100ms,
              opacity 600ms cubic-bezier(0.4, 0, 0.2, 1) 100ms;
}
.lumiv6--v20.lumiv6--animated .lumiv6__posture {
  transition: transform 800ms cubic-bezier(0.4, 0, 0.2, 1) 50ms;
}

/* ----- Bounce physics (one-shot celebration animation) ---------------- */
@keyframes lumiv20BouncePhysics {
  0%   { transform: translateY(0)     scale(1, 1); }
  10%  { transform: translateY(-12px) scale(0.95, 1.05); }
  25%  { transform: translateY(-16px) scale(0.92, 1.08); }
  40%  { transform: translateY(-8px)  scale(0.97, 1.03); }
  55%  { transform: translateY(-14px) scale(0.94, 1.06); }
  70%  { transform: translateY(-4px)  scale(0.98, 1.02); }
  85%  { transform: translateY(-6px)  scale(0.97, 1.03); }
  100% { transform: translateY(0)     scale(1, 1); }
}
.lumiv6--v20.lumiv6--animated.lumiv6--celebrating .lumiv6__posture {
  animation: lumiv20BouncePhysics 1.2s ease-in-out;
}

/* ----- Tear drops (deep empathy — never crisis, gated render) -------- */
.lumiv6__tear {
  position: absolute;
  top: 55%;
  width: 4px;
  height: 6px;
  background: linear-gradient(to bottom, rgba(116, 192, 252, 0.5), rgba(116, 192, 252, 0.1));
  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;
  pointer-events: none;
  z-index: 20;
  opacity: 0;
}
.lumiv6__tear--left  { left:  22%; }
.lumiv6__tear--right { right: 22%; }
@keyframes lumiv20TearDrop {
  0%   { transform: translateY(0)    scaleY(1);   opacity: 0.6; }
  50%  { transform: translateY(8px)  scaleY(0.8); opacity: 0.4; }
  100% { transform: translateY(16px) scaleY(0.6); opacity: 0; }
}
.lumiv6--v20.lumiv6--animated.lumiv6--tearful .lumiv6__tear {
  animation: lumiv20TearDrop 3s ease-in infinite;
  animation-delay: 2s;
}

/* ----- Reduced motion · belt-and-braces ------------------------------ */
@media (prefers-reduced-motion: reduce) {
  .lumiv6 .lumiv6__tear { display: none; }
  .lumiv6.lumiv6--celebrating .lumiv6__posture { animation: none !important; }
  .lumiv6--v20.lumiv6--animated .lumiv6__eye,
  .lumiv6--v20.lumiv6--animated .lumiv6__mouth,
  .lumiv6--v20.lumiv6--animated .lumiv6__posture { transition: none !important; }
}

/*
 * LumiV7 — Avatar Evolution Engine (V32 spec)
 *
 * Body appearance is FROZEN per V22/V24/V27/V32. Only eye, mouth,
 * arm, and leg layers gain coordination. Crisis signal forces
 * instant calm and disables all motion.
 *
 * EVERY selector is scoped under `.lumi-v7` so styles cannot leak
 * if other components ever happen to reuse a shared class name.
 *
 * Spec reference: V32 OMEGA INFINITY § Avatar Evolution
 *   - Eye: 4 types, lerp 0.05/0.12, blink 2-6s, 150ms, double-blink 15%
 *   - Mouth: 10 expressions, 600ms cubic-bezier(0.4,0,0.2,1), 100ms after eyes
 *   - Arm: 6 movements, ±30°, 800ms ease-in-out
 *   - Leg: 5 movements
 */

.lumi-v7 {
  --lumi-cream: #F5F0E8;
  --lumi-sage: #A8C9A0;
  --lumi-sage-deep: #4A7E72;
  --lumi-blush: #F5A3A3;
  --lumi-eye: #1A1A1A;
  --lumi-mouth: #2A2A2A;
  --lumi-shadow: rgba(74, 126, 114, 0.18);
  display: inline-block;
  position: relative;
  line-height: 0;
}

.lumi-v7 svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: visible;
}

/* ---------------- Body (FROZEN — never animate) ---------------- */
.lumi-v7 .lumi-v7-body,
.lumi-v7 .lumi-v7-belly,
.lumi-v7 .lumi-v7-head,
.lumi-v7 .lumi-v7-blush,
.lumi-v7 .lumi-v7-sprout {
  transform-box: fill-box;
  transform-origin: center;
}

/* ---------------- Eye coordination (4 types) ---------------- */
.lumi-v7 .lumi-v7-eye {
  fill: var(--lumi-eye);
  transform-box: fill-box;
  transform-origin: center;
  transition: rx 200ms cubic-bezier(0.4, 0, 0.2, 1),
              ry 200ms cubic-bezier(0.4, 0, 0.2, 1),
              opacity 200ms ease-out,
              transform 150ms ease-out;
}
.lumi-v7 .lumi-v7-eye-highlight { fill: #FFFFFF; pointer-events: none; }
.lumi-v7 .lumi-v7-pupil {
  fill: var(--lumi-eye);
  scale: 1; /* V34 Phase 2: emotion-driven dilation, composes with RAF translate */
  transform-box: fill-box;
  transform-origin: center;
  transition: transform 280ms cubic-bezier(0.22, 1, 0.36, 1),
              scale 600ms cubic-bezier(0.4, 0, 0.2, 1);
}

/* ---------------- V34 Phase 2: Pupil dilation by emotion ----------------
 * Driven by [data-mouth] on the wrapper so no extra prop wiring is needed.
 * neutral 1.0 (default) → excited 1.15 → calm/sleepy/breathing 0.85 → loving 0.95 */
.lumi-v7[data-mouth="excited"]   .lumi-v7-pupil { scale: 1.15; }
.lumi-v7[data-mouth="loving"]    .lumi-v7-pupil { scale: 0.95; }
.lumi-v7[data-mouth="calm"]      .lumi-v7-pupil,
.lumi-v7[data-mouth="sleepy"]    .lumi-v7-pupil,
.lumi-v7[data-mouth="breathing"] .lumi-v7-pupil { scale: 0.85; }

/* ---------------- V34 Phase 2: Blush escalation transition ---------------- */
.lumi-v7 .lumi-v7-blush {
  transition: opacity 600ms ease-out;
}

.lumi-v7 .lumi-v7-eye.lumi-eye--default { /* baseline rx/ry set in SVG */ }
.lumi-v7 .lumi-v7-eye.lumi-eye--wide   { transform: scale(1.4, 1.5); }
.lumi-v7 .lumi-v7-eye.lumi-eye--soft   { transform: scale(1.0, 0.55); opacity: 0.85; }
.lumi-v7 .lumi-v7-eye.lumi-eye--happy  { transform: scale(1.1, 0.45); }

/* Blink — driven by JS toggling .is-blinking on each .lumi-v7-eye */
.lumi-v7 .lumi-v7-eye.is-blinking { transform: scale(1.0, 0.05); opacity: 1; }

/* ---------------- Mouth coordination (10 expressions) ---------------- */
.lumi-v7 .lumi-v7-mouth {
  fill: none;
  stroke: var(--lumi-mouth);
  stroke-width: 4;
  stroke-linecap: round;
  stroke-linejoin: round;
  transition: d 600ms cubic-bezier(0.4, 0, 0.2, 1),
              stroke-width 600ms cubic-bezier(0.4, 0, 0.2, 1),
              fill 600ms cubic-bezier(0.4, 0, 0.2, 1),
              transform 600ms cubic-bezier(0.4, 0, 0.2, 1),
              opacity 600ms ease-out;
  transition-delay: 100ms; /* eyes lead, mouth follows */
}

.lumi-v7 .lumi-v7-mouth.lumi-mouth--happy     { stroke-width: 4;   fill: none; }
.lumi-v7 .lumi-v7-mouth.lumi-mouth--calm      { stroke-width: 3;   fill: none; }
.lumi-v7 .lumi-v7-mouth.lumi-mouth--surprise  { stroke-width: 3.5; fill: var(--lumi-mouth); }
.lumi-v7 .lumi-v7-mouth.lumi-mouth--sleepy    { stroke-width: 2.5; fill: none; opacity: 0.85; }
.lumi-v7 .lumi-v7-mouth.lumi-mouth--open      { stroke-width: 3;   fill: var(--lumi-mouth); }
.lumi-v7 .lumi-v7-mouth.lumi-mouth--worried   { stroke-width: 3;   fill: none; }
.lumi-v7 .lumi-v7-mouth.lumi-mouth--excited   { stroke-width: 4.5; fill: var(--lumi-mouth); }
.lumi-v7 .lumi-v7-mouth.lumi-mouth--loving    { stroke-width: 4;   fill: var(--lumi-blush); stroke: var(--lumi-blush); }
.lumi-v7 .lumi-v7-mouth.lumi-mouth--focused   { stroke-width: 3;   fill: none; }
.lumi-v7 .lumi-v7-mouth.lumi-mouth--breathing { stroke-width: 3;   fill: var(--lumi-mouth); opacity: 0.9; }

/* ---------------- Arm coordination (6 movements) ---------------- */
.lumi-v7 .lumi-v7-arm {
  transform-box: fill-box;
  transform-origin: top center;
  transition: transform 800ms ease-in-out;
  will-change: transform;
}
.lumi-v7 .lumi-v7-arm--left  { transform-origin: 100% 0%; }
.lumi-v7 .lumi-v7-arm--right { transform-origin: 0% 0%; }

.lumi-v7.lumi-arm--rest    .lumi-v7-arm--left  { transform: rotate(0deg); }
.lumi-v7.lumi-arm--rest    .lumi-v7-arm--right { transform: rotate(0deg); }

.lumi-v7.lumi-arm--wave    .lumi-v7-arm--right {
  transform: rotate(-30deg);
  animation: lumi-v7-wave 1.4s ease-in-out infinite;
}

.lumi-v7.lumi-arm--hug     .lumi-v7-arm--left  { transform: rotate(28deg) translate(8px, 4px); }
.lumi-v7.lumi-arm--hug     .lumi-v7-arm--right { transform: rotate(-28deg) translate(-8px, 4px); }

.lumi-v7.lumi-arm--point   .lumi-v7-arm--right { transform: rotate(-22deg); }

.lumi-v7.lumi-arm--present .lumi-v7-arm--left  { transform: rotate(22deg); }
.lumi-v7.lumi-arm--present .lumi-v7-arm--right { transform: rotate(-22deg); }

.lumi-v7.lumi-arm--heart   .lumi-v7-arm--left  { transform: rotate(20deg) translate(10px, 8px); }
.lumi-v7.lumi-arm--heart   .lumi-v7-arm--right { transform: rotate(-20deg) translate(-10px, 8px); }

@keyframes lumi-v7-wave {
  0%, 100% { transform: rotate(-30deg); }
  50%      { transform: rotate(-12deg); }
}

/* ---------------- Leg coordination (5 movements) ---------------- */
.lumi-v7 .lumi-v7-leg {
  transform-box: fill-box;
  transform-origin: top center;
  transition: transform 800ms ease-in-out;
  will-change: transform;
}
.lumi-v7 .lumi-v7-leg--left  { transform-origin: 50% 0%; }
.lumi-v7 .lumi-v7-leg--right { transform-origin: 50% 0%; }

.lumi-v7.lumi-leg--rest   .lumi-v7-leg { transform: translateY(0) rotate(0); }

.lumi-v7.lumi-leg--sit    .lumi-v7-leg--left  { transform: translateY(-6px) translateX(4px) rotate(-12deg); }
.lumi-v7.lumi-leg--sit    .lumi-v7-leg--right { transform: translateY(-6px) translateX(-4px) rotate(12deg); }

.lumi-v7.lumi-leg--walk   .lumi-v7-leg--left  { animation: lumi-v7-walk-l 0.9s ease-in-out infinite; }
.lumi-v7.lumi-leg--walk   .lumi-v7-leg--right { animation: lumi-v7-walk-r 0.9s ease-in-out infinite; }

.lumi-v7.lumi-leg--bounce .lumi-v7-leg--left,
.lumi-v7.lumi-leg--bounce .lumi-v7-leg--right { animation: lumi-v7-bounce 0.6s ease-in-out infinite; }

.lumi-v7.lumi-leg--tuck   .lumi-v7-leg--left  { transform: translateY(-10px) translateX(8px); }
.lumi-v7.lumi-leg--tuck   .lumi-v7-leg--right { transform: translateY(-10px) translateX(-8px); }

@keyframes lumi-v7-walk-l {
  0%, 100% { transform: rotate(-12deg); }
  50%      { transform: rotate(12deg); }
}
@keyframes lumi-v7-walk-r {
  0%, 100% { transform: rotate(12deg); }
  50%      { transform: rotate(-12deg); }
}
@keyframes lumi-v7-bounce {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-3px); }
}

/* ---------------- Heart glow (V8 contract) ---------------- */
.lumi-v7 .lumi-v7-heart-glow {
  fill: var(--lumi-blush);
  opacity: 0.6;
  transform-origin: center;
  animation: lumi-v7-heart-pulse 2.4s ease-in-out infinite;
}
@keyframes lumi-v7-heart-pulse {
  0%, 100% { opacity: 0.45; transform: scale(1); }
  50%      { opacity: 0.75; transform: scale(1.06); }
}

/* ---------------- Crisis override → instant calm, no motion ----------------
 * BHCE asymmetric-risk safety contract. Must beat blink + every keyframe class.
 * `!important` is intentional and required here. */
.lumi-v7.is-crisis .lumi-v7-eye,
.lumi-v7.is-crisis .lumi-v7-pupil,
.lumi-v7.is-crisis .lumi-v7-mouth,
.lumi-v7.is-crisis .lumi-v7-arm,
.lumi-v7.is-crisis .lumi-v7-leg,
.lumi-v7.is-crisis .lumi-v7-heart-glow,
.lumi-v7.is-crisis .lumi-v7-blush {
  animation: none !important;
  transition: none !important;
}
/* V34 Phase 2: pin pupil dilation under crisis */
.lumi-v7.is-crisis .lumi-v7-pupil { scale: 1 !important; }
.lumi-v7.is-crisis .lumi-v7-eye,
.lumi-v7.is-crisis .lumi-v7-eye.is-blinking,
.lumi-v7.is-crisis .lumi-v7-eye.lumi-eye--default,
.lumi-v7.is-crisis .lumi-v7-eye.lumi-eye--wide,
.lumi-v7.is-crisis .lumi-v7-eye.lumi-eye--soft,
.lumi-v7.is-crisis .lumi-v7-eye.lumi-eye--happy {
  transform: scale(1.0, 0.7) !important;
  opacity: 0.9 !important;
}
.lumi-v7.is-crisis .lumi-v7-arm--left,
.lumi-v7.is-crisis .lumi-v7-arm--right {
  transform: rotate(0deg) !important;
}
.lumi-v7.is-crisis .lumi-v7-leg--left,
.lumi-v7.is-crisis .lumi-v7-leg--right {
  transform: rotate(0deg) translateY(0) !important;
}

/* ---------------- Reduced-motion contract ---------------- */
@media (prefers-reduced-motion: reduce) {
  .lumi-v7 *,
  .lumi-v7 *::before,
  .lumi-v7 *::after {
    animation: none !important;
    transition: none !important;
  }
  .lumi-v7 .lumi-v7-pupil { transform: none !important; scale: 1 !important; }
}

.seo-content-discovery-rail {
