@media (prefers-reduced-motion: reduce) {
  .seo-content-discovery-rail__link {
    transition: none;
  }

  .seo-content-discovery-rail__link:hover,
  .seo-content-discovery-rail__link:focus-visible {
    transform: none;
  }
}

