.bg-gradient-mesh {
  background:
    radial-gradient(1100px 700px at 15% 0%, rgba(143,191,159,.35), transparent 60%),
    radial-gradient(900px 600px at 85% 10%, rgba(244,199,195,.30), transparent 55%),
    linear-gradient(180deg, var(--ivory), #ffffff);
}

/* Glass effect */
.glass {
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(143, 191, 159, 0.2);
}

/* Sacred Glow Utilities */
.glow-gold {
  box-shadow: 0 0 24px rgba(212, 175, 55, 0.6);
}

.glow-sage {
  box-shadow: 0 0 20px rgba(143, 191, 159, 0.5);
}

.glow-blossom {
  box-shadow: 0 0 20px rgba(244, 199, 195, 0.6);
}

.glow-healing {
  box-shadow: 0 0 30px rgba(143, 191, 159, 0.4), 0 0 60px rgba(212, 175, 55, 0.2);
}

/* Emotion-Linked Gradient Backgrounds */
.bg-emotion-calm {
  background: linear-gradient(135deg, rgba(143, 191, 159, 0.15) 0%, rgba(250, 249, 247, 1) 50%, rgba(173, 216, 230, 0.1) 100%);
}

.bg-emotion-joy {
  background: linear-gradient(135deg, rgba(255, 223, 186, 0.2) 0%, rgba(250, 249, 247, 1) 50%, rgba(212, 175, 55, 0.1) 100%);
}

.bg-emotion-reflection {
  background: linear-gradient(135deg, rgba(200, 162, 200, 0.15) 0%, rgba(250, 249, 247, 1) 50%, rgba(143, 191, 159, 0.1) 100%);
}

.bg-emotion-healing {
  background: linear-gradient(135deg, rgba(244, 199, 195, 0.2) 0%, rgba(250, 249, 247, 1) 50%, rgba(143, 191, 159, 0.15) 100%);
}

.bg-emotion-focus {
  background: linear-gradient(135deg, rgba(90, 138, 110, 0.1) 0%, rgba(250, 249, 247, 1) 50%, rgba(70, 130, 180, 0.1) 100%);
}

.dark .bg-emotion-calm {
  background: linear-gradient(135deg, rgba(143, 191, 159, 0.1) 0%, hsl(180, 22%, 10%) 50%, rgba(173, 216, 230, 0.05) 100%);
}

.dark .bg-emotion-joy {
  background: linear-gradient(135deg, rgba(255, 223, 186, 0.1) 0%, hsl(180, 22%, 10%) 50%, rgba(212, 175, 55, 0.05) 100%);
}

.dark .bg-emotion-reflection {
  background: linear-gradient(135deg, rgba(200, 162, 200, 0.08) 0%, hsl(180, 22%, 10%) 50%, rgba(143, 191, 159, 0.05) 100%);
}

.dark .bg-emotion-healing {
  background: linear-gradient(135deg, rgba(244, 199, 195, 0.1) 0%, hsl(180, 22%, 10%) 50%, rgba(143, 191, 159, 0.08) 100%);
}

.dark .bg-emotion-focus {
  background: linear-gradient(135deg, rgba(90, 138, 110, 0.08) 0%, hsl(180, 22%, 10%) 50%, rgba(70, 130, 180, 0.05) 100%);
}

/* Animated Gradient Background */
@keyframes gradientShift {
  0%, 100% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
}

.bg-emotion-animated {
  background: linear-gradient(-45deg, rgba(143, 191, 159, 0.15), rgba(244, 199, 195, 0.15), rgba(212, 175, 55, 0.1), rgba(173, 216, 230, 0.1));
  background-size: 400% 400%;
  animation: gradientShift 15s ease infinite;
}

@media (prefers-reduced-motion: reduce) {
  .bg-emotion-animated {
    animation: none;
    background-size: 100% 100%;
  }
}

/* Button styles */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.25rem;
  border-radius: 0.875rem;
  font-weight: 600;
  transition: all 0.2s ease;
}

.btn-primary {
  background: var(--glp-sage-deep);
  color: var(--glp-paper);
  box-shadow: 0 4px 14px rgba(var(--glp-sage-deep-rgb), 0.35);
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
  font-weight: 600;
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(var(--glp-sage-deep-rgb), 0.45);
  filter: brightness(1.08);
}

.btn-secondary {
  background: var(--glp-surface);
  color: var(--glp-sage-deep);
  border: 2px solid var(--glp-sage);
}

.btn-secondary:hover {
  background: var(--sage);
  color: white;
}

/* Card styles */
.card-brand {
  background: white;
  border-radius: 1.25rem;
  padding: 1.5rem;
  border: 1px solid rgba(var(--glp-sage-rgb), 0.15);
  box-shadow: 0 10px 40px rgba(var(--glp-sage-deep-rgb), 0.08);
  transition: all 0.3s ease;
}

.card-brand:hover {
  transform: translateY(-4px);
  box-shadow: 0 20px 60px rgba(var(--glp-sage-deep-rgb), 0.12);
}

/* Navigation */
.nav-link {
  color: var(--teal);
  font-weight: 500;
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  transition: all 0.2s ease;
}

.nav-link:hover {
  background: rgba(var(--glp-sage-rgb), 0.15);
}

.nav-link:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--glp-gold);
}

/* Global link focus styles */
a:focus-visible {
  outline: 2px solid var(--glp-gold);
  outline-offset: 2px;
  border-radius: 2px;
}

/* Section styles */
.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

/* NOTE: .section-title is defined in PREMIUM VISUAL ENHANCEMENTS section below */

.section-subtitle {
  font-size: 1.125rem;
  color: var(--charcoal);
  opacity: 0.8;
  max-width: 600px;
  margin: 0 auto;
}

/* Feature cards */
.feature-card {
  background: white;
  border-radius: 1.25rem;
  padding: 2rem;
  border: 1px solid rgba(var(--glp-sage-rgb), 0.15);
  box-shadow: 0 10px 40px rgba(var(--glp-sage-deep-rgb), 0.06);
  transition: all 0.3s ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 20px 50px rgba(47, 93, 93, 0.1);
}

.feature-icon {
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1rem;
}

/* Animations */
@keyframes fade-in-up {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fade-in-scale {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes gentle-breathe {
  0%, 100% {
    transform: scale(1);
    opacity: 0.8;
  }
  50% {
    transform: scale(1.02);
    opacity: 1;
  }
}

@keyframes subtle-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(212, 175, 55, 0);
  }
  50% {
    box-shadow: 0 0 20px 4px rgba(212, 175, 55, 0.15);
  }
}

@keyframes float {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}

@keyframes shimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

.animate-fade-in-up {
  animation: fade-in-up 0.6s ease-out forwards;
}

.animate-fade-in-scale {
  animation: fade-in-scale 0.5s ease-out forwards;
}

.animate-breathe {
  animation: gentle-breathe 4s ease-in-out infinite;
}

.animate-float {
  animation: float 6s ease-in-out infinite;
}

.animate-pulse-gold {
  animation: subtle-pulse 3s ease-in-out infinite;
}

/* Premium Glassmorphism */
.glass-premium {
  background: rgba(255, 255, 255, 0.75);
  backdrop-filter: blur(16px) saturate(180%);
  border: 1px solid rgba(143, 191, 159, 0.18);
  box-shadow: 
    0 4px 30px rgba(90, 138, 110, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.6);
}

.dark .glass-premium {
  background: rgba(26, 32, 44, 0.8);
  border: 1px solid rgba(143, 191, 159, 0.12);
  box-shadow: 
    0 4px 30px rgba(0, 0, 0, 0.2),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

/* See .glow-gold in Sacred Glow Utilities section above */

.hover-glow-gold:hover {
  box-shadow: 0 4px 20px rgba(212, 175, 55, 0.3);
}

/* Legacy card-elevated removed - see ENHANCED CARD SYSTEM section */

/* Premium Hero Gradient */
.hero-gradient {
  background: 
    radial-gradient(ellipse 80% 50% at 50% -20%, rgba(143, 191, 159, 0.25), transparent),
    radial-gradient(ellipse 60% 40% at 80% 60%, rgba(244, 199, 195, 0.2), transparent),
    radial-gradient(ellipse 40% 30% at 20% 80%, rgba(212, 175, 55, 0.1), transparent),
    linear-gradient(180deg, hsl(var(--background)) 0%, hsl(var(--background)) 100%);
}

.dark .hero-gradient {
  background: 
    radial-gradient(ellipse 80% 50% at 50% -20%, rgba(110, 165, 132, 0.15), transparent),
    radial-gradient(ellipse 60% 40% at 80% 60%, rgba(212, 165, 165, 0.1), transparent),
    radial-gradient(ellipse 40% 30% at 20% 80%, rgba(196, 165, 88, 0.08), transparent),
    linear-gradient(180deg, hsl(var(--background)) 0%, hsl(var(--background)) 100%);
}

/* Scroll reveal animation classes */
.scroll-reveal {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.6s ease-out, transform 0.6s ease-out;
}

.scroll-reveal.revealed {
  opacity: 1;
  transform: translateY(0);
}

/* Legacy btn-premium/btn-secondary-premium removed - see ENHANCED BUTTON SYSTEM section */

/* Text gradient effect */
.text-gradient-brand {
  background: linear-gradient(135deg, var(--glp-sage) 0%, var(--glp-sage-deep) 40%, var(--glp-gold) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* NOTE: .decorative-orb classes are defined in PREMIUM VISUAL ENHANCEMENTS section below */

/* Focus styles for accessibility */
:focus-visible {
  outline: 2px solid var(--sage);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px rgba(143, 191, 159, 0.2);
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .scroll-reveal {
    opacity: 1;
    transform: none;
  }
}

