/* --- ENHANCED HOVER EFFECTS --- */
.hover-lift {
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.3s ease;
}

.hover-lift:hover {
  transform: translateY(-6px);
}

.hover-glow:hover {
  box-shadow: 0 0 24px rgba(var(--glp-sage-deep-rgb), 0.2);
}

.hover-scale {
  transition: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

.hover-scale:hover {
  transform: scale(1.03);
}

.hover-brighten {
  transition: filter 0.2s ease;
}

.hover-brighten:hover {
  filter: brightness(1.08);
}

/* --- ENHANCED ANIMATIONS --- */
@keyframes fade-in-up-stagger {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes glow-pulse-teal {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(42, 84, 84, 0);
  }
  50% {
    box-shadow: 0 0 32px 10px rgba(42, 84, 84, 0.2);
  }
}

@keyframes shimmer-premium {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

@keyframes float-gentle {
  0%, 100% { transform: translateY(0) rotate(0deg); }
  25% { transform: translateY(-6px) rotate(0.5deg); }
  75% { transform: translateY(-6px) rotate(-0.5deg); }
}

@keyframes scale-breathe {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.02); }
}

.animate-fade-in-stagger {
  animation: fade-in-up-stagger 0.6s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  opacity: 0;
}

.animate-glow-teal {
  animation: glow-pulse-teal 4s ease-in-out infinite;
}

.animate-shimmer-premium {
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.5), transparent);
  background-size: 200% 100%;
  animation: shimmer-premium 2s ease-in-out infinite;
}

.animate-float-gentle {
  animation: float-gentle 6s ease-in-out infinite;
}

.animate-breathe {
  animation: scale-breathe 4s ease-in-out infinite;
}

/* Stagger delays */
.stagger-1 { animation-delay: 0.1s; }
.stagger-2 { animation-delay: 0.2s; }
.stagger-3 { animation-delay: 0.3s; }
.stagger-4 { animation-delay: 0.4s; }
.stagger-5 { animation-delay: 0.5s; }
.stagger-6 { animation-delay: 0.6s; }

/* --- ENHANCED DIVIDERS --- */
.divider-premium {
