/* --- ACCESSIBILITY ENHANCEMENTS --- */
@media (prefers-reduced-motion: reduce) {
  .animate-fade-in-stagger,
  .animate-glow-teal,
  .animate-shimmer-premium,
  .animate-float-gentle,
  .animate-breathe,
  .hover-lift,
  .hover-scale {
    animation: none !important;
    transition: none !important;
  }

