/* --- ANIMATION UTILITIES --- */

/* Safety net: opacity:1 base ensures content is ALWAYS visible even if
   the keyframe never fires (slow first paint, broken keyframe, etc.).
   The animation still runs; it briefly dips to opacity:0 from the keyframe
   then returns to 1 — but content can never be permanently invisible. */
.animate-fade-in-up {
  opacity: 1;
  animation: fadeInUp 0.5s ease-out forwards;
}

.animate-fade-in-scale {
  opacity: 1;
  animation: fadeInScale 0.4s ease-out forwards;
}

.animate-glow-pulse {
  animation: glowPulse 2s ease-in-out infinite;
}

.animate-bounce-subtle {
  animation: bounceSubtle 2s ease-in-out infinite;
}

@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes fadeInScale {
  from { opacity: 0; transform: scale(0.95); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes glowPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(var(--glp-gold-rgb), 0.4); }
  50% { box-shadow: 0 0 24px 4px rgba(var(--glp-gold-rgb), 0.2); }
}

@keyframes bounceSubtle {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}

/* Delay utilities for staggered animations */
.delay-100 { animation-delay: 100ms; }
.delay-200 { animation-delay: 200ms; }
.delay-300 { animation-delay: 300ms; }
.delay-400 { animation-delay: 400ms; }
.delay-500 { animation-delay: 500ms; }

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  .animate-fade-in-up,
  .animate-fade-in-scale,
  .animate-glow-pulse,
  .animate-bounce-subtle {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .hover-lift:hover,
  .hover-scale:hover {
    transform: none;
  }
}

