/* ===== SECTION 13: PREMIUM VISUAL REFINEMENTS ===== */
/* Stunning depth and dimensionality for healing UI */

/* Enhanced 3D Card Lift Effect */
.card-3d-lift {
  transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  transform-style: preserve-3d;
  perspective: 1000px;
}

.card-3d-lift:hover {
  transform: translateY(-8px) rotateX(2deg);
  box-shadow: 
    0 25px 50px rgba(42, 84, 84, 0.15),
    0 12px 24px rgba(42, 84, 84, 0.08),
    0 0 0 1px rgba(127, 179, 154, 0.12);
}

/* Luminous Border Glow */
.border-luminous {
  position: relative;
  border: 1px solid rgba(127, 179, 154, 0.25);
}

.border-luminous::before {
  content: '';
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  background: linear-gradient(
    135deg,
    rgba(127, 179, 154, 0.4) 0%,
    rgba(212, 168, 75, 0.3) 50%,
    rgba(242, 189, 184, 0.4) 100%
  );
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
  padding: 1px;
  opacity: 0;
  transition: opacity 0.4s ease;
  pointer-events: none;
}

.border-luminous:hover::before {
  opacity: 1;
}

/* Premium Shimmer Effect */
.shimmer-premium {
  position: relative;
  overflow: hidden;
}

.shimmer-premium::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 50%;
  height: 100%;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(255, 255, 255, 0.4) 50%,
    transparent 100%
  );
  animation: shimmer-sweep 3s ease-in-out infinite;
}

@keyframes shimmer-sweep {
  0%, 100% { left: -100%; }
  50% { left: 150%; }
}

/* Frosted Glass Ultra */
.glass-ultra {
  background: rgba(255, 255, 255, 0.65);
  backdrop-filter: blur(24px) saturate(200%);
  border: 1px solid rgba(255, 255, 255, 0.4);
  box-shadow: 
    0 8px 32px rgba(42, 84, 84, 0.1),
    inset 0 1px 1px rgba(255, 255, 255, 0.7),
    inset 0 -1px 1px rgba(0, 0, 0, 0.02);
}

.dark .glass-ultra {
  background: rgba(30, 41, 59, 0.7);
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 
    0 8px 32px rgba(0, 0, 0, 0.25),
    inset 0 1px 1px rgba(255, 255, 255, 0.04);
}

/* Healing Gradient Backgrounds */
.bg-healing-dawn {
  background: linear-gradient(
    135deg,
    rgba(237, 245, 245, 1) 0%,
    rgba(250, 250, 248, 1) 35%,
    rgba(253, 246, 245, 1) 70%,
    rgba(252, 248, 237, 1) 100%
  );
}

.bg-healing-dusk {
  background: linear-gradient(
    180deg,
    rgba(42, 84, 84, 0.03) 0%,
    rgba(127, 179, 154, 0.05) 50%,
    rgba(212, 168, 75, 0.03) 100%
  );
}

/* Ambient Glow Animation */
@keyframes ambient-glow {
  0%, 100% {
    box-shadow: 0 0 30px rgba(127, 179, 154, 0.15);
  }
  50% {
    box-shadow: 0 0 60px rgba(127, 179, 154, 0.25);
  }
}

.animate-ambient-glow {
  animation: ambient-glow 4s ease-in-out infinite;
}

/* Soft Focus Ring (Enhanced Accessibility) */
.focus-ring-premium:focus-visible {
  outline: none;
  box-shadow: 
    0 0 0 3px rgba(212, 168, 75, 0.35),
    0 0 0 5px rgba(212, 168, 75, 0.15),
    0 4px 12px rgba(42, 84, 84, 0.1);
}

/* Premium Text Shadow */
.text-shadow-soft {
  text-shadow: 0 1px 2px rgba(42, 84, 84, 0.08);
}

.text-shadow-gold {
  text-shadow: 0 2px 4px rgba(212, 168, 75, 0.2);
}

/* Gradient Text Enhanced */
.text-gradient-healing {
  background: linear-gradient(
    135deg,
    var(--glp-teal-500) 0%,
    var(--glp-sage-400) 40%,
    var(--glp-gold-400) 80%,
    var(--glp-blush-400) 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Divider with Gradient */
.divider-gradient {
  height: 1px;
  background: linear-gradient(
    90deg,
    transparent 0%,
    rgba(127, 179, 154, 0.3) 20%,
    rgba(212, 168, 75, 0.2) 50%,
    rgba(127, 179, 154, 0.3) 80%,
    transparent 100%
  );
}

/* Premium Button Glow Pulse */
@keyframes glow-pulse-premium {
  0%, 100% {
    box-shadow: 
      0 4px 15px rgba(42, 84, 84, 0.2),
      0 0 0 0 rgba(212, 168, 75, 0);
  }
  50% {
    box-shadow: 
      0 6px 20px rgba(42, 84, 84, 0.25),
      0 0 20px 3px rgba(212, 168, 75, 0.15);
  }
}

.animate-glow-pulse {
  animation: glow-pulse-premium 3s ease-in-out infinite;
}

/* Smooth Entrance Animations */
@keyframes slide-in-bottom {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slide-in-left {
  from {
    opacity: 0;
    transform: translateX(-30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slide-in-right {
  from {
    opacity: 0;
    transform: translateX(30px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.animate-slide-in-bottom {
  animation: slide-in-bottom 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.animate-slide-in-left {
  animation: slide-in-left 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

.animate-slide-in-right {
  animation: slide-in-right 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}

/* Stagger Animation Delays */
.delay-75 { animation-delay: 75ms; }
.delay-150 { animation-delay: 150ms; }
.delay-225 { animation-delay: 225ms; }
.delay-300 { animation-delay: 300ms; }

/* Premium Card Hover States */
.card-hover-premium {
  transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}

.card-hover-premium:hover {
  transform: translateY(-6px);
  box-shadow: 
    0 20px 40px rgba(42, 84, 84, 0.12),
    0 8px 16px rgba(42, 84, 84, 0.06),
    0 0 1px rgba(127, 179, 154, 0.2);
}

/* Healing Pulse Background */
@keyframes healing-pulse {
  0%, 100% {
    opacity: 0.5;
  }
  50% {
    opacity: 0.8;
  }
}

.bg-healing-pulse {
  position: relative;
}

.bg-healing-pulse::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(
    circle at 50% 50%,
    rgba(127, 179, 154, 0.1) 0%,
    transparent 70%
  );
  animation: healing-pulse 6s ease-in-out infinite;
  pointer-events: none;
}

/* Safe Mode for Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  .card-3d-lift:hover {
    transform: none;
  }

  .shimmer-premium::after {
    animation: none;
  }

  .animate-ambient-glow,
  .animate-glow-pulse {
    animation: none;
  }

  .animate-slide-in-bottom,
  .animate-slide-in-left,
  .animate-slide-in-right {
    animation: none;
    opacity: 1;
    transform: none;
  }

  .bg-healing-pulse::before {
    animation: none;
    opacity: 0.5;
  }
}

