  color: var(--glp-blush-700);
}

/* Icon Background Variants - Gradient */
.icon-bg-gradient-teal {
  background: linear-gradient(135deg, var(--glp-teal-400) 0%, var(--glp-teal-600) 100%);
  color: white;
  box-shadow: 0 4px 12px rgba(var(--glp-sage-deep-rgb), 0.3);
}
.icon-bg-gradient-sage {
  background: linear-gradient(135deg, var(--glp-sage-300) 0%, var(--glp-sage-500) 100%);
  color: white;
  box-shadow: 0 4px 12px rgba(var(--glp-sage-rgb), 0.3);
}
.icon-bg-gradient-gold {
  background: linear-gradient(135deg, var(--glp-gold-300) 0%, var(--glp-gold-500) 100%);
  color: white;
  box-shadow: 0 4px 12px rgba(var(--glp-gold-rgb), 0.3);
}
.icon-bg-gradient-blush {
  background: linear-gradient(135deg, var(--glp-blush-200) 0%, var(--glp-blush-400) 100%);
  color: white;
  box-shadow: 0 4px 12px rgba(var(--glp-blush-rgb), 0.3);
}

/* Icon Background Variants - Glass */
.icon-bg-glass {
  background: rgba(255, 255, 255, 0.75);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(var(--glp-sage-rgb), 0.15);
  color: var(--glp-teal-600);
}

/* Icon Outline Variants */
.icon-outline-teal {
  background: transparent;
  border: 2px solid var(--glp-teal-400);
  color: var(--glp-teal-600);
}
.icon-outline-sage {
  background: transparent;
  border: 2px solid var(--glp-sage-400);
  color: var(--glp-sage-600);
}
.icon-outline-gold {
  background: transparent;
  border: 2px solid var(--glp-gold-400);
  color: var(--glp-gold-600);
}

/* Icon Interactive States */
.icon-interactive {
  transition: all 0.2s ease;
  cursor: pointer;
}
.icon-interactive:hover {
  transform: scale(1.08);
}
.icon-interactive:active {
  transform: scale(0.95);
}

/* Icon with Glow */
.icon-glow-teal {
  box-shadow: 0 0 16px rgba(var(--glp-sage-deep-rgb), 0.4);
}
.icon-glow-gold {
  box-shadow: 0 0 16px rgba(var(--glp-gold-rgb), 0.4);
}
.icon-glow-sage {
  box-shadow: 0 0 16px rgba(var(--glp-sage-rgb), 0.4);
}

/* Icon Badge Position */
.icon-with-badge {
  position: relative;
}
.icon-badge {
  position: absolute;
  top: -0.25rem;
  right: -0.25rem;
  min-width: 1rem;
  height: 1rem;
  font-size: 0.625rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  background: var(--glp-error);
  color: white;
  border: 2px solid white;
}

/* --- 14.5: ENHANCED FOCUS & ACCESSIBILITY --- */
.focus-ring-gold:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--glp-gold), 0 0 0 5px rgba(var(--glp-gold-rgb), 0.25);
}

.focus-ring-teal:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--glp-teal-400), 0 0 0 5px rgba(var(--glp-sage-deep-rgb), 0.2);
}

/* Skip Link for Accessibility */
.skip-link {
  position: absolute;
  top: -100px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--glp-teal-600);
  color: white;
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  font-weight: 600;
  z-index: 9999;
  transition: top 0.2s ease;
}

.skip-link:focus {
  top: 1rem;
}

/* High Contrast Mode Support */
@media (prefers-contrast: high) {
  .border-brand-subtle {
    border-color: var(--glp-ink);
  }
  .text-brand-muted,
  .text-brand-subtle {
    color: var(--glp-ink);
  }
}

