  border-radius: 50%;
  background: var(--glp-cream-50, #fdfaf3);
  box-shadow: 0 0 6px rgba(253,250,243,0.6);
}
:where(input[type="checkbox"], input[type="radio"]):not(.peer):not([hidden]):disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.dark :where(input[type="checkbox"], input[type="radio"]):not(.peer):not([hidden]) {
  background-color: rgba(15, 30, 28, 0.6);
  border-color: var(--glp-sage-500, #6fa39a);
}
.dark :where(input[type="checkbox"], input[type="radio"]):not(.peer):not([hidden]):checked {
  background-color: var(--glp-sage-500, #6fa39a);
  border-color: var(--glp-sage-400, #88b8af);
}

/* --- Branded native <select> ----------------------------------------------
   Replaces the OS chevron with an inline aurora-tinted SVG. Only touches
   native <select> elements; shadcn Select renders a div-based combobox.
*/
:where(select):not(.no-aurora-select) {
  appearance: none;
  -webkit-appearance: none;
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='none'><path d='M4 6l4 4 4-4' stroke='%234f8b80' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'/></svg>");
  background-repeat: no-repeat;
  background-position: right 0.75rem center;
  background-size: 1rem 1rem;
  padding-right: 2.25rem;
  cursor: pointer;
  transition: box-shadow 240ms ease, border-color 240ms ease;
}
.dark :where(select):not(.no-aurora-select) {
  background-image:
    url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16' fill='none'><path d='M4 6l4 4 4-4' stroke='%2388b8af' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round'/></svg>");
}

/* --- Branded blockquote ---------------------------------------------------
   Long-form content surfaces (about, learning hub, blog posts, journal
   excerpts) gain an elegant left aurora rail + decorative oversized opening
   quote, italic body, soft cream tint background.
*/
:where(blockquote):not(.no-aurora) {
  position: relative;
  margin: 1.75rem 0;
  padding: 1rem 1.25rem 1rem 1.75rem;
  border-left: 3px solid transparent;
  border-image: linear-gradient(
    180deg,
    var(--glp-aurora-1, rgba(143,188,143,0.65)) 0%,
    var(--glp-aurora-2, rgba(212,175,55,0.55)) 50%,
    var(--glp-aurora-3, rgba(167,139,250,0.6)) 100%
  ) 1 100%;
  background: linear-gradient(
    90deg,
    rgba(143,188,143,0.06) 0%,
    transparent 60%
  );
  border-radius: 0 0.5rem 0.5rem 0;
  font-style: italic;
  color: var(--glp-ink-800, #2d3748);
  line-height: 1.65;
}
:where(blockquote):not(.no-aurora)::before {
  content: "\201C"; /* curly opening quote */
  position: absolute;
  top: -0.35rem;
  left: 0.55rem;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 2.4rem;
  line-height: 1;
  color: var(--glp-sage-500, #6fa39a);
  opacity: 0.55;
  pointer-events: none;
}
:where(blockquote):not(.no-aurora) > :first-child { margin-top: 0; }
:where(blockquote):not(.no-aurora) > :last-child { margin-bottom: 0; }

.dark :where(blockquote):not(.no-aurora) {
  color: var(--glp-cream-100, #f4ede0);
  background: linear-gradient(
    90deg,
    rgba(143,188,143,0.10) 0%,
    transparent 60%
  );
}
.dark :where(blockquote):not(.no-aurora)::before {
  color: var(--glp-sage-300, #a8d0c7);
  opacity: 0.7;
}

/* --- Branded list markers --------------------------------------------------
   Sage-tinted ::marker for <ul>/<ol> in long-form content, leaving Tailwind
   list-* utilities and shadcn-styled lists untouched (since they typically
   render custom bullets via padding+pseudo or remove markers entirely).
   Only applied inside .prose-aurora opt-in containers OR inside <blockquote>.
*/
.prose-aurora :where(ul, ol) > li::marker,
:where(blockquote) :where(ul, ol) > li::marker {
  color: var(--glp-sage-600, #4f8b80);
  font-weight: 600;
}
.dark .prose-aurora :where(ul, ol) > li::marker,
.dark :where(blockquote) :where(ul, ol) > li::marker {
  color: var(--glp-sage-300, #a8d0c7);
}

/* --- Reduced motion --------------------------------------------------------- */
@media (prefers-reduced-motion: reduce) {
  :where(input[type="checkbox"], input[type="radio"]):not(.peer):not([hidden]),
  :where(select):not(.no-aurora-select) {
    transition: none !important;
  }
}

/* ============================================================
 * V28 utility classes — added v5.8.31
 * Canonical paper bg + white sage-bordered card for consistent
 * V28 surface treatment across tool pages and tier-3 surfaces.
 * Uses literal hex (not vars) to defeat any token override.
 * ============================================================ */
.v28-paper-bg {
  background: #F7F4EE;
}
.v28-card {
  background: #FFFFFF;
  border: 1px solid rgba(168, 201, 160, 0.55);
  box-shadow: 0 1px 3px rgba(20, 38, 38, 0.06), 0 1px 2px rgba(20, 38, 38, 0.04);
}

/* ============================================================
 * V28 Polish Card — added v5.8.34
 * The definitive content card pattern per IMG_4320 reference:
 * white surface, sage-15 hairline border, 2px top accent stripe
 * (parameterized via --card-accent), generous padding, gentle
 * hover lift. Used for tier cards, feature grids, benefit rows.
 * Drop-in: <article class="polish-card" style="--card-accent:#A8C9A0">
 *   <span class="polish-card-icon">…</span>
 *   <h3>…</h3><p>…</p>
 * </article>
 * ============================================================ */
.polish-card {
  position: relative;
  background: #FFFFFF;
  border: 1px solid rgba(168, 201, 160, 0.30);
  border-radius: 18px;
  padding: 1.75rem 1.5rem;
  box-shadow: 0 1px 3px rgba(45, 55, 50, 0.04), 0 1px 2px rgba(45, 55, 50, 0.03);
  transition: transform 240ms cubic-bezier(0.22, 0.9, 0.32, 1),
              box-shadow 240ms cubic-bezier(0.22, 0.9, 0.32, 1),
              border-color 240ms ease;
  overflow: hidden;
}
.polish-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 2px;
  background: var(--card-accent, #A8C9A0);
  opacity: 0.85;
}
.polish-card:hover,
.polish-card:focus-within {
  transform: translateY(-2px);
  border-color: rgba(168, 201, 160, 0.55);
  box-shadow: 0 10px 24px rgba(45, 55, 50, 0.08), 0 2px 6px rgba(45, 55, 50, 0.04);
}
.polish-card-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.75rem;
  height: 2.75rem;
  border-radius: 12px;
  background: color-mix(in srgb, var(--card-accent, #A8C9A0) 14%, transparent);
  color: var(--card-accent, #A8C9A0);
  margin-bottom: 1rem;
}
.polish-card-title {
  font-family: var(--font-serif, ui-serif, Georgia, serif);
  font-size: 1.125rem;
  font-weight: 700;
  color: #2F5443;
  line-height: 1.3;
  margin: 0 0 0.5rem;
}
.polish-card-body {
  font-size: 0.9rem;
  line-height: 1.6;
  color: #5C6B62;
  margin: 0;
}

/* Section rhythm — calmer, more deliberate vertical pacing.
 * Pairs with .v28-paper-bg. 64/80/96px — never the old 128. */
.section-rhythm {
  padding-top: 4rem;
  padding-bottom: 4rem;
}
@media (min-width: 768px) {
  .section-rhythm { padding-top: 5rem; padding-bottom: 5rem; }
}
@media (min-width: 1024px) {
  .section-rhythm { padding-top: 6rem; padding-bottom: 6rem; }
}

/* Standardized polish-card grids */
.polish-grid-3 {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.25rem;
}
.polish-grid-4 {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.25rem;
}
@media (min-width: 640px) {
  .polish-grid-4 { grid-template-columns: repeat(2, 1fr); }
}
@media (min-width: 768px) {
  .polish-grid-3 { grid-template-columns: repeat(3, 1fr); gap: 1.5rem; }
}
@media (min-width: 1024px) {
  .polish-grid-4 { grid-template-columns: repeat(4, 1fr); }
}

/* Sage gradient pill CTA — paired with polish cards */
.polish-cta {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.875rem 1.75rem;
  font-size: 0.9375rem;
  font-weight: 600;
  color: #FFFFFF;
  background: linear-gradient(135deg, #4A7E72 0%, #A8C9A0 100%);
  border-radius: 999px;
  text-decoration: none;
  box-shadow: 0 6px 18px rgba(74, 126, 114, 0.22);
  transition: transform 200ms cubic-bezier(0.22, 0.9, 0.32, 1),
              box-shadow 200ms cubic-bezier(0.22, 0.9, 0.32, 1);
}
.polish-cta:hover {
  transform: translateY(-2px);
  box-shadow: 0 10px 26px rgba(74, 126, 114, 0.30);
}
.polish-cta:focus-visible {
  outline: 3px solid #4A7E72;
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .polish-card,
  .polish-card:hover,
  .polish-card:focus-within,
  .polish-cta,
  .polish-cta:hover {
    transform: none !important;
    transition: none !important;
  }
}

/* PHASE D6 — calm polished navigation safety layer */
body {
  margin: 0;
  background: #f7f4ee;
  color: #2f4f4a;
}

header a,
nav a {
  text-decoration: none;
}

header {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

details summary {
  list-style: none;
}

details summary::-webkit-details-marker {
  display: none;
}

a:focus,
button:focus,
summary:focus {
  outline: 3px solid #f4b942;
  outline-offset: 3px;
}

.raw-nav,
.legacy-nav,
.debug-nav,
.dev-nav {
  display: none !important;
}


/* =======================================================
   D9 — SINGLE SOURCE NAVIGATION SYSTEM
======================================================= */

.desktop-sidebar,
.sidebar,
.left-sidebar,
.mobile-sidebar,
.tool-sidebar,
.floating-sidebar,
.legacy-sidebar {
  display: none !important;
  visibility: hidden !important;
  width: 0 !important;
  opacity: 0 !important;
  overflow: hidden !important;
}

/* Phase D12: removed D9 over-broad navbar-forcing rules — generic
   header / nav / [role="navigation"] containers and header a / nav a
   pill styling, plus a[href] CTA gold !important. These styled every
   page <header>, breadcrumb, and footer <nav> as a sticky navbar and
   fought TglpNavbar's own Tailwind styling, producing extra nav-looking
   surfaces. The canonical navbar (TglpNavbar) self-styles via Tailwind;
   legacy class hooks (.top-nav/.main-nav/.navbar/.nav-links) are unused. */

/* MOBILE MENU */

.mobile-menu,
.hamburger-menu,
.menu-drawer {

  position: fixed;
  top: 72px;
  right: 1rem;

  width: 290px;
  max-height: 78vh;

  overflow-y: auto;

  padding: 1rem;

  border-radius: 24px;

  background: rgba(247,244,238,0.98);

  backdrop-filter: blur(14px);

  box-shadow:
    0 30px 60px rgba(0,0,0,0.12);

  border:
    1px solid rgba(74,126,114,0.12);
}

/* MOBILE LINKS */

.mobile-menu a,
.menu-drawer a {

  display: flex;
  align-items: center;

  min-height: 46px;

  padding: 0.7rem 1rem;

  border-radius: 14px;

  margin-bottom: 0.45rem;

  text-decoration: none !important;

  color: #355f56 !important;

  background:
    rgba(255,255,255,0.7);
}

/* HIDE MOBILE MENU ON DESKTOP */

@media (min-width: 1024px) {

  .mobile-menu,
  .menu-drawer,
  .hamburger-menu {
    display: none !important;
  }
}

/* Phase D12: removed D9 mobile `header nav` overflow override — TglpNavbar
   uses its own drawer; the generic rule wrongly applied to all page navs. */


/* =========================================================
   D10 NAVIGATION LOCK — prevent duplicate visible nav systems
   Goal: one top nav + one optional menu drawer only
========================================================= */

/* Hide known duplicate/legacy nav containers */
.legacy-nav,
.legacy-navbar,
.old-nav,
.old-navbar,
.secondary-nav,
.secondary-navbar,
.duplicate-nav,
.extra-nav,
.desktop-sidebar,
.left-sidebar,
.side-nav,
.sidebar,
.tool-sidebar,
.tools-sidebar,
.floating-sidebar,
.mobile-sidebar:not(.canonical-mobile-drawer),
.menu-drawer:not(.canonical-mobile-drawer),
.hamburger-menu:not(.canonical-mobile-drawer),
[aria-label="Secondary navigation"],
[aria-label="Tools sidebar"],
[aria-label="Legacy navigation"] {
  display: none !important;
  visibility: hidden !important;
  pointer-events: none !important;
  width: 0 !important;
  height: 0 !important;
  overflow: hidden !important;
}

/* Keep the real top navigation clean */
.app-shell > header:first-of-type,
.site-header,
.main-navbar,
.canonical-navbar {
  position: sticky !important;
  top: 0 !important;
  z-index: 9999 !important;
  width: 100% !important;
  background: rgba(247, 244, 238, 0.96) !important;
  backdrop-filter: blur(14px) !important;
  border-bottom: 1px solid rgba(74,126,114,0.14) !important;
}

/* Phase 158: removed broad header-suppression selectors (main header,
   section header[role="navigation"], root-level header + header). Duplicate
   navs are now prevented at the component level (single canonical TglpNavbar),
   so these over-broad rules — which also wrongly hid legitimate page-title
   <header> elements inside <main> — are no longer needed. */

/* Menu drawer should overlay, not push page content sideways */
.canonical-mobile-drawer,
.mobile-menu,
.menu-panel {
  position: fixed !important;
  top: 76px !important;
  right: 1rem !important;
  z-index: 10000 !important;
  width: min(340px, calc(100vw - 2rem)) !important;
  max-height: calc(100vh - 96px) !important;
  overflow-y: auto !important;
  border-radius: 22px !important;
  background: rgba(247,244,238,0.98) !important;
  box-shadow: 0 24px 70px rgba(0,0,0,0.18) !important;
}

/* Desktop: hide drawer unless explicitly open */
@media (min-width: 1024px) {
  .canonical-mobile-drawer,
  .mobile-menu,
  .menu-panel {
    display: none !important;
  }
}

/* Mobile: reduce nav crowding */
@media (max-width: 760px) {
  .desktop-only,
  .nav-expanded-links {
    display: none !important;
  }

  .site-header,
  .main-navbar,
  .canonical-navbar {
    min-height: 64px !important;
  }
}

/* =========================================================
D11 — SINGLE CANONICAL NAVIGATION SYSTEM
========================================================= */

/* KILL DUPLICATE NAV SYSTEMS */

.secondary-nav,
.legacy-nav,
.old-nav,
.floating-nav,
.quick-nav,
.tools-nav-inline,
.left-sidebar,
.right-sidebar,
.desktop-sidebar,
.mobile-sidebar,
.duplicate-navbar,
.extra-navbar,
.extra-menu,
.nav-clone,
.floating-toolbar,
.overlay-toolbar {
  display: none !important;
}

/* Phase 158: removed broad `header + header` / `nav + nav` suppression —
   the single-navbar invariant is now enforced at the component level. The
   class-based legacy-nav kill list above remains as defensive coverage. */

/* DRAWER MUST OVERLAY */

.mobile-menu,
.mobile-drawer,
.canonical-mobile-drawer {
  position: fixed !important;
  top: 72px !important;
  right: 16px !important;
  width: 320px !important;
  max-height: calc(100vh - 90px) !important;
  overflow-y: auto !important;
  z-index: 99999 !important;
  background: rgba(247,244,238,0.98) !important;
  border-radius: 24px !important;
  box-shadow: 0 30px 80px rgba(0,0,0,0.18) !important;
}

/* PREVENT DRAWER FROM PUSHING PAGE */

body,
#root,
.app-shell,
main {
  overflow-x: hidden !important;
}

/* PREVENT STACKED NAV BARS */

.main-navbar {
  position: sticky !important;
  top: 0 !important;
  z-index: 9999 !important;
}

/* HIDE DUPLICATE CHIP GROUPS */

.chip-group + .chip-group {
  display: none !important;
}

/* ONLY MOBILE HAMBURGER */

@media (min-width: 1024px) {
  .mobile-menu-button,
  .hamburger-button {
    display: none !important;
  }

  .mobile-menu,
  .mobile-drawer,
  .canonical-mobile-drawer {
    display: none !important;
  }
}


/* PHASE 58: universal visual polish + button/readability/focus coherence */
:root {
  --mmhb-focus-ring: 0 0 0 3px rgba(124, 58, 237, 0.32);
  --mmhb-readable-line: 1.65;
  --mmhb-tap-target: 44px;
}

html {
  scroll-behavior: smooth;
}

body {
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
}

button,
[role="button"],
a,
input,
select,
textarea {
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease,
    background-color 160ms ease,
    color 160ms ease,
    opacity 160ms ease;
}

button,
[role="button"],
a[class*="button"],
a[class*="Button"] {
  min-height: var(--mmhb-tap-target);
  min-width: var(--mmhb-tap-target);
}

button:focus-visible,
[role="button"]:focus-visible,
a:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible {
  outline: 2px solid transparent;
