/* PHASE113JM_DESIGN_TOKEN_COHESION_VISUAL_POLISH
   Purpose:
   - lock official palette cohesion
   - correct sage tone
   - improve button visibility and polish
   - reduce red/square avatar background artifacts
   - normalize mobile typography
   This is a visual-system patch only. It does not rewrite content, monetization, or healing logic.
*/

:root {
  --glp-serenity-sage: #8FBF9F;
  --glp-serenity-sage-rgb: 143, 191, 159;
  --glp-serenity-sage-soft: #DCECDF;
  --glp-serenity-sage-mist: #EEF7F1;

  --glp-warm-blossom: #F4C7C3;
  --glp-warm-blossom-soft: #FBE8E5;

  --glp-deep-teal: #2F5D5D;
  --glp-deep-teal-rgb: 47, 93, 93;
  --glp-deep-teal-strong: #214747;

  --glp-ivory-light: #FAF9F7;
  --glp-ivory-warm: #FFFDF9;

  --glp-charcoal-deep: #3A3A3A;
  --glp-charcoal-soft: #565656;

  --glp-eternal-gold: #D4AF37;
  --glp-eternal-gold-soft: #F5E8B8;

  --glp-focus-ring: rgba(var(--glp-deep-teal-rgb), 0.34);
  --glp-card-border: rgba(var(--glp-deep-teal-rgb), 0.14);
  --glp-card-shadow: 0 18px 45px rgba(47, 93, 93, 0.10);
  --glp-button-shadow: 0 12px 28px rgba(47, 93, 93, 0.20);
  --glp-button-shadow-hover: 0 18px 42px rgba(47, 93, 93, 0.28);
}

/* Stable brand foundation */
html,
body {
  background:
    radial-gradient(circle at top left, rgba(var(--glp-serenity-sage-rgb), 0.18), transparent 32rem),
    radial-gradient(circle at top right, rgba(244, 199, 195, 0.20), transparent 30rem),
    linear-gradient(180deg, var(--glp-ivory-light), var(--glp-ivory-warm));
  color: var(--glp-charcoal-deep);
  text-rendering: optimizeLegibility;
}

/* Cohesive readable headings */
h1,
h2,
h3,
[class*="title" i],
[class*="heading" i] {
  color: var(--glp-deep-teal);
  letter-spacing: -0.025em;
}

/* Button visibility, title contrast, and premium polish.
   Kept global because audit found high button drift across many files. */
:where(button, [role="button"], a[href].btn, a[href][class*="button" i], .button, .btn) {
  min-height: 2.75rem;
  border-radius: 999px;
  font-weight: 700;
  letter-spacing: -0.01em;
  text-decoration: none;
  transition:
    transform 160ms ease,
    box-shadow 160ms ease,
    border-color 160ms ease,
    background 160ms ease,
    color 160ms ease,
    opacity 160ms ease;
}

:where(button, [role="button"], a[href].btn, a[href][class*="button" i], .button, .btn):not(:disabled):not([aria-disabled="true"]):hover {
  transform: translateY(-1px);
}

:where(button, [role="button"], a[href].btn, a[href][class*="button" i], .button, .btn):focus-visible {
  outline: 3px solid var(--glp-focus-ring);
  outline-offset: 3px;
}

/* Strong default for primary-looking CTAs while preserving explicit destructive buttons. */
:where(button, [role="button"], a[href][class*="button" i], .button, .btn):not([class*="ghost" i]):not([class*="outline" i]):not([class*="destructive" i]):not([class*="danger" i]):not([class*="red-" i]) {
  background:
    linear-gradient(135deg, var(--glp-deep-teal), var(--glp-serenity-sage));
  color: #FFFFFF;
  border-color: rgba(var(--glp-deep-teal-rgb), 0.28);
  box-shadow: var(--glp-button-shadow);
}

:where(button, [role="button"], a[href][class*="button" i], .button, .btn):not([class*="ghost" i]):not([class*="outline" i]):not([class*="destructive" i]):not([class*="danger" i]):not([class*="red-" i]):hover {
  box-shadow: var(--glp-button-shadow-hover);
}

/* Secondary / outline-style buttons: visible title, brand border, soft surface. */
:where(button[class*="outline" i], button[class*="secondary" i], a[class*="outline" i], a[class*="secondary" i]) {
  background: rgba(250, 249, 247, 0.86);
  color: var(--glp-deep-teal);
  border-color: rgba(var(--glp-deep-teal-rgb), 0.26);
  box-shadow: 0 10px 25px rgba(47, 93, 93, 0.08);
}

/* Premium accent should be warm, not loud. */
:where([class*="premium" i], [class*="upgrade" i], [class*="gold" i]) :where(button, a[href], [role="button"]),
:where(button[class*="premium" i], button[class*="upgrade" i], a[class*="premium" i], a[class*="upgrade" i]) {
  background:
    linear-gradient(135deg, var(--glp-eternal-gold), var(--glp-eternal-gold-soft));
  color: var(--glp-charcoal-deep);
  border-color: rgba(212, 175, 55, 0.38);
}

/* Card/surface cohesion without refactoring component markup. */
:where(.card, [class*="card" i], [class*="panel" i], [class*="surface" i]) {
  border-color: var(--glp-card-border);
  box-shadow: var(--glp-card-shadow);
}

/* Avatar square / red background artifact mitigation.
   This does not animate avatars yet; it removes obvious container bleed and prepares the 3D-object presentation layer. */
:where([class*="avatar" i], [class*="mascot" i], [class*="lumi" i], [data-avatar], [data-mascot]) {
  background-color: transparent;
}

:where([class*="avatar" i], [class*="mascot" i], [class*="lumi" i], [data-avatar], [data-mascot]) :where(img, picture, svg, canvas) {
  background: transparent;
  object-fit: contain;
  filter: drop-shadow(0 20px 28px rgba(47, 93, 93, 0.18));
}

/* Red squares around avatars are never part of the official visual language. */
:where([class*="avatar" i], [class*="mascot" i], [class*="lumi" i], [data-avatar], [data-mascot]) :where([class*="bg-red" i], [class*="border-red" i]) {
  background-color: transparent;
  border-color: transparent;
}

/* Standard avatar display size target for carousel/preview contexts. */
:where([class*="avatar" i], [class*="mascot" i], [class*="lumi" i]) :where(img) {
  max-width: min(100%, 18rem);
  max-height: 18rem;
}

/* Mobile typography safety: reduce oversized headings and prevent overflow. */
@media (max-width: 640px) {
  h1,
  .text-5xl,
  .text-6xl,
  .text-7xl,
  .text-8xl,
  .text-9xl,
  [class*="hero" i] h1,
  [class*="title" i] {
    font-size: clamp(1.6rem, 6.5vw, 2.4rem);
    line-height: 1.05;
    letter-spacing: -0.04em;
  }

  h2,
  .text-4xl,
  [class*="subtitle" i] {
    font-size: clamp(1.5rem, 6.5vw, 2.25rem);
    line-height: 1.12;
  }

  h3,
  .text-3xl {
    font-size: clamp(1.25rem, 5.5vw, 1.75rem);
    line-height: 1.18;
  }

  :where(button, [role="button"], a[href][class*="button" i], .button, .btn) {
    min-height: 2.875rem;
    padding-inline: 1rem;
    font-size: clamp(0.875rem, 3.7vw, 1rem);
    white-space: normal;
    text-align: center;
  }

  :where([class*="avatar" i], [class*="mascot" i], [class*="lumi" i]) :where(img) {
    max-width: min(78vw, 14rem);
    max-height: 14rem;
  }
}

/* Reduced motion respects nervous-system-safe UX. */
@media (prefers-reduced-motion: reduce) {
  :where(button, [role="button"], a[href][class*="button" i], .button, .btn) {
    transition: none;
  }

  :where(button, [role="button"], a[href][class*="button" i], .button, .btn):hover {
    transform: none;
  }
}

/* PHASE114P_GLOBAL_VISUAL_SYSTEM_FOUNDATION_PATCH
   Governed visual foundation for MyMentalHealthBuddy / The Genuine Love Project.
   Scope: palette cohesion, mobile typography, button readability, avatar background blending.
   Canonical brand palette:
   Serenity Sage #8FBF9F | Warm Blossom Pink #F4C7C3 | Deep Teal #2F5D5D
   Ivory Light #FAF9F7 | Charcoal Deep #3A3A3A | Eternal Gold #D4AF37
*/

:root {
  --mmhb-serenity-sage: #8FBF9F;
  --mmhb-serenity-sage-soft: #DDEBDD;
  --mmhb-serenity-sage-deep: #6EA985;
  --mmhb-warm-blossom-pink: #F4C7C3;
  --mmhb-warm-blossom-pink-soft: #FBE7E4;
  --mmhb-deep-teal: #2F5D5D;
  --mmhb-deep-teal-ink: #183A3A;
  --mmhb-ivory-light: #FAF9F7;
  --mmhb-ivory-warm: #F7F4EE;
  --mmhb-charcoal-deep: #3A3A3A;
  --mmhb-eternal-gold: #D4AF37;
  --mmhb-eternal-gold-soft: #F1DF9A;

  --mmhb-text-primary: var(--mmhb-charcoal-deep);
  --mmhb-text-strong: #243737;
  --mmhb-text-muted: #5F6F6F;
  --mmhb-surface: rgba(250, 249, 247, 0.94);
  --mmhb-surface-soft: rgba(255, 255, 255, 0.72);
  --mmhb-border-soft: rgba(47, 93, 93, 0.16);
  --mmhb-focus-ring: rgba(143, 191, 159, 0.46);
  --mmhb-shadow-soft: 0 14px 34px rgba(47, 93, 93, 0.14);
  --mmhb-shadow-button: 0 10px 22px rgba(47, 93, 93, 0.18);
  --mmhb-radius-button: 999px;
  --mmhb-radius-card: 28px;
}

html {
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  background:
    radial-gradient(circle at top left, rgba(143, 191, 159, 0.18), transparent 34rem),
    radial-gradient(circle at top right, rgba(244, 199, 195, 0.18), transparent 32rem),
    var(--mmhb-ivory-light);
}

body {
  color: var(--mmhb-text-primary);
  background:
    linear-gradient(135deg, rgba(250, 249, 247, 0.98), rgba(247, 244, 238, 0.92)),
    var(--mmhb-ivory-light);
}

/* Mobile-first type restraint: prevents oversized hero/headline text on phones while preserving desktop scale. */
h1,
.text-5xl,
.text-6xl,
.text-7xl,
.text-8xl,
.text-9xl {
  line-height: 1.05;
  letter-spacing: -0.035em;
}

@media (max-width: 640px) {
  h1,
  .text-5xl,
  .text-6xl,
  .text-7xl,
  .text-8xl,
  .text-9xl {
    font-size: clamp(2rem, 9.5vw, 3.35rem) !important;
    line-height: 1.06 !important;
  }

  h2,
  .text-4xl {
    font-size: clamp(1.65rem, 7vw, 2.35rem) !important;
    line-height: 1.1 !important;
  }

  h3,
  .text-3xl {
    font-size: clamp(1.35rem, 5.8vw, 1.85rem) !important;
    line-height: 1.16 !important;
  }

  p,
  li {
    line-height: 1.65;
  }
}

/* Button visibility + polish foundation. Keeps labels visible inside buttons and reduces plain/flat appearance. */
button,
[role="button"],
a[class*="button"],
a[class*="Button"],
.mmhb-button,
.btn {
  min-height: 44px;
  color: inherit;
  text-decoration: none;
  text-wrap: balance;
}

button:not([class*="unstyled"]):not([class*="ghost"]),
[role="button"]:not([class*="unstyled"]):not([class*="ghost"]),
.mmhb-button,
.btn {
  border-radius: var(--mmhb-radius-button);
  border-color: var(--mmhb-border-soft);
  box-shadow: var(--mmhb-shadow-button);
  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease;
}

button:not([class*="unstyled"]):not([class*="ghost"]):hover,
[role="button"]:not([class*="unstyled"]):not([class*="ghost"]):hover,
.mmhb-button:hover,
.btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 14px 30px rgba(47, 93, 93, 0.22);
}

button:focus-visible,
[role="button"]:focus-visible,
a:focus-visible,
.mmhb-button:focus-visible,
.btn:focus-visible {
  outline: 3px solid var(--mmhb-focus-ring);
  outline-offset: 3px;
}

button[aria-disabled="true"],
[role="button"][aria-disabled="true"],
.mmhb-button[aria-disabled="true"],
.btn[aria-disabled="true"] {
  cursor: not-allowed;
  opacity: 0.62;
  transform: none;
  box-shadow: none;
}

/* Canonical gradient utility for premium primary actions without forcing every button to change. */
.mmhb-primary-action,
.tglp-primary-action,
[data-visual-role="primary-action"] {
  color: #183A3A !important;
  background:
    linear-gradient(135deg, var(--mmhb-serenity-sage), var(--mmhb-warm-blossom-pink)) !important;
  border: 1px solid rgba(47, 93, 93, 0.18) !important;
  box-shadow: var(--mmhb-shadow-button) !important;
}

.mmhb-gold-action,
.tglp-gold-action,
[data-visual-role="premium-action"] {
  color: #2F2A14 !important;
  background:
    linear-gradient(135deg, var(--mmhb-eternal-gold-soft), var(--mmhb-eternal-gold)) !important;
  border: 1px solid rgba(212, 175, 55, 0.34) !important;
}

/* Avatar/mascot visual foundation: remove hard square/red-box feel and blend objects into the scene. */
[class*="avatar" i],
[class*="lumi" i],
[class*="buddy" i],
[class*="mascot" i],
[data-avatar],
[data-mascot] {
  background-color: transparent;
  border-color: rgba(143, 191, 159, 0.18);
  box-shadow:
    0 18px 40px rgba(47, 93, 93, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.56);
}

[class*="avatar" i] img,
[class*="lumi" i] img,
[class*="buddy" i] img,
[class*="mascot" i] img,
[data-avatar] img,
[data-mascot] img {
  background: transparent !important;
  border-color: transparent !important;
  object-fit: contain;
  filter: drop-shadow(0 16px 22px rgba(47, 93, 93, 0.20));
}

/* Suppress accidental red square artifacts around avatar/mascot surfaces without altering alert/error UI globally. */
[class*="avatar" i][class*="red" i],
[class*="lumi" i][class*="red" i],
[class*="buddy" i][class*="red" i],
[class*="mascot" i][class*="red" i],
[data-avatar][class*="red" i],
[data-mascot][class*="red" i] {
  background: transparent !important;
  border-color: rgba(143, 191, 159, 0.22) !important;
}

/* Cohesive surface helpers available to components without forcing source refactors. */
.mmhb-healing-surface,
.tglp-healing-surface,
[data-visual-role="healing-surface"] {
  background:
    linear-gradient(145deg, rgba(250, 249, 247, 0.94), rgba(247, 244, 238, 0.86)),
    var(--mmhb-surface);
  border: 1px solid var(--mmhb-border-soft);
  border-radius: var(--mmhb-radius-card);
  box-shadow: var(--mmhb-shadow-soft);
  color: var(--mmhb-text-primary);
}

.mmhb-sage-text,
.tglp-sage-text {
  color: var(--mmhb-deep-teal) !important;
}

.mmhb-muted-text,
.tglp-muted-text {
  color: var(--mmhb-text-muted) !important;
}

/* End PHASE114P_GLOBAL_VISUAL_SYSTEM_FOUNDATION_PATCH */

/* PHASE116W1_SHARED_BUTTON_CTA_VISIBILITY_POLISH_PATCH */
:root {
  --glp-button-radius: 999px;
  --glp-button-min-height: 44px;
  --glp-button-shadow: 0 14px 32px color-mix(in srgb, var(--glp-deep-teal, #2F5D5D) 16%, transparent);
  --glp-button-shadow-hover: 0 18px 42px color-mix(in srgb, var(--glp-deep-teal, #2F5D5D) 22%, transparent);
  --glp-button-focus: 0 0 0 3px color-mix(in srgb, var(--glp-gold, #D4AF37) 45%, transparent);
}

/* Shared CTA/button clarity layer.
   Goal: readable labels, cohesive palette, mobile-safe sizing, and polished states
   without refactoring route/component structure. */
button,
[role="button"],
.button,
.btn,
[class*="Button"],
[class*="button"],
[class*="btn"],
[class*="cta"],
[class*="CTA"] {
  min-height: var(--glp-button-min-height);
  border-radius: var(--glp-button-radius);
