/* Keep button titles visible even when page-level classes accidentally over-flatten contrast. */
button:not(:disabled),
[role="button"]:not([aria-disabled="true"]),
.button,
.btn,
[class*="button"],
[class*="btn"],
[class*="cta"],
[class*="CTA"] {
  color: var(--glp-ink, #3A3A3A);
}

/* Primary/premium CTA polish: deep teal + sage + gold, no harsh red/orange drift. */
.glp-button-primary,
.glp-cta-primary,
.premium-button,
.premium-btn,
button[data-variant="primary"],
button[data-variant="premium"],
a[data-variant="primary"],
a[data-variant="premium"] {
