/* PHASE116X1_CANONICAL_PALETTE_SAGE_TONE_BRIDGE_PATCH */
:root {
  /* Canonical Genuine Love Project palette bridge.
     This layer intentionally reasserts the approved brand colors after legacy
     token blocks so the live UI resolves to one cohesive visual language. */

  --glp-sage: #8FBF9F;
  --glp-sage-rgb: 143 191 159;
  --glp-sage-soft: #DDECE3;
  --glp-sage-mist: #EEF7F1;
  --glp-sage-light: #CFE5D7;
  --glp-sage-vivid: #8FBF9F;
  --glp-sage-glow: #BFDCC9;
  --glp-sage-deep: #2F5D5D;
  --glp-sage-deep-rgb: 47 93 93;

  --glp-blossom: #F4C7C3;
  --glp-blossom-rgb: 244 199 195;
  --glp-blossom-soft: #FBE9E7;
  --glp-blossom-mist: #FFF5F3;
  --glp-blossom-glow: #F8D7D4;

