import { BRAND } from "@shared/brand.mjs";

export { BRAND };

export function applyBrandToDocument(): void {
  if (typeof document === "undefined") return;

  const root = document.documentElement;

  root.style.setProperty("--gl-primary", BRAND.colors.primary);
  root.style.setProperty("--gl-secondary", BRAND.colors.secondary);
  root.style.setProperty("--gl-accent", BRAND.colors.accent);
  root.style.setProperty("--gl-gold", BRAND.colors.gold);
  root.style.setProperty("--gl-bg", BRAND.colors.background);
  root.style.setProperty("--gl-text", BRAND.colors.text);

  document.title = BRAND.seo?.title || BRAND.name;

  const meta = document.querySelector('meta[name="description"]');
  if (meta) meta.setAttribute("content", BRAND.seo.description);

  const ensureMeta = (name: string, content: string): void => {
    let tag = document.querySelector(`meta[name="${name}"]`);
    if (!tag) {
      tag = document.createElement("meta");
      tag.setAttribute("name", name);
      document.head.appendChild(tag);
    }
    tag.setAttribute("content", content);
  };

  ensureMeta("description", BRAND.seo?.description || BRAND.mission);
}

export const applyBrand = applyBrandToDocument;

/* File: client/src/lib/mode.js */
export function setUIMode(mode) {
  const root = document.documentElement;
  if (!mode || mode === "default") root.removeAttribute("data-mode");
  else root.setAttribute("data-mode", mode);
  try { localStorage.setItem("glp-mode", mode || "default"); } catch { /* localStorage unavailable */ }
}

export function initUIMode() {
  try {
    const saved = localStorage.getItem("glp-mode");
    if (saved && saved !== "default") document.documentElement.setAttribute("data-mode", saved);
  } catch { /* localStorage unavailable */ }
}

/**
 * Phase 30 — Lumi motion CSS (CSS-only, no JS animation libraries).
 *
 * Breath cycle locked to 7100ms (matches v5.8.60 voice + v5.8.62
 * motion governance). Reduced-motion is honored at the @media level —
 * any class that would animate falls back to `animation: none`.
 *
 * This file is opt-in; importing it from `client/src/lumi-registry/index.ts`
 * means hosts that import any registry symbol pick up the keyframes.
 */

.lumi-official {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
  position: relative;
}

/* Phase 30 fix — opt-in interactivity for clickable Lumi instances. */
.lumi-official.lumi-interactive {
  pointer-events: auto;
  cursor: pointer;
}

.lumi-official img {
  display: block;
  width: 100%;
  height: auto;
  user-select: none;
  -webkit-user-drag: none;
  will-change: transform;
}

.lumi-motion-soft img {
  animation: lumi-soft-breathe 7.1s ease-in-out infinite;
  transform-origin: center bottom;
}

.lumi-motion-reduced img {
  animation: lumi-soft-breathe 10s ease-in-out infinite;
  transform-origin: center bottom;
}

.lumi-motion-none img {
  animation: none;
}

@keyframes lumi-soft-breathe {
  0% {
    transform: translateY(0px) scale(1);
  }
  39% {
    transform: translateY(-3px) scale(1.012);
  }
  45% {
    transform: translateY(-3px) scale(1.012);
  }
  96% {
    transform: translateY(0px) scale(1);
  }
  100% {
    transform: translateY(0px) scale(1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .lumi-motion-soft img,
  .lumi-motion-reduced img,
  .lumi-motion-none img {
    animation: none !important;
    transform: none !important;
  }
}

.hero-lumi {
  width: min(42vw, 340px);
  margin-inline: auto;
  filter: drop-shadow(0 18px 30px rgba(126, 144, 110, 0.16));
}

