@font-face {
  font-family: 'OpenDyslexic';
  src: url('https://cdn.jsdelivr.net/npm/open-dyslexic@1.0.3/woff/OpenDyslexic-Bold.woff') format('woff');
  font-weight: bold;
  font-style: normal;
  font-display: swap;
}

body.dyslexia-font,
body.dyslexia-font * {
  font-family: 'OpenDyslexic', Arial, sans-serif !important;
  letter-spacing: 0.05em;
  word-spacing: 0.1em;
  line-height: 1.8;
}

body.dyslexia-font h1,
body.dyslexia-font h2,
body.dyslexia-font h3,
body.dyslexia-font h4,
body.dyslexia-font h5,
body.dyslexia-font h6 {
  font-family: 'OpenDyslexic', Arial, sans-serif !important;
}

body.focus-indicators *:focus-visible {
  outline: 3px solid var(--glp-sage, #8FBF9F) !important;
  outline-offset: 2px !important;
}

body.focus-indicators button:focus-visible,
body.focus-indicators a:focus-visible,
body.focus-indicators input:focus-visible,
body.focus-indicators select:focus-visible,
body.focus-indicators textarea:focus-visible {
  outline: 3px solid var(--glp-sage, #8FBF9F) !important;
  outline-offset: 2px !important;
  box-shadow: 0 0 0 6px rgba(143, 191, 159, 0.3) !important;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: var(--glp-sage, #8FBF9F);
  color: white;
  padding: 8px 16px;
  z-index: 9999;
  text-decoration: none;
  font-weight: 600;
  border-radius: 0 0 8px 0;
}

.skip-link:focus {
  top: 0;
}

[role="button"],
button,
a {
  cursor: pointer;
}

[aria-disabled="true"],
[disabled] {
  cursor: not-allowed;
  opacity: 0.6;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@media (prefers-contrast: high) {
  :root {
    --glp-paper: #ffffff;
    --glp-ink: #000000;
  }

  * {
    border-color: currentColor !important;
  }
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--glp-sage, #8FBF9F);
  cursor: pointer;
  border: 2px solid white;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--glp-sage, #8FBF9F);
  cursor: pointer;
  border: 2px solid white;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
}

input[type="range"]:focus-visible::-webkit-slider-thumb {
  outline: 3px solid var(--glp-sage, #8FBF9F);
  outline-offset: 2px;
}

.touch-target {
  min-width: 44px;
  min-height: 44px;
}

@media (pointer: coarse) {
  button,
  a,
  input,
  select,
  textarea {
    min-height: 44px;
  }
}

/* client/src/styles/brand-tokens.css */
/* MyMentalHealthBuddy by The Genuine Love Project — Design Tokens */
/* SINGLE SOURCE OF TRUTH for all brand colors and semantic tokens */
/* Color Psychology: Empathic Intelligence — calming, empowering, mesmerizing, safe, loving */

:root{
  /* Safe area insets for mobile devices */
  --glp-safe-top: env(safe-area-inset-top, 0px);
  --glp-safe-bottom: env(safe-area-inset-bottom, 0px);
  --glp-safe-left: env(safe-area-inset-left, 0px);
  --glp-safe-right: env(safe-area-inset-right, 0px);
  /* ------------------------------------------------------------
    Core palette — Transcendent Intelligence Color System
    Each color is precision-tuned for maximum psychological depth,
    sensory magnetism, and emotional resonance. The palette weaves
    safety, wisdom, warmth, and quiet power into a mesmerizing
    visual language that draws the visitor inward and holds them
    in a state of calm, empowered awareness.

    Color Psychology Map (Evolved — Enterprise Elite II):
    • Luminous Sage (#1ec890) — Magnetic vitality, alive growth, sensory calm that draws you inward
    • Abyssal Wisdom (#062a2a) — Hypnotic depth, infinite grounding, mystery that feels like safety
    • Sacred Pearl (#fcf6ea) — Golden sanctuary warmth, luminous embrace, the feeling of coming home
    • Wisdom Ink (#142626) — Quiet genius, deep knowing, the intelligence behind stillness
    • Liquid Amber (#be8622) — Molten confidence, warm inner power, radiance that inspires trust
    • Heart Rose (#d08672) — Tender compassion, unconditional loving kindness, warmth without limit
    • Consciousness Violet (#6c58b8) — Expanded perception, awakened intuition, deeper seeing
  ------------------------------------------------------------ */
  --glp-sage: #1ec890;          /* Luminous Sage — magnetic vitality, alive growth */
  --glp-blush: #d08672;         /* Heart Rose — tender compassion, unconditional warmth */
  --glp-rose: #d08672;          /* Alias for blush */
  --glp-sage-deep: #062a2a;     /* Abyssal Wisdom — hypnotic depth, infinite grounding */
  --glp-paper: #fcf6ea;         /* Sacred Pearl — golden sanctuary warmth, coming home */
  --glp-ink: #142626;           /* Wisdom Ink — quiet genius, intelligent stillness */
  --glp-gold: #E8913A;          /* Heart Amber — warm radiant gold, canonical palette */
  --glp-gold-dark: #C9701F;     /* Deep Heart Amber — grounded warm wisdom */
  --glp-violet: #6c58b8;        /* Consciousness Violet — expanded perception, awakened seeing */
  --glp-violet-dark: #5c4aa0;   /* Deep Violet — profound intuition */

  /* Opacity variants for UI components */
  --glp-sage-10: rgba(30, 200, 144, 0.1);
  --glp-sage-15: rgba(30, 200, 144, 0.15);
  --glp-sage-20: rgba(30, 200, 144, 0.2);
  --glp-sage-30: rgba(30, 200, 144, 0.3);
  --glp-sage-40: rgba(30, 200, 144, 0.4);
  --glp-rose-10: rgba(208, 134, 114, 0.1);
  --glp-rose-15: rgba(208, 134, 114, 0.15);
  --glp-rose-20: rgba(208, 134, 114, 0.2);
  --glp-rose-30: rgba(208, 134, 114, 0.3);
  --glp-gold-10: rgba(232, 145, 58, 0.1);
  --glp-gold-15: rgba(232, 145, 58, 0.15);
  --glp-gold-20: rgba(232, 145, 58, 0.2);
  --glp-gold-30: rgba(232, 145, 58, 0.3);
  --glp-gold-60: rgba(232, 145, 58, 0.6);
  --glp-violet-10: rgba(108, 88, 184, 0.1);
  --glp-violet-20: rgba(108, 88, 184, 0.2);
  --glp-violet-30: rgba(108, 88, 184, 0.3);
  --glp-sage-deep-12: rgba(6, 42, 42, 0.12);
  --glp-sage-deep-20: rgba(6, 42, 42, 0.2);
  --glp-sage-deep-30: rgba(6, 42, 42, 0.3);
  --glp-sage-deep-40: rgba(6, 42, 42, 0.4);
  --glp-paper-70: rgba(252, 246, 234, 0.7);
  --glp-paper-95: rgba(252, 246, 234, 0.95);
  --glp-paper-98: rgba(252, 246, 234, 0.98);
  --glp-overlay-50: rgba(0, 0, 0, 0.5);
  --glp-white-40: rgba(255, 255, 255, 0.4);
  --glp-white-80: rgba(255, 255, 255, 0.8);
  --glp-white: #ffffff;

  /* Logo gradient and shadow */
  --glp-logo-gradient: linear-gradient(135deg, var(--glp-sage-20), var(--glp-rose-15));
  --glp-logo-shadow: 0 2px 8px var(--glp-sage-15);
  --glp-gold-gradient: linear-gradient(135deg, var(--glp-gold), var(--glp-gold-dark));
  --glp-gold-shadow: 0 4px 16px var(--glp-gold-30);

  /* ----------------------------------------------------------------
     Aurora system — sage→gold→violet→rose triad used by halos,
     button sheen, premium card rings, and ambient glows. Composed
     so any surface can opt-in with a single var().
     ---------------------------------------------------------------- */
  --glp-aurora-1: rgba(30, 200, 144, 0.55);   /* Luminous Sage */
  --glp-aurora-2: rgba(190, 134, 34, 0.50);   /* Liquid Amber */
  --glp-aurora-3: rgba(108, 88, 184, 0.45);   /* Consciousness Violet */
  --glp-aurora-4: rgba(208, 134, 114, 0.45);  /* Heart Rose */
  --glp-aurora-conic: conic-gradient(
    from 0deg,
    transparent 0%,
    var(--glp-aurora-1) 18%,
    var(--glp-aurora-2) 42%,
    var(--glp-aurora-3) 66%,
    var(--glp-aurora-4) 86%,
    transparent 100%
  );
  --glp-aurora-linear: linear-gradient(
    115deg,
    var(--glp-aurora-1) 0%,
    var(--glp-aurora-2) 38%,
    var(--glp-aurora-3) 72%,
    var(--glp-aurora-4) 100%
  );
  --glp-aurora-glow: 0 0 32px rgba(30, 200, 144, 0.18),
                     0 0 64px rgba(108, 88, 184, 0.12);

  /* Extended teal palette — Abyssal Wisdom spectrum */
  --glp-teal-50: #dff1ee;
  --glp-teal-100: #aedcd6;
  --glp-teal-200: #74beb6;
  --glp-teal-300: #3e9c94;
  --glp-teal-400: #1c6e6c;
  --glp-teal-500: #0e4e4e;
  --glp-teal-600: #0b4040;
  --glp-teal-700: #062a2a;
  --glp-teal-800: #041e1e;
  --glp-teal-900: #021414;

  /* Extended gold palette — Heart Amber spectrum (canonical warm gold) */
  --glp-gold-50: #fdf2e8;
  --glp-gold-100: #fbe0c5;
  --glp-gold-200: #f6c388;
  --glp-gold-300: #f0a55a;
  --glp-gold-400: #E8913A;
  --glp-gold-500: #C9701F;
  --glp-gold-600: #a55a14;
  --glp-gold-700: #82480f;
  --glp-gold-800: #5e340a;
  --glp-gold-900: #3a2106;

  /* Extended sage palette — Luminous Sage spectrum */
  --glp-sage-50: #e0f9f0;
  --glp-sage-100: #b2f0d6;
  --glp-sage-200: #7ee5ba;
  --glp-sage-300: #4cd8a0;
  --glp-sage-400: #1ec890;
  --glp-sage-500: #18a876;
  --glp-sage-600: #148a60;
  --glp-sage-700: #0e6c4a;
  --glp-sage-800: #094e34;
  --glp-sage-900: #04301e;

  /* Extended blush palette — Heart Rose spectrum */
  --glp-blush-50: #f8ede8;
  --glp-blush-100: #efd4ca;
  --glp-blush-200: #e2b2a4;
  --glp-blush-300: #d08672;
  --glp-blush-400: #c07060;
  --glp-blush-500: #ae584c;
  --glp-blush-600: #984840;
  --glp-blush-700: #7e3832;
  --glp-blush-800: #642c26;
  --glp-blush-900: #4a1e1a;

  /* Shorthand aliases for utilities (teal/gold/sage/blush) */
  --teal-50: var(--glp-teal-50);
  --teal-100: var(--glp-teal-100);
  --teal-200: var(--glp-teal-200);
  --teal-300: var(--glp-teal-300);
  --teal-400: var(--glp-teal-400);
  --teal-500: var(--glp-teal-500);
  --teal-600: var(--glp-teal-600);
  --teal-700: var(--glp-teal-700);
  --teal-800: var(--glp-teal-800);
  --teal-900: var(--glp-teal-900);

  --gold-50: var(--glp-gold-50);
  --gold-100: var(--glp-gold-100);
  --gold-200: var(--glp-gold-200);
  --gold-300: var(--glp-gold-300);
  --gold-400: var(--glp-gold-400);
  --gold-500: var(--glp-gold-500);
  --gold-600: var(--glp-gold-600);
  --gold-700: var(--glp-gold-700);
  --gold-800: var(--glp-gold-800);
  --gold-900: var(--glp-gold-900);

  --sage-50: var(--glp-sage-50);
  --sage-100: var(--glp-sage-100);
  --sage-200: var(--glp-sage-200);
  --sage-300: var(--glp-sage-300);
  --sage-400: var(--glp-sage-400);
  --sage-500: var(--glp-sage-500);
  --sage-600: var(--glp-sage-600);
  --sage-700: var(--glp-sage-700);
  --sage-800: var(--glp-sage-800);
  --sage-900: var(--glp-sage-900);

  --blush-50: var(--glp-blush-50);
  --blush-100: var(--glp-blush-100);
  --blush-200: var(--glp-blush-200);
  --blush-300: var(--glp-blush-300);
  --blush-400: var(--glp-blush-400);
  --blush-500: var(--glp-blush-500);
  --blush-600: var(--glp-blush-600);
  --blush-700: var(--glp-blush-700);
  --blush-800: var(--glp-blush-800);
  --blush-900: var(--glp-blush-900);

  /* RGB helpers (for rgba(var(--x-rgb), a)) — synced to Enterprise Elite II palette */
  --glp-sage-rgb: 30, 200, 144;       /* #1ec890 */
  --glp-sage-deep-rgb: 6, 42, 42;     /* #062a2a */
  --glp-blush-rgb: 208, 134, 114;     /* #d08672 */
  --glp-paper-rgb: 252, 246, 234;     /* #fcf6ea */
  --glp-ink-rgb: 20, 38, 38;          /* #142626 */
  --glp-gold-rgb: 232, 145, 58;       /* #E8913A — Heart Amber */
  --glp-violet-rgb: 108, 88, 184;     /* #6c58b8 */

  /* ------------------------------------------------------------
    Semantic tokens (use these everywhere in new code)
  ------------------------------------------------------------ */
  --glp-bg: var(--glp-paper);
  --glp-surface: #FFFFFF;
  --glp-surface-2: #F5F2EE;

  --glp-text: var(--glp-ink);
  --glp-text-muted: rgba(var(--glp-ink-rgb), 0.72);

  --glp-primary: var(--glp-sage-deep);
  --glp-primary-foreground: var(--glp-paper);

  --glp-accent: var(--glp-gold);
  --glp-accent-foreground: #1A1A1A;

  --glp-border: rgba(var(--glp-ink-rgb), 0.10);
  --glp-ring: var(--glp-gold);

  /* Shorthand semantic aliases */
  --bg: var(--glp-paper);
  --text-1: var(--glp-ink);
  --text-2: rgba(var(--glp-ink-rgb), 0.72);
  --surface-1: #FFFFFF;
  --surface-2: rgba(var(--glp-paper-rgb), 0.70);
  --primary: var(--glp-sage-deep);
  --primary-contrast: var(--glp-paper);
  --accent: var(--glp-gold);
  --ring: var(--glp-gold);
  --border: rgba(var(--glp-ink-rgb), 0.12);

  /* Radius tokens */
  --glp-radius-1: 12px;
  --glp-radius-2: 16px;
  --glp-radius-sm: 12px;
  --glp-radius-md: 16px;

  /* Shadow tokens — deeper, more dimensional */
  --glp-shadow-1: 0 6px 24px rgba(22, 61, 61, 0.06);
  --glp-shadow-2: 0 10px 36px rgba(22, 61, 61, 0.08);

  /* Motion tokens */
  --glp-motion-fast: 140ms;
  --glp-motion-med: 220ms;
  --glp-ease: cubic-bezier(.2,.8,.2,1);

  /* ------------------------------------------------------------
    Functional colors (for UI states, charts, and visualizations)
  ------------------------------------------------------------ */
  --glp-success: #10b981;
  --glp-success-light: #34d399;
  --glp-success-dark: #059669;
  --glp-success-rgb: 16, 185, 129;

  --glp-warning: #f59e0b;
  --glp-warning-light: #fbbf24;
  --glp-warning-dark: #d97706;
  --glp-warning-rgb: 245, 158, 11;

  --glp-error: #ef4444;
  --glp-error-light: #f87171;
  --glp-error-dark: #dc2626;
  --glp-error-rgb: 239, 68, 68;

  --glp-info: #3b82f6;
  --glp-info-light: #60a5fa;
  --glp-info-dark: #2563eb;
  --glp-info-rgb: 59, 130, 246;

  --glp-cyan: #06b6d4;
  --glp-cyan-light: #22d3ee;
  --glp-cyan-rgb: 6, 182, 212;

  --glp-purple: #8b5cf6;
  --glp-purple-light: #a78bfa;
  --glp-purple-dark: #7c3aed;
  --glp-purple-rgb: 139, 92, 246;

  --glp-indigo: #6366f1;
  --glp-indigo-light: #818cf8;
  --glp-indigo-rgb: 99, 102, 241;

  --glp-status-rose: #f43f5e;
  --glp-status-rose-light: #fb7185;
  --glp-status-rose-dark: #e11d48;
  --glp-status-rose-rgb: 244, 63, 94;
  --glp-rose-light: var(--glp-status-rose-light);
  --glp-rose-dark: var(--glp-status-rose-dark);
  --glp-rose-rgb: 244, 63, 94;

  --glp-orange: #f97316;
  --glp-orange-light: #fb923c;
  --glp-orange-rgb: 249, 115, 22;

  --glp-lime: #84cc16;
  --glp-lime-rgb: 132, 204, 22;

  --glp-teal-light: #14b8a6;
  --glp-teal-rgb: 20, 184, 166;

  --glp-pink: #ec4899;
  --glp-pink-light: #f472b6;
  --glp-pink-rgb: 236, 72, 153;

  /* Gray scale for neutral elements */
  --glp-gray-50: #f9fafb;
  --glp-gray-100: #f3f4f6;
  --glp-gray-200: #e5e7eb;
  --glp-gray-300: #d1d5db;
  --glp-gray-400: #9ca3af;
  --glp-gray-500: #6b7280;
  --glp-gray-600: #4b5563;
  --glp-gray-700: #374151;
  --glp-gray-800: #1f2937;
  --glp-gray-900: #111827;

  /* ------------------------------------------------------------
    Premium Typography System
  ------------------------------------------------------------ */
  --glp-font-display: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --glp-font-heading: 'Inter', 'Geist Sans', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --glp-font-body: 'Inter', 'Geist Sans', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --glp-font-mono: 'JetBrains Mono', 'Fira Code', monospace;

  /* Type Scale (fluid, clamp-based for responsive) */
  --glp-text-xs: clamp(0.6875rem, 0.65rem + 0.15vw, 0.75rem);
  --glp-text-sm: clamp(0.8125rem, 0.78rem + 0.15vw, 0.875rem);
  --glp-text-base: clamp(0.9375rem, 0.9rem + 0.18vw, 1rem);
  --glp-text-lg: clamp(1.0625rem, 1rem + 0.25vw, 1.125rem);
  --glp-text-xl: clamp(1.1875rem, 1.1rem + 0.4vw, 1.25rem);
  --glp-text-2xl: clamp(1.375rem, 1.2rem + 0.6vw, 1.5rem);
  --glp-text-3xl: clamp(1.625rem, 1.4rem + 0.9vw, 1.875rem);
  --glp-text-4xl: clamp(2rem, 1.7rem + 1.2vw, 2.25rem);
  --glp-text-5xl: clamp(2.5rem, 2rem + 2vw, 3rem);
  --glp-text-6xl: clamp(3rem, 2.4rem + 2.5vw, 3.75rem);

  /* Font weights */
  --glp-weight-light: 300;
  --glp-weight-normal: 400;
  --glp-weight-medium: 500;
  --glp-weight-semibold: 600;
  --glp-weight-bold: 700;
  --glp-weight-extrabold: 800;

  /* Letter spacing */
  --glp-tracking-tighter: -0.05em;
  --glp-tracking-tight: -0.025em;
  --glp-tracking-normal: 0;
  --glp-tracking-wide: 0.025em;
  --glp-tracking-wider: 0.05em;
  --glp-tracking-widest: 0.1em;

  /* Line heights */
  --glp-leading-none: 1;
  --glp-leading-tight: 1.2;
  --glp-leading-snug: 1.35;
  --glp-leading-normal: 1.5;
  --glp-leading-relaxed: 1.65;
  --glp-leading-loose: 2;

  /* ------------------------------------------------------------
    Enhanced Semantic Text Colors
  ------------------------------------------------------------ */
  --glp-text-primary: var(--glp-ink);
  --glp-text-secondary: rgba(var(--glp-ink-rgb), 0.72);
  --glp-text-tertiary: rgba(var(--glp-ink-rgb), 0.52);
  --glp-text-disabled: rgba(var(--glp-ink-rgb), 0.36);
  --glp-text-inverse: var(--glp-paper);
  --glp-text-brand: var(--glp-sage-deep);
  --glp-text-accent: var(--glp-gold);

  /* ------------------------------------------------------------
    Enhanced Shadow System — teal-tinted for brand cohesion
  ------------------------------------------------------------ */
  --glp-shadow-xs: 0 1px 3px rgba(22, 61, 61, 0.04);
  --glp-shadow-sm: 0 2px 6px rgba(22, 61, 61, 0.05);
  --glp-shadow-md: 0 4px 14px rgba(22, 61, 61, 0.07);
  --glp-shadow-lg: 0 8px 28px rgba(22, 61, 61, 0.09);
  --glp-shadow-xl: 0 16px 48px rgba(22, 61, 61, 0.11);
  --glp-shadow-2xl: 0 24px 64px rgba(22, 61, 61, 0.14);
  --glp-shadow-inner: inset 0 2px 4px rgba(22, 61, 61, 0.06);
  --glp-shadow-glow-sage: 0 0 28px rgba(var(--glp-sage-rgb), 0.35);
  --glp-shadow-glow-gold: 0 0 28px rgba(var(--glp-gold-rgb), 0.40);
  --glp-shadow-glow-teal: 0 0 28px rgba(var(--glp-sage-deep-rgb), 0.30);

  /* ------------------------------------------------------------
    Premium Gradient Presets — layered, dimensional, mesmerizing
  ------------------------------------------------------------ */
  --glp-gradient-hero: 
    radial-gradient(ellipse 80% 50% at 50% -20%, rgba(var(--glp-sage-rgb), 0.20), transparent),
    radial-gradient(ellipse 60% 40% at 80% 50%, rgba(var(--glp-blush-rgb), 0.12), transparent),
    radial-gradient(ellipse 50% 30% at 20% 80%, rgba(var(--glp-gold-rgb), 0.08), transparent),
    linear-gradient(180deg, var(--glp-bg), var(--glp-surface));

  --glp-gradient-card: linear-gradient(135deg, rgba(255,255,255,0.92), rgba(255,255,255,0.72));
  --glp-gradient-glass: linear-gradient(135deg, rgba(255,255,255,0.28), rgba(255,255,255,0.06));
  --glp-gradient-shimmer: linear-gradient(90deg, transparent, rgba(255,255,255,0.45), transparent);
  --glp-gradient-sage: linear-gradient(135deg, var(--glp-sage), var(--glp-primary));
  --glp-gradient-gold: linear-gradient(135deg, var(--glp-gold), var(--glp-warning-dark));
  --glp-gradient-premium: linear-gradient(135deg, var(--glp-primary), var(--glp-sage), var(--glp-gold));

  /* ------------------------------------------------------------
    Animation Timing Functions
  ------------------------------------------------------------ */
  --glp-ease-in: cubic-bezier(0.4, 0, 1, 1);
  --glp-ease-out: cubic-bezier(0, 0, 0.2, 1);
  --glp-ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --glp-ease-bounce: cubic-bezier(0.68, -0.55, 0.265, 1.55);
  --glp-ease-elastic: cubic-bezier(0.175, 0.885, 0.32, 1.275);
  --glp-motion-slow: 400ms;

  /* ------------------------------------------------------------
    Z-Index Scale
  ------------------------------------------------------------ */
  --glp-z-base: 0;
  --glp-z-dropdown: 100;
  --glp-z-sticky: 200;
  --glp-z-modal: 300;
  --glp-z-popover: 400;
  --glp-z-tooltip: 500;
  --glp-z-toast: 600;
}

/* ------------------------------------------------------------
  MODE 1: Low-Stim (reduced saturation + minimal decoration)
  Apply by setting: <html data-mode="low-stim">
------------------------------------------------------------ */
html[data-mode="low-stim"]{
  --glp-gold: #D9B43A;
  --glp-gold-rgb: 217, 180, 58;

  --glp-surface-2: #F4F2EE;
  --glp-border: rgba(var(--glp-ink-rgb), 0.08);
  --glp-shadow-1: none;
  --glp-shadow-2: none;

  --glp-primary: var(--glp-sage-deep);
  --glp-accent: var(--glp-gold);
  --glp-ring: var(--glp-gold);

  --accent: var(--glp-gold);
  --ring: var(--glp-gold);
  --border: rgba(28, 43, 43, 0.08);
  --surface-2: rgba(245, 243, 240, 0.70);
}

/* ------------------------------------------------------------
  MODE 2: Reading (max legibility, no gradients, neutral surfaces)
  Apply by setting: <html data-mode="reading">
------------------------------------------------------------ */
html[data-mode="reading"]{
  --glp-bg: #FFFFFF;
  --glp-paper: #FFFFFF;
  --glp-paper-rgb: 255, 255, 255;

  --glp-surface: #FFFFFF;
  --glp-surface-2: #FAFAFA;

  --glp-text: #2A2A2A;
  --glp-ink: #2A2A2A;
  --glp-ink-rgb: 42, 42, 42;
  --glp-text-muted: rgba(var(--glp-ink-rgb), 0.68);

  --glp-border: rgba(var(--glp-ink-rgb), 0.14);
  --glp-shadow-1: 0 2px 8px rgba(0,0,0,0.04);
  --glp-shadow-2: 0 4px 16px rgba(0,0,0,0.06);

  --glp-ring: var(--glp-gold);

  --bg: #FFFFFF;
  --text-1: #2A2A2A;
  --text-2: rgba(42, 42, 42, 0.68);
  --surface-1: #FFFFFF;
  --surface-2: rgba(250, 250, 250, 0.85);
  --primary-contrast: #FFFFFF;
  --ring: var(--glp-gold);
  --border: rgba(42, 42, 42, 0.14);
}

/* Brand Component Styles - The Genuine Love Project */
/* Token definitions are in brand-tokens.css - this file contains component styles only */

/* Global "healing luxury" background */
body {
  background: linear-gradient(180deg, var(--glp-bg), var(--glp-surface));
  color: var(--glp-text);
}

/* Navigation Links - Landing variant */
.nav-link-landing {
  color: var(--glp-primary);
  transition: color var(--glp-motion-fast) var(--glp-ease);
  padding: 0.25rem 0.5rem;
}

.nav-link-landing:hover {
  color: var(--glp-sage);
}

.nav-link-landing[aria-current="page"] {
  color: var(--glp-sage);
  font-weight: 600;
}

/* Glass Card - consistent component */
.glass-card {
  background: rgba(255, 255, 255, 0.8);
  backdrop-filter: blur(12px);
  border: 1px solid var(--glp-border);
  box-shadow: var(--glp-shadow-1);
  border-radius: var(--glp-radius-2);
}

.dark .glass-card {
  background: rgba(45, 55, 72, 0.8);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

/* Icon Container - unified sizing */
.icon-container {
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--glp-radius-1);
  background: linear-gradient(135deg, var(--glp-sage), var(--glp-primary));
  color: var(--glp-primary-foreground);
}

.icon-container-sm {
  width: 1.5rem;
  height: 1.5rem;
}

.icon-container-md {
  width: 2rem;
  height: 2rem;
}

.icon-container-lg {
  width: 2.5rem;
  height: 2.5rem;
}

.icon-container-xl {
  width: 3rem;
  height: 3rem;
}

/* Icon soft variants */
.icon-soft-sage {
  background: rgba(143, 191, 159, 0.15);
  color: var(--glp-sage);
}

.icon-soft-teal {
  background: rgba(var(--glp-sage-deep-rgb), 0.12);
  color: var(--glp-primary);
}

.icon-soft-gold {
  background: rgba(var(--glp-gold-rgb), 0.12);
  color: var(--glp-gold);
}

.icon-soft-blush {
  background: rgba(var(--glp-blush-rgb), 0.2);
  color: var(--glp-rose-dark);
}

/* Gradient icon containers */
.icon-gradient-sage {
  background: linear-gradient(135deg, var(--glp-sage), var(--glp-primary));
  color: white;
}

.icon-gradient-teal {
  background: linear-gradient(135deg, var(--glp-primary), var(--glp-sage-deep));
  color: var(--glp-primary-foreground);
}

.icon-gradient-gold {
  background: linear-gradient(135deg, var(--glp-gold), var(--glp-warning-dark));
  color: var(--glp-gray-900);
}

/* Enhanced CTA Buttons - WCAG AA 44px min-height */
.btn-premium {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 44px;
  padding: 0.75rem 1.5rem;
  background: linear-gradient(135deg, var(--glp-primary), var(--glp-sage));
  color: var(--glp-primary-foreground);
  font-weight: 600;
  border-radius: var(--glp-radius-1);
  transition: all var(--glp-motion-fast) var(--glp-ease);
  box-shadow: 0 2px 8px rgba(var(--glp-sage-deep-rgb), 0.3);
}

.btn-premium:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(var(--glp-sage-deep-rgb), 0.4);
}

/* v5.6 polish — press state + palette focus ring + reduced-motion guard */
.btn-premium:active {
  transform: translateY(1px);
  box-shadow: 0 1px 6px rgba(var(--glp-sage-deep-rgb), 0.28);
  transition-duration: 90ms;
}

.btn-premium:focus-visible {
  outline: 3px solid var(--glp-gold, #D4AF37);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .btn-premium { transition: none !important; }
  .btn-premium:hover, .btn-premium:active { transform: none !important; }
}

.btn-premium.btn-lg {
  padding: 0.875rem 1.75rem;
  font-size: 1.0625rem;
}

.btn-premium.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

.btn-secondary-premium {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  min-height: 44px;
  padding: 0.75rem 1.5rem;
  background: transparent;
  color: var(--glp-primary);
  font-weight: 600;
  border: 1.5px solid var(--glp-primary);
  border-radius: var(--glp-radius-1);
  transition: all var(--glp-motion-fast) var(--glp-ease);
}

.btn-secondary-premium:hover {
  background: rgba(var(--glp-sage-deep-rgb), 0.08);
  transform: translateY(-1px);
  box-shadow: 0 4px 14px rgba(var(--glp-sage-deep-rgb), 0.18);
}

/* v5.6 polish — press state + palette focus ring + reduced-motion guard */
.btn-secondary-premium:active {
  transform: translateY(1px);
  background: rgba(var(--glp-sage-deep-rgb), 0.14);
  box-shadow: 0 1px 4px rgba(var(--glp-sage-deep-rgb), 0.14);
  transition-duration: 90ms;
}

.btn-secondary-premium:focus-visible {
  outline: 3px solid var(--glp-primary);
  outline-offset: 3px;
}

@media (prefers-reduced-motion: reduce) {
  .btn-secondary-premium { transition: none !important; }
  .btn-secondary-premium:hover, .btn-secondary-premium:active { transform: none !important; }
}

/* =====================================================================
   v5.6 follow-up — Header & Footer CTA polish (Option 2 extension)
   Scope: TglpNavbar (Get Started / Dashboard / Sign In) + Footer nav links.
   Composes additively with existing Tailwind utility classes — only adds
   transform + box-shadow + outline transitions; never overrides color,
   padding, or radius (those stay owned by the JSX).
   prefers-reduced-motion blanket at the bottom kills every transform.
   ===================================================================== */

/* Primary header CTA — the gold pill ("Get Started" / "Start" / "Dashboard"). */
.btn-header-cta {
  /* Locked AA-safe text on the amber gold gradient (passes 4.75:1 on the
     darkest stop #C9701F, 6.97:1 on the light stop). Uses a literal value so
     it never drifts with the per-theme --glp-sage-deep override (which resolves
     to a mid-tone teal on the homepage and washes out to 3:1). */
  color: #0A1F1B !important;
  transition:
    transform 240ms cubic-bezier(0.22, 0.9, 0.32, 1),
    box-shadow 240ms cubic-bezier(0.22, 0.9, 0.32, 1),
    opacity 200ms ease;
  will-change: transform, box-shadow;
}

/* Real media-query label swap for header CTAs. The Tailwind responsive
   variants (hidden sm:inline / sm:hidden) emit no CSS in this build, so the
   desktop button was stuck on the short mobile label. */
.cta-label-full { display: none; }
.cta-label-short { display: inline; }
@media (min-width: 640px) {
  .cta-label-full { display: inline; }
  .cta-label-short { display: none; }
}

.btn-header-cta:hover {
  transform: translateY(-1px);
  /* !important required to override the inline `style={{ boxShadow: var(--glp-gold-shadow) }}`
     on TglpNavbar's gold pills (inline style normally beats stylesheet specificity). */
  box-shadow:
    0 8px 22px rgba(212, 175, 55, 0.32),
    0 0 0 4px rgba(212, 175, 55, 0.10) !important;
}

.btn-header-cta:active {
  transform: translateY(1px);
  box-shadow:
    0 2px 8px rgba(212, 175, 55, 0.22),
    0 0 0 2px rgba(212, 175, 55, 0.08) !important;
  transition-duration: 90ms;
}

.btn-header-cta:focus-visible {
  /* Warm CTA → canonical MMHB gold focus ring (token --glp-gold currently
     resolves to #be8622; use literal #D4AF37 to honor the v5.6 palette spec). */
  outline: 3px solid #D4AF37;
  outline-offset: 3px;
}

/* ---------------------------------------------------------------------------
   CTA RECLAMATION — restore the canonical amber-gold navbar pill.
   The generated-page button helpers in lumi-*.css use over-broad attribute
   selectors ([class*="cta"], [class*="primary"]) with !important to repaint
   ANY element whose class contains those substrings. "btn-header-cta" matches
   [class*="cta"], so the navbar CTA's inline gold gradient + dark text were
   clobbered into a sage fill with white text and an oversized sage box-shadow
   (the "square box behind the rounded pill"). Element-qualified selectors
   (a.btn-header-cta = specificity 0,1,1) outrank the attribute selectors
   (0,1,0), so these win regardless of stylesheet import order. */
a.btn-header-cta,
a.btn-header-cta:link,
a.btn-header-cta:visited,
a.btn-header-cta:hover,
a.btn-header-cta:focus {
  background: var(--glp-gold-gradient) !important;
  background-image: var(--glp-gold-gradient) !important;
  color: #0A1F1B !important;
  border: none !important;
  -webkit-text-fill-color: #0A1F1B !important;
  box-shadow: var(--glp-gold-shadow) !important;
}
a.btn-header-cta:hover {
  box-shadow:
    0 8px 22px rgba(212, 175, 55, 0.32),
    0 0 0 4px rgba(212, 175, 55, 0.10) !important;
}
/* Keep the label + sparkle icon dark on the gold gradient (children would
   otherwise inherit the global helpers' white !important color). */
a.btn-header-cta > *,
a.btn-header-cta svg {
  color: #0A1F1B !important;
  -webkit-text-fill-color: #0A1F1B !important;
}

/* Real-CSS layout for the header CTA. Tailwind's numeric spacing utilities
   (px-*, py-*, gap-*) do NOT emit in this build (v3/v4 mismatch), so the
   inline `px-5 py-3 gap-2.5` produced a zero-padding pill whose label
   collided with the rounded-full curved ends and spilled out. Define the
   geometry explicitly so the pill always has proper padding, icon gap, and a
   clean stadium shape regardless of which utilities compile. */
.btn-header-cta {
  display: inline-flex !important;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.7rem 1.5rem !important;
  border-radius: 9999px !important;
  line-height: 1;
  white-space: nowrap;
}

/* Secondary header CTA — the text-link "Sign In" / "Log Out" sibling. */
.btn-header-secondary {
  transition:
    background-color 200ms cubic-bezier(0.22, 0.9, 0.32, 1),
    transform 200ms cubic-bezier(0.22, 0.9, 0.32, 1);
  will-change: transform, background-color;
}

.btn-header-secondary:hover {
  transform: translateY(-1px);
}

.btn-header-secondary:active {
  transform: translateY(1px);
  transition-duration: 90ms;
}

.btn-header-secondary:focus-visible {
  /* Calm CTA → canonical MMHB sage-deep focus ring (token --glp-sage-deep
     currently resolves to #062a2a; use literal #2F5443 per v5.6 palette spec). */
  outline: 3px solid #2F5443;
  outline-offset: 3px;
  border-radius: 0.5rem;
}

/* Footer nav links — no hover lift (dense rows feel jumpy), but consistent
   palette-tinted focus ring + subtle underline thickening on focus/hover. */
.footer-nav-link {
  position: relative;
  transition:
    color 200ms ease,
    background-color 200ms ease;
}

.footer-nav-link:focus-visible {
  /* Canonical MMHB sage-deep — see note on .btn-header-secondary above. */
  outline: 3px solid #2F5443;
  outline-offset: 3px;
  border-radius: 4px;
}

@media (prefers-reduced-motion: reduce) {
  .btn-header-cta,
  .btn-header-secondary,
  .footer-nav-link {
    transition: none !important;
    will-change: auto !important;
  }
  .btn-header-cta:hover,
  .btn-header-cta:active,
  .btn-header-secondary:hover,
  .btn-header-secondary:active {
    transform: none !important;
  }
}

.btn-secondary-premium.btn-sm {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  color: var(--glp-text-muted);
  font-weight: 500;
  border-radius: var(--glp-radius-1);
  transition: color var(--glp-motion-fast) var(--glp-ease);
}

.btn-ghost:hover {
  color: var(--glp-primary);
}

/* Typography utilities */
.text-teal-dark {
  color: var(--glp-primary);
}

.text-sage {
  color: var(--glp-sage);
}

.text-gold {
  color: var(--glp-gold);
}

.text-gradient-brand {
  background: linear-gradient(135deg, var(--glp-primary), var(--glp-sage));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Content layout utilities */
.content-wrapper {
  width: 100%;
  max-width: 80rem;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1rem;
  padding-right: 1rem;
}

@media (min-width: 640px) {
  .content-wrapper {
    padding-left: 1.5rem;
    padding-right: 1.5rem;
  }
}

@media (min-width: 1024px) {
  .content-wrapper {
    padding-left: 2rem;
    padding-right: 2rem;
  }
}

.content-max-lg {
  max-width: 64rem;
}

.content-max-md {
  max-width: 48rem;
}

.content-center {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

/* Hero gradient backgrounds */
.hero-gradient {
  background: 
    radial-gradient(ellipse 80% 50% at 50% -20%, rgba(var(--glp-sage-rgb), 0.15), transparent),
    radial-gradient(ellipse 60% 40% at 80% 50%, rgba(var(--glp-blush-rgb), 0.08), transparent),
    linear-gradient(180deg, var(--glp-bg), var(--glp-surface));
}

/* Decorative orbs */
.decorative-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.5;
  pointer-events: none;
}

.decorative-orb-sage {
  background: radial-gradient(circle, rgba(var(--glp-sage-rgb), 0.4), transparent 70%);
}

.decorative-orb-blush {
  background: radial-gradient(circle, rgba(var(--glp-blush-rgb), 0.35), transparent 70%);
}

.decorative-orb-gold {
  background: radial-gradient(circle, rgba(var(--glp-gold-rgb), 0.25), transparent 70%);
}

/* Badge styles */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.375rem 0.75rem;
  font-size: 0.8125rem;
  font-weight: 500;
  border-radius: 9999px;
  background: var(--glp-surface);
  border: 1px solid var(--glp-border);
  color: var(--glp-text-muted);
}

.badge-sage {
  background: rgba(var(--glp-sage-rgb), 0.1);
  border-color: rgba(var(--glp-sage-rgb), 0.2);
  color: var(--glp-primary);
}

.badge-gold {
  background: rgba(var(--glp-gold-rgb), 0.1);
  border-color: rgba(var(--glp-gold-rgb), 0.2);
  color: var(--glp-warning-dark);
}

.badge-lg {
  padding: 0.5rem 1rem;
  font-size: 0.875rem;
}

/* Soft background utilities */
.bg-sage-soft {
  background: rgba(var(--glp-sage-rgb), 0.08);
}

.bg-gold-soft {
  background: rgba(var(--glp-gold-rgb), 0.08);
}

.bg-blush-soft {
  background: rgba(var(--glp-blush-rgb), 0.12);
}

/* Card styles */
.card-elevated {
  background: var(--glp-surface);
  border-radius: var(--glp-radius-2);
  box-shadow: var(--glp-shadow-1);
  border: 1px solid var(--glp-border);
}

.card-bordered {
  background: var(--glp-surface);
  border-radius: var(--glp-radius-2);
  border: 1px solid var(--glp-border);
  padding: 1.25rem;
}

/* Animation utilities */
.animate-fade-in-up {
  animation: fadeInUp 0.6s var(--glp-ease) both;
}

.animate-bounce-subtle {
  animation: bounceSubtle 2s ease-in-out infinite;
}

.animate-glow-pulse {
  animation: glowPulse 3s ease-in-out infinite;
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes bounceSubtle {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

@keyframes glowPulse {
  0%, 100% { box-shadow: 0 2px 8px rgba(var(--glp-sage-deep-rgb), 0.3); }
  50% { box-shadow: 0 4px 20px rgba(var(--glp-sage-deep-rgb), 0.5); }
}

/* Skeleton loading */
.skeleton {
  background: linear-gradient(90deg, var(--glp-surface-2) 25%, var(--glp-surface) 50%, var(--glp-surface-2) 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.5s ease-in-out infinite;
}

.skeleton-card {
  height: 12rem;
  border-radius: var(--glp-radius-2);
  background: linear-gradient(90deg, var(--glp-surface-2) 25%, var(--glp-surface) 50%, var(--glp-surface-2) 75%);
  background-size: 200% 100%;
  animation: skeleton-shimmer 1.5s ease-in-out infinite;
}

@keyframes skeleton-shimmer {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* Gradient mesh background */
.bg-gradient-mesh {
  background: 
    radial-gradient(ellipse at 20% 30%, rgba(var(--glp-sage-rgb), 0.1) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 70%, rgba(var(--glp-blush-rgb), 0.08) 0%, transparent 50%),
    var(--glp-bg);
}

/* Premium Shimmer Effect */
.shimmer-gold {
  position: relative;
  overflow: hidden;
}

.shimmer-gold::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    115deg,
    transparent 20%,
    rgba(var(--glp-gold-rgb), 0.15) 40%,
    rgba(var(--glp-gold-rgb), 0.25) 50%,
    rgba(var(--glp-gold-rgb), 0.15) 60%,
    transparent 80%
  );
  background-size: 200% 100%;
  animation: shimmer-sweep 3s ease-in-out infinite;
}

@keyframes shimmer-sweep {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

/* Elite Gradient Text */
.text-gradient-elite {
  background: linear-gradient(135deg, var(--glp-primary) 0%, var(--glp-sage) 50%, var(--glp-gold) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Premium Ring Glow */
.ring-glow-gold {
  box-shadow: 0 0 0 2px var(--glp-gold), 0 0 12px rgba(var(--glp-gold-rgb), 0.4);
}

.ring-glow-teal {
  box-shadow: 0 0 0 2px var(--glp-primary), 0 0 12px rgba(var(--glp-sage-deep-rgb), 0.4);
}

/* Premium Input Focus */
.input-focus-gold:focus {
  border-color: var(--glp-gold);
  box-shadow: 0 0 0 3px rgba(var(--glp-gold-rgb), 0.15);
}

/* Elevated Card Hover */
.card-hover-lift {
  transition: transform var(--glp-motion-med) var(--glp-ease), box-shadow var(--glp-motion-med) var(--glp-ease);
}

.card-hover-lift:hover {
  transform: translateY(-4px);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.1);
}

/* Premium Divider */
.divider-gradient {
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--glp-border), transparent);
  border: none;
}

/* Premium Badge Variants */
.badge-elite {
  background: linear-gradient(135deg, var(--glp-gold), var(--glp-warning-dark));
  color: var(--glp-gray-900);
  font-weight: 600;
  padding: 0.375rem 0.875rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  box-shadow: 0 2px 8px rgba(var(--glp-gold-rgb), 0.3);
}

.badge-premium {
  background: linear-gradient(135deg, var(--glp-primary), var(--glp-sage));
  color: white;
  font-weight: 600;
  padding: 0.375rem 0.875rem;
  border-radius: 9999px;
  font-size: 0.75rem;
}

/* Floating Animation */
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

.animate-float {
  animation: float 4s ease-in-out infinite;
}

/* Pulse Ring Animation */
@keyframes pulse-ring {
  0% { box-shadow: 0 0 0 0 rgba(var(--glp-gold-rgb), 0.4); }
  70% { box-shadow: 0 0 0 12px rgba(var(--glp-gold-rgb), 0); }
  100% { box-shadow: 0 0 0 0 rgba(var(--glp-gold-rgb), 0); }
}

.animate-pulse-ring {
  animation: pulse-ring 2s ease-out infinite;
}

/* ============================================================
   ACCESSIBILITY: SKIP TO CONTENT LINK
============================================================ */

.skip-to-content {
  position: absolute;
  top: -100%;
  left: 50%;
  transform: translateX(-50%);
  z-index: 9999;
  padding: 0.75rem 1.5rem;
  background: var(--glp-primary);
  color: var(--glp-primary-foreground);
  font-weight: 600;
  border-radius: var(--glp-radius-1);
  text-decoration: none;
  transition: top var(--glp-motion-fast) var(--glp-ease);
}

.skip-to-content:focus {
  top: 1rem;
  outline: 2px solid var(--glp-ring);
  outline-offset: 2px;
}

/* ============================================================
   REDUCED MOTION SUPPORT
   Respects prefers-reduced-motion AND Low-Stim mode
============================================================ */

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .nav-link-landing,
  .btn-premium,
  .btn-secondary-premium,
  .icon-container {
    transition: none;
  }

  .btn-premium:hover {
    transform: none;
  }

  .animate-fade-in-up,
  .animate-fade-in-scale,
  .animate-breathe,
  .animate-pulse-gold,
  .animate-bounce-subtle,
  .animate-glow-pulse,
  .decorative-orb,
  .skeleton,
  .skeleton-card,
  .card-shimmer::after {
    animation: none !important;
    opacity: 1 !important;
  }

  .hover-lift:hover,
  .hover-scale:hover,
  .card-premium:hover,
  .card-hover-lift:hover {
    transform: none;
  }
}

/* Low-Stim mode: reduce visual noise */
html[data-mode="low-stim"] .decorative-orb,
html[data-mode="low-stim"] .animate-breathe,
html[data-mode="low-stim"] .animate-pulse-gold,
html[data-mode="low-stim"] .animate-glow-pulse,
html[data-mode="low-stim"] .card-shimmer::after,
html[data-mode="low-stim"] .icon-glow-sage,
html[data-mode="low-stim"] .icon-glow-gold,
html[data-mode="low-stim"] .icon-glow-teal {
  animation: none !important;
  opacity: 0.6;
}

html[data-mode="low-stim"] .hover-lift:hover,
html[data-mode="low-stim"] .hover-scale:hover,
html[data-mode="low-stim"] .card-premium:hover {
  transform: none;
}

/* ============================================================
   PREMIUM VISUAL ENHANCEMENTS
   Elite-level visual refinements for 360° platform excellence
============================================================ */

/* Premium Card Variants */
.card-premium {
  background: var(--glp-gradient-card);
