  font-size: 1.5rem;
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.01em;
}

/* Gradient text fallback for accessibility */
.canva-landing [style*="WebkitTextFillColor"] {
  color: var(--glp-sage-deep);
}

@supports (-webkit-background-clip: text) or (background-clip: text) {
  .canva-landing [style*="WebkitTextFillColor"] {
    color: transparent;
  }
}

/* Inter for body text */
.canva-landing p,
.canva-landing span,
.canva-landing button,
.canva-landing a {
  font-family: 'Inter', system-ui, sans-serif;
}

/* Navigation styles */
.canva-landing .nav-link {
  position: relative;
  transition: all 0.3s ease;
}

.canva-landing .nav-link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 2px;
  background: var(--warm-gold);
  transition: width 0.3s ease;
}

.canva-landing .nav-link:hover::after {
  width: 100%;
}

/* Gradient backgrounds */
.canva-landing .gradient-sage-ivory {
  background: linear-gradient(135deg, var(--sage-green) 0%, var(--soft-ivory) 100%);
}

.canva-landing .gradient-teal-sage {
  background: linear-gradient(135deg, var(--deep-teal) 0%, var(--sage-green) 100%);
}

.canva-landing .gradient-blush-ivory {
  background: linear-gradient(135deg, var(--blush-pink) 0%, var(--soft-ivory) 100%);
}

/* Glass morphism effects - uses glp token opacity variants */
/* Canonical definition at end of file, after consciousness-expanding layer */

/* Floating animation for decorative icons */
@keyframes float {
  0%, 100% {
    transform: translateY(0) rotate(0deg);
  }
  33% {
    transform: translateY(-12px) rotate(3deg);
  }
  66% {
    transform: translateY(-6px) rotate(-2deg);
  }
}

.animate-float {
  animation: float 6s ease-in-out infinite;
}

/* Slow drift animation for background orbs */
@keyframes drift {
  0%, 100% {
    transform: translate(0, 0) scale(1);
  }
  25% {
    transform: translate(20px, -15px) scale(1.05);
  }
  50% {
    transform: translate(-10px, 10px) scale(0.98);
  }
  75% {
    transform: translate(-20px, -10px) scale(1.02);
  }
}

.animate-drift {
  animation: drift 20s ease-in-out infinite;
}

/* Sparkle animation */
@keyframes sparkle {
  0%, 100% {
    opacity: 0.3;
    transform: scale(0.8);
  }
  50% {
    opacity: 1;
    transform: scale(1.2);
  }
}

.animate-sparkle {
  animation: sparkle 2s ease-in-out infinite;
}

/* Rotate gently */
@keyframes gentle-rotate {
  0% {
    transform: rotate(0deg);
  }
  100% {
    transform: rotate(360deg);
  }
}

.animate-rotate-slow {
  animation: gentle-rotate 30s linear infinite;
}

/* Shimmer effect */
@keyframes shimmer {
  0% {
    background-position: -200% center;
  }
  100% {
    background-position: 200% center;
  }
}

.animate-shimmer {
  background: linear-gradient(
    90deg,
    transparent 0%,
    var(--glp-white-40) 50%,
    transparent 100%
  );
  background-size: 200% 100%;
  animation: shimmer 3s ease-in-out infinite;
}

/* Decorative orb styles */
.decorative-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(60px);
  pointer-events: none;
}

.decorative-orb.sage {
  background: radial-gradient(circle, var(--glp-sage-40) 0%, transparent 70%);
