/* Primary: warm gold gradient pill with embossed inner highlight + outer glow.
   Reads as a confident "press me" surface against the dark green section.
   Gradient stops are all kept in the LIGHT gold range (luminance >= 0.43) so that
   the var(--glp-sage-deep) #062a2a foreground exceeds AA 4.5:1 across the entire
   button surface — the prior --glp-gold-dark #9e7018 stop sat at ~3.5:1 and was
   trimmed out. */
.canva-landing .cta-btn-primary {
  background: linear-gradient(135deg, #fbe39a 0%, #f4d271 50%, #e7bf5d 100%);
  color: var(--glp-sage-deep);
  border: 1px solid rgba(255, 255, 255, 0.45);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.6),
    inset 0 -2px 6px rgba(110, 70, 10, 0.16),
    0 10px 28px rgba(190, 134, 34, 0.45),
    0 0 0 1px rgba(255, 255, 255, 0.08),
    0 0 32px rgba(var(--glp-gold-rgb), 0.35);
  position: relative;
  overflow: hidden;
}
.canva-landing .cta-btn-primary::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: linear-gradient(120deg, transparent 30%, rgba(255, 255, 255, 0.28) 50%, transparent 70%);
  transform: translateX(-100%);
  transition: transform 0.7s ease;
  pointer-events: none;
}
.canva-landing .cta-btn-primary:hover::before {
  transform: translateX(100%);
}
.canva-landing .cta-btn-primary:hover {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.6),
    inset 0 -2px 6px rgba(110, 70, 10, 0.22),
    0 16px 42px rgba(190, 134, 34, 0.55),
    0 0 0 1px rgba(255, 255, 255, 0.12),
    0 0 48px rgba(var(--glp-gold-rgb), 0.5);
}

/* Secondary: dark-tinted frosted-glass pill with crisp gold border.
   Uses a dark sage tint (not white-12%) so that white text exceeds AA across
   the entire underlying section gradient — the prior white-on-white-glass
   could drop below AA where the section reaches the bright var(--glp-sage)
   #1ec890 half. */
.canva-landing .cta-btn-secondary {
  background: rgba(6, 42, 42, 0.55);
  color: #ffffff;
  border: 1.5px solid rgba(var(--glp-gold-rgb), 0.7);
  backdrop-filter: blur(14px) saturate(160%);
  -webkit-backdrop-filter: blur(14px) saturate(160%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.18),
    0 8px 22px rgba(0, 0, 0, 0.22),
    0 0 22px rgba(var(--glp-gold-rgb), 0.18);
}
.canva-landing .cta-btn-secondary:hover {
  background: rgba(6, 42, 42, 0.7);
  border-color: rgba(var(--glp-gold-rgb), 0.95);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.24),
    0 12px 30px rgba(0, 0, 0, 0.28),
    0 0 36px rgba(var(--glp-gold-rgb), 0.32);
}

@media (prefers-reduced-motion: reduce) {
