   `.canva-landing-hero-polish` so the rest of the landing page is unaffected.
   Reduced-motion safety: every animation is disabled and particles hide.
   ========================================================================== */

/* 1. Warm cream overlay — sits above the existing sage→teal hero gradient
   and adds a centered cream wash so the background reads warmer/cozier
   without losing the sage→teal brand tones at the edges. */
.canva-landing-hero-polish .hero-cream-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 50% 40%, rgba(249, 247, 244, 0.55) 0%, rgba(240, 237, 230, 0.25) 35%, transparent 65%),
    linear-gradient(180deg, rgba(249, 247, 244, 0.35) 0%, transparent 30%, rgba(232, 228, 222, 0.2) 100%);
  z-index: 0;
}

/* 2. Soft sage particles — 8 small floating dots, very subtle (0.02-0.05
   opacity), 40-70s upward drift cycles. Positioned absolutely inside the
   hero section. Distinct from the existing decorative-orb layer. */
.canva-landing-hero-polish .hero-particle-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 1;
}
.canva-landing-hero-polish .hero-particle {
  position: absolute;
  border-radius: 50%;
  background: radial-gradient(circle, #A8C9A0 0%, transparent 70%);
  animation: hero-particle-drift linear infinite;
}
/* Per-particle --p-opacity drives the keyframe's mid-cycle opacity stop so
   each particle keeps its intended subtle variance (0.03 / 0.04 / 0.05)
   instead of all normalizing to the keyframe fallback. */
.canva-landing-hero-polish .hero-particle:nth-child(1) { left:  8%; bottom: -40px; width: 14px; height: 14px; --p-opacity: 0.05; animation-duration: 58s; animation-delay:   0s; }
.canva-landing-hero-polish .hero-particle:nth-child(2) { left: 22%; bottom: -60px; width: 10px; height: 10px; --p-opacity: 0.04; animation-duration: 64s; animation-delay:  -8s; }
.canva-landing-hero-polish .hero-particle:nth-child(3) { left: 38%; bottom: -50px; width: 18px; height: 18px; --p-opacity: 0.03; animation-duration: 70s; animation-delay: -22s; }
.canva-landing-hero-polish .hero-particle:nth-child(4) { left: 52%; bottom: -30px; width:  8px; height:  8px; --p-opacity: 0.05; animation-duration: 46s; animation-delay: -14s; }
.canva-landing-hero-polish .hero-particle:nth-child(5) { left: 66%; bottom: -55px; width: 12px; height: 12px; --p-opacity: 0.04; animation-duration: 52s; animation-delay:  -4s; }
.canva-landing-hero-polish .hero-particle:nth-child(6) { left: 78%; bottom: -45px; width: 16px; height: 16px; --p-opacity: 0.03; animation-duration: 62s; animation-delay: -30s; }
.canva-landing-hero-polish .hero-particle:nth-child(7) { left: 88%; bottom: -35px; width:  9px; height:  9px; --p-opacity: 0.05; animation-duration: 48s; animation-delay: -18s; }
.canva-landing-hero-polish .hero-particle:nth-child(8) { left: 14%; bottom: -25px; width: 11px; height: 11px; --p-opacity: 0.04; animation-duration: 56s; animation-delay: -36s; }

@keyframes hero-particle-drift {
  0%   { transform: translateY(0)        translateX(0);    opacity: 0; }
  10%  {                                                   opacity: var(--p-opacity, 0.04); }
  50%  { transform: translateY(-40vh)    translateX(20px); }
  90%  {                                                   opacity: var(--p-opacity, 0.04); }
  100% { transform: translateY(-90vh)    translateX(-15px); opacity: 0; }
}

/* 3. Lumi entrance — scale 0.8 → 1 over 800ms with gentle fade. Wrapped
   around the existing Lumi container so the inner LumiV6 component (with
   its own V8/V9 animations) remains untouched. Uses `forwards` so the
   final state is locked even after the keyframe completes. */
.canva-landing-hero-polish .hero-lumi-wrapper {
  display: inline-block;
  animation: hero-lumi-entrance 0.8s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
  transform-origin: center center;
  transition: transform 0.3s ease, filter 0.3s ease;
}
.canva-landing-hero-polish .hero-lumi-wrapper:hover {
  transform: scale(1.03);
  filter: drop-shadow(0 8px 24px rgba(168, 201, 160, 0.35));
}
@keyframes hero-lumi-entrance {
  0%   { opacity: 0; transform: scale(0.8); }
  60%  { opacity: 1; transform: scale(1.04); }
  100% { opacity: 1; transform: scale(1); }
}

/* 4. Reduced motion — kill every hero-polish animation + hide particles
   entirely. The Lumi wrapper still appears (final scale 1, opacity 1)
   because `animation: none` resolves it to its un-animated state, which
   is the wrapper's natural rendering (scale 1 by default). */
@media (prefers-reduced-motion: reduce) {
  .canva-landing-hero-polish .hero-particle-layer,
  .canva-landing-hero-polish .hero-particle {
    display: none !important;
  }
  .canva-landing-hero-polish .hero-lumi-wrapper {
    animation: none !important;
    transition: none !important;
    opacity: 1;
    transform: none;
  }
  .canva-landing-hero-polish .hero-lumi-wrapper:hover {
    transform: none;
    filter: none;
  }
}

/* 5. Z-index normalization (architect-fixed, v4.5.1) — make the hero
   stacking deterministic to match the universal "decorative 0/1/2 →
   content z-10" contract used on every other polish surface. The
   pre-existing `.hero-depth-layer` and the two `.decorative-orb`s in
   the hero markup previously relied on source order; this block
   assigns explicit tiers within the hero polish scope only (no leak
   to other landing sections). */
.canva-landing-hero-polish .hero-depth-layer { z-index: 0; }
.canva-landing-hero-polish .decorative-orb   { z-index: 2; }

/* ============================================================
   Emotional Journey Section (v5.0) — V13 port
   Scoped under .emotional-journey-polish; vertical timeline
   with gradient connecting line, per-phase entrance reveal,
   hover lift on cards. Uses CSS keyframes (no framer-motion
   dependency) to match the rest of the codebase.
   ============================================================ */
.emotional-journey-polish .emotional-journey-list {
  position: relative;
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}
/* Line is centered behind the dot column. Card has padding-left 0.5rem
   and the dot is 3rem wide (sm: 3.5rem), so dot-center sits at
   0.5rem + 1.5rem = 2rem (sm: 0.5rem + 1.75rem = 2.25rem). The 2px
   line is offset by 1px (translateX) to center on that axis. */
.emotional-journey-polish .emotional-journey-line {
  position: absolute;
  left: 2rem;
  top: 1rem;
  bottom: 1rem;
  width: 2px;
  margin-left: -1px;
  border-radius: 2px;
  pointer-events: none;
  z-index: 0;
}
@media (min-width: 640px) {
  .emotional-journey-polish .emotional-journey-line {
    left: 2.25rem;
  }
}
.emotional-journey-polish .emotional-journey-item {
  position: relative;
  z-index: 1;
  opacity: 0;
  transform: translateY(12px);
}
.emotional-journey-polish.revealed .emotional-journey-item {
  animation: emotional-journey-reveal 0.6s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  animation-delay: var(--journey-delay, 0ms);
}
@keyframes emotional-journey-reveal {
  to { opacity: 1; transform: translateY(0); }
}
.emotional-journey-polish .emotional-journey-card {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
  padding: 0.85rem 1rem 0.85rem 0.5rem;
  border-radius: 1rem;
  text-decoration: none;
  transition: background-color 0.3s ease, transform 0.3s ease, box-shadow 0.3s ease;
}
.emotional-journey-polish .emotional-journey-card:hover,
.emotional-journey-polish .emotional-journey-card:focus-visible {
  background: rgba(255, 255, 255, 0.6);
  transform: translateX(2px);
  box-shadow: 0 4px 18px rgba(168, 201, 160, 0.10);
  outline: none;
}
.emotional-journey-polish .emotional-journey-dot {
  flex-shrink: 0;
  width: 3rem;
  height: 3rem;
  border-radius: 9999px;
  border: 2px solid;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
@media (min-width: 640px) {
  .emotional-journey-polish .emotional-journey-dot {
    width: 3.5rem;
    height: 3.5rem;
  }
}
.emotional-journey-polish .emotional-journey-card:hover .emotional-journey-dot,
.emotional-journey-polish .emotional-journey-card:focus-visible .emotional-journey-dot {
  transform: scale(1.08);
  box-shadow: 0 0 0 6px rgba(255, 255, 255, 0.5);
}
.emotional-journey-polish .emotional-journey-text {
  display: flex;
  flex-direction: column;
  padding-top: 0.35rem;
  min-width: 0;
}
.emotional-journey-polish .emotional-journey-label {
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.3;
}
@media (min-width: 640px) {
  .emotional-journey-polish .emotional-journey-label {
    font-size: 1.125rem;
  }
}
.emotional-journey-polish .emotional-journey-description {
  font-size: 0.875rem;
  line-height: 1.5;
  margin-top: 0.15rem;
}
@media (prefers-reduced-motion: reduce) {
  .emotional-journey-polish .emotional-journey-item {
    opacity: 1 !important;
    transform: none !important;
    animation: none !important;
  }
  .emotional-journey-polish .emotional-journey-card,
  .emotional-journey-polish .emotional-journey-dot {
    transition: none !important;
  }
  .emotional-journey-polish .emotional-journey-card:hover,
  .emotional-journey-polish .emotional-journey-card:focus-visible {
    transform: none !important;
    box-shadow: none !important;
  }
  .emotional-journey-polish .emotional-journey-card:hover .emotional-journey-dot,
  .emotional-journey-polish .emotional-journey-card:focus-visible .emotional-journey-dot {
    transform: none !important;
    box-shadow: none !important;
  }
}

/* PHASE113HG_CANVA_LANDING_EMOTIONAL_JOURNEY_FOCUS_FIX
   Purpose: restore visible keyboard focus for emotional journey cards.
   Scope: additive accessibility patch only; no route, component, layout, or token rewrite.
   Defect source: earlier .emotional-journey-card:focus-visible used outline: none.
*/
.canva-landing .emotional-journey-polish .emotional-journey-card:focus-visible {
  outline: 3px solid var(--glp-sage-deep, #2F5D5D);
  outline-offset: 4px;
  box-shadow:
    0 0 0 6px rgba(var(--glp-sage-rgb), 0.18),
    0 12px 32px rgba(var(--glp-sage-deep-rgb), 0.12);
}

@media (prefers-reduced-motion: reduce) {
  .canva-landing .emotional-journey-polish .emotional-journey-card:focus-visible {
    transition: none !important;
    transform: none !important;
  }
}

/* ==========================================================================
   Celebration polish (additive) — sunshine radiance wash, ambient gold
   sparkle particles (separate from the falling confetti so the warmth
   sustains across all 3 phases), per-phase content entrance, and a
   badge-style entrance for the streak counter on phase 2. All scoped
   under `.celebration-polish` so nothing leaks. Every effect honors
   `prefers-reduced-motion: reduce`. The existing CelebrationFlow
   confetti, 3-phase auto-advance, localStorage streak math, and ARIA
   live region are completely untouched — this file only adds visual
   layers on top.
   ========================================================================== */

.celebration-polish {
  position: relative;
  isolation: isolate;
}

/* 1. Sunshine radiance wash — sits above the existing amber→rose→amber
   Tailwind gradient and adds warm radial glow per V10 §3.4. Two stacked
   pseudo-element layers cross-fade between "early" (warmer orange,
   phase 1-2) and "settled" (calmer gold, phase 3). Pointer-events
   disabled so click targets aren't blocked. Z-index 0 keeps it behind
   confetti (already z-index auto, no z) and content (relative z-10). */
.celebration-polish .celebration-wash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}
.celebration-polish .celebration-wash::before,
.celebration-polish .celebration-wash::after {
  content: "";
  position: absolute;
  inset: 0;
  transition: opacity 800ms ease-in-out;
}
.celebration-polish .celebration-wash::before {
  background:
    radial-gradient(ellipse at 50% 25%, rgba(255, 217, 61, 0.22) 0%, transparent 55%),
    radial-gradient(ellipse at 50% 80%, rgba(255, 184, 140, 0.15) 0%, transparent 60%);
  opacity: 1;
}
.celebration-polish .celebration-wash::after {
  background:
    radial-gradient(ellipse at 50% 30%, rgba(255, 217, 61, 0.12) 0%, transparent 55%),
    radial-gradient(ellipse at 50% 85%, rgba(168, 201, 160, 0.10) 0%, transparent 60%);
  opacity: 0;
}
.celebration-polish[data-phase="3"] .celebration-wash::before { opacity: 0; }
.celebration-polish[data-phase="3"] .celebration-wash::after  { opacity: 1; }

/* 2. Ambient gold sparkle particles — 6 subtle (0.10-0.18 opacity)
   sunshine dots that twinkle in place across all 3 phases. Distinct
   from the falling confetti so warmth sustains after confetti stops
   in phase 3. Per-particle --sp-opacity / --sp-delay vars. */
.celebration-polish .celebration-sparkle-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 1;
}
.celebration-polish .celebration-sparkle {
  position: absolute;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: radial-gradient(circle, #FFD93D 0%, transparent 70%);
  animation: celebration-sparkle-twinkle 3.6s ease-in-out infinite;
}
.celebration-polish .celebration-sparkle:nth-child(1) { top: 18%; left: 12%; --sp-opacity: 0.18; animation-delay:  0.0s; width: 8px;  height: 8px; }
.celebration-polish .celebration-sparkle:nth-child(2) { top: 28%; left: 84%; --sp-opacity: 0.14; animation-delay:  0.6s; width: 5px;  height: 5px; }
.celebration-polish .celebration-sparkle:nth-child(3) { top: 62%; left: 22%; --sp-opacity: 0.16; animation-delay:  1.2s; width: 7px;  height: 7px; }
.celebration-polish .celebration-sparkle:nth-child(4) { top: 70%; left: 78%; --sp-opacity: 0.12; animation-delay:  1.8s; width: 6px;  height: 6px; }
.celebration-polish .celebration-sparkle:nth-child(5) { top: 42%; left: 92%; --sp-opacity: 0.10; animation-delay:  2.4s; width: 4px;  height: 4px; }
.celebration-polish .celebration-sparkle:nth-child(6) { top: 50%; left:  6%; --sp-opacity: 0.15; animation-delay:  3.0s; width: 6px;  height: 6px; }

@keyframes celebration-sparkle-twinkle {
  0%, 100% { opacity: 0;                                  transform: scale(0.6); }
  50%      { opacity: var(--sp-opacity, 0.14);            transform: scale(1.0); }
}

/* 3. Per-phase content entrance — each phase's <section> content fades
   in + scales up briefly when the phase changes. Uses `key={phase}` on
   the <section> in the JSX to force remount and replay. */
.celebration-polish .celebration-phase-enter {
  animation: celebration-phase-entrance 600ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
@keyframes celebration-phase-entrance {
  0%   { opacity: 0; transform: translateY(12px) scale(0.96); }
  100% { opacity: 1; transform: translateY(0)    scale(1);    }
}

/* 4. Streak badge entrance — the phase-2 streak counter gets a stronger
   "burst in" entrance + a soft sustained gold ring pulse to draw the
   eye to the achievement. Triggered by an additive class added to the
   <h2> in phase 2 only. */
.celebration-polish .celebration-streak-badge {
  display: inline-block;
  position: relative;
  animation: celebration-streak-burst 800ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
.celebration-polish .celebration-streak-badge::before {
  content: "";
  position: absolute;
  inset: -8px -16px;
  border-radius: 9999px;
  background: radial-gradient(ellipse, rgba(255, 217, 61, 0.18) 0%, transparent 70%);
  z-index: -1;
  animation: celebration-streak-glow 2.4s ease-in-out infinite;
}
@keyframes celebration-streak-burst {
  0%   { opacity: 0; transform: scale(0.7); }
  60%  { opacity: 1; transform: scale(1.08); }
  100% { opacity: 1; transform: scale(1);    }
}
@keyframes celebration-streak-glow {
  0%, 100% { opacity: 0.7; transform: scale(1);    }
  50%      { opacity: 1.0; transform: scale(1.05); }
}

/* 5. Reduced-motion contract — kill every additive animation, hide
   sparkle particles entirely, pin static states. Existing component
   confetti is already gated by the JSX `!reducedMotion && phase < 3`
   check, so no double-coverage needed there. */
@media (prefers-reduced-motion: reduce) {
  .celebration-polish .celebration-sparkle-layer,
  .celebration-polish .celebration-sparkle {
    display: none !important;
  }
  .celebration-polish .celebration-phase-enter,
  .celebration-polish .celebration-streak-badge,
  .celebration-polish .celebration-streak-badge::before {
    animation: none !important;
    transform: none !important;
  }
  .celebration-polish .celebration-wash::before,
  .celebration-polish .celebration-wash::after {
    transition: none !important;
  }
}

/* ==========================================================================
   Check-in polish (additive) — soft purple wash over the existing emerald
   gradient, per-emotion card accent colors with hover glow, gentle particle
   layer, header entrance animation, heart pulse on emotion selection.
   All scoped under `.checkin-polish` so nothing leaks. Every effect honors
   `prefers-reduced-motion: reduce`. The existing CheckIn behavior, phase
   timing, localStorage logic, and accessibility wiring are completely
   untouched — this file only adds visual layers on top.
   ========================================================================== */

.checkin-polish {
  position: relative;
  isolation: isolate;
}

/* 1. Soft purple wash — sits above the existing emerald→white→emerald
   Tailwind gradient and warms the page with a gentle empathy-purple
   ambience per the V10 §3.3 spec. Pointer-events disabled so click
   targets aren't blocked. Z-index 0 keeps it behind all content.
   Two stacked layers (purple base always-on, sunshine celebration on
   complete) cross-fade via opacity transitions — gradient `background`
   shorthand transitions snap rather than animate cross-browser, so we
   use opacity on separate layers instead. */
.checkin-polish .checkin-wash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
}
.checkin-polish .checkin-wash::before,
.checkin-polish .checkin-wash::after {
  content: "";
  position: absolute;
  inset: 0;
  transition: opacity 800ms ease-in-out;
}
/* Soft purple base — visible during select / intensity / note. */
.checkin-polish .checkin-wash::before {
  background:
    radial-gradient(ellipse at 50% 30%, rgba(200, 182, 255, 0.18) 0%, transparent 60%),
    linear-gradient(180deg, rgba(200, 182, 255, 0.10) 0%, transparent 35%, rgba(255, 154, 139, 0.06) 100%);
  opacity: 1;
}
/* Sunshine celebration — fades in on complete, fades out otherwise. */
.checkin-polish .checkin-wash::after {
  background:
    radial-gradient(ellipse at 50% 30%, rgba(255, 217, 61, 0.18) 0%, transparent 60%),
    linear-gradient(180deg, rgba(255, 217, 61, 0.08) 0%, transparent 35%, rgba(255, 184, 140, 0.06) 100%);
  opacity: 0;
}
.checkin-polish[data-phase="complete"] .checkin-wash::before { opacity: 0; }
.checkin-polish[data-phase="complete"] .checkin-wash::after  { opacity: 1; }

/* 2. Floating soft-purple particles — 5 very subtle (0.04-0.08 opacity)
   empathy-purple dots drifting upward, hidden under reduced motion.
   Same per-particle --cp-opacity pattern that worked correctly on hero
   and breathing tool. */
.checkin-polish .checkin-particle-layer {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
  z-index: 1;
}
.checkin-polish .checkin-particle {
  position: absolute;
  border-radius: 50%;
  background: radial-gradient(circle, #C8B6FF 0%, transparent 70%);
  animation: checkin-particle-drift linear infinite;
}
.checkin-polish .checkin-particle:nth-child(1) { left: 10%; bottom: -30px; width: 13px; height: 13px; --cp-opacity: 0.06; animation-duration: 54s; animation-delay:   0s; }
.checkin-polish .checkin-particle:nth-child(2) { left: 28%; bottom: -50px; width:  9px; height:  9px; --cp-opacity: 0.05; animation-duration: 60s; animation-delay: -16s; }
.checkin-polish .checkin-particle:nth-child(3) { left: 56%; bottom: -25px; width: 15px; height: 15px; --cp-opacity: 0.04; animation-duration: 66s; animation-delay: -32s; }
.checkin-polish .checkin-particle:nth-child(4) { left: 74%; bottom: -40px; width: 10px; height: 10px; --cp-opacity: 0.07; animation-duration: 48s; animation-delay:  -8s; }
.checkin-polish .checkin-particle:nth-child(5) { left: 90%; bottom: -35px; width:  8px; height:  8px; --cp-opacity: 0.08; animation-duration: 42s; animation-delay: -22s; }

@keyframes checkin-particle-drift {
  0%   { transform: translateY(0)      translateX(0);    opacity: 0; }
  10%  {                                                 opacity: var(--cp-opacity, 0.05); }
  50%  { transform: translateY(-50vh)  translateX(18px); }
  90%  {                                                 opacity: var(--cp-opacity, 0.05); }
  100% { transform: translateY(-95vh)  translateX(-12px); opacity: 0; }
}

/* 3. Header greeting entrance — 700ms gentle fade + translate-up. Plays
   once on mount per phase. Honors reduced motion via the blanket below. */
.checkin-polish .checkin-greeting {
  animation: checkin-greeting-entrance 700ms cubic-bezier(0.4, 0, 0.2, 1) both;
}
@keyframes checkin-greeting-entrance {
  0%   { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

/* 4. Per-emotion card accent — each emotion card uses a CSS var for its
   accent color, applied as a hover/focus glow ring + soft tinted bg.
   The data-emotion-accent attribute on each button maps to the
   appropriate canonical brand hex. Selected state (data-selected="true")
   gets a stronger persistent glow. */
.checkin-polish .checkin-emotion-card {
  position: relative;
  transition: transform 200ms ease, box-shadow 300ms ease, background-color 300ms ease;
  --emotion-accent: 168, 201, 160; /* default sage */
}
.checkin-polish .checkin-emotion-card[data-emotion-accent="calm"]        { --emotion-accent: 116, 192, 252; }
.checkin-polish .checkin-emotion-card[data-emotion-accent="anxiety"]     { --emotion-accent: 200, 182, 255; }
.checkin-polish .checkin-emotion-card[data-emotion-accent="sadness"]     { --emotion-accent: 200, 182, 255; }
.checkin-polish .checkin-emotion-card[data-emotion-accent="tiredness"]   { --emotion-accent: 168, 213, 186; }
.checkin-polish .checkin-emotion-card[data-emotion-accent="frustration"] { --emotion-accent: 255, 184, 140; }
.checkin-polish .checkin-emotion-card[data-emotion-accent="gratitude"]   { --emotion-accent: 255, 154, 139; }

.checkin-polish .checkin-emotion-card:hover,
.checkin-polish .checkin-emotion-card:focus-visible {
  transform: translateY(-2px);
  background-color: rgba(var(--emotion-accent), 0.10);
  box-shadow: 0 4px 16px rgba(var(--emotion-accent), 0.30);
}
