/* ===== EMOTION BACKGROUND OVERLAYS ===== */

/* Joy - Sunbeam Animation */
.emotion-bg-joy {
  position: relative;
  overflow: hidden;
}

.emotion-bg-joy::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: radial-gradient(
    ellipse at center,
    rgba(255, 215, 0, 0.15) 0%,
    rgba(255, 183, 77, 0.1) 30%,
    transparent 70%
  );
  animation: sunbeam 8s ease-in-out infinite;
  pointer-events: none;
}

@keyframes sunbeam {
  0%, 100% {
    transform: rotate(0deg) scale(1);
    opacity: 0.6;
  }
  50% {
    transform: rotate(15deg) scale(1.1);
    opacity: 1;
  }
}

/* Sadness - Calming Mist Gradient */
.emotion-bg-sadness {
  position: relative;
  overflow: hidden;
}

.emotion-bg-sadness::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(107, 140, 174, 0.08) 0%,
    rgba(149, 165, 184, 0.12) 50%,
    rgba(107, 140, 174, 0.05) 100%
  );
  animation: calmingMist 12s ease-in-out infinite;
  pointer-events: none;
}

@keyframes calmingMist {
  0%, 100% {
    opacity: 0.5;
    filter: blur(0px);
  }
  50% {
    opacity: 0.8;
    filter: blur(2px);
  }
}

/* Calm - Floating Lotus Petals */
.emotion-bg-calm {
  position: relative;
  overflow: hidden;
}

.emotion-bg-calm::before,
.emotion-bg-calm::after {
  content: '🪷';
  position: absolute;
  font-size: 24px;
  opacity: 0.3;
  animation: floatingPetal 15s ease-in-out infinite;
  pointer-events: none;
}

.emotion-bg-calm::before {
  top: 20%;
  left: 10%;
  animation-delay: 0s;
}

.emotion-bg-calm::after {
  top: 60%;
  right: 15%;
  animation-delay: 5s;
}

@keyframes floatingPetal {
  0%, 100% {
    transform: translateY(0) rotate(0deg);
    opacity: 0.2;
  }
  25% {
    transform: translateY(-20px) rotate(10deg);
    opacity: 0.4;
  }
  50% {
    transform: translateY(-10px) rotate(-5deg);
    opacity: 0.3;
  }
  75% {
    transform: translateY(-25px) rotate(15deg);
    opacity: 0.35;
  }
}

/* Anxiety - Gentle Grounding Waves */
.emotion-bg-anxiety {
  position: relative;
  overflow: hidden;
}

.emotion-bg-anxiety::before {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    0deg,
    transparent,
    transparent 50px,
    rgba(143, 191, 159, 0.05) 50px,
    rgba(143, 191, 159, 0.05) 100px
  );
  animation: groundingWave 20s linear infinite;
  pointer-events: none;
}

@keyframes groundingWave {
  from {
    transform: translateY(0);
  }
  to {
    transform: translateY(100px);
  }
}

/* Gratitude - Golden Sparkles */
.emotion-bg-gratitude {
  position: relative;
  overflow: hidden;
}

.emotion-bg-gratitude::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: 
    radial-gradient(circle at 20% 30%, rgba(212, 175, 55, 0.3) 1px, transparent 1px),
    radial-gradient(circle at 80% 70%, rgba(255, 215, 0, 0.25) 1px, transparent 1px),
    radial-gradient(circle at 50% 50%, rgba(212, 175, 55, 0.2) 1px, transparent 1px);
  background-size: 100px 100px, 80px 80px, 120px 120px;
  animation: sparkleFloat 10s ease-in-out infinite;
  pointer-events: none;
}

@keyframes sparkleFloat {
  0%, 100% {
    opacity: 0.5;
    transform: translateY(0);
  }
  50% {
    opacity: 1;
    transform: translateY(-10px);
  }
}

/* Hope - Rising Dawn Gradient */
.emotion-bg-hope {
  position: relative;
  overflow: hidden;
}

.emotion-bg-hope::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 50%;
  background: linear-gradient(
    to top,
    rgba(255, 183, 77, 0.15) 0%,
    rgba(244, 199, 195, 0.1) 50%,
    transparent 100%
  );
  animation: risingDawn 15s ease-in-out infinite;
  pointer-events: none;
}

@keyframes risingDawn {
  0%, 100% {
    height: 30%;
    opacity: 0.5;
  }
  50% {
    height: 50%;
    opacity: 0.8;
  }
}

/* ===== MICROINTERACTION CLASSES ===== */

/* Button Hover - Soft Pulse */
.btn-sacred-pulse {
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.btn-sacred-pulse:hover {
