}

/* Journal Save - Heart Burst */
.save-heart-burst {
  position: relative;
}

.save-heart-burst.saving::after {
  content: '💜';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0);
  animation: heartBurst 0.6s ease-out forwards;
  pointer-events: none;
}

@keyframes heartBurst {
  0% {
    transform: translate(-50%, -50%) scale(0);
    opacity: 1;
  }
  50% {
    transform: translate(-50%, -50%) scale(1.5);
    opacity: 0.8;
  }
  100% {
    transform: translate(-50%, -50%) scale(2);
    opacity: 0;
  }
}

/* Sparkle Effect on Success */
.sparkle-success {
  position: relative;
}

.sparkle-success.active::before,
.sparkle-success.active::after {
  content: '✨';
  position: absolute;
  animation: sparkleAway 0.8s ease-out forwards;
  pointer-events: none;
}

.sparkle-success.active::before {
  top: -10px;
  left: 20%;
}

.sparkle-success.active::after {
  top: -15px;
  right: 25%;
  animation-delay: 0.1s;
}

@keyframes sparkleAway {
  0% {
    transform: translateY(0) scale(0);
    opacity: 1;
  }
  100% {
    transform: translateY(-30px) scale(1.2);
    opacity: 0;
  }
}

/* ===== MODAL ANIMATIONS ===== */
.modal-backdrop {
  animation: backdropFadeIn 0.3s ease-out;
}

@keyframes backdropFadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.modal-content {
  animation: modalScaleIn 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}

@keyframes modalScaleIn {
