/* ────────────────────────────────────────────────────────────────────────
   glp-pane.css — Reusable Sanctuary-Depth Pane Token
   --------------------------------------------------------------------
   Design-token primitive for any opt-in container that wants the
   shared "Genuine Love Project" sanctuary-depth chrome:
     • cream gradient bg
     • subtle inset highlight
     • soft elevation that lifts on hover
     • animated tri-color top accent bar (gold → sage → gold)
     • sage hover border + brighter accent

   Apply via className "glp-pane" on any element.  Modifiers:
     .glp-pane--accent  → permanent gold ring (for "highlighted" panes)
     .glp-pane--quiet   → no hover lift (for non-interactive surfaces)

   Honors prefers-reduced-motion automatically.
   Designed to compose with Tailwind utility classes.
   ──────────────────────────────────────────────────────────────────────── */

.glp-pane {
  position: relative;
  overflow: hidden;
  background: linear-gradient(180deg,
    rgba(255, 255, 255, 1) 0%,
    rgba(252, 246, 234, 0.30) 100%) !important;
  /* NOTE: border intentionally NOT marked !important so that inline
     style="border:..." or per-element classes can override. */
  border: 1px solid rgba(30, 200, 144, 0.20);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 2px 8px rgba(6, 42, 42, 0.04),
    0 14px 32px rgba(6, 42, 42, 0.05);
  transition:
    box-shadow 0.4s ease,
    border-color 0.4s ease,
    transform 0.4s cubic-bezier(0.23, 1, 0.32, 1);
}

/* Animated tri-color top accent bar */
.glp-pane::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg,
    transparent 0%,
    rgba(190, 134, 34, 0.50) 25%,
    rgba(30, 200, 144, 0.60) 50%,
    rgba(190, 134, 34, 0.50) 75%,
    transparent 100%);
  opacity: 0.55;
  transition: opacity 0.5s ease;
  pointer-events: none;
  z-index: 1;
}

.glp-pane:hover {
  transform: translateY(-1px);
  border-color: rgba(30, 200, 144, 0.30);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 4px 14px rgba(6, 42, 42, 0.06),
    0 22px 48px rgba(6, 42, 42, 0.08);
}

.glp-pane:hover::before {
  opacity: 0.95;
}

/* Modifier: permanent gold accent ring (e.g. "live now" / featured panes) */
.glp-pane.glp-pane--accent {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 0 0 1px rgba(190, 134, 34, 0.22),
    0 2px 8px rgba(6, 42, 42, 0.05),
    0 14px 32px rgba(6, 42, 42, 0.06);
}

/* Modifier: quiet — no hover lift, for non-interactive cards */
.glp-pane.glp-pane--quiet:hover {
  transform: none;
}

/* Modifier: bare — for surfaces that already have their own border + clipping
   needs (e.g. pricing tier cards with absolutely-positioned popular badges).
   Disables overflow clipping + the top accent bar so the host element controls
   its own visual chrome.  Keeps gradient bg + hover lift + shadow. */
.glp-pane.glp-pane--bare {
  overflow: visible;
}
.glp-pane.glp-pane--bare::before {
  display: none;
}

/* Dark mode — preserve depth, swap the cream wash for a subtle sage tint */
.dark .glp-pane {
  background: linear-gradient(180deg,
    rgba(31, 41, 55, 1) 0%,
    rgba(6, 42, 42, 0.55) 100%) !important;
  border-color: rgba(30, 200, 144, 0.22);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.04),
    0 2px 8px rgba(0, 0, 0, 0.2),
    0 14px 32px rgba(0, 0, 0, 0.25);
}

.dark .glp-pane:hover {
  border-color: rgba(30, 200, 144, 0.36);
}

/* Reduced-motion compliance */
@media (prefers-reduced-motion: reduce) {
  .glp-pane,
  .glp-pane:hover,
  .glp-pane::before {
    transition: none;
    transform: none;
  }
}

