.sacred-circle {
  border-radius: 50%;
  position: relative;
}

.sacred-circle::before {
  content: '';
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  border: 2px solid rgba(143, 191, 159, 0.2);
  animation: breathingAura 4s ease-in-out infinite;
}

.sacred-hexagon {
  clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
}

.sacred-flower {
  position: relative;
}

.sacred-flower::before,
.sacred-flower::after {
  content: '';
  position: absolute;
  border-radius: 50%;
  border: 1px solid rgba(143, 191, 159, 0.2);
}

.sacred-flower::before {
  inset: -20%;
  animation: sacredRotate 30s linear infinite;
}

.sacred-flower::after {
  inset: -10%;
  animation: sacredRotate 20s linear infinite reverse;
}

/* ===== FLUID WATERCOLOR BACKGROUNDS ===== */
.watercolor-bg {
  position: relative;
  overflow: hidden;
}

.watercolor-bg::before {
  content: '';
  position: absolute;
  inset: -50%;
  background: 
    radial-gradient(ellipse at 20% 30%, rgba(143, 191, 159, 0.15) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 70%, rgba(244, 199, 195, 0.12) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 50%, rgba(234, 195, 59, 0.08) 0%, transparent 60%);
  animation: watercolor 12s ease-in-out infinite;
  pointer-events: none;
}

/* ===== ORGANIC BLOB SHAPES ===== */
.organic-blob {
  border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%;
  animation: blobMorph 8s ease-in-out infinite;
}

@keyframes blobMorph {
  0%, 100% {
    border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%;
  }
  25% {
    border-radius: 30% 60% 70% 40% / 50% 60% 30% 60%;
  }
  50% {
    border-radius: 50% 60% 30% 60% / 30% 60% 70% 40%;
  }
  75% {
    border-radius: 60% 40% 60% 30% / 70% 30% 50% 60%;
  }
}

/* ===== REDUCED MOTION SUPPORT ===== */
@media (prefers-reduced-motion: reduce) {
  .animate-breathing,
  .animate-breathing-glow,
  .animate-pulsing-border,
  .animate-gentle-float,
  .animate-sacred-rotate,
  .animate-shimmer,
  .animate-ripple,
  .animate-heartbeat,
  .animate-watercolor,
  .organic-blob,
  .sacred-circle::before,
  .sacred-flower::before,
  .sacred-flower::after,
  .watercolor-bg::before {
    animation: none;
  }

  .animate-fade-in-up,
  .animate-fade-in-scale {
    animation-duration: 0.01ms;
  }
}

/* ──────────────────────────────────────────────────────────────────────
 * HX-OS vNEXT — Shared Visual Unification Tokens (Iter 2g Phases 2-5)
 * Created: 2026-05-15
 *
 * Engine pattern (architect-approved in Phase 1):
 *   Pages opt-in by adding `hxos-vnext` (or `hxos-vnext-crisis`) to their
 *   outermost JSX wrapper. The class redefines 14 `--glp-*` CSS variables
 *   only beneath that subtree. Global `brand-tokens.css` is NEVER touched,
 *   so non-opted-in pages remain on canonical palette.
 *
 * Coexist contract (per replit.md Universal Contracts):
 *   - Brand accents (gold #E8913A, violet #6c58b8, aurora) → preserved
 *     (these tokens are NOT redefined here).
 *   - Page chrome (paper, ink, sage, sage-deep, rose) → vNEXT palette.
 *   - Approved governance exception: local sage/rose values diverge from
 *     the locked 8-hex palette under explicit Iter 2g scope.
 *
 * Pages currently opted-in (Iter 2g):
 *   Phase 1 — CanvaLanding (via canva-landing.css scoped block; equiv. tokens)
 *   Phase 2 — CheckIn, BreathingExercisesPage
 *   Phase 3 — JournalPage, AIChatPage
 *   Phase 4 — HabitsHubPage, SavedLibrary
 *   Phase 5 — Settings, CrisisResources (rose-only via .hxos-vnext-crisis)
 * ────────────────────────────────────────────────────────────────────── */

.hxos-vnext {
  /* Surface */
  --glp-paper: #F6F1E8;
  --glp-paper-98: #F6F1E8;
  --glp-ink: rgb(22, 58, 54);

  /* Brand line — shifted to HX-OS vNEXT */
  --glp-sage: rgb(143, 191, 159);
  --glp-sage-deep: rgb(47, 93, 93);
  --glp-rose: #C4787A;
  --glp-blush: #C4787A;

  /* Alpha derivatives — recomputed from new sage rgb(143,191,159) */
  --glp-sage-10: rgba(143, 191, 159, 0.10);
  --glp-sage-15: rgba(143, 191, 159, 0.15);
  --glp-sage-20: rgba(143, 191, 159, 0.20);
  --glp-sage-30: rgba(143, 191, 159, 0.30);
  --glp-sage-40: rgba(143, 191, 159, 0.40);

  /* Alpha derivatives — recomputed from new sage-deep rgb(47,93,93) */
  --glp-sage-deep-12: rgba(47, 93, 93, 0.12);
  --glp-sage-deep-20: rgba(47, 93, 93, 0.20);
  --glp-sage-deep-30: rgba(47, 93, 93, 0.30);
  --glp-sage-deep-40: rgba(47, 93, 93, 0.40);

  /* Alpha derivatives — recomputed from new rose #C4787A → rgb(196,120,122) */
  --glp-rose-10: rgba(196, 120, 122, 0.10);
  --glp-rose-15: rgba(196, 120, 122, 0.15);
  --glp-rose-20: rgba(196, 120, 122, 0.20);
  --glp-rose-30: rgba(196, 120, 122, 0.30);

  /* v5.8.70 — utility tokens (warm-white surface tier, light-gray subtle fill,
     ink-derived border + shadow). Brand accents (--glp-violet, --glp-gold)
     intentionally NOT overridden here: canonical brand palette preserved per
     Universal Contracts. */
  --glp-warm-white: #FAFAF7;
  --glp-light-gray: #F0EDE6;
  --glp-border: rgba(22, 58, 54, 0.08);
  --glp-shadow: rgba(22, 58, 54, 0.06);

  /* Apply warm-cream surface tint to the wrapper itself so pages whose
     children don't read --glp-paper still receive the cream backdrop. */
  background-color: var(--glp-paper);
  color: var(--glp-ink);
  min-height: 100vh;
}

/* Phase 5 exception — CrisisResources keeps its own urgent surface; only
   re-tone --glp-rose so the dusty-rose accent unifies with the system.
   Do NOT redefine paper/ink/sage on the crisis page. */
.hxos-vnext-crisis {
  --glp-rose: #C4787A;
  --glp-blush: #C4787A;
  --glp-rose-10: rgba(196, 120, 122, 0.10);
  --glp-rose-15: rgba(196, 120, 122, 0.15);
  --glp-rose-20: rgba(196, 120, 122, 0.20);
  --glp-rose-30: rgba(196, 120, 122, 0.30);
}

/*
 * Lumi v2.0 — Accessibility utilities (D8)
 */

.lumi-skip-link {
  position: absolute;
  top: -100px;
  left: 0;
  background: var(--lumi-sage-700);
  color: #ffffff;
  padding: 0.625rem 1rem;
  border-radius: 0 0 var(--lumi-radius-sm) 0;
  font-weight: 600;
  text-decoration: none;
  z-index: 9999;
  transition: top var(--lumi-dur-quick) var(--lumi-ease);
}
.lumi-skip-link:focus {
  top: 0;
  outline: 3px solid var(--lumi-amber-400);
  outline-offset: 2px;
}

.lumi-focus-ring:focus-visible {
  outline: 3px solid var(--lumi-amber-500);
  outline-offset: 2px;
  border-radius: var(--lumi-radius-sm);
}

.lumi-sr-only {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Touch target minimum 44px on interactive elements opting in */
.lumi-touch-target {
  min-width: 44px;
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* ============================================
 * MMHB v2.0 — ADMIN COMPONENT SYSTEM
 * lumi-admin.css
 * ----------------------------------------------
 * Additive companion to lumi-buttons.css / lumi-links.css / lumi-layout.css
 * / lumi-mascot.css. Only ships classes that were NOT already present in the
 * existing Lumi stack so we never override a load-bearing rule. Anything
 * already styled (lumi-card, lumi-section, lumi-btn-primary/secondary/etc.,
 * lumi-link-text/inline/etc.) is intentionally absent here.
 *
 * Newly published surfaces:
 *   - .lumi-table + th/td/hover                                (data tables)
 *   - .lumi-status-{success|warning|error|info|neutral}        (state badges)
 *   - .admin-page-title / .admin-section-title / .admin-body
 *     / .admin-metric-value / .admin-metric-label / .admin-caption (admin typography)
 *   - .header-brand / .header-wordmark / .header-subhead       (header utility set)
 *   - .lumi-section-alt / .footer-grid / .hero-cta-group       (layout helpers)
 *   - .trust-badges + un-scoped .trust-badge                   (trust strip)
 *   - .hero-mascot                                             (full-width hero artwork)
 *   - .mascot-container                                        (compact 48px mascot wrapper)
 *   - .lumi-btn-sm / -lg / -icon / -loading / -dark             (size + state aliases)
 *   - .lumi-link-dark                                           (dark-surface link)
 *   - .lumi-error-boundary                                      (SafeBoundary fallback)
 * ============================================ */

/* ============================================
   TABLES
   ============================================ */
.lumi-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-family: var(--lumi-font-body);
  font-size: var(--lumi-text-sm);
}
.lumi-table th {
  background: var(--lumi-sage-50);
  color: var(--lumi-sage-800);
  font-weight: 600;
  text-align: left;
  padding: 12px 16px;
  border-bottom: 2px solid var(--lumi-sage-200);
  font-size: var(--lumi-text-xs);
  letter-spacing: 0.02em;
  text-transform: uppercase;
  white-space: nowrap;
}
.lumi-table td {
  padding: 12px 16px;
  border-bottom: 1px solid var(--lumi-stone-200);
  color: var(--lumi-stone-700);
  vertical-align: middle;
}
.lumi-table tr:hover td {
  background: var(--lumi-sage-50);
}
.lumi-table tr:last-child td {
  border-bottom: none;
}

/* ============================================
   STATUS BADGES
   ============================================ */
.lumi-status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 9999px;
  font-size: var(--lumi-text-xs);
  font-weight: 600;
  white-space: nowrap;
  font-family: var(--lumi-font-body);
}
.lumi-status::before {
  content: '';
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}
.lumi-status-success { background: #d4ede4; color: #2d6a4f; }
.lumi-status-success::before { background: #2d6a4f; }
.lumi-status-warning { background: #fcebc7; color: #8a5a00; }
.lumi-status-warning::before { background: #d4943a; }
.lumi-status-error   { background: #f0d4d0; color: #8a3a2a; }
.lumi-status-error::before { background: #c45b4a; }
.lumi-status-info    { background: #d8e0f0; color: #3a5a8a; }
.lumi-status-info::before { background: #5a8ad4; }
.lumi-status-neutral { background: var(--lumi-stone-200); color: var(--lumi-stone-700); }
.lumi-status-neutral::before { background: var(--lumi-stone-500); }

/* ============================================
   ADMIN TYPOGRAPHY
   ============================================ */
.admin-page-title {
  font-family: var(--lumi-font-display);
  font-size: var(--lumi-text-2xl);
  font-weight: 500;
  color: var(--lumi-stone-800);
  line-height: 1.35;
  margin: 0 0 var(--lumi-space-4) 0;
}
.admin-section-title {
  font-family: var(--lumi-font-display);
  font-size: var(--lumi-text-xl);
  font-weight: 500;
  color: var(--lumi-stone-700);
  line-height: 1.35;
  margin: 0 0 var(--lumi-space-3) 0;
}
.admin-body {
  font-family: var(--lumi-font-body);
  font-size: var(--lumi-text-sm);
  color: var(--lumi-stone-600);
  line-height: 1.6;
  margin: 0;
}
.admin-metric-value {
  font-family: var(--lumi-font-display);
  font-size: var(--lumi-text-3xl);
  font-weight: 500;
  color: var(--lumi-sage-700);
  line-height: 1.2;
  margin: 0;
}
.admin-metric-label {
  font-family: var(--lumi-font-body);
  font-size: var(--lumi-text-xs);
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--lumi-stone-500);
  text-transform: uppercase;
  margin: var(--lumi-space-1) 0 0 0;
}
.admin-caption {
  font-family: var(--lumi-font-body);
  font-size: var(--lumi-text-xs);
  color: var(--lumi-stone-500);
  font-weight: 500;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

/* ============================================
   HEADER UTILITY CLASSES
   ============================================ */
.header-brand {
  display: flex;
  align-items: center;
  gap: var(--lumi-space-3);
  min-width: fit-content;
}
.header-wordmark {
  font-family: var(--lumi-font-display);
  font-size: var(--lumi-text-lg);
  font-weight: 500;
  color: var(--lumi-stone-800);
  text-decoration: none;
  line-height: 1.2;
}
.header-subhead {
  font-family: var(--lumi-font-body);
  font-size: var(--lumi-text-xs);
  font-weight: 500;
  letter-spacing: 0.1em;
  color: var(--lumi-sage-600);
  text-transform: uppercase;
  margin: 0;
}

/* ============================================
   LAYOUT HELPERS
   ============================================ */
.lumi-section-alt {
  background: var(--lumi-sage-50);
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: var(--lumi-space-8);
  max-width: 1200px;
  margin: 0 auto;
}
.hero-cta-group {
  display: flex;
  gap: var(--lumi-space-4);
  margin-top: var(--lumi-space-6);
  flex-wrap: wrap;
}
.trust-badges {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: var(--lumi-space-8);
  flex-wrap: wrap;
  margin-top: var(--lumi-space-8);
}
/* Un-scoped .trust-badge — canva-landing.css already publishes a scoped
 * `.canva-landing .trust-badge`. This class is the spec's bare form for
 * surfaces outside CanvaLanding (e.g. blog post heroes, admin dashboards).
 * Kept low-specificity so the existing scoped variant continues to win. */
.trust-badge {
  display: inline-flex;
  align-items: center;
  gap: var(--lumi-space-2);
  font-family: var(--lumi-font-body);
  font-size: var(--lumi-text-sm);
  font-weight: 500;
  color: var(--lumi-stone-600);
  background: #ffffff;
  padding: var(--lumi-space-2) var(--lumi-space-4);
  border-radius: 9999px;
  border: 1px solid var(--lumi-sage-200);
  box-shadow: 0 1px 2px rgba(26, 25, 23, 0.05);
}

/* ============================================
   MASCOT WRAPPERS (admin / hero forms)
   ============================================ */
/* Hero-form mascot rules per spec. CURRENT consumer status: CanvaLanding.jsx
 * and Home.jsx reference `hero-mascot` only via data-testid attributes, NOT
 * via className, so these rules are presently dormant on the live pages —
 * the existing hero sizing comes from inline styles + LumiCompanion props.
 * Published here so any future surface that opts in via className gets the
 * spec defaults (60vw cap with 400px ceiling + sage drop-shadow). */
.hero-mascot {
  width: min(400px, 60vw);
  height: auto;
  object-fit: contain;
  filter: drop-shadow(0 8px 24px rgba(90, 138, 90, 0.15));
}
.hero-mascot:hover {
  filter: drop-shadow(0 8px 24px rgba(245, 166, 35, 0.25));
  transition: filter 0.4s ease;
}

/* Compact 48px mascot wrapper for header logos / nav avatars. */
.mascot-container {
  width: 48px;
  height: 48px;
  overflow: visible;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
}
.mascot-container img {
  width: 44px;
  height: 44px;
  object-fit: contain;
}

/* ============================================
   BUTTON SIZE / STATE ALIASES
   ----------------------------------------------
 * The existing lumi-buttons.css publishes BEM-style sizes (.lumi-btn--sm /
 * .lumi-btn--lg) and a [data-loading="true"] state. These dash-style spec
 * aliases let templates and pasted snippets use the alternate naming
 * without hand-mapping. Both forms now resolve to the same visuals.
 * ============================================ */
.lumi-btn-sm {
  height: 36px;
  padding: 0 16px;
  font-size: var(--lumi-text-xs);
}
.lumi-btn-lg {
  height: 56px;
  padding: 0 32px;
  font-size: var(--lumi-text-base);
  border-radius: 9999px;
}
.lumi-btn-icon {
  width: 44px;
  height: 44px;
  padding: 0;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
/* Loading state: hide button text via text-indent + overflow rather than
 * collapsing currentColor (the previous transparent-color approach broke the
 * spinner because its border inherited currentColor). The spinner border
 * uses an explicit sage-700 token so it remains visible regardless of the
 * host button variant; --lumi-on-* could be substituted by callers if needed. */
.lumi-btn-loading {
  position: relative;
  text-indent: -9999px;
  overflow: hidden;
  pointer-events: none;
}
.lumi-btn-loading::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 18px;
  height: 18px;
  margin: -9px 0 0 -9px;
  border: 2px solid var(--lumi-sage-700);
  border-top-color: transparent;
  border-radius: 50%;
  animation: lumi-admin-spin 0.8s linear infinite;
  text-indent: 0;
}
@keyframes lumi-admin-spin {
  to { transform: rotate(360deg); }
}
.lumi-btn-dark {
  background: var(--lumi-grad-cta);
  color: var(--lumi-stone-100);
  border: none;
}
.lumi-btn-dark:hover {
  filter: brightness(1.1);
}

/* ============================================
   LINK — DARK SURFACE VARIANT
   ============================================ */
.lumi-link-dark {
  color: var(--lumi-sage-300);
  text-decoration: none;
  font-family: var(--lumi-font-body);
  font-weight: 500;
  transition: color 0.2s ease;
  cursor: pointer;
}
.lumi-link-dark:hover {
  color: var(--lumi-amber-400);
  text-decoration: underline;
}

/* ============================================
   SAFE BOUNDARY ERROR STYLES
   ============================================ */
.lumi-error-boundary {
  background: #f0d4d0;
  border: 1px solid #c45b4a;
  border-radius: 12px;
  padding: var(--lumi-space-6);
  color: #5a2a20;
  font-family: var(--lumi-font-body);
  font-size: var(--lumi-text-sm);
  line-height: 1.6;
}
.lumi-error-boundary h3 {
  font-family: var(--lumi-font-display);
  font-size: var(--lumi-text-lg);
  font-weight: 600;
  color: #8a3a2a;
  margin: 0 0 var(--lumi-space-2) 0;
}

/* ============================================
   REDUCED MOTION
   ============================================ */
@media (prefers-reduced-motion: reduce) {
  .lumi-btn-loading::after { animation: none !important; }
  .hero-mascot:hover { transition: none !important; }
}

/*
 * Lumi v2.0 — Button library (D4)
 * 8 variants × 6 states. Pure CSS classes; opt-in.
 */

.lumi-btn {
  --_btn-bg: var(--lumi-sage-600);
  --_btn-fg: #ffffff;
  --_btn-border: transparent;
  --_btn-shadow: var(--lumi-shadow-1);
  --_btn-hover-lift: -1px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--lumi-space-2);
  padding: 0.625rem 1.25rem;
  min-height: 44px; /* WCAG touch target */
  font-family: var(--lumi-font-body);
  font-weight: 600;
  font-size: var(--lumi-text-sm);
  line-height: 1.2;
  letter-spacing: 0.01em;
  border-radius: var(--lumi-radius-md);
  border: 1.5px solid var(--_btn-border);
  background: var(--_btn-bg);
  color: var(--_btn-fg);
  box-shadow: var(--_btn-shadow);
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition:
    transform var(--lumi-dur-quick) var(--lumi-ease),
    box-shadow var(--lumi-dur-quick) var(--lumi-ease),
    background var(--lumi-dur-quick) var(--lumi-ease),
    color var(--lumi-dur-quick) var(--lumi-ease),
    border-color var(--lumi-dur-quick) var(--lumi-ease);
  text-decoration: none;
  user-select: none;
  white-space: nowrap;
}
.lumi-btn:hover  { transform: translateY(var(--_btn-hover-lift)); box-shadow: var(--lumi-shadow-2); }
.lumi-btn:active { transform: translateY(0); box-shadow: var(--lumi-shadow-1); }
.lumi-btn:focus-visible {
  outline: 3px solid var(--lumi-sage-300);
  outline-offset: 3px;
}
.lumi-btn[disabled],
.lumi-btn[aria-disabled="true"] {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none !important;
  box-shadow: var(--lumi-shadow-1) !important;
}
.lumi-btn[data-loading="true"] {
  cursor: wait;
  pointer-events: none;
}
.lumi-btn[data-loading="true"]::before {
  content: "";
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid currentColor;
  border-right-color: transparent;
  margin-right: var(--lumi-space-2);
  animation: lumi-spin 720ms linear infinite;
}
@keyframes lumi-spin { to { transform: rotate(360deg); } }

/* Sizes */
.lumi-btn--sm { padding: 0.4rem 0.875rem; font-size: var(--lumi-text-xs); min-height: 36px; }
.lumi-btn--lg { padding: 0.875rem 1.75rem; font-size: var(--lumi-text-base); min-height: 52px; }

/* ── Variants ──────────────────────────────────────────────────── */

.lumi-btn-primary {
  --_btn-bg: var(--lumi-amber-500);
  --_btn-fg: #1a1308;
  --_btn-border: transparent;
}
.lumi-btn-primary::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    100deg,
    transparent 30%,
    rgba(255, 255, 255, 0.55) 50%,
    transparent 70%
  );
  background-size: 200% 100%;
  background-position: -100% 0;
  pointer-events: none;
  transition: background-position var(--lumi-dur-slow) var(--lumi-ease-out);
  border-radius: inherit;
}
.lumi-btn-primary:hover::after { background-position: 200% 0; }
.lumi-btn-primary:hover { background: var(--lumi-amber-600); }

.lumi-btn-secondary {
  --_btn-bg: var(--lumi-sage-600);
  --_btn-fg: #ffffff;
}
.lumi-btn-secondary:hover { background: var(--lumi-sage-700); }

.lumi-btn-tertiary {
  --_btn-bg: transparent;
  --_btn-fg: var(--lumi-sage-700);
  --_btn-border: var(--lumi-sage-400);
  --_btn-shadow: none;
}
.lumi-btn-tertiary:hover { background: var(--lumi-sage-50); border-color: var(--lumi-sage-600); }
.dark .lumi-btn-tertiary { --_btn-fg: var(--lumi-sage-200); --_btn-border: var(--lumi-sage-500); }
.dark .lumi-btn-tertiary:hover { background: rgba(255,255,255,0.04); }

.lumi-btn-ghost {
  --_btn-bg: transparent;
  --_btn-fg: var(--lumi-stone-700);
  --_btn-border: transparent;
  --_btn-shadow: none;
}
.lumi-btn-ghost:hover { background: var(--lumi-stone-100); }
.dark .lumi-btn-ghost { --_btn-fg: var(--lumi-stone-200); }
.dark .lumi-btn-ghost:hover { background: rgba(255,255,255,0.05); }

.lumi-btn-text {
  --_btn-bg: transparent;
  --_btn-fg: var(--lumi-sage-700);
  --_btn-border: transparent;
  --_btn-shadow: none;
  padding-left: 0; padding-right: 0; min-height: auto;
  text-decoration: underline;
  text-decoration-color: transparent;
  text-underline-offset: 4px;
  transition: text-decoration-color var(--lumi-dur-quick) var(--lumi-ease);
}
.lumi-btn-text:hover { text-decoration-color: currentColor; transform: none; box-shadow: none; }
.dark .lumi-btn-text { --_btn-fg: var(--lumi-sage-300); }

.lumi-btn-calm {
  --_btn-bg: var(--lumi-sage-100);
  --_btn-fg: var(--lumi-sage-800);
  --_btn-border: var(--lumi-sage-200);
}
.lumi-btn-calm:hover { background: var(--lumi-sage-200); }
.dark .lumi-btn-calm { --_btn-bg: var(--lumi-sage-800); --_btn-fg: var(--lumi-sage-100); --_btn-border: var(--lumi-sage-700); }

.lumi-btn-love {
  /* AA fix: --lumi-love token (hsl 350 70% 62%) on #fff = ~3.32:1, fails WCAG AA.
     Use a darker shade locally so the token stays usable elsewhere. */
  --_btn-bg: hsl(350, 72%, 42%);
  --_btn-fg: #ffffff;
}
.lumi-btn-love:hover { filter: brightness(0.94); }

.lumi-btn-crisis {
  --_btn-bg: hsl(0, 72%, 48%);
  --_btn-fg: #ffffff;
  font-weight: 700;
  letter-spacing: 0.02em;
}
.lumi-btn-crisis:hover { background: hsl(0, 72%, 42%); }
.lumi-btn-crisis:focus-visible { outline-color: hsl(0, 72%, 60%); }

@media (prefers-reduced-motion: reduce) {
  .lumi-btn,
  .lumi-btn-primary::after { transition: none !important; animation: none !important; }
  .lumi-btn:hover { transform: none !important; }
}

/*
 * Lumi v2.0 — Layout, spacing, and card primitives (D6)
 */

.lumi-section {
  padding-top: var(--lumi-space-9);
  padding-bottom: var(--lumi-space-9);
  padding-left: var(--lumi-space-5);
  padding-right: var(--lumi-space-5);
}
@media (min-width: 768px) {
  .lumi-section { padding-top: var(--lumi-space-11); padding-bottom: var(--lumi-space-11); }
}

.lumi-container {
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
  width: 100%;
}
.lumi-container--narrow { max-width: 760px; }
.lumi-container--wide   { max-width: 1440px; }

.lumi-stack { display: flex; flex-direction: column; gap: var(--lumi-space-4); }
.lumi-stack--lg { gap: var(--lumi-space-6); }
.lumi-stack--xl { gap: var(--lumi-space-8); }
.lumi-row { display: flex; flex-direction: row; gap: var(--lumi-space-4); flex-wrap: wrap; align-items: center; }

.lumi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--lumi-space-5);
}
.lumi-grid--3 { grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); }

/* Card primitive — additive, doesn't conflict with shadcn .card */
.lumi-card {
  background: var(--lumi-bg-elev);
  color: var(--lumi-text);
  border: 1px solid var(--lumi-border);
  border-radius: var(--lumi-radius-lg);
  padding: var(--lumi-space-6);
  box-shadow: var(--lumi-shadow-1);
  transition:
    transform var(--lumi-dur-normal) var(--lumi-ease),
    box-shadow var(--lumi-dur-normal) var(--lumi-ease),
    border-color var(--lumi-dur-normal) var(--lumi-ease);
  position: relative;
  overflow: hidden;
}
.lumi-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--lumi-shadow-3);
  border-color: var(--lumi-sage-300);
}
.lumi-card__icon {
  display: inline-flex; align-items: center; justify-content: center;
  width: 48px; height: 48px;
  border-radius: var(--lumi-radius-md);
  background: var(--lumi-grad-sage);
  color: white;
  margin-bottom: var(--lumi-space-4);
}
.lumi-card__title {
  font-family: var(--lumi-font-display);
  font-size: var(--lumi-text-lg);
  font-weight: 600;
  line-height: var(--lumi-leading-heading);
  margin: 0 0 var(--lumi-space-3);
  color: var(--lumi-stone-900);
}
.dark .lumi-card__title { color: var(--lumi-stone-50); }
.lumi-card__body {
  font-family: var(--lumi-font-body);
  font-size: var(--lumi-text-sm);
  line-height: var(--lumi-leading-body);
  color: var(--lumi-text-muted);
  margin: 0;
}
.lumi-card--glow::before {
  content: "";
  position: absolute;
  inset: -2px;
  background: var(--lumi-grad-sage);
  border-radius: inherit;
  z-index: -1;
  opacity: 0;
  transition: opacity var(--lumi-dur-normal) var(--lumi-ease);
}
.lumi-card--glow:hover::before { opacity: 0.4; filter: blur(8px); }

@media (prefers-reduced-motion: reduce) {
  .lumi-card { transition: none; }
  .lumi-card:hover { transform: none; }
}

/*
 * Lumi v2.0 — Link library (D5)
 * 9 link types. Pure CSS classes; opt-in.
 */

.lumi-link-text {
  color: var(--lumi-sage-700);
  text-decoration: underline;
  text-decoration-color: var(--lumi-sage-300);
  text-underline-offset: 3px;
  transition: color var(--lumi-dur-quick) var(--lumi-ease),
              text-decoration-color var(--lumi-dur-quick) var(--lumi-ease);
}
.lumi-link-text:hover { color: var(--lumi-sage-800); text-decoration-color: currentColor; }
.dark .lumi-link-text { color: var(--lumi-sage-300); text-decoration-color: var(--lumi-sage-500); }
.dark .lumi-link-text:hover { color: var(--lumi-sage-100); }

.lumi-link-nav {
  color: var(--lumi-stone-700);
  text-decoration: none;
  font-weight: 500;
  padding: 0.4rem 0.75rem;
  border-radius: var(--lumi-radius-sm);
  position: relative;
  transition: color var(--lumi-dur-quick) var(--lumi-ease),
              background var(--lumi-dur-quick) var(--lumi-ease);
}
.lumi-link-nav::after {
  content: ""; position: absolute; left: 0.75rem; right: 0.75rem; bottom: 0.15rem;
  height: 2px; background: var(--lumi-amber-500); border-radius: 1px;
  transform: scaleX(0); transform-origin: left center;
  transition: transform var(--lumi-dur-normal) var(--lumi-ease-out);
}
.lumi-link-nav:hover { color: var(--lumi-sage-800); }
.lumi-link-nav:hover::after,
.lumi-link-nav[aria-current="page"]::after { transform: scaleX(1); }
.dark .lumi-link-nav { color: var(--lumi-stone-200); }
.dark .lumi-link-nav:hover { color: var(--lumi-sage-200); }

.lumi-link-footer {
  color: var(--lumi-stone-600);
  text-decoration: none;
  font-size: var(--lumi-text-sm);
  transition: color var(--lumi-dur-quick) var(--lumi-ease);
}
.lumi-link-footer:hover { color: var(--lumi-sage-700); text-decoration: underline; text-underline-offset: 3px; }
.dark .lumi-link-footer { color: var(--lumi-stone-300); }
.dark .lumi-link-footer:hover { color: var(--lumi-sage-200); }

.lumi-link-inline {
  color: inherit;
  text-decoration: underline;
  text-decoration-color: var(--lumi-amber-400);
  text-decoration-thickness: 2px;
  text-underline-offset: 4px;
  transition: text-decoration-color var(--lumi-dur-quick) var(--lumi-ease);
}
.lumi-link-inline:hover { text-decoration-color: var(--lumi-amber-600); }

.lumi-link-brand {
  color: var(--lumi-sage-800);
  text-decoration: none;
  font-family: var(--lumi-font-display);
  font-weight: 600;
  letter-spacing: -0.01em;
}
.lumi-link-brand:hover { color: var(--lumi-amber-700); }
.dark .lumi-link-brand { color: var(--lumi-sage-100); }

.lumi-link-external {
  color: var(--lumi-sage-700);
  text-decoration: underline;
  text-decoration-color: var(--lumi-sage-300);
  text-underline-offset: 3px;
}
.lumi-link-external::after {
  content: " ↗";
  font-size: 0.85em;
  color: var(--lumi-stone-500);
}
.lumi-link-external:hover { color: var(--lumi-sage-800); }
.dark .lumi-link-external { color: var(--lumi-sage-300); }

.lumi-link-crisis {
  color: hsl(0, 72%, 42%);
  background: hsl(0, 72%, 96%);
  border: 1.5px solid hsl(0, 72%, 80%);
  padding: 0.4rem 0.75rem;
  border-radius: var(--lumi-radius-sm);
  text-decoration: none;
  font-weight: 700;
  letter-spacing: 0.01em;
  display: inline-flex; align-items: center; gap: var(--lumi-space-2);
  transition: background var(--lumi-dur-quick) var(--lumi-ease);
}
.lumi-link-crisis:hover { background: hsl(0, 72%, 92%); }
.lumi-link-crisis:focus-visible { outline: 3px solid hsl(0, 72%, 60%); outline-offset: 2px; }
.dark .lumi-link-crisis { color: hsl(0, 72%, 80%); background: hsl(0, 30%, 18%); border-color: hsl(0, 50%, 35%); }
.dark .lumi-link-crisis:hover { background: hsl(0, 30%, 22%); }

.lumi-link-subtle {
  color: var(--lumi-stone-500);
  text-decoration: none;
  font-size: var(--lumi-text-sm);
}
.lumi-link-subtle:hover { color: var(--lumi-stone-700); text-decoration: underline; text-underline-offset: 3px; }
.dark .lumi-link-subtle { color: var(--lumi-stone-400); }
.dark .lumi-link-subtle:hover { color: var(--lumi-stone-200); }

.lumi-link-ghost {
  color: var(--lumi-stone-700);
  text-decoration: none;
  padding: 0.3rem 0.6rem;
  border-radius: var(--lumi-radius-sm);
  transition: background var(--lumi-dur-quick) var(--lumi-ease);
}
.lumi-link-ghost:hover { background: var(--lumi-stone-100); }
.dark .lumi-link-ghost { color: var(--lumi-stone-200); }
.dark .lumi-link-ghost:hover { background: rgba(255,255,255,0.05); }

@media (prefers-reduced-motion: reduce) {
  .lumi-link-nav::after { transition: none; }
}

/* ----------------------------------------------------------------------------
 * Universal :focus-visible — keyboard accessibility contract for ALL Lumi
 * link variants. The crisis link keeps its higher-emphasis red ring above.
 * Implemented as a single shared rule so every variant gets a consistent,
 * AA-contrasting focus indicator regardless of background.
 * -------------------------------------------------------------------------- */
.lumi-link-text:focus-visible,
.lumi-link-nav:focus-visible,
.lumi-link-footer:focus-visible,
.lumi-link-inline:focus-visible,
.lumi-link-brand:focus-visible,
.lumi-link-external:focus-visible,
.lumi-link-subtle:focus-visible,
.lumi-link-ghost:focus-visible {
  outline: 2px solid var(--lumi-amber-600, hsl(38, 92%, 45%));
  outline-offset: 3px;
  border-radius: var(--lumi-radius-sm, 6px);
}
.dark .lumi-link-text:focus-visible,
.dark .lumi-link-nav:focus-visible,
.dark .lumi-link-footer:focus-visible,
.dark .lumi-link-inline:focus-visible,
.dark .lumi-link-brand:focus-visible,
.dark .lumi-link-external:focus-visible,
.dark .lumi-link-subtle:focus-visible,
.dark .lumi-link-ghost:focus-visible {
  outline-color: var(--lumi-amber-400, hsl(38, 92%, 65%));
}

/* ==========================================================
   Phase 64 — Lumi Living Presence + Page Scene Polish
   Goals:
   - Make Lumi feel alive, warm, premium, and emotionally present.
   - Reduce empty hero whitespace without breaking routes.
   - Improve page coherence, visual hierarchy, button readability,
     content visibility, and soft pastel depth.
   - Preserve reduced-motion accessibility.
   ========================================================== */

:root {
  --phase64-cream: #fffaf2;
  --phase64-cream-deep: #f7ecdc;
  --phase64-soft-sage: #eaf3e5;
  --phase64-sage: #b9d0ad;
  --phase64-sage-strong: #5f8a68;
  --phase64-evergreen: #12342f;
  --phase64-text: #1d3f38;
  --phase64-muted: #60766f;
  --phase64-gold: #ffd875;
  --phase64-gold-soft: #fff3bd;
  --phase64-rose: #ffdfe4;
  --phase64-sky: #c8efff;
  --phase64-lavender: #ece4ff;
  --phase64-card: rgba(255, 253, 248, 0.82);
  --phase64-border: rgba(18, 52, 47, 0.12);
  --phase64-shadow: 0 24px 70px rgba(18, 52, 47, 0.13);
  --phase64-glow: 0 0 42px rgba(255, 216, 117, 0.36), 0 0 70px rgba(200, 239, 255, 0.24);
  --phase64-radius-xl: 42px;
  --phase64-radius-lg: 30px;
  --phase64-radius-md: 20px;
  --phase64-pill: 999px;
  --phase64-ease: cubic-bezier(.22, 1, .36, 1);
}

/* Page-level depth */
body {
  background:
    radial-gradient(circle at 10% 7%, rgba(255, 216, 117, .20), transparent 28%),
    radial-gradient(circle at 92% 12%, rgba(200, 239, 255, .24), transparent 30%),
    radial-gradient(circle at 52% 92%, rgba(255, 223, 228, .22), transparent 34%),
    linear-gradient(180deg, #fffdf8 0%, var(--phase64-cream) 45%, var(--phase64-soft-sage) 100%) !important;
  color: var(--phase64-text);
}

/* Premium page container feel */
main,
[class*="Page"],
[class*="page"],
[class*="Screen"],
[class*="screen"] {
  position: relative;
  isolation: isolate;
}

/* Coherent content width and vertical rhythm */
main > section,
[class*="section"],
[class*="Section"] {
  scroll-margin-top: 96px;
}

section,
[class*="Section"],
[class*="section"] {
  position: relative;
}

/* Reduce plain empty hero whitespace while keeping calm breathing room */
[class*="hero"],
[class*="Hero"],
[class*="journey"],
[class*="Journey"],
[class*="landing"],
[class*="Landing"],
[class*="Home"] {
  min-height: auto;
}

[class*="hero"] > *,
[class*="Hero"] > *,
[class*="journey"] > *,
[class*="Journey"] > * {
  position: relative;
  z-index: 1;
}

/* Add scene aura to hero / journey areas */
[class*="hero"]::after,
[class*="Hero"]::after,
[class*="journey"]::after,
[class*="Journey"]::after,
[class*="landing"]::after,
[class*="Landing"]::after {
  content: "";
  position: absolute;
  inset: 4% 5%;
  pointer-events: none;
  z-index: 0;
  border-radius: var(--phase64-radius-xl);
  background:
    radial-gradient(circle at 20% 28%, rgba(255, 216, 117, .22), transparent 30%),
    radial-gradient(circle at 78% 22%, rgba(200, 239, 255, .22), transparent 34%),
    radial-gradient(circle at 58% 82%, rgba(255, 223, 228, .18), transparent 36%);
  filter: blur(8px);
  opacity: .78;
}

/* Cards: stronger hierarchy, still gentle */
.card,
[class*="Card"],
[class*="panel"],
[class*="Panel"],
[class*="module"],
[class*="Module"] {
  background-color: var(--phase64-card);
  border: 1px solid var(--phase64-border);
  box-shadow: 0 16px 50px rgba(18, 52, 47, .08);
  backdrop-filter: blur(16px);
}

/* Visual cards with images should feel intentional */
img {
  max-width: 100%;
}

img[alt*="Lumi"],
img[alt*="lumi"],
img[src*="lumi"],
img[src*="Lumi"],
[class*="Lumi"] img,
[class*="lumi"] img {
  transform-origin: center bottom;
  will-change: transform, filter;
  filter:
    drop-shadow(0 28px 42px rgba(18, 52, 47, .18))
    drop-shadow(0 0 26px rgba(255, 216, 117, .22));
  animation:
    phase64LumiBreath 5.8s ease-in-out infinite,
    phase64LumiFloat 8s var(--phase64-ease) infinite,
    phase64LumiGlow 6.8s ease-in-out infinite;
}

/* Living Lumi scene wrapper — works when added later and also with common existing class names */
.lumi-living-presence,
.lumi-scene,
.lumi-avatar-scene,
[class*="LumiScene"],
[class*="LumiPresence"],
[class*="lumi-scene"],
[class*="lumi-presence"] {
  position: relative;
  isolation: isolate;
  overflow: visible;
}

.lumi-living-presence::before,
.lumi-scene::before,
.lumi-avatar-scene::before,
[class*="LumiScene"]::before,
[class*="LumiPresence"]::before,
[class*="lumi-scene"]::before,
[class*="lumi-presence"]::before {
  content: "";
  position: absolute;
  inset: 7%;
  z-index: -1;
  pointer-events: none;
  border-radius: 50%;
  background:
    radial-gradient(circle, rgba(255, 216, 117, .42), transparent 42%),
    radial-gradient(circle, rgba(200, 239, 255, .28), transparent 66%),
    radial-gradient(circle, rgba(255, 223, 228, .24), transparent 76%);
  filter: blur(22px);
  animation: phase64ScenePulse 5.4s ease-in-out infinite;
}

.lumi-living-presence::after,
.lumi-scene::after,
.lumi-avatar-scene::after,
[class*="LumiScene"]::after,
[class*="LumiPresence"]::after,
[class*="lumi-scene"]::after,
[class*="lumi-presence"]::after {
  content: "";
  position: absolute;
  inset: -8%;
  z-index: -1;
  pointer-events: none;
  background-image:
    radial-gradient(circle, rgba(255, 216, 117, .65) 0 1px, transparent 2px),
    radial-gradient(circle, rgba(185, 208, 173, .58) 0 1px, transparent 2px),
    radial-gradient(circle, rgba(200, 239, 255, .56) 0 1px, transparent 2px),
    radial-gradient(circle, rgba(255, 223, 228, .46) 0 1px, transparent 2px);
  background-size: 72px 72px, 104px 104px, 136px 136px, 168px 168px;
  background-position: 10px 20px, 50px 80px, 90px 30px, 30px 120px;
  opacity: .58;
  animation: phase64SparkleDrift 22s linear infinite;
}

/* Button label visibility: force accessible contrast over opaque sage */
button,
a[role="button"],
.btn,
.button,
[class*="Button"],
[class*="button"],
[class*="btn"] {
  min-height: 44px;
  color: var(--phase64-evergreen);
  text-shadow: none !important;
  font-weight: 700;
  letter-spacing: -0.01em;
}

/* Primary CTAs */
button[class*="primary"],
button[class*="Primary"],
a[class*="primary"],
a[class*="Primary"],
[class*="CTA"],
[class*="cta"],
.btn-primary,
.lumi-button-primary {
  color: #fffdf8 !important;
  background:
    linear-gradient(135deg, #315f51 0%, #5f8a68 58%, #8fb98d 100%) !important;
  border: 1px solid rgba(255, 253, 248, .42) !important;
  box-shadow:
    0 14px 34px rgba(49, 95, 81, .24),
    0 0 0 1px rgba(255, 253, 248, .18) inset !important;
}

/* Soft CTAs */
button[class*="secondary"],
button[class*="Secondary"],
a[class*="secondary"],
a[class*="Secondary"],
.lumi-button-soft {
  color: var(--phase64-evergreen) !important;
  background:
    linear-gradient(135deg, rgba(255, 253, 248, .96), rgba(234, 243, 229, .80)) !important;
  border: 1px solid rgba(49, 95, 81, .20) !important;
}

/* Protect labels inside buttons */
button *,
a[role="button"] *,
.btn *,
.button *,
[class*="Button"] *,
[class*="button"] * {
  color: inherit;
}

/* Links must be visible */
a {
  color: #315f51;
  text-underline-offset: 3px;
}

a:hover {
  color: #12342f;
}

/* Form clarity */
input,
textarea,
select {
  color: var(--phase64-text);
  background: rgba(255, 253, 248, .94);
  border: 1px solid rgba(18, 52, 47, .16);
}

input::placeholder,
textarea::placeholder {
  color: rgba(96, 118, 111, .70);
}

/* Headline readability */
h1,
h2,
h3 {
  color: var(--phase64-evergreen);
  text-wrap: balance;
}

p,
li {
  color: var(--phase64-text);
}

/* Small labels should not disappear into pastel background */
small,
[class*="eyebrow"],
[class*="Eyebrow"],
[class*="label"],
[class*="Label"] {
  color: var(--phase64-muted);
}

/* Timeline / left rail polish from screenshot-like pages */
[class*="timeline"],
[class*="Timeline"],
[class*="step"],
[class*="Step"] {
  border-color: rgba(95, 138, 104, .18);
}

/* Floating back-to-top / action buttons */
[class*="floating"],
[class*="Floating"],
[class*="backToTop"],
[class*="BackToTop"] {
  color: #fffdf8 !important;
  background: linear-gradient(135deg, #006f5e, #14967f) !important;
  box-shadow: 0 18px 40px rgba(0, 111, 94, .24);
}

/* Motion */
@keyframes phase64LumiBreath {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.018); }
}

@keyframes phase64LumiFloat {
  0%, 100% { translate: 0 0; }
  50% { translate: 0 -10px; }
}

@keyframes phase64LumiGlow {
  0%, 100% {
    filter:
      drop-shadow(0 28px 42px rgba(18, 52, 47, .18))
      drop-shadow(0 0 26px rgba(255, 216, 117, .22));
  }
  50% {
    filter:
      drop-shadow(0 32px 52px rgba(18, 52, 47, .22))
      drop-shadow(0 0 44px rgba(255, 216, 117, .40))
      drop-shadow(0 0 24px rgba(200, 239, 255, .28));
  }
}

@keyframes phase64ScenePulse {
  0%, 100% { opacity: .48; transform: scale(.97); }
  50% { opacity: .86; transform: scale(1.05); }
}

@keyframes phase64SparkleDrift {
  0% { background-position: 10px 20px, 50px 80px, 90px 30px, 30px 120px; }
  100% { background-position: 110px 90px, 10px 140px, 160px 20px, 90px 20px; }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
  }

  img[alt*="Lumi"],
  img[alt*="lumi"],
  img[src*="lumi"],
  img[src*="Lumi"],
  [class*="Lumi"] img,
  [class*="lumi"] img,
  .lumi-living-presence::before,
  .lumi-living-presence::after,
  .lumi-scene::before,
  .lumi-scene::after,
  .lumi-avatar-scene::before,
  .lumi-avatar-scene::after,
  [class*="LumiScene"]::before,
  [class*="LumiScene"]::after,
  [class*="LumiPresence"]::before,
  [class*="LumiPresence"]::after,
  [class*="lumi-scene"]::before,
  [class*="lumi-scene"]::after,
  [class*="lumi-presence"]::before,
  [class*="lumi-presence"]::after {
    animation: none !important;
  }
}

@media (max-width: 900px) {
  [class*="hero"]::after,
  [class*="Hero"]::after,
  [class*="journey"]::after,
  [class*="Journey"]::after,
  [class*="landing"]::after,
  [class*="Landing"]::after {
    inset: 2%;
    border-radius: 28px;
  }

  button,
  a[role="button"],
  .btn,
  .button,
  [class*="Button"],
  [class*="button"],
  [class*="btn"] {
    min-height: 46px;
  }
}

/*
 * Lumi Mascot — Performance & Reduced-Motion Hardening
 * ADDITIVE ONLY. Keyframes themselves live in lumi-motion.css and
 * LumiMascot.css; this file owns GPU-accel hints and the global
 * reduced-motion fallback that opacity-cross-fades instead of animating.
 */

.lumi-mascot {
  /* GPU-accel hint to keep the mascot on its own composite layer so
     transform/filter animations don't repaint surrounding text. */
  transform: translateZ(0);
  backface-visibility: hidden;
  -webkit-backface-visibility: hidden;
  /* Default to 'auto' — only promote will-change while a finite-duration
     animation is actively running, so we don't permanently allocate a
     compositor layer for every Lumi on the page. */
  will-change: auto;
}

.lumi-mascot.animating {
  will-change: transform, filter;
}

/* Avoid layout shift while the PNG is loading by reserving the box. */
.lumi-mascot[data-loading="true"] {
  background: transparent;
}

/* ── Reduced motion fallback ───────────────────────────────────────────────
   Disables every keyframe animation on Lumi components and replaces them
   with a soft opacity cross-fade on emotion change. The wrapper component
   adds .lumi-reduced-motion when the OS-level setting is on; we also honor
   the system media query directly so partial component coverage is safe. */
.lumi-reduced-motion .lumi-mascot,
.lumi-reduced-motion .lumi-mascot * {
  animation: none !important;
  transition: opacity 200ms ease-out !important;
}

@media (prefers-reduced-motion: reduce) {
  .lumi-mascot,
  .lumi-mascot * {
    animation: none !important;
    transition: opacity 200ms ease-out !important;
  }
  .lumi-mascot.animating {
    will-change: opacity;
  }
}

/* ============================================================================
 * THEME FILTERS — runtime color customization via CSS hue-rotate filters
 * useLumiTheme.js applies one of these classes to <body> when a user picks a
 * theme in LumiCustomizer. Filters are applied to .lumi-mascot inside the
 * themed body so the canonical sage PNG re-tints without per-theme artwork.
 * Smooth cross-fade transition added below.
 * ========================================================================== */

.lumi-mascot,
.lumi-mascot img {
  transition: filter 0.6s cubic-bezier(0.4, 0, 0.2, 1);
}

body.lumi-theme-sage     .lumi-mascot { filter: none; }
body.lumi-theme-ocean    .lumi-mascot { filter: hue-rotate(190deg) saturate(1.1); }
body.lumi-theme-lavender .lumi-mascot { filter: hue-rotate(260deg) saturate(0.9) brightness(1.05); }
body.lumi-theme-coral    .lumi-mascot { filter: hue-rotate(320deg) saturate(1.2) brightness(1.02); }
body.lumi-theme-sunshine .lumi-mascot { filter: hue-rotate(40deg)  saturate(1.3) brightness(1.1); }
body.lumi-theme-rose     .lumi-mascot { filter: hue-rotate(340deg) saturate(1.1) brightness(0.95); }
body.lumi-theme-mint     .lumi-mascot { filter: hue-rotate(150deg) saturate(1.05) brightness(1.02); }
body.lumi-theme-onyx     .lumi-mascot { filter: grayscale(0.6) brightness(0.7) contrast(1.1); }
body.lumi-theme-snow     .lumi-mascot { filter: grayscale(0.3) brightness(1.3) saturate(0.5); }

/* ============================================================================
 * 18 EMOTION ANIMATION UTILITY CLASSES
 * Parallel API to the existing [data-emotion] attribute selectors in
 * LumiMascot.css. Use these when you want to apply a one-shot or looping
 * animation to ANY element (not just .lumi-mascot wrappers). Class-based
 * means callers compose freely: <div className="lumi-pulse-heart">…</div>.
 * All animations honor prefers-reduced-motion via the global block at the
 * bottom of this rule set + the .lumi-mascot * cascade above.
 * ========================================================================== */

/* 1. idle — gentle breathing */
.lumi-breathe {
  animation: lumi-anim-breathe 4s ease-in-out infinite;
  transform-origin: center bottom;
}
@keyframes lumi-anim-breathe {
  0%, 100% { transform: scale(1) translateY(0); }
  50%      { transform: scale(1.02) translateY(-6px); }
}

/* 2. welcome — friendly wave (3 loops) */
.lumi-wave { animation: lumi-anim-wave 0.8s ease-in-out 3; }
@keyframes lumi-anim-wave {
  0%, 100% { transform: rotate(0deg); }
  25%      { transform: rotate(-8deg); }
  75%      { transform: rotate(8deg); }
}

/* 3. listen — attentive lean */
.lumi-attentive { animation: lumi-anim-attentive 2s ease-in-out infinite; }
@keyframes lumi-anim-attentive {
  0%, 100% { transform: translateX(0) rotate(0deg); }
  50%      { transform: translateX(3px) rotate(1deg); }
}

/* 4. think — gentle sway */
.lumi-think { animation: lumi-anim-think 3s ease-in-out infinite; }
@keyframes lumi-anim-think {
  0%, 100% { transform: translateX(0); }
  50%      { transform: translateX(5px); }
}

/* 5. speak — speaking bounce */
.lumi-speak { animation: lumi-anim-speak 0.4s ease-in-out infinite; }
@keyframes lumi-anim-speak {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-3px); }
}

/* 6. celebrate — celebration jump (3 loops) */
.lumi-jump { animation: lumi-anim-jump 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) 3; }
@keyframes lumi-anim-jump {
  0%, 100% { transform: translateY(0) scale(1); }
  50%      { transform: translateY(-20px) scale(1.05); }
}

/* 7. calm — ocean-like float drift */
.lumi-float { animation: lumi-anim-float 6s ease-in-out infinite; }
@keyframes lumi-anim-float {
  0%, 100% { transform: translateY(0) translateX(0); }
  33%      { transform: translateY(-8px) translateX(4px); }
  66%      { transform: translateY(-4px) translateX(-4px); }
}

/* 8. love — heart pulse glow */
.lumi-pulse-heart { animation: lumi-anim-pulse-heart 2s ease-in-out infinite; }
@keyframes lumi-anim-pulse-heart {
  0%, 100% { filter: drop-shadow(0 0 4px rgba(245, 166, 35, 0.30)); }
  50%      { filter: drop-shadow(0 0 16px rgba(245, 166, 35, 0.60)); }
}

/* 9. insight — sparkle shimmer */
.lumi-sparkle { animation: lumi-anim-sparkle 3s ease-in-out infinite; }
@keyframes lumi-anim-sparkle {
  0%, 100% { filter: brightness(1); }
  50%      { filter: brightness(1.08); }
}

/* 10. rest — dimmed slow breath */
.lumi-dim { animation: lumi-anim-dim 5s ease-in-out infinite; opacity: 0.75; }
@keyframes lumi-anim-dim {
  0%, 100% { transform: scale(1) translateY(0);     opacity: 0.75; }
  50%      { transform: scale(1.01) translateY(-3px); opacity: 0.85; }
}

/* 11. sleep — gentle snooze rock */
.lumi-snooze { animation: lumi-anim-snooze 4s ease-in-out infinite; }
@keyframes lumi-anim-snooze {
  0%, 100% { transform: rotate(0deg) translateY(0); }
  25%      { transform: rotate(-2deg) translateY(-2px); }
  75%      { transform: rotate(2deg)  translateY(-2px); }
}

/* 12. focus — steady minimal (no animation, slight scale-down) */
.lumi-steady { animation: none; transform: scale(0.98); }

/* 13. joy — fast happy bounce */
.lumi-bounce-fast { animation: lumi-anim-bounce-fast 0.5s cubic-bezier(0.34, 1.56, 0.64, 1) infinite; }
@keyframes lumi-anim-bounce-fast {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-10px); }
}

/* 14. comfort — warm soften glow */
.lumi-soften { animation: lumi-anim-soften 3s ease-in-out infinite; }
@keyframes lumi-anim-soften {
  0%, 100% { filter: brightness(1) saturate(1); }
  50%      { filter: brightness(1.05) saturate(1.1); }
}

/* 15. curiosity — head-tilt peek */
.lumi-peek { animation: lumi-anim-peek 2s ease-in-out infinite; }
@keyframes lumi-anim-peek {
  0%, 100% { transform: rotate(0deg); }
  50%      { transform: rotate(5deg); }
}

/* 16. empathy — reaching outward */
.lumi-reach { animation: lumi-anim-reach 2.5s ease-in-out infinite; }
@keyframes lumi-anim-reach {
  0%, 100% { transform: translateX(0); }
  50%      { transform: translateX(8px); }
}

/* 17. proud — standing-tall stretch */
.lumi-stand-tall { animation: lumi-anim-stand-tall 3s ease-in-out infinite; }
@keyframes lumi-anim-stand-tall {
  0%, 100% { transform: scaleY(1); }
  50%      { transform: scaleY(1.03); }
}

/* 18. surprise — sudden pop (one-shot) */
.lumi-pop { animation: lumi-anim-pop 0.4s cubic-bezier(0.34, 1.56, 0.64, 1); }
@keyframes lumi-anim-pop {
  0%   { transform: scale(0.9); }
  50%  { transform: scale(1.08); }
  100% { transform: scale(1); }
}

/* Reduced-motion safety for ALL 18 utility classes (covers usage outside
   .lumi-mascot wrappers, where the cascade above wouldn't reach). */
@media (prefers-reduced-motion: reduce) {
  .lumi-breathe, .lumi-wave, .lumi-attentive, .lumi-think, .lumi-speak,
  .lumi-jump, .lumi-float, .lumi-pulse-heart, .lumi-sparkle, .lumi-dim,
  .lumi-snooze, .lumi-bounce-fast, .lumi-soften, .lumi-peek, .lumi-reach,
  .lumi-stand-tall, .lumi-pop {
    animation: none !important;
    transition: opacity 0.3s ease !important;
  }
}

/*
 * Lumi v2.0 — Motion utilities (D7)
 * All animations respect prefers-reduced-motion.
 */

@keyframes lumi-breathe {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.04); }
}
@keyframes lumi-float {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-6px); }
}
@keyframes lumi-heart-pulse {
  0%, 100% { filter: drop-shadow(0 0 4px var(--lumi-amber-400)); transform: scale(1); }
  50%      { filter: drop-shadow(0 0 14px var(--lumi-amber-500)); transform: scale(1.08); }
}
@keyframes lumi-shimmer-sweep {
  0%   { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}
@keyframes lumi-fade-up {
  0%   { opacity: 0; transform: translateY(16px); }
  100% { opacity: 1; transform: translateY(0); }
}
@keyframes lumi-blink {
  0%, 92%, 100% { transform: scaleY(1); }
  95%, 97%      { transform: scaleY(0.05); }
}

.lumi-anim-breathe { animation: lumi-breathe var(--lumi-dur-breathe) ease-in-out infinite; transform-origin: center; }
.lumi-anim-float   { animation: lumi-float 6s ease-in-out infinite; }
.lumi-anim-heart   { animation: lumi-heart-pulse 3s ease-in-out infinite; transform-origin: center; }

.lumi-shimmer {
  position: relative;
  overflow: hidden;
}
.lumi-shimmer::before {
  content: "";
  position: absolute; inset: 0;
  background: linear-gradient(
    100deg,
    transparent 30%,
    rgba(255,255,255,0.4) 50%,
    transparent 70%
  );
  background-size: 200% 100%;
  animation: lumi-shimmer-sweep 2.4s ease-in-out infinite;
  pointer-events: none;
  border-radius: inherit;
}

/* Scroll reveal: opt-in via [data-reveal] attribute, IntersectionObserver
   sets [data-revealed="true"] to trigger transition. */
[data-reveal] {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 700ms var(--lumi-ease-out),
              transform 700ms var(--lumi-ease-out);
}
[data-reveal][data-revealed="true"] {
  opacity: 1;
  transform: translateY(0);
}
[data-reveal-stagger] > * {
  opacity: 0;
  transform: translateY(16px);
  transition: opacity 600ms var(--lumi-ease-out),
              transform 600ms var(--lumi-ease-out);
}
[data-reveal-stagger][data-revealed="true"] > * { opacity: 1; transform: translateY(0); }
[data-reveal-stagger][data-revealed="true"] > *:nth-child(1) { transition-delay: 0ms; }
[data-reveal-stagger][data-revealed="true"] > *:nth-child(2) { transition-delay: 80ms; }
[data-reveal-stagger][data-revealed="true"] > *:nth-child(3) { transition-delay: 160ms; }
[data-reveal-stagger][data-revealed="true"] > *:nth-child(4) { transition-delay: 240ms; }
[data-reveal-stagger][data-revealed="true"] > *:nth-child(5) { transition-delay: 320ms; }
[data-reveal-stagger][data-revealed="true"] > *:nth-child(6) { transition-delay: 400ms; }

@media (prefers-reduced-motion: reduce) {
  .lumi-anim-breathe,
  .lumi-anim-float,
  .lumi-anim-heart,
  .lumi-shimmer::before {
    animation: none !important;
  }
  [data-reveal],
  [data-reveal-stagger] > * {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
}

/* ==========================================================
   Phase 63 — Lumi Soft Pastel Visual System
   Purpose:
   - Reduce opaque sage heaviness
   - Add Lumi-derived soft pastel palette
   - Fix invisible button labels
   - Add warmer visual depth, glow, motion, and scene polish
   - Preserve accessibility and avoid dark patterns
   ========================================================== */

:root {
  /* Lumi Core Neutrals */
  --lumi-cream-00: #fffdf8;
  --lumi-cream-50: #fff9f1;
  --lumi-cream-100: #f9f1e7;
  --lumi-cream-200: #efe3d4;

  /* Soft Pastel Sage — lighter and less opaque than prior sage */
  --lumi-sage-25: #f4f8f0;
  --lumi-sage-50: #edf4e8;
  --lumi-sage-100: #dfeadb;
  --lumi-sage-200: #cdddc5;
  --lumi-sage-300: #b4caa8;
  --lumi-sage-400: #91ad86;
  --lumi-sage-500: #6f936d;
  --lumi-sage-600: #4f765b;
  --lumi-sage-700: #315b4d;
  --lumi-sage-800: #183f37;
  --lumi-sage-900: #0f2d29;

  /* Lumi Pastel Companions */
  --lumi-rose-50: #fff1f2;
  --lumi-rose-100: #ffe0e4;
  --lumi-rose-200: #ffc6cf;
  --lumi-peach-50: #fff2e5;
  --lumi-peach-100: #ffe0bf;
  --lumi-gold-50: #fff8db;
  --lumi-gold-100: #ffeaa3;
  --lumi-gold-200: #ffd66e;
  --lumi-sky-50: #edfaff;
  --lumi-sky-100: #cdefff;
  --lumi-sky-200: #9de0ff;
  --lumi-lavender-50: #f6f1ff;
  --lumi-lavender-100: #e8ddff;
  --lumi-mint-50: #effbf4;
  --lumi-mint-100: #d8f2e3;

  /* Text */
  --lumi-text-strong: #102f2b;
  --lumi-text-main: #1f4039;
  --lumi-text-soft: #5f756d;
  --lumi-text-muted: #7f9089;
  --lumi-text-inverse: #fffdf8;

  /* Surfaces */
  --lumi-surface: rgba(255, 253, 248, 0.94);
  --lumi-surface-soft: rgba(255, 249, 241, 0.88);
  --lumi-surface-sage: rgba(244, 248, 240, 0.78);
  --lumi-surface-rose: rgba(255, 241, 242, 0.72);
  --lumi-surface-gold: rgba(255, 248, 219, 0.72);
  --lumi-surface-sky: rgba(237, 250, 255, 0.7);

  /* Borders / shadows / glow */
  --lumi-border-soft: rgba(49, 91, 77, 0.14);
  --lumi-border-sage: rgba(111, 147, 109, 0.22);
  --lumi-shadow-soft: 0 18px 50px rgba(49, 91, 77, 0.10);
  --lumi-shadow-card: 0 20px 60px rgba(49, 91, 77, 0.13);
  --lumi-shadow-button: 0 12px 30px rgba(79, 118, 91, 0.22);
  --lumi-glow-sage: 0 0 34px rgba(205, 221, 197, 0.72);
  --lumi-glow-gold: 0 0 38px rgba(255, 214, 110, 0.54);
  --lumi-glow-sky: 0 0 32px rgba(157, 224, 255, 0.48);

  /* Radius */
  --lumi-radius-sm: 14px;
  --lumi-radius-md: 20px;
  --lumi-radius-lg: 30px;
  --lumi-radius-xl: 42px;
  --lumi-radius-pill: 999px;

  /* Motion */
  --lumi-ease: cubic-bezier(.22, 1, .36, 1);
}

/* Global visual softness */
body {
  color: var(--lumi-text-main);
  background:
    radial-gradient(circle at 18% 12%, rgba(255, 214, 110, 0.16), transparent 32%),
    radial-gradient(circle at 82% 18%, rgba(205, 239, 255, 0.22), transparent 34%),
    radial-gradient(circle at 50% 92%, rgba(255, 224, 228, 0.24), transparent 38%),
    linear-gradient(180deg, var(--lumi-cream-00), var(--lumi-cream-50) 42%, var(--lumi-sage-25));
}

/* Prevent sage opacity from swallowing labels */
button,
a[role="button"],
.btn,
.button,
[class*="btn"],
[class*="Button"],
[class*="button"] {
  color: var(--lumi-text-strong);
  text-shadow: none;
  -webkit-font-smoothing: antialiased;
}

/* Primary CTA visibility */
button[class*="primary"],
a[class*="primary"],
.btn-primary,
[class*="PrimaryButton"],
[class*="cta"],
[class*="CTA"] {
  color: var(--lumi-text-inverse);
  background:
    linear-gradient(135deg, var(--lumi-sage-600), var(--lumi-sage-500));
  border-color: rgba(255, 253, 248, 0.36);
  box-shadow: var(--lumi-shadow-button);
}

/* Common green/sage buttons: brighten surface + ensure readable text */
button:not([disabled]),
a[role="button"],
.btn,
.button {
  border-radius: var(--lumi-radius-pill);
  font-weight: 700;
  letter-spacing: -0.01em;
}

button:not([disabled]):hover,
a[role="button"]:hover,
.btn:hover,
.button:hover {
  transform: translateY(-1px);
  filter: saturate(1.03) brightness(1.02);
}

/* If buttons use pale sage backgrounds, force high-contrast deep text */
button[style*="sage"],
button[style*="green"],
a[style*="sage"],
a[style*="green"],
[class*="sage"] button,
[class*="green"] button {
  color: var(--lumi-text-strong);
}

/* Disabled buttons must remain readable */
button:disabled,
[aria-disabled="true"] {
  color: rgba(16, 47, 43, 0.58);
  background: rgba(223, 234, 219, 0.48);
  border-color: rgba(49, 91, 77, 0.12);
}

/* Accessible focus ring */
button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid rgba(157, 224, 255, 0.95);
  outline-offset: 4px;
  box-shadow: 0 0 0 7px rgba(157, 224, 255, 0.22);
}

/* Cards and sections: more premium, less flat */
section,
.card,
[class*="Card"],
[class*="panel"],
[class*="Panel"],
[class*="surface"],
[class*="Surface"] {
  border-color: var(--lumi-border-soft);
}

.card,
[class*="Card"] {
  box-shadow: var(--lumi-shadow-soft);
}

/* Hero / journey areas: reduce empty flatness */
[class*="hero"],
[class*="Hero"],
[class*="journey"],
[class*="Journey"],
[class*="gentle"],
[class*="Gentle"] {
  position: relative;
  isolation: isolate;
}

[class*="hero"]::before,
[class*="Hero"]::before,
[class*="journey"]::before,
[class*="Journey"]::before {
  content: "";
  position: absolute;
  inset: -2rem;
  pointer-events: none;
  z-index: -1;
  background:
    radial-gradient(circle at 24% 24%, rgba(255, 214, 110, 0.18), transparent 32%),
    radial-gradient(circle at 78% 28%, rgba(157, 224, 255, 0.22), transparent 34%),
    radial-gradient(circle at 50% 78%, rgba(255, 198, 207, 0.18), transparent 38%);
  filter: blur(2px);
}

/* Lumi image treatment */
img[alt*="Lumi"],
img[alt*="lumi"],
[class*="lumi"] img,
[class*="Lumi"] img {
  filter:
    drop-shadow(0 22px 34px rgba(49, 91, 77, 0.16))
    drop-shadow(0 0 22px rgba(255, 214, 110, 0.18));
  transform-origin: center bottom;
  animation: lumiFloat 7.5s var(--lumi-ease) infinite, lumiGlow 5.8s ease-in-out infinite;
}

/* Living Lumi wrappers */
.lumi-presence,
[class*="LumiPresence"],
[class*="lumi-presence"] {
  position: relative;
  isolation: isolate;
}

.lumi-presence::before,
[class*="LumiPresence"]::before,
[class*="lumi-presence"]::before {
  content: "";
  position: absolute;
  inset: 8%;
  z-index: -1;
  border-radius: 50%;
  background:
    radial-gradient(circle, rgba(255, 214, 110, 0.34), transparent 48%),
    radial-gradient(circle, rgba(157, 224, 255, 0.22), transparent 64%);
  filter: blur(18px);
  animation: lumiPulse 4.8s ease-in-out infinite;
}

.lumi-presence::after,
[class*="LumiPresence"]::after,
[class*="lumi-presence"]::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    radial-gradient(circle, rgba(145, 173, 134, 0.40) 0 1px, transparent 2px),
    radial-gradient(circle, rgba(255, 214, 110, 0.38) 0 1px, transparent 2px),
    radial-gradient(circle, rgba(157, 224, 255, 0.34) 0 1px, transparent 2px);
  background-size: 80px 80px, 120px 120px, 160px 160px;
  background-position: 10px 20px, 40px 70px, 90px 30px;
  opacity: .55;
  animation: lumiSparkleDrift 18s linear infinite;
}

/* Pills / tags */
[class*="tag"],
[class*="Tag"],
[class*="pill"],
[class*="Pill"],
.badge,
[class*="Badge"] {
  color: var(--lumi-text-main);
  background: rgba(255, 253, 248, 0.68);
  border: 1px solid var(--lumi-border-soft);
  box-shadow: 0 6px 18px rgba(49, 91, 77, 0.06);
}

/* Inputs */
input,
textarea,
select {
  color: var(--lumi-text-main);
  background: rgba(255, 253, 248, 0.92);
  border-color: var(--lumi-border-soft);
}

input::placeholder,
textarea::placeholder {
  color: rgba(95, 117, 109, 0.62);
}

/* Top banner readability */
[class*="banner"],
[class*="Banner"],
[class*="notice"],
[class*="Notice"],
[class*="announcement"],
[class*="Announcement"] {
  color: var(--lumi-text-main);
}

/* Safer readable text gradients: do not let text become too pale */
h1,
h2,
h3,
h4 {
  color: var(--lumi-text-strong);
}

p,
li {
  color: var(--lumi-text-main);
}

/* Utility classes for future components */
.lumi-soft-page {
  background:
    radial-gradient(circle at 12% 10%, rgba(255, 214, 110, .18), transparent 30%),
    radial-gradient(circle at 88% 14%, rgba(157, 224, 255, .22), transparent 28%),
    linear-gradient(180deg, var(--lumi-cream-00), var(--lumi-sage-25));
}

.lumi-glass-card {
  background: rgba(255, 253, 248, 0.78);
  border: 1px solid var(--lumi-border-soft);
  border-radius: var(--lumi-radius-lg);
  box-shadow: var(--lumi-shadow-card);
  backdrop-filter: blur(18px);
}

.lumi-button-primary {
  color: var(--lumi-text-inverse);
  background: linear-gradient(135deg, var(--lumi-sage-700), var(--lumi-sage-500));
  border: 1px solid rgba(255, 253, 248, .34);
  border-radius: var(--lumi-radius-pill);
  box-shadow: var(--lumi-shadow-button);
}

.lumi-button-soft {
  color: var(--lumi-text-strong);
  background: linear-gradient(135deg, rgba(255,253,248,.92), rgba(223,234,219,.70));
  border: 1px solid var(--lumi-border-sage);
  border-radius: var(--lumi-radius-pill);
  box-shadow: 0 10px 24px rgba(49, 91, 77, .10);
}

.lumi-gradient-text {
  color: var(--lumi-text-strong);
  background: linear-gradient(90deg, var(--lumi-sage-700), var(--lumi-sage-500), #b18d25);
  -webkit-background-clip: text;
  background-clip: text;
}

/* Motion */
@keyframes lumiFloat {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-8px) scale(1.012); }
}

@keyframes lumiGlow {
  0%, 100% {
    filter:
      drop-shadow(0 22px 34px rgba(49, 91, 77, 0.16))
      drop-shadow(0 0 20px rgba(255, 214, 110, 0.16));
  }
  50% {
    filter:
      drop-shadow(0 28px 42px rgba(49, 91, 77, 0.20))
      drop-shadow(0 0 34px rgba(255, 214, 110, 0.32));
  }
}

@keyframes lumiPulse {
  0%, 100% { opacity: .50; transform: scale(.98); }
  50% { opacity: .82; transform: scale(1.04); }
}

@keyframes lumiSparkleDrift {
  0% { background-position: 10px 20px, 40px 70px, 90px 30px; }
  100% { background-position: 90px 80px, 140px 10px, 10px 130px; }
}

@media (prefers-reduced-motion: reduce) {
  img[alt*="Lumi"],
  img[alt*="lumi"],
  [class*="lumi"] img,
  [class*="Lumi"] img,
  .lumi-presence::before,
  .lumi-presence::after,
  [class*="LumiPresence"]::before,
  [class*="LumiPresence"]::after,
  [class*="lumi-presence"]::before,
  [class*="lumi-presence"]::after {
    animation: none !important;
  }

  button,
  a,
  .btn,
  .button {
    transition: none !important;
  }
}

/* Mobile polish */
@media (max-width: 768px) {
  body {
    background:
      radial-gradient(circle at 50% 8%, rgba(255, 214, 110, 0.14), transparent 34%),
      linear-gradient(180deg, var(--lumi-cream-00), var(--lumi-cream-50));
  }

  img[alt*="Lumi"],
  img[alt*="lumi"],
  [class*="lumi"] img,
  [class*="Lumi"] img {
    max-width: min(84vw, 360px);
  }

  button,
  a[role="button"],
  .btn,
  .button {
    min-height: 44px;
  }
}

/*
 * Lumi Design System v2.0 — Token Foundation
 * ADDITIVE ONLY: All variables prefixed with --lumi- to avoid colliding
 * with existing --glp-* and shadcn HSL semantic tokens.
 * Imported additively from client/src/index.css (last in chain).
 */

/* v5.7.8: Fraunces / Crimson Pro removed — these were Lumi-only display/quote fonts.
   Existing fallback chains in this file resolve to self-hosted Playfair Display / Cormorant Garamond instead. */

:root {
  /* ── Sage scale (trust, growth, healing) ───────────────────────── */
  --lumi-sage-50:  hsl(150, 30%, 96%);
  --lumi-sage-100: hsl(150, 28%, 90%);
  --lumi-sage-200: hsl(150, 26%, 80%);
  --lumi-sage-300: hsl(150, 24%, 68%);
  --lumi-sage-400: hsl(150, 26%, 55%);
  --lumi-sage-500: hsl(150, 32%, 42%);
  --lumi-sage-600: hsl(150, 36%, 34%);
  --lumi-sage-700: hsl(150, 38%, 27%);
  --lumi-sage-800: hsl(150, 40%, 20%);
  --lumi-sage-900: hsl(150, 42%, 14%);
  --lumi-sage-950: hsl(150, 44%, 9%);

  /* ── Amber scale (warmth, energy, action / heart-glow) ─────────── */
  --lumi-amber-50:  hsl(36, 92%, 96%);
  --lumi-amber-100: hsl(36, 90%, 90%);
  --lumi-amber-200: hsl(36, 88%, 80%);
  --lumi-amber-300: hsl(36, 86%, 68%);
  --lumi-amber-400: hsl(36, 88%, 56%);
  --lumi-amber-500: hsl(36, 92%, 48%);
  --lumi-amber-600: hsl(34, 90%, 42%);
  --lumi-amber-700: hsl(32, 88%, 35%);
  --lumi-amber-800: hsl(30, 84%, 28%);
  --lumi-amber-900: hsl(28, 80%, 20%);

  /* ── Stone scale (calm, readable, sophisticated text hierarchy) ── */
  --lumi-stone-50:  hsl(36, 14%, 97%);
  --lumi-stone-100: hsl(36, 12%, 92%);
  --lumi-stone-200: hsl(34, 10%, 84%);
  --lumi-stone-300: hsl(32, 9%, 72%);
  --lumi-stone-400: hsl(30, 8%, 58%);
  --lumi-stone-500: hsl(28, 8%, 44%);
  --lumi-stone-600: hsl(28, 9%, 34%);
  --lumi-stone-700: hsl(28, 10%, 25%);
  --lumi-stone-800: hsl(28, 11%, 17%);
  --lumi-stone-900: hsl(28, 12%, 11%);

  /* ── Semantic emotion tokens ──────────────────────────────────── */
  --lumi-calm:    var(--lumi-sage-400);   /* breath, grounding */
  --lumi-growth:  var(--lumi-sage-600);   /* progress, mastery */
  --lumi-love:    hsl(350, 70%, 62%);     /* compassion, care */
  --lumi-insight: hsl(258, 60%, 64%);     /* wisdom, reflection */
  --lumi-energy:  var(--lumi-amber-500);  /* action, motivation */
  --lumi-rest:    hsl(218, 30%, 50%);     /* sleep, rest */

  /* ── Gradients ────────────────────────────────────────────────── */
  --lumi-grad-sage:  linear-gradient(135deg, var(--lumi-sage-300), var(--lumi-sage-600));
  --lumi-grad-amber: linear-gradient(135deg, var(--lumi-amber-300), var(--lumi-amber-600));
  --lumi-grad-hero:  linear-gradient(135deg, var(--lumi-sage-100) 0%, var(--lumi-amber-50) 50%, var(--lumi-sage-200) 100%);
  --lumi-grad-cta:   linear-gradient(135deg, var(--lumi-amber-500), var(--lumi-amber-600));
  --lumi-grad-card:  linear-gradient(180deg, rgba(255,255,255,0.6), rgba(255,255,255,0.2));
  --lumi-grad-glow:  radial-gradient(circle at 50% 50%, var(--lumi-amber-400) 0%, transparent 65%);

  /* ── Typography ───────────────────────────────────────────────── */
  --lumi-font-display: 'Fraunces', 'Playfair Display', Georgia, serif;
  --lumi-font-body:    'Inter', system-ui, -apple-system, sans-serif;
  --lumi-font-quote:   'Crimson Pro', 'Cormorant Garamond', Georgia, serif;

  /* Fluid type scale — clamps for responsive sizing */
  --lumi-text-xs:   clamp(0.75rem, 0.7rem + 0.25vw, 0.875rem);
  --lumi-text-sm:   clamp(0.875rem, 0.8rem + 0.375vw, 1rem);
  --lumi-text-base: clamp(1rem, 0.9rem + 0.5vw, 1.125rem);
  --lumi-text-lg:   clamp(1.125rem, 1rem + 0.625vw, 1.375rem);
  --lumi-text-xl:   clamp(1.375rem, 1.2rem + 0.875vw, 1.75rem);
  --lumi-text-2xl:  clamp(1.75rem, 1.5rem + 1.25vw, 2.5rem);
  --lumi-text-3xl:  clamp(2.25rem, 1.9rem + 1.75vw, 3.5rem);
  --lumi-text-4xl:  clamp(2.75rem, 2.3rem + 2.25vw, 4.5rem);

  --lumi-leading-body:    1.75;
  --lumi-leading-heading: 1.2;
  --lumi-leading-quote:   1.6;

  /* ── Spacing (8px base, 12 steps) ─────────────────────────────── */
  --lumi-space-1: 0.25rem;
  --lumi-space-2: 0.5rem;
  --lumi-space-3: 0.75rem;
  --lumi-space-4: 1rem;
  --lumi-space-5: 1.5rem;
  --lumi-space-6: 2rem;
  --lumi-space-7: 2.5rem;
  --lumi-space-8: 3rem;
  --lumi-space-9: 4rem;
  --lumi-space-10: 5rem;
  --lumi-space-11: 6rem;
  --lumi-space-12: 8rem;

  /* ── Radii / shadows ──────────────────────────────────────────── */
  --lumi-radius-sm: 0.375rem;
  --lumi-radius-md: 0.625rem;
  --lumi-radius-lg: 1rem;
  --lumi-radius-xl: 1.5rem;
  --lumi-radius-pill: 999px;

  --lumi-shadow-1: 0 1px 2px rgba(28, 30, 28, 0.06), 0 2px 6px rgba(28, 30, 28, 0.04);
  --lumi-shadow-2: 0 4px 12px rgba(28, 30, 28, 0.08), 0 2px 4px rgba(28, 30, 28, 0.04);
  --lumi-shadow-3: 0 12px 28px rgba(28, 30, 28, 0.10), 0 4px 10px rgba(28, 30, 28, 0.06);
  --lumi-shadow-glow-amber: 0 0 24px rgba(243, 168, 49, 0.45);
  --lumi-shadow-glow-sage:  0 0 24px rgba(94, 168, 134, 0.35);

  /* ── Default surface mappings (light) ─────────────────────────── */
  --lumi-bg:        var(--lumi-stone-50);
  --lumi-bg-elev:   #ffffff;
  --lumi-bg-muted:  var(--lumi-sage-50);
  --lumi-text:      var(--lumi-stone-900);
  --lumi-text-muted:var(--lumi-stone-600);
  --lumi-border:    var(--lumi-stone-200);
  --lumi-accent:    var(--lumi-sage-600);
  --lumi-accent-fg: #ffffff;

  /* ── Motion ───────────────────────────────────────────────────── */
  --lumi-ease:        cubic-bezier(0.4, 0, 0.2, 1);
  --lumi-ease-out:    cubic-bezier(0.16, 1, 0.3, 1);
  --lumi-dur-quick:   140ms;
  --lumi-dur-normal:  240ms;
  --lumi-dur-slow:    480ms;
  --lumi-dur-breathe: 4s;
}

/* Dark-mode mappings — opt-in via [data-theme="dark"] OR .dark wrapper */
.dark, [data-theme="dark"] {
  --lumi-bg:        var(--lumi-stone-900);
  --lumi-bg-elev:   var(--lumi-stone-800);
  --lumi-bg-muted:  var(--lumi-sage-900);
  --lumi-text:      var(--lumi-stone-50);
  --lumi-text-muted:var(--lumi-stone-300);
  --lumi-border:    var(--lumi-stone-700);
  --lumi-accent:    var(--lumi-sage-300);
  --lumi-accent-fg: var(--lumi-stone-900);
  --lumi-grad-card: linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.01));
}

/* Utility classes — opt-in only */
.font-display-lumi { font-family: var(--lumi-font-display); line-height: var(--lumi-leading-heading); letter-spacing: -0.01em; }
.font-quote-lumi   { font-family: var(--lumi-font-quote); line-height: var(--lumi-leading-quote); font-style: italic; }
.font-body-lumi    { font-family: var(--lumi-font-body); line-height: var(--lumi-leading-body); }

.lumi-text-xs   { font-size: var(--lumi-text-xs); }
.lumi-text-sm   { font-size: var(--lumi-text-sm); }
.lumi-text-base { font-size: var(--lumi-text-base); }
.lumi-text-lg   { font-size: var(--lumi-text-lg); }
.lumi-text-xl   { font-size: var(--lumi-text-xl); }
.lumi-text-2xl  { font-size: var(--lumi-text-2xl); }
.lumi-text-3xl  { font-size: var(--lumi-text-3xl); }
.lumi-text-4xl  { font-size: var(--lumi-text-4xl); }

.lumi-bg          { background: var(--lumi-bg); color: var(--lumi-text); }
.lumi-bg-elev     { background: var(--lumi-bg-elev); color: var(--lumi-text); }
.lumi-text-muted  { color: var(--lumi-text-muted); }
.lumi-border      { border-color: var(--lumi-border); }
.lumi-accent-bg   { background: var(--lumi-accent); color: var(--lumi-accent-fg); }
.lumi-grad-hero-bg { background: var(--lumi-grad-hero); }
.lumi-grad-amber-bg { background: var(--lumi-grad-amber); color: white; }
.lumi-grad-sage-bg { background: var(--lumi-grad-sage); color: white; }

/* ============================================
 * SPEC-COMPATIBLE TOKEN ALIASES
 * ----------------------------------------------
 * The pasted v2.0 Aurora Token spec uses the un-namespaced `--color-*` /
 * `--gradient-*` / `--text-*` / `--space-*` / `--btn-*` naming. Every
 * existing MMHB consumer uses the namespaced `--lumi-*` form. To keep the
 * project authoritative on `--lumi-*` while still letting drop-in spec
 * snippets resolve, we publish thin alias variables here. Each alias is
 * defined ONLY in terms of the underlying `--lumi-*` token, so changing a
 * source value automatically flows through both names. If a token has no
 * direct `--lumi-*` counterpart (e.g. the spec's `--color-warning` /
 * `--color-crisis-light`), we materialize a literal value sourced from the
 * spec verbatim so neither naming convention drifts.
 * ============================================ */
:root {
  /* Sage scale — full ramp 50..950 */
  --color-sage-50:  var(--lumi-sage-50);
  --color-sage-100: var(--lumi-sage-100);
  --color-sage-200: var(--lumi-sage-200);
  --color-sage-300: var(--lumi-sage-300);
  --color-sage-400: var(--lumi-sage-400);
  --color-sage-500: var(--lumi-sage-500);
  --color-sage-600: var(--lumi-sage-600);
  --color-sage-700: var(--lumi-sage-700);
  --color-sage-800: var(--lumi-sage-800);
  --color-sage-900: var(--lumi-sage-900);
  --color-sage-950: var(--lumi-sage-950);

  /* Amber scale — 50..900 */
  --color-amber-50:  var(--lumi-amber-50);
  --color-amber-100: var(--lumi-amber-100);
  --color-amber-200: var(--lumi-amber-200);
  --color-amber-300: var(--lumi-amber-300);
  --color-amber-400: var(--lumi-amber-400);
  --color-amber-500: var(--lumi-amber-500);
  --color-amber-600: var(--lumi-amber-600);
  --color-amber-700: var(--lumi-amber-700);
  --color-amber-800: var(--lumi-amber-800);
  --color-amber-900: var(--lumi-amber-900);

  /* Stone scale — 50..900 */
  --color-stone-50:  var(--lumi-stone-50);
  --color-stone-100: var(--lumi-stone-100);
  --color-stone-200: var(--lumi-stone-200);
  --color-stone-300: var(--lumi-stone-300);
  --color-stone-400: var(--lumi-stone-400);
  --color-stone-500: var(--lumi-stone-500);
  --color-stone-600: var(--lumi-stone-600);
  --color-stone-700: var(--lumi-stone-700);
  --color-stone-800: var(--lumi-stone-800);
  --color-stone-900: var(--lumi-stone-900);

  /* Semantic colors — base + light surface variants. The base hue is the
   * existing `--lumi-*` token; the `-light` companion is materialized from
   * the spec since we did not previously expose a tinted surface for these. */
  --color-calm:        var(--lumi-calm);
  --color-calm-light:  #d4ede4;
  --color-growth:      var(--lumi-growth);
  --color-growth-light:#e1edd3;
  --color-love:        var(--lumi-love);
  --color-love-light:  #f5d4cc;
  --color-insight:     var(--lumi-insight);
  --color-insight-light:#d8e0f0;
  --color-energy:      var(--lumi-energy);
  --color-energy-light:#fcebc7;
  --color-rest:        var(--lumi-rest);
  --color-rest-light:  #e5deec;

  /* Functional / interface colors — sourced from spec */
  --color-white:         #ffffff;
  --color-black:         #000000;
  --color-crisis:        #c45b4a;
  --color-crisis-light:  #f0d4d0;
  --color-warning:       #d4943a;
  --color-warning-light: #f5e5d0;

  /* Gradient aliases */
  --gradient-sage:  var(--lumi-grad-sage);
  --gradient-amber: var(--lumi-grad-amber);
  --gradient-hero:  var(--lumi-grad-hero);
  --gradient-cta:   var(--lumi-grad-cta);
  --gradient-card:  var(--lumi-grad-card);
  --gradient-glow:  var(--lumi-grad-glow);

  /* Type scale aliases — note spec adds md/5xl/6xl which extend the existing
   * lumi range. md sits between sm and lg; 5xl/6xl extend the upper range. */
  --text-xs:   var(--lumi-text-xs);
  --text-sm:   var(--lumi-text-sm);
  --text-base: var(--lumi-text-base);
  --text-md:   clamp(1.0625rem, 1rem + 0.31vw, 1.125rem);
  --text-lg:   var(--lumi-text-lg);
  --text-xl:   var(--lumi-text-xl);
  --text-2xl:  var(--lumi-text-2xl);
  --text-3xl:  var(--lumi-text-3xl);
  --text-4xl:  var(--lumi-text-4xl);
  --text-5xl:  clamp(2.75rem, 2rem + 3.75vw, 4rem);
  --text-6xl:  clamp(3.25rem, 2.2rem + 5.25vw, 5rem);

  /* Line-height + tracking + weight aliases */
  --leading-tight:   1.2;
  --leading-snug:    1.35;
  --leading-normal:  1.6;
  --leading-relaxed: 1.75;
  --leading-loose:   2;
  --tracking-tight:   -0.02em;
  --tracking-normal:   0;
  --tracking-wide:     0.02em;
  --tracking-wider:    0.05em;
  --tracking-widest:   0.1em;
  --weight-light:    300;
  --weight-regular:  400;
  --weight-medium:   500;
  --weight-semibold: 600;
  --weight-bold:     700;

  /* Font-family aliases */
  --font-display: var(--lumi-font-display);
  --font-body:    var(--lumi-font-body);
  --font-accent:  var(--lumi-font-quote);
  --font-mono:    'JetBrains Mono', 'Fira Code', monospace;

  /* Button sizing tokens (spec-only — no prior --lumi-btn-* exposed) */
  --btn-height-sm: 36px;
  --btn-height-md: 44px;
  --btn-height-lg: 56px;
  --btn-height-xl: 64px;
  --btn-padding-sm: 0 16px;
  --btn-padding-md: 0 24px;
  --btn-padding-lg: 0 32px;
  --btn-padding-xl: 0 40px;
  --btn-radius-sm:  8px;
  --btn-radius-md:  12px;
  --btn-radius-lg:  9999px;
  --btn-shadow-rest:   0 1px 2px rgba(26, 25, 23, 0.05);
  --btn-shadow-hover:  0 4px 12px rgba(26, 25, 23, 0.10);
  --btn-shadow-active: 0 1px 2px rgba(26, 25, 23, 0.08) inset;
  --btn-shadow-focus:  0 0 0 3px rgba(90, 138, 90, 0.30);

  /* Spacing aliases — map to existing --lumi-space-N */
  --space-1:  var(--lumi-space-1);
  --space-2:  var(--lumi-space-2);
  --space-3:  var(--lumi-space-3);
  --space-4:  var(--lumi-space-4);
  --space-5:  var(--lumi-space-5);
  --space-6:  var(--lumi-space-6);
  --space-8:  var(--lumi-space-8);
  --space-10: var(--lumi-space-10);
  --space-12: var(--lumi-space-12);
  --space-16: 64px;
  --space-20: 80px;
}

/* Spec uses [data-theme="dark"]; existing system uses .dark on <html>.
 * Mirror the spec selector so either trigger surfaces dark tokens. */
[data-theme="dark"] {
  --color-bg-primary:    var(--lumi-sage-950);
  --color-bg-secondary:  var(--lumi-sage-900);
  --color-bg-card:       var(--lumi-sage-800);
  --color-bg-elevated:   var(--lumi-sage-700);
  --color-text-primary:   var(--lumi-stone-100);
  --color-text-secondary: var(--lumi-stone-300);
  --color-text-muted:     var(--lumi-stone-500);
  --color-border:         var(--lumi-sage-700);
  --color-border-subtle:  var(--lumi-sage-800);
  --color-accent:         var(--lumi-amber-400);
  --color-accent-hover:   var(--lumi-amber-300);
  --gradient-hero:        linear-gradient(180deg, var(--lumi-sage-950) 0%, var(--lumi-sage-900) 100%);
}

:root {
  --lumi-sage-50: #F4F8F1;
