  --lumi-eternal-cream-50: #fffdf9;
  --lumi-eternal-cream-100: #fff9f2;
  --lumi-eternal-cream-200: #f7f0e8;
  --lumi-eternal-cream-300: #efe5d7;

  --lumi-healing-gold-100: #fff1bd;
  --lumi-healing-gold-200: #ffe38f;
  --lumi-healing-gold-300: #ffd46b;
  --lumi-healing-gold-400: #f6c14b;
  --lumi-healing-gold-500: #e2aa2b;

  --lumi-compassion-rose-100: #fff0f2;
  --lumi-compassion-rose-200: #ffd6da;
  --lumi-compassion-rose-300: #f9bec5;

  --lumi-hope-sky-100: #eafbff;
  --lumi-hope-sky-200: #aee9ff;
  --lumi-hope-sky-300: #77d8ff;

  --lumi-readable-ink: #243024;
  --lumi-readable-ink-soft: #374637;
  --lumi-readable-on-sage: #172517;
  --lumi-readable-on-gold: #2e2608;
  --lumi-readable-on-dark: #fffdf9;

  --lumi-focus-ring: 0 0 0 4px rgba(255, 212, 107, 0.42);
  --lumi-soft-border: rgba(36, 48, 36, 0.14);
  --lumi-card-glow: 0 22px 70px rgba(144, 175, 133, 0.22);
  --lumi-gold-glow: 0 18px 55px rgba(255, 212, 107, 0.28);
}

