/* MMHB public pages: scoped palette, readable controls, no automatic motion. */
.mm-public {
  --mp-paper:#faf8f2; --mp-card:#fffdf8; --mp-heading:#293329;
  --mp-text:#293329; --mp-primary:#3f6249; --mp-on-primary:#fffdf8;
