  --mp-text:#eaf0e6; --mp-primary:#bcd3be; --mp-on-primary:#293329;
  --mp-soft:#304d39; --mp-accent:#49372e; --mp-border:#9bab8d;
}
.mm-public *, .mm-public *::before, .mm-public *::after { box-sizing:border-box; }
.mm-public :is(h1,h2,h3,p,strong,summary,li,a,span) {
  -webkit-text-fill-color:currentColor !important; text-shadow:none !important;
  background-image:none !important; filter:none !important;
}
.mm-public :is(h1,h2,h3) { color:var(--mp-heading) !important; margin:0 0 .8rem; text-wrap:balance; }
