.mm-public a { color:var(--mp-primary) !important; }
.mm-public .mp-button { display:inline-flex; align-items:center; justify-content:center; min-height:48px; padding:12px 20px; border:1px solid var(--mp-primary) !important; border-radius:12px; color:var(--mp-primary) !important; background:var(--mp-card) !important; font:600 1rem/1.5 Inter,system-ui,sans-serif; text-decoration:none !important; text-align:center; box-shadow:none !important; opacity:1 !important; transform:none !important; }
.mm-public .mp-primary { color:var(--mp-on-primary) !important; background:var(--mp-primary) !important; }
