@media(max-width:640px) { .mm-public .mp-grid { grid-template-columns:1fr; } .mm-public .mp-button { width:100%; } }
@media(prefers-reduced-motion:reduce) { .mm-public *, .mm-public *::before, .mm-public *::after { animation:none !important; transition:none !important; scroll-behavior:auto !important; } }
@media(forced-colors:active) { .mm-public .mp-button, .mm-public .mp-card, .mm-public details { border:1px solid ButtonText !important; } .mm-public :is(a,summary):focus-visible { outline-color:Highlight !important; } }

