/* ────────────────────────────────────────────────────────────────────────
   peacescape-shell.css — Sanctuary Depth for the Peace Scape surface
   Scoped to `.peacescape-shell` so effects never leak to other pages.

   The hero ZenScape already provides ambient depth, so this file focuses
   on the supporting cards: roadmap-phase tiles and bottom callouts.
   Honors prefers-reduced-motion.
   ──────────────────────────────────────────────────────────────────────── */

.peacescape-shell {
  position: relative;
}

/* Soft floating gold/sage radial accents behind the scape */
.peacescape-shell::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(ellipse 50% 35% at 15% 15%,
      rgba(190, 134, 34, 0.05) 0%,
      transparent 65%),
    radial-gradient(ellipse 55% 40% at 85% 85%,
      rgba(30, 200, 144, 0.05) 0%,
      transparent 70%);
  pointer-events: none;
}

/* ── Roadmap phase cards — sanctuary depth + animated accent ──────────── */
.peacescape-shell [data-testid^='card-roadmap-phase-'] {
  position: relative;
  overflow: hidden;
  transition:
    transform 0.4s cubic-bezier(0.23, 1, 0.32, 1),
    box-shadow 0.4s ease,
    border-color 0.4s ease !important;
}

.peacescape-shell [data-testid^='card-roadmap-phase-']::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg,
    transparent 0%,
    rgba(190, 134, 34, 0.55) 30%,
    rgba(30, 200, 144, 0.65) 50%,
    rgba(190, 134, 34, 0.55) 70%,
    transparent 100%);
  opacity: 0.4;
  transition: opacity 0.5s ease;
  pointer-events: none;
}

.peacescape-shell [data-testid^='card-roadmap-phase-']:hover {
  transform: translateY(-2px);
  border-color: rgba(30, 200, 144, 0.30) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 6px 18px rgba(6, 42, 42, 0.08),
    0 18px 38px rgba(6, 42, 42, 0.07) !important;
}

.peacescape-shell [data-testid^='card-roadmap-phase-']:hover::before {
  opacity: 0.95;
}

/* The "live now" first card gets a subtle gold ring to denote presence */
.peacescape-shell [data-testid='card-roadmap-phase-1'] {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    0 0 0 1px rgba(190, 134, 34, 0.18),
    0 4px 16px -8px rgba(45, 80, 60, 0.12) !important;
}

/* ── Bottom callouts — refined sanctuary feel ────────────────────────── */
.peacescape-shell [data-testid='callout-customizer'],
.peacescape-shell [data-testid='callout-companion'] {
  position: relative;
  overflow: hidden;
  background: linear-gradient(180deg,
    rgba(255, 255, 255, 0.96) 0%,
    rgba(252, 246, 234, 0.45) 100%) !important;
  border-color: rgba(30, 200, 144, 0.20) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 2px 8px rgba(6, 42, 42, 0.04),
    0 12px 28px rgba(6, 42, 42, 0.05) !important;
  transition:
    box-shadow 0.4s ease,
    border-color 0.4s ease,
    transform 0.4s cubic-bezier(0.23, 1, 0.32, 1) !important;
}

.peacescape-shell [data-testid='callout-customizer']::before,
.peacescape-shell [data-testid='callout-companion']::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
  background: linear-gradient(180deg,
    rgba(190, 134, 34, 0.50) 0%,
    rgba(30, 200, 144, 0.65) 50%,
    rgba(190, 134, 34, 0.50) 100%);
  opacity: 0.55;
  transition: opacity 0.5s ease;
  pointer-events: none;
}

.peacescape-shell [data-testid='callout-customizer']:hover,
.peacescape-shell [data-testid='callout-companion']:hover {
  transform: translateY(-1px);
  border-color: rgba(30, 200, 144, 0.32) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 4px 14px rgba(6, 42, 42, 0.06),
    0 22px 42px rgba(6, 42, 42, 0.07) !important;
}

.peacescape-shell [data-testid='callout-customizer']:hover::before,
.peacescape-shell [data-testid='callout-companion']:hover::before {
  opacity: 0.95;
}

/* ── Roadmap section heading — soft serif emphasis ───────────────────── */
.peacescape-shell [data-testid='text-roadmap-title'] {
  background: linear-gradient(135deg,
    var(--glp-sage-deep, #062a2a) 0%,
    #0d4a3d 50%,
    var(--glp-sage-deep, #062a2a) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  letter-spacing: -0.01em;
}

/* ── Reduced-motion compliance ───────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .peacescape-shell [data-testid^='card-roadmap-phase-'],
  .peacescape-shell [data-testid^='card-roadmap-phase-']:hover,
  .peacescape-shell [data-testid^='card-roadmap-phase-']::before,
  .peacescape-shell [data-testid='callout-customizer'],
  .peacescape-shell [data-testid='callout-customizer']:hover,
  .peacescape-shell [data-testid='callout-companion'],
  .peacescape-shell [data-testid='callout-companion']:hover {
    transition: none;
    transform: none;
  }
}

:root {
  --mmhb-text-strong: #111827;
  --mmhb-text-body: #374151;
  --mmhb-surface: rgba(255, 255, 255, 0.94);
  --mmhb-surface-soft: rgba(255, 255, 255, 0.78);
  --mmhb-border: rgba(17, 24, 39, 0.12);
  --mmhb-shadow: 0 18px 48px rgba(17, 24, 39, 0.12);
  --mmhb-radius: 22px;
}

body {
  color: var(--mmhb-text-body);
  text-rendering: optimizeLegibility;
}

main,
section,
article {
  overflow-wrap: anywhere;
}

h1,
h2,
h3,
h4 {
  color: var(--mmhb-text-strong);
  letter-spacing: -0.035em;
  line-height: 1.08;
}

p,
li {
  line-height: 1.72;
}

button,
a[role="button"],
.btn,
.button {
  min-height: 44px;
  color: inherit;
  font-weight: 700;
  line-height: 1.15;
  text-align: center;
  white-space: normal;
  overflow-wrap: anywhere;
}

button:not(:disabled),
a[href],
[role="button"] {
  cursor: pointer;
}

button:focus-visible,
a:focus-visible,
input:focus-visible,
textarea:focus-visible,
select:focus-visible {
  outline: 3px solid rgba(99, 102, 241, 0.55);
  outline-offset: 3px;
}

button:disabled,
[aria-disabled="true"] {
  opacity: 0.58;
  cursor: not-allowed;
}

.card,
.panel,
.dashboard-card,
.pricing-card,
[class*="Card"],
[class*="Panel"] {
  border-color: var(--mmhb-border);
}

img,
svg,
video {
  max-width: 100%;
  height: auto;
}

/* a11y-lint indicator REMOVED — this red dashed outline on unlabeled images
   was a development audit helper that leaked into production and rendered as
   "red squares" around decorative avatars (NlpMiContent / VisualBenefits).
   Decorative images carry alt="" by design; enforcement belongs in tooling,
   never as a user-visible outline. Do not re-add a visible outline here. */

.prose,
.content,
.page-content {
  max-width: 78ch;
}

.pricing-card,
[class*="pricing"],
[class*="Premium"],
[class*="Billing"] {
  scroll-margin-top: 96px;
}

@media (max-width: 768px) {
  h1 {
    font-size: clamp(2rem, 12vw, 3.5rem);
  }

  h2 {
    font-size: clamp(1.55rem, 8vw, 2.5rem);
  }

  button,
  a[role="button"],
  .btn,
  .button {
    width: 100%;
  }
}

/**
 * Sacred Typography - Type Scale Utilities
 * The Genuine Love Project
 * 
 * Typography: Playfair Display (headings), Inter (body/UI)
 * Scale: Title 56, Subtitle 36, Heading 32, Subheading 28, Section 24, Body 18, Quote 20 italic, Caption 14
 */

/* Fonts self-hosted via @font-face in client/index.html (v5.7.8) */

/* Sacred font families */
.font-sacred,
.font-display {
  font-family: 'Playfair Display', 'Cormorant Garamond', Georgia, serif;
}

.font-body {
  font-family: 'Inter', 'Poppins', system-ui, sans-serif;
}

/* ============================================
   TYPE SCALE UTILITIES (Sacred-Grade)
   ============================================ */

/* Title - 56px / 3.5rem */
.type-title {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 3.5rem;
  font-weight: 600;
  line-height: 1.1;
  letter-spacing: -0.02em;
  color: var(--sacred-charcoal, #3a3a3a);
}

/* Subtitle - 36px / 2.25rem */
.type-subtitle {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 2.25rem;
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--sacred-charcoal, #3a3a3a);
}

/* Heading - 32px / 2rem */
.type-heading {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 2rem;
  font-weight: 600;
  line-height: 1.25;
  color: var(--sacred-charcoal, #3a3a3a);
}

/* Subheading - 28px / 1.75rem */
.type-subheading {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.75rem;
  font-weight: 500;
  line-height: 1.3;
  color: var(--sacred-charcoal, #3a3a3a);
}

/* Section - 24px / 1.5rem */
.type-section {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.5rem;
  font-weight: 500;
  line-height: 1.35;
  color: var(--sacred-charcoal, #3a3a3a);
}

/* Body - 18px / 1.125rem */
.type-body {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 1.125rem;
  font-weight: 400;
  line-height: 1.6;
  color: var(--sacred-charcoal, #3a3a3a);
}

/* Quote - 20px italic / 1.25rem */
.type-quote {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 1.25rem;
  font-weight: 400;
  font-style: italic;
  line-height: 1.5;
  color: var(--sacred-teal, #2f5d5d);
}

/* Caption - 14px light / 0.875rem */
.type-caption {
  font-family: 'Inter', system-ui, sans-serif;
  font-size: 0.875rem;
