/* Sacred Visual Styles - The Genuine Love Project */

/* Playfair Display self-hosted via @font-face in client/index.html (v5.7.8) */

.font-playfair {
  font-family: 'Playfair Display', Georgia, 'Times New Roman', serif;
}

/* ============================================
   LOTUS BLOSSOM ANIMATION
   ============================================ */
@keyframes lotusBlossom {
  0% {
    transform: scale(0.8) rotate(0deg);
    opacity: 0.6;
  }
  25% {
    transform: scale(1) rotate(15deg);
    opacity: 0.9;
  }
  50% {
    transform: scale(1.1) rotate(0deg);
    opacity: 1;
  }
  75% {
    transform: scale(1) rotate(-15deg);
    opacity: 0.9;
  }
  100% {
    transform: scale(0.8) rotate(0deg);
    opacity: 0.6;
  }
}

@keyframes lotusGlow {
  0%, 100% {
    box-shadow: 0 0 20px rgba(244, 114, 182, 0.3),
                0 0 40px rgba(251, 191, 36, 0.2),
                0 0 60px rgba(167, 139, 250, 0.1);
  }
  50% {
    box-shadow: 0 0 30px rgba(244, 114, 182, 0.5),
                0 0 60px rgba(251, 191, 36, 0.3),
                0 0 90px rgba(167, 139, 250, 0.2);
  }
}

@keyframes petalFloat {
  0% {
    transform: translateY(0) rotate(0deg) scale(1);
    opacity: 1;
  }
  100% {
    transform: translateY(-100px) rotate(45deg) scale(0);
    opacity: 0;
  }
}

.lotus-blossom {
  animation: lotusBlossom 6s ease-in-out infinite;
}

.lotus-glow {
  animation: lotusGlow 3s ease-in-out infinite;
}

.petal-float {
  animation: petalFloat 4s ease-out forwards;
}

/* ============================================
   MOOD-BASED GLOW RINGS
   ============================================ */
@keyframes glowPulse {
  0%, 100% {
    opacity: 0.5;
    transform: scale(1);
  }
  50% {
    opacity: 0.8;
    transform: scale(1.05);
  }
}

.glow-ring {
  position: absolute;
  inset: -3px;
  border-radius: inherit;
  pointer-events: none;
  animation: glowPulse 3s ease-in-out infinite;
}

.glow-ring-joy {
  background: linear-gradient(135deg, rgba(250, 204, 21, 0.4), rgba(251, 191, 36, 0.2));
  box-shadow: 0 0 20px rgba(250, 204, 21, 0.3), inset 0 0 20px rgba(250, 204, 21, 0.1);
}

.glow-ring-calm {
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.4), rgba(14, 165, 233, 0.2));
  box-shadow: 0 0 20px rgba(56, 189, 248, 0.3), inset 0 0 20px rgba(56, 189, 248, 0.1);
}

.glow-ring-grateful {
  background: linear-gradient(135deg, rgba(244, 114, 182, 0.4), rgba(236, 72, 153, 0.2));
  box-shadow: 0 0 20px rgba(244, 114, 182, 0.3), inset 0 0 20px rgba(244, 114, 182, 0.1);
}

.glow-ring-hopeful {
  background: linear-gradient(135deg, rgba(74, 222, 128, 0.4), rgba(34, 197, 94, 0.2));
  box-shadow: 0 0 20px rgba(74, 222, 128, 0.3), inset 0 0 20px rgba(74, 222, 128, 0.1);
}

.glow-ring-healing {
  background: linear-gradient(135deg, rgba(45, 212, 191, 0.4), rgba(20, 184, 166, 0.2));
  box-shadow: 0 0 20px rgba(45, 212, 191, 0.3), inset 0 0 20px rgba(45, 212, 191, 0.1);
}

.glow-ring-loved {
  background: linear-gradient(135deg, rgba(251, 113, 133, 0.4), rgba(244, 63, 94, 0.2));
  box-shadow: 0 0 20px rgba(251, 113, 133, 0.3), inset 0 0 20px rgba(251, 113, 133, 0.1);
}

.glow-ring-sad {
  background: linear-gradient(135deg, rgba(129, 140, 248, 0.4), rgba(99, 102, 241, 0.2));
  box-shadow: 0 0 20px rgba(129, 140, 248, 0.3), inset 0 0 20px rgba(129, 140, 248, 0.1);
}

.glow-ring-anxious {
  background: linear-gradient(135deg, rgba(251, 146, 60, 0.4), rgba(249, 115, 22, 0.2));
  box-shadow: 0 0 20px rgba(251, 146, 60, 0.3), inset 0 0 20px rgba(251, 146, 60, 0.1);
}

.glow-ring-balanced {
  background: linear-gradient(135deg, rgba(167, 139, 250, 0.4), rgba(139, 92, 246, 0.2));
  box-shadow: 0 0 20px rgba(167, 139, 250, 0.3), inset 0 0 20px rgba(167, 139, 250, 0.1);
}

/* ============================================
   PASTEL GRADIENT BACKGROUNDS
   ============================================ */
.bg-sunrise {
  background: linear-gradient(135deg, 
    hsl(35, 100%, 95%) 0%, 
    hsl(350, 100%, 92%) 50%, 
    hsl(280, 80%, 92%) 100%);
}

.bg-moonlight {
  background: linear-gradient(135deg, 
    hsl(230, 60%, 92%) 0%, 
    hsl(260, 50%, 88%) 50%, 
    hsl(280, 40%, 90%) 100%);
}

.bg-dawn {
  background: linear-gradient(135deg, 
    hsl(210, 50%, 92%) 0%, 
    hsl(340, 60%, 92%) 50%, 
    hsl(40, 80%, 94%) 100%);
}

/* Dark mode variants */
.dark .bg-sunrise {
  background: linear-gradient(135deg, 
    hsl(35, 40%, 12%) 0%, 
    hsl(350, 40%, 10%) 50%, 
    hsl(280, 30%, 12%) 100%);
}

.dark .bg-moonlight {
  background: linear-gradient(135deg, 
    hsl(230, 30%, 10%) 0%, 
    hsl(260, 25%, 12%) 50%, 
    hsl(280, 20%, 10%) 100%);
}

.dark .bg-dawn {
  background: linear-gradient(135deg, 
    hsl(210, 25%, 10%) 0%, 
    hsl(340, 30%, 10%) 50%, 
    hsl(40, 35%, 12%) 100%);
}

/* ============================================
   GLOW BORDER FOR CARDS
   ============================================ */
.glow-border {
  position: relative;
  overflow: visible;
}

.glow-border::before {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: inherit;
  background: linear-gradient(135deg, 
    rgba(167, 139, 250, 0.5), 
    rgba(244, 114, 182, 0.5), 
    rgba(251, 191, 36, 0.5));
  z-index: -1;
  filter: blur(8px);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.glow-border:hover::before {
  opacity: 1;
}

.glow-border-active::before {
  opacity: 1;
}

/* Blessed reflection glow */
.blessed-glow {
  box-shadow: 
    0 0 10px rgba(251, 191, 36, 0.3),
    0 0 20px rgba(244, 114, 182, 0.2),
    0 0 30px rgba(167, 139, 250, 0.1);
  animation: blessedPulse 2s ease-in-out infinite;
}

@keyframes blessedPulse {
  0%, 100% {
    box-shadow: 
      0 0 10px rgba(251, 191, 36, 0.3),
      0 0 20px rgba(244, 114, 182, 0.2),
      0 0 30px rgba(167, 139, 250, 0.1);
  }
  50% {
    box-shadow: 
      0 0 15px rgba(251, 191, 36, 0.5),
      0 0 30px rgba(244, 114, 182, 0.3),
      0 0 45px rgba(167, 139, 250, 0.2);
  }
}

/* ============================================
   SACRED ANIMATIONS
   ============================================ */
@keyframes sacredFadeIn {
  from {
    opacity: 0;
    transform: translateY(20px) scale(0.95);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes sacredFloat {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-10px);
  }
}

@keyframes sacredShimmer {
  0% {
    background-position: -200% 0;
  }
  100% {
    background-position: 200% 0;
  }
}

.sacred-fade-in {
  animation: sacredFadeIn 0.6s ease-out forwards;
}

.sacred-float {
  animation: sacredFloat 4s ease-in-out infinite;
}

.sacred-shimmer {
  background: linear-gradient(90deg, 
    transparent 0%, 
    rgba(255, 255, 255, 0.3) 50%, 
    transparent 100%);
  background-size: 200% 100%;
  animation: sacredShimmer 3s linear infinite;
}

/* ============================================
   QUOTE CARD ENHANCEMENTS
   ============================================ */
.quote-card {
  position: relative;
  overflow: hidden;
}

.quote-card::before {
  content: '"';
  position: absolute;
  top: -20px;
  left: 10px;
  font-size: 120px;
  font-family: 'Playfair Display', serif;
  color: currentColor;
  opacity: 0.1;
  line-height: 1;
}

.quote-card::after {
  content: '';
  position: absolute;
  bottom: 0;
  right: 0;
  width: 60%;
  height: 60%;
  background: radial-gradient(circle at bottom right, 
    rgba(255, 255, 255, 0.1) 0%, 
    transparent 70%);
  pointer-events: none;
}

/* Sacred UI Styles - The Genuine Love Project */
/* GSAP + AOS Animation Utilities with Reduced Motion Safety */

/* =========================================
   Sacred Typography — fonts self-hosted via @font-face in client/index.html (v5.7.8)
   ========================================= */

/* =========================================
   Brand Tokens (EXACT — DO NOT CHANGE)
   ========================================= */
:root {
  /* Core Brand Colors */
  --sacred-sage: #8fbf9f;
  --sacred-rose: #f4c7c3;
  --sacred-teal: #2f5d5d;
  --sacred-white: #faf9f7;
  --sacred-charcoal: #3a3a3a;
  --sacred-gold: #eac33b;

  /* Typography */
  --font-sacred: 'Playfair Display', Georgia, serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;

  /* Animation timing */
  --sacred-timing-slow: 1.5s;
  --sacred-timing-medium: 0.8s;
  --sacred-timing-fast: 0.4s;
  --sacred-easing: cubic-bezier(0.4, 0, 0.2, 1);
  --sacred-easing-bounce: cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* =========================================
   Type Scale Utilities (CANVA EXACT — DO NOT CHANGE)
   Title: 56px, Subtitle: 36px, Heading: 32px,
   Subheading: 28px, Section Header: 24px, Body: 18px,
   Quote: 20px, Caption: 14px
   ========================================= */
.sacred-title {
  font-family: var(--font-sacred);
  font-size: 3.5rem; /* 56px */
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.01em;
  color: var(--sacred-charcoal);
}

.sacred-subtitle {
  font-family: var(--font-sacred);
  font-size: 2.25rem; /* 36px */
  font-weight: 600;
  line-height: 1.2;
  color: var(--sacred-charcoal);
}

.sacred-heading {
  font-family: var(--font-sacred);
  font-size: 2rem; /* 32px */
  font-weight: 500;
  line-height: 1.25;
  color: var(--sacred-charcoal);
}

.sacred-subheading {
  font-family: var(--font-sacred);
  font-size: 1.75rem; /* 28px */
  font-weight: 400;
  line-height: 1.3;
  color: var(--sacred-charcoal);
}

.sacred-section-header {
  font-family: var(--font-body);
  font-size: 1.5rem; /* 24px */
  font-weight: 700;
  line-height: 1.35;
  color: var(--sacred-charcoal);
}

.sacred-body {
  font-family: var(--font-body);
  font-size: 1.125rem; /* 18px */
  font-weight: 400;
  line-height: 1.7;
  color: var(--sacred-charcoal);
}

.sacred-quote {
  font-family: var(--font-body);
  font-size: 1.25rem; /* 20px */
  font-style: italic;
  line-height: 1.6;
  color: var(--sacred-charcoal);
}

.sacred-caption {
  font-family: var(--font-body);
  font-size: 0.875rem; /* 14px */
  font-weight: 300;
  line-height: 1.5;
  color: var(--sacred-charcoal);
}

/* Mobile responsive type scale */
@media (max-width: 768px) {
  .sacred-title { font-size: 2.5rem; /* 40px */ }
  .sacred-subtitle { font-size: 1.75rem; /* 28px */ }
  .sacred-heading { font-size: 1.75rem; /* 28px */ }
  .sacred-subheading { font-size: 1.5rem; /* 24px */ }
  .sacred-section-header { font-size: 1.25rem; /* 20px */ }
  .sacred-body { font-size: 1rem; /* 16px */ }
  .sacred-quote { font-size: 1.125rem; /* 18px */ }
}

/* Legacy class aliases */
.font-sacred {
  font-family: var(--font-sacred);
}

.font-body {
  font-family: var(--font-body);
}

/* =========================================
   Button Sizing Standards (WCAG AA: min 44px)
   ========================================= */
.btn-sacred {
  min-height: 44px;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: all 0.2s ease;
}

.btn-sacred-lg {
  min-height: 52px;
  padding: 14px 32px;
  font-size: 1.125rem;
  font-weight: 600;
  border-radius: 14px;
}

.btn-sacred-primary {
  background: var(--sacred-teal);
  color: var(--sacred-white);
  border: none;
}

.btn-sacred-primary:hover {
  background: #274e4e;
  transform: translateY(-1px);
  box-shadow: 0 4px 16px rgba(47, 93, 93, 0.25);
}

.btn-sacred-secondary {
  background: transparent;
  color: var(--sacred-teal);
  border: 2px solid var(--sacred-teal);
}

.btn-sacred-secondary:hover {
  background: var(--sacred-teal);
  color: var(--sacred-white);
}

/* Spacing Scale Utilities */
.spacing-relaxed {
  --spacing-unit: 1.5rem;
}

.spacing-comfortable {
  --spacing-unit: 2rem;
}

.spacing-spacious {
  --spacing-unit: 3rem;
}

/* =========================================
   GSAP Animation Keyframes
   ========================================= */
@keyframes sacred-breathe {
  0%, 100% {
    transform: scale(1);
    opacity: 1;
  }
  50% {
    transform: scale(1.02);
    opacity: 0.95;
  }
}

@keyframes sacred-pulse {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(143, 191, 159, 0.4);
  }
  50% {
    box-shadow: 0 0 20px 8px rgba(143, 191, 159, 0.1);
  }
}

@keyframes sacred-glow {
  0%, 100% {
    filter: drop-shadow(0 0 8px rgba(234, 195, 59, 0.3));
  }
  50% {
    filter: drop-shadow(0 0 16px rgba(234, 195, 59, 0.5));
  }
}

@keyframes sacred-rotate-glow {
  0% {
    transform: rotate(0deg);
    filter: drop-shadow(0 0 8px rgba(234, 195, 59, 0.3));
  }
  50% {
    filter: drop-shadow(0 0 16px rgba(234, 195, 59, 0.5));
  }
  100% {
    transform: rotate(360deg);
    filter: drop-shadow(0 0 8px rgba(234, 195, 59, 0.3));
  }
}

@keyframes sacred-float {
  0%, 100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}

@keyframes sacred-rotate-slow {
  from {
    transform: rotate(0deg);
  }
  to {
    transform: rotate(360deg);
  }
}

@keyframes sacred-fade-in-up {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes sacred-scale-in {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes sacred-aura {
  0%, 100% {
    opacity: 0.4;
    transform: scale(1);
  }
  50% {
    opacity: 0.6;
    transform: scale(1.02);
  }
}

/* =========================================
   Animation Utility Classes
   ========================================= */
.sacred-animate-breathe {
  animation: sacred-breathe 4s var(--sacred-easing) infinite;
}

.sacred-animate-pulse {
  animation: sacred-pulse 3s var(--sacred-easing) infinite;
}

.sacred-animate-glow {
  animation: sacred-glow 3s var(--sacred-easing) infinite;
}

.sacred-animate-rotate-glow {
  animation: sacred-rotate-glow 20s linear infinite, sacred-breathe 4s var(--sacred-easing) infinite;
}

.sacred-animate-float {
  animation: sacred-float 4s var(--sacred-easing) infinite;
}

.sacred-animate-rotate-slow {
  animation: sacred-rotate-slow 60s linear infinite;
}

.sacred-animate-fade-in-up {
  animation: sacred-fade-in-up var(--sacred-timing-medium) var(--sacred-easing) forwards;
}

.sacred-animate-scale-in {
  animation: sacred-scale-in var(--sacred-timing-medium) var(--sacred-easing) forwards;
}

.sacred-animate-aura {
  animation: sacred-aura 6s var(--sacred-easing) infinite;
}

/* =========================================
   Reduced Motion Safety (REQUIRED)
   ========================================= */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }

  .sacred-animate-breathe,
  .sacred-animate-pulse,
  .sacred-animate-glow,
  .sacred-animate-rotate-glow,
  .sacred-animate-float,
  .sacred-animate-rotate-slow,
  .sacred-animate-fade-in-up,
  .sacred-animate-scale-in,
  .sacred-animate-aura {
    animation: none !important;
  }

  [data-aos] {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
}

/* =========================================
   Sacred Layout Styles
   ========================================= */
.sacred-layout {
  position: relative;
  min-height: 100vh;
  background: var(--sacred-white);
  overflow-x: hidden;
  font-family: var(--font-body);
  color: var(--sacred-charcoal);
}

/* Sacred Pattern Overlay (Layer 1) */
.sacred-pattern-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  z-index: 0;
  opacity: 0.03;
  background-image: url('/brand/sacred-pattern.svg');
  background-repeat: repeat;
  background-size: 300px 300px;
}

/* Aura Gradient Overlay (Layer 2) */
.sacred-aura-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  pointer-events: none;
  z-index: 0;
  background: 
    radial-gradient(ellipse at 20% 20%, rgba(143, 191, 159, 0.08) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 80%, rgba(244, 199, 195, 0.06) 0%, transparent 50%),
    radial-gradient(ellipse at 50% 50%, rgba(234, 195, 59, 0.03) 0%, transparent 70%);
}

@media (prefers-reduced-motion: no-preference) {
  .sacred-aura-overlay {
    animation: sacred-aura 8s var(--sacred-easing) infinite;
  }
}

.sacred-content {
  position: relative;
  z-index: 1;
}

/* =========================================
   Sacred Section Styles
   ========================================= */
.sacred-section {
  position: relative;
  padding: 4rem 1.5rem;
}

@media (min-width: 768px) {
  .sacred-section {
    padding: 6rem 2rem;
  }
}

@media (min-width: 1024px) {
  .sacred-section {
    padding: 8rem 2rem;
  }
}

.sacred-section-inner {
  max-width: 1200px;
  margin: 0 auto;
}

/* Calm Divider */
.sacred-divider {
  width: 100%;
  max-width: 200px;
  height: 1px;
  margin: 3rem auto;
  background: linear-gradient(
    90deg,
    transparent,
    var(--sacred-sage),
    transparent
  );
  opacity: 0.5;
}

/* =========================================
   Sacred Button Styles
   ========================================= */
.sacred-button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.875rem 2rem;
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 0.9375rem;
  border-radius: 9999px;
  border: none;
  cursor: pointer;
  transition: all var(--sacred-timing-fast) var(--sacred-easing);
  text-decoration: none;
  overflow: hidden;
}

.sacred-button::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, transparent 0%, rgba(255, 255, 255, 0.1) 50%, transparent 100%);
  opacity: 0;
  transition: opacity var(--sacred-timing-fast) var(--sacred-easing);
}

.sacred-button:hover::before {
  opacity: 1;
}

.sacred-button:focus-visible {
  outline: 2px solid var(--sacred-gold);
  outline-offset: 3px;
}

.sacred-button--primary {
  background: linear-gradient(135deg, var(--sacred-teal), #3d7a7a);
  color: white;
  box-shadow: 0 4px 16px rgba(47, 93, 93, 0.3);
}

.sacred-button--primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(47, 93, 93, 0.4);
}

.sacred-button--secondary {
  background: transparent;
  color: var(--sacred-teal);
  border: 2px solid var(--sacred-sage);
}

.sacred-button--secondary:hover {
  background: rgba(143, 191, 159, 0.1);
  border-color: var(--sacred-teal);
}

.sacred-button--ghost {
  background: transparent;
  color: var(--sacred-teal);
}

.sacred-button--ghost:hover {
  background: rgba(143, 191, 159, 0.1);
}

/* Icon scaling (REQUIRED: ~30%) */
.sacred-button svg,
.sacred-button .icon,
.sacred-icon {
  transform: scale(0.7);
}

.sacred-icon-sm {
  width: 1rem;
  height: 1rem;
  transform: scale(0.7);
}

.sacred-icon-md {
  width: 1.5rem;
  height: 1.5rem;
  transform: scale(0.7);
}

.sacred-icon-lg {
  width: 2rem;
  height: 2rem;
  transform: scale(0.7);
}

/* =========================================
   Sacred Hero Styles
   ========================================= */
.sacred-hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 4rem 1.5rem;
}

.sacred-hero-logo {
  width: clamp(80px, 15vw, 150px);
  height: auto;
  margin-bottom: 2rem;
}

.sacred-hero-title {
  font-family: var(--font-sacred);
  font-size: clamp(2.5rem, 6vw, 4rem);
  font-weight: 700;
  color: var(--sacred-teal);
  margin-bottom: 1rem;
  line-height: 1.1;
}

.sacred-hero-subtitle {
  font-family: var(--font-body);
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--sacred-charcoal);
  max-width: 600px;
  margin: 0 auto 2rem;
  line-height: 1.7;
}

.sacred-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: center;
}

/* =========================================
   Accessibility Enhancements (REQUIRED)
   ========================================= */
.skip-link {
  position: absolute;
  top: -100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--sacred-teal);
  color: white;
  padding: 0.75rem 1.5rem;
  border-radius: 0 0 0.5rem 0.5rem;
  z-index: 9999;
  transition: top 0.2s ease;
  font-family: var(--font-body);
  font-weight: 500;
  text-decoration: none;
}

.skip-link:focus {
  top: 0;
}

/* Focus visible states */
a:focus-visible,
button:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--sacred-sage);
  outline-offset: 2px;
}

/* =========================================
   AOS Custom Animations
   ========================================= */
[data-aos="sacred-fade-up"] {
  opacity: 0;
  transform: translateY(30px);
  transition-property: opacity, transform;
}

[data-aos="sacred-fade-up"].aos-animate {
  opacity: 1;
  transform: translateY(0);
}

[data-aos="sacred-scale"] {
  opacity: 0;
  transform: scale(0.95);
  transition-property: opacity, transform;
}

[data-aos="sacred-scale"].aos-animate {
  opacity: 1;
  transform: scale(1);
}

[data-aos="sacred-fade-left"] {
  opacity: 0;
  transform: translateX(-30px);
  transition-property: opacity, transform;
}

[data-aos="sacred-fade-left"].aos-animate {
  opacity: 1;
  transform: translateX(0);
}

[data-aos="sacred-fade-right"] {
  opacity: 0;
  transform: translateX(30px);
  transition-property: opacity, transform;
}

[data-aos="sacred-fade-right"].aos-animate {
  opacity: 1;
  transform: translateX(0);
}

/* tokens.css - Extended utility classes for The Genuine Love Project */
/* These extend Tailwind with brand-specific utilities */

/* =============================================================================
   VISUAL CONSISTENCY TOKENS (Process-085)
   ============================================================================= */

:root {
  /* Button Sizing Tokens */
  --btn-min-height: 44px;
  --btn-min-height-sm: 36px;
  --btn-min-height-lg: 52px;
  --btn-padding-x: 1.5rem;
  --btn-padding-x-sm: 1rem;
  --btn-padding-x-lg: 2rem;
  --btn-padding-y: 0.75rem;
  --btn-padding-y-sm: 0.5rem;
  --btn-padding-y-lg: 1rem;
  --btn-font-size: 1rem;
  --btn-font-size-sm: 0.875rem;
  --btn-font-size-lg: 1.125rem;
  --btn-border-radius: 9999px;

  /* Heading Scale Tokens (Mobile First) */
  --heading-h1: clamp(1.75rem, 5vw, 2.5rem);
  --heading-h2: clamp(1.5rem, 4vw, 2rem);
  --heading-h3: clamp(1.25rem, 3vw, 1.5rem);
  --heading-h4: clamp(1.125rem, 2.5vw, 1.25rem);
  --heading-h5: 1rem;
  --heading-h6: 0.875rem;
  --heading-line-height: 1.2;
  --heading-letter-spacing: -0.02em;

  /* Spacing Tokens */
  --space-section: clamp(3rem, 8vw, 5rem);
  --space-section-sm: clamp(2rem, 5vw, 3rem);
  --space-section-lg: clamp(4rem, 10vw, 6rem);
  --space-card: 1.5rem;
  --space-card-sm: 1rem;
  --space-card-lg: 2rem;
  --space-form: 1.25rem;
  --space-form-group: 1rem;
  --space-stack: 1rem;
  --space-stack-sm: 0.5rem;
  --space-stack-lg: 1.5rem;
  --space-inline: 0.75rem;
  --space-inline-sm: 0.5rem;
  --space-inline-lg: 1rem;

  /* Container Widths */
  --container-xs: 20rem;
  --container-sm: 24rem;
  --container-md: 28rem;
  --container-lg: 32rem;
  --container-xl: 36rem;
  --container-2xl: 42rem;
  --container-3xl: 48rem;
  --container-4xl: 56rem;
  --container-5xl: 64rem;
  --container-6xl: 72rem;
  --container-7xl: 80rem;
  --container-full: 100%;

  /* Touch Target Minimum (WCAG) */
  --touch-target-min: 44px;
}

/* =============================================================================
   BUTTON CONSISTENCY CLASSES
   ============================================================================= */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-inline-sm);
  min-height: var(--btn-min-height);
  padding: var(--btn-padding-y) var(--btn-padding-x);
  font-size: var(--btn-font-size);
  font-weight: 600;
  line-height: 1.25;
  border-radius: var(--btn-border-radius);
  cursor: pointer;
  border: 2px solid transparent;
  text-decoration: none;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 2px solid var(--glp-ring, hsl(145 25% 65%));
  outline-offset: 2px;
}

.btn-sm {
  min-height: var(--btn-min-height-sm);
  padding: var(--btn-padding-y-sm) var(--btn-padding-x-sm);
  font-size: var(--btn-font-size-sm);
}

.btn-lg {
  min-height: var(--btn-min-height-lg);
  padding: var(--btn-padding-y-lg) var(--btn-padding-x-lg);
  font-size: var(--btn-font-size-lg);
}

.btn-primary {
  background: linear-gradient(135deg, var(--glp-sage, #8fbf9f), var(--glp-sage-deep, #2f5d5d));
  color: white;
  box-shadow: 0 4px 14px rgba(47, 93, 93, 0.25);
}

.btn-primary:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(47, 93, 93, 0.35);
}

.btn-secondary {
  background: transparent;
  color: var(--glp-sage-deep, #2f5d5d);
  border-color: var(--glp-sage-deep, #2f5d5d);
}

.btn-secondary:hover {
  background: rgba(143, 191, 159, 0.1);
}

.btn-ghost {
  background: transparent;
  color: var(--glp-sage-deep, #2f5d5d);
  border: none;
  min-height: var(--btn-min-height-sm);
}

.btn-ghost:hover {
  background: rgba(143, 191, 159, 0.1);
}

.btn-icon {
  min-width: var(--btn-min-height);
  padding: var(--btn-padding-y);
}

.btn-icon-sm {
  min-width: var(--btn-min-height-sm);
  min-height: var(--btn-min-height-sm);
  padding: var(--btn-padding-y-sm);
}

/* =============================================================================
   HEADING CONSISTENCY CLASSES
   ============================================================================= */

.h1, .heading-1 {
  font-size: var(--heading-h1);
  line-height: var(--heading-line-height);
  letter-spacing: var(--heading-letter-spacing);
  font-weight: 600;
  font-family: var(--font-display, 'Cormorant Garamond', Georgia, serif);
}

.h2, .heading-2 {
  font-size: var(--heading-h2);
  line-height: var(--heading-line-height);
  letter-spacing: var(--heading-letter-spacing);
  font-weight: 600;
  font-family: var(--font-display, 'Cormorant Garamond', Georgia, serif);
}

.h3, .heading-3 {
  font-size: var(--heading-h3);
  line-height: var(--heading-line-height);
  letter-spacing: var(--heading-letter-spacing);
  font-weight: 600;
  font-family: var(--font-display, 'Cormorant Garamond', Georgia, serif);
}

.h4, .heading-4 {
  font-size: var(--heading-h4);
  line-height: 1.3;
  font-weight: 600;
  font-family: var(--font-body, 'Inter', sans-serif);
}

.h5, .heading-5 {
  font-size: var(--heading-h5);
  line-height: 1.4;
  font-weight: 600;
  font-family: var(--font-body, 'Inter', sans-serif);
}

.h6, .heading-6 {
  font-size: var(--heading-h6);
  line-height: 1.4;
  font-weight: 600;
  font-family: var(--font-body, 'Inter', sans-serif);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* =============================================================================
   SECTION SPACING CLASSES
   ============================================================================= */

.section-spacing {
  padding-top: var(--space-section);
  padding-bottom: var(--space-section);
}

.section-spacing-sm {
  padding-top: var(--space-section-sm);
  padding-bottom: var(--space-section-sm);
}

.section-spacing-lg {
  padding-top: var(--space-section-lg);
  padding-bottom: var(--space-section-lg);
}

/* =============================================================================
   CARD SPACING CLASSES
   ============================================================================= */

.card-spacing {
  padding: var(--space-card);
}

.card-spacing-sm {
  padding: var(--space-card-sm);
}

.card-spacing-lg {
  padding: var(--space-card-lg);
}

/* =============================================================================
   FORM SPACING CLASSES
   ============================================================================= */

.form-spacing {
  display: flex;
  flex-direction: column;
  gap: var(--space-form);
}

.form-group {
  display: flex;
  flex-direction: column;
  gap: var(--space-form-group);
}

.form-row {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-form);
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-inline);
  margin-top: var(--space-form);
}

/* =============================================================================
   STACK SPACING (VERTICAL)
   ============================================================================= */

.stack {
  display: flex;
  flex-direction: column;
  gap: var(--space-stack);
}

.stack-sm {
  gap: var(--space-stack-sm);
}

.stack-lg {
  gap: var(--space-stack-lg);
}

/* =============================================================================
   INLINE SPACING (HORIZONTAL)
   ============================================================================= */

.inline {
  display: flex;
  align-items: center;
  gap: var(--space-inline);
}

.inline-sm {
  gap: var(--space-inline-sm);
}

.inline-lg {
  gap: var(--space-inline-lg);
}

/* =============================================================================
   MOBILE-SAFE OVERFLOW PREVENTION
   ============================================================================= */

.overflow-safe {
  max-width: 100%;
  overflow-x: hidden;
}

.text-wrap-safe {
  word-wrap: break-word;
  overflow-wrap: break-word;
  hyphens: auto;
}

/* =============================================================================
   KEYBOARD NAVIGATION ENHANCEMENTS
   ============================================================================= */

.keyboard-nav *:focus-visible {
  outline: 2px solid var(--glp-ring, hsl(145 25% 65%));
  outline-offset: 2px;
}

.keyboard-nav button:focus-visible,
.keyboard-nav a:focus-visible,
.keyboard-nav input:focus-visible,
.keyboard-nav select:focus-visible,
.keyboard-nav textarea:focus-visible {
  outline: 2px solid var(--glp-ring, hsl(145 25% 65%));
  outline-offset: 2px;
  border-radius: 4px;
}

/* Touch target minimum for interactive elements */
.touch-target {
  min-width: var(--touch-target-min);
  min-height: var(--touch-target-min);
}

/* =============================================================================
   REDUCED MOTION SUPPORT
   ============================================================================= */

@media (prefers-reduced-motion: reduce) {
  .btn,
  .btn-primary,
  .card-hover,
  .hover-lift {
    transition: none;
  }

  .btn:hover,
  .btn-primary:hover {
    transform: none;
  }
}

/* =============================================================================
   TYPOGRAPHY UTILITIES
   ============================================================================= */

/* Display text - for hero headlines */
.text-display-xl {
  font-family: "Playfair Display", ui-serif, Georgia, serif;
  font-size: clamp(2.5rem, 5vw, 4rem);
  line-height: 1.1;
  letter-spacing: -0.02em;
  font-weight: 600;
}

.text-display-lg {
  font-family: "Playfair Display", ui-serif, Georgia, serif;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1.15;
  letter-spacing: -0.015em;
  font-weight: 600;
}

.text-display-md {
  font-family: "Playfair Display", ui-serif, Georgia, serif;
  font-size: clamp(1.75rem, 3vw, 2.25rem);
  line-height: 1.2;
  font-weight: 600;
}

/* Heading text */
.text-heading-xl {
  font-family: "Inter", ui-sans-serif, system-ui, sans-serif;
  font-size: 1.75rem;
  line-height: 1.25;
  font-weight: 600;
}

.text-heading-lg {
  font-family: "Inter", ui-sans-serif, system-ui, sans-serif;
  font-size: 1.5rem;
  line-height: 1.3;
  font-weight: 600;
}

.text-heading-md {
  font-family: "Inter", ui-sans-serif, system-ui, sans-serif;
  font-size: 1.25rem;
  line-height: 1.35;
  font-weight: 600;
}

.text-heading-sm {
  font-family: "Inter", ui-sans-serif, system-ui, sans-serif;
  font-size: 1.125rem;
  line-height: 1.4;
  font-weight: 600;
}

/* Body text */
.text-body-lg {
  font-size: 1.125rem;
  line-height: 1.65;
}

.text-body-md {
  font-size: 1rem;
  line-height: 1.6;
}

.text-body-sm {
  font-size: 0.875rem;
  line-height: 1.5;
}

/* Lead paragraph */
.text-lead {
  font-size: 1.125rem;
  line-height: 1.65;
  color: var(--glp-text-muted);
  max-width: 42rem;
}

/* Caption text */
.text-caption {
  font-size: 0.8125rem;
  line-height: 1.45;
  color: var(--glp-text-muted);
}

/* Quote text */
.text-quote {
  font-family: "Playfair Display", ui-serif, Georgia, serif;
  font-size: 1.25rem;
  line-height: 1.6;
  font-style: italic;
}

/* =============================================================================
   COLOR UTILITIES
   ============================================================================= */

.text-teal {
  color: var(--glp-primary);
}

.text-sage {
  color: var(--glp-sage);
}

.text-gold {
  color: var(--glp-gold);
}

.text-blush {
  color: var(--glp-blush);
}

.text-ink {
  color: var(--glp-ink);
}

.text-paper {
  color: var(--glp-paper);
}

.bg-teal {
  background-color: var(--glp-primary);
}

.bg-sage {
  background-color: var(--glp-sage);
}

.bg-gold {
  background-color: var(--glp-gold);
}

.bg-paper {
  background-color: var(--glp-paper);
}

.bg-ink {
  background-color: var(--glp-ink);
}

/* =============================================================================
   ICON UTILITIES
   ============================================================================= */

.icon-xs {
  width: 1rem;
  height: 1rem;
}

.icon-sm {
  width: 1.25rem;
  height: 1.25rem;
}

.icon-md {
  width: 1.5rem;
  height: 1.5rem;
}

.icon-lg {
  width: 2rem;
  height: 2rem;
}

.icon-xl {
  width: 2.5rem;
  height: 2.5rem;
}

/* Icon with circular background */
.icon-circle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  background: var(--glp-surface-2);
  padding: 0.5rem;
}

.icon-circle-sm {
  padding: 0.375rem;
}

.icon-circle-lg {
  padding: 0.75rem;
}

/* =============================================================================
   CARD UTILITIES
   ============================================================================= */

.card {
  background: var(--glp-surface);
  border-radius: var(--glp-radius-2);
  padding: 1.5rem;
}

.card-sm {
  padding: 1rem;
}

.card-lg {
  padding: 2rem;
}

.card-shadow {
  box-shadow: var(--glp-shadow-1);
}

.card-border {
  border: 1px solid var(--glp-border);
}

.card-hover {
  transition: all var(--glp-motion-fast) var(--glp-ease);
}

.card-hover:hover {
  transform: translateY(-2px);
  box-shadow: var(--glp-shadow-2);
}

/* Stat cards */
.stat-card {
  padding: 1.5rem;
  border-radius: var(--glp-radius-2);
}

.stat-value {
  font-size: 2.5rem;
  font-weight: 700;
  line-height: 1;
}

.stat-label {
  font-size: 0.875rem;
  font-weight: 500;
  opacity: 0.8;
}

/* =============================================================================
   LAYOUT UTILITIES
   ============================================================================= */

.section {
  padding-top: 3rem;
  padding-bottom: 3rem;
}

.section-lg {
  padding-top: 4rem;
  padding-bottom: 4rem;
}

.section-xl {
  padding-top: 5rem;
  padding-bottom: 5rem;
}

/* Stack spacing */
.stack-sm > * + * {
  margin-top: 0.5rem;
}

.stack-md > * + * {
  margin-top: 1rem;
}

.stack-lg > * + * {
  margin-top: 1.5rem;
}

.stack-xl > * + * {
  margin-top: 2rem;
}

/* Inline spacing */
.inline-sm {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.inline-md {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.inline-lg {
  display: flex;
  align-items: center;
  gap: 1.5rem;
}

/* =============================================================================
   DIVIDERS
   ============================================================================= */

.divider {
  height: 1px;
  background: var(--glp-border);
  margin: 1.5rem 0;
}

.divider-sm {
  margin: 1rem 0;
}

.divider-lg {
  margin: 2rem 0;
}

/* =============================================================================
   FOCUS STATES
   ============================================================================= */

.focus-ring:focus-visible {
  outline: 2px solid var(--glp-ring);
  outline-offset: 2px;
}

.focus-ring-inset:focus-visible {
  outline: 2px solid var(--glp-ring);
  outline-offset: -2px;
}

/* =============================================================================
   RESPONSIVE VISIBILITY
   ============================================================================= */

@media (max-width: 639px) {
  .hide-mobile {
    display: none !important;
  }
}

@media (min-width: 640px) {
  .show-mobile-only {
    display: none !important;
  }
}

/* =============================================================================
   ACCESSIBILITY
   ============================================================================= */

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Skip link */
.skip-link {
  position: absolute;
  top: -100%;
  left: 50%;
  transform: translateX(-50%);
  padding: 0.75rem 1.5rem;
  background: var(--glp-primary);
  color: var(--glp-primary-foreground);
  border-radius: var(--glp-radius-1);
  font-weight: 600;
  z-index: 9999;
  transition: top 0.2s;
}

.skip-link:focus {
  top: 1rem;
}

/* =============================================================================
   GLASS EFFECTS
   ============================================================================= */

.glass {
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}

.glass-premium {
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid rgba(255, 255, 255, 0.3);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.06);
}

/* =============================================================================
   GRADIENT TEXT
   ============================================================================= */

.text-gradient-sage {
  background: linear-gradient(135deg, var(--glp-sage), var(--glp-primary));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.text-gradient-gold {
  background: linear-gradient(135deg, var(--glp-gold), #D4A520);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* =============================================================================
   HOVER EFFECTS
   ============================================================================= */

.hover-lift {
  transition: transform var(--glp-motion-fast) var(--glp-ease);
}

.hover-lift:hover {
  transform: translateY(-2px);
}

.hover-glow-gold {
  transition: box-shadow var(--glp-motion-fast) var(--glp-ease);
}

.hover-glow-gold:hover {
  box-shadow: 0 0 20px rgba(var(--glp-gold-rgb), 0.3);
}

.hover-glow-sage {
  transition: box-shadow var(--glp-motion-fast) var(--glp-ease);
}

.hover-glow-sage:hover {
  box-shadow: 0 0 20px rgba(var(--glp-sage-deep-rgb), 0.25);
}

/* ==========================================================================
   /v6 Lumi preview "control panel" polish (additive) — workspace ambient
   wash, page-entrance fade, cell hover lift, and section header accent.
   Internal design tool, scoped under `.v6-preview-polish`. Honors
   `prefers-reduced-motion: reduce`. Existing demo functionality (V8
   click zones, V9 entrance/escalation/etc, all preview cells) is
   completely untouched — this file only adds workspace-feel layers.
   ========================================================================== */

.v6-preview-polish {
  position: relative;
  isolation: isolate;
}

/* 1. Workspace ambient wash — sits above the existing amber→white→rose
   Tailwind gradient and adds a subtle radial focus over the upper-third
   so the page reads as a "control panel" rather than a flat layout.
   Pointer-events disabled. Z-index 0 keeps it behind content. */
.v6-preview-polish .v6-preview-wash {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(ellipse at 50% 12%, rgba(168, 201, 160, 0.10) 0%, transparent 55%),
    radial-gradient(ellipse at 50% 90%, rgba(200, 182, 255, 0.08) 0%, transparent 55%);
}

/* 2. Page entrance — the top nav + header + content fade + translate-up
   on mount. Single 500ms beat, no replay, so it stays out of the way
   while iterating on demos. */
.v6-preview-polish .v6-preview-content {
  animation: v6-preview-entrance 500ms ease-out both;
}
@keyframes v6-preview-entrance {
  0%   { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0);   }
}

/* 3. Cell hover lift — every preview cell uses `.rounded-2xl border
   border-amber-100 bg-white` markup, so we target that pattern via a
   shared class added to the Cell component (and any other previewers
   that match). 200ms lift + soft amber shadow on hover, restores on
   leave. Skipped under reduced motion. */
.v6-preview-polish .v6-preview-cell-hoverable {
  transition: transform 200ms ease, box-shadow 300ms ease;
}
/* Scope `will-change` to hover-capable devices and only during the
   interaction itself, so the dense /v6 grid (30+ cells) doesn't pay
   compositor/GPU memory overhead at rest. */
@media (hover: hover) {
  .v6-preview-polish .v6-preview-cell-hoverable:hover {
    will-change: transform;
    transform: translateY(-3px);
    box-shadow: 0 8px 24px rgba(255, 217, 61, 0.18), 0 2px 6px rgba(0, 0, 0, 0.04);
  }
}

/* 4. Section header accent — adds a soft amber underline glow to any
   `.v6-preview-section-header` element so the visual hierarchy of the
   long stacked preview reads more clearly. */
.v6-preview-polish .v6-preview-section-header {
  position: relative;
  padding-bottom: 4px;
}
.v6-preview-polish .v6-preview-section-header::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -2px;
  width: 56px;
  height: 3px;
  border-radius: 9999px;
  background: linear-gradient(90deg, #FFD93D 0%, #FFB88C 100%);
  opacity: 0.65;
}

/* 5. Reduced-motion contract — kill every additive animation, restore
   resting states. Wash is opacity-only (no transition), so it stays. */
@media (prefers-reduced-motion: reduce) {
  .v6-preview-polish .v6-preview-content,
  .v6-preview-polish .v6-preview-cell-hoverable {
    animation: none !important;
    transition: none !important;
    transform: none !important;
  }
  .v6-preview-polish .v6-preview-cell-hoverable:hover {
    transform: none !important;
    box-shadow: none !important;
  }
}

/**
 * Visual Benefits Polish — v5.8.0 (V17)
 *
 * Scoped under .visual-benefits-polish so it cannot leak into other surfaces.
 * Brand palette only. Reduced-motion blanket pins everything to end state.
 */

.visual-benefits-polish {
  padding-top: clamp(56px, 8vw, 96px);
  padding-bottom: clamp(56px, 8vw, 96px);
  background: linear-gradient(
    180deg,
    var(--glp-paper, #fdfcf9) 0%,
    rgba(168, 201, 160, 0.04) 50%,
    var(--glp-paper, #fdfcf9) 100%
  );
}

.visual-benefits-polish .vb-header {
  opacity: 0;
  transform: translateY(20px);
  transition: opacity 600ms ease, transform 600ms ease;
}

.visual-benefits-polish .vb-header.revealed {
  opacity: 1;
  transform: translateY(0);
}

.visual-benefits-polish .vb-row {
  display: grid;
  grid-template-columns: 1fr;
  gap: clamp(24px, 4vw, 56px);
  align-items: center;
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 700ms cubic-bezier(0.22, 1, 0.36, 1), transform 700ms cubic-bezier(0.22, 1, 0.36, 1);
}

@media (min-width: 900px) {
  .visual-benefits-polish .vb-row {
    grid-template-columns: 1.05fr 1fr;
  }
  .visual-benefits-polish .vb-row-reversed .vb-image-wrap {
    order: 2;
  }
  .visual-benefits-polish .vb-row-reversed .vb-text-wrap {
    order: 1;
  }
}

.visual-benefits-polish .vb-row.revealed {
  opacity: 1;
  transform: translateY(0);
}

/* ── Image side ───────────────────────────────────────────────────────── */
.visual-benefits-polish .vb-image-wrap {
  position: relative;
  isolation: isolate;
}

.visual-benefits-polish .vb-image-frame {
  position: relative;
  border-radius: 28px;
  overflow: hidden;
  background: var(--vb-tint);
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow:
    0 24px 60px -24px rgba(74, 126, 114, 0.35),
    0 0 0 1px rgba(168, 201, 160, 0.10);
  transition: box-shadow 360ms ease, transform 360ms ease;
  aspect-ratio: 16 / 9;
}

.visual-benefits-polish .vb-image-frame::after {
  /* soft accent halo bloom inside the frame */
  content: '';
  position: absolute;
  inset: -10%;
  background: radial-gradient(circle at 30% 30%, var(--vb-halo), transparent 60%);
  pointer-events: none;
  z-index: 1;
  mix-blend-mode: soft-light;
  opacity: 0.9;
}

.visual-benefits-polish .vb-image {
  position: relative;
  z-index: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 700ms cubic-bezier(0.22, 1, 0.36, 1);
}

.visual-benefits-polish .vb-image-wrap:hover .vb-image-frame {
  box-shadow:
    0 30px 70px -22px var(--vb-halo),
    0 0 0 1.5px var(--vb-accent);
  transform: translateY(-3px);
}

.visual-benefits-polish .vb-image-wrap:hover .vb-image {
  transform: scale(1.025);
}

/* Floating avatar overlay (1:1) */
.visual-benefits-polish .vb-avatar-overlay {
  position: absolute;
  bottom: -22px;
  right: -14px;
  width: clamp(78px, 14vw, 132px);
  height: clamp(78px, 14vw, 132px);
  border-radius: 50%;
  background: radial-gradient(circle, var(--vb-halo) 0%, transparent 70%);
  display: grid;
  place-items: center;
  z-index: 3;
  animation: vb-float 6s ease-in-out infinite;
}

.visual-benefits-polish .vb-row-reversed .vb-avatar-overlay {
  right: auto;
  left: -14px;
}

.visual-benefits-polish .vb-avatar-img {
  width: 84%;
  height: 84%;
  object-fit: contain;
  filter: drop-shadow(0 8px 20px rgba(74, 126, 114, 0.30));
}

@keyframes vb-float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

/* ── Text side ────────────────────────────────────────────────────────── */
.visual-benefits-polish .vb-text-wrap {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 18px;
}

.visual-benefits-polish .vb-icon-badge {
  display: inline-grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border-radius: 16px;
  background: var(--vb-tint);
  color: var(--vb-accent);
  border: 1px solid color-mix(in srgb, var(--vb-accent) 30%, transparent);
  box-shadow: 0 4px 14px -6px var(--vb-halo);
}

.visual-benefits-polish .vb-title {
  color: var(--glp-sage-deep, #4A7E72);
  line-height: 1.15;
  letter-spacing: -0.01em;
  margin: 0;
}

.visual-benefits-polish .vb-description {
  color: var(--glp-ink, #2d3a35);
  line-height: 1.7;
  margin: 0;
  max-width: 56ch;
}

/* Sensory-word pill tags (V17 spec) */
.visual-benefits-polish .vb-sensory-tags {
  list-style: none;
  padding: 0;
  margin: 4px 0 4px;
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.visual-benefits-polish .vb-sensory-tag {
  font-size: 0.75rem;
  letter-spacing: 0.02em;
  padding: 4px 10px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--vb-accent) 10%, transparent);
  color: color-mix(in srgb, var(--vb-accent) 70%, #2d3a35);
  border: 1px solid color-mix(in srgb, var(--vb-accent) 22%, transparent);
}

/* ── CTA link ─────────────────────────────────────────────────────────── */
.visual-benefits-polish .vb-cta {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-top: 6px;
  padding: 12px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.975rem;
  color: #ffffff;
  background: linear-gradient(135deg, #4A7E72 0%, var(--vb-accent) 100%);
  border: 1px solid color-mix(in srgb, var(--vb-accent) 40%, transparent);
  text-decoration: none;
  transition: transform 220ms cubic-bezier(0.22, 1, 0.36, 1),
              box-shadow 220ms ease,
              background-position 360ms ease;
  background-size: 180% 180%;
  background-position: 0% 50%;
  box-shadow: 0 6px 18px -8px rgba(74, 126, 114, 0.55);
}

.visual-benefits-polish .vb-cta:hover {
  transform: translateY(-2px);
  background-position: 100% 50%;
  box-shadow:
    0 12px 30px -10px var(--vb-halo),
    0 0 0 1px color-mix(in srgb, var(--vb-accent) 50%, transparent);
}

.visual-benefits-polish .vb-cta:active {
  transform: translateY(1px);
  box-shadow: 0 4px 10px -6px rgba(74, 126, 114, 0.45);
  transition-duration: 90ms;
}

.visual-benefits-polish .vb-cta:focus-visible {
  outline: 3px solid var(--vb-accent);
  outline-offset: 3px;
}

.visual-benefits-polish .vb-cta-arrow {
  transition: transform 260ms cubic-bezier(0.22, 1, 0.36, 1);
}

.visual-benefits-polish .vb-cta:hover .vb-cta-arrow {
  transform: translateX(4px);
}

/* ── btn-sacred-gold (global utility introduced with V17) ─────────────── */
.btn-sacred-gold {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 26px;
  border-radius: 999px;
  font-weight: 600;
  color: #ffffff;
  background: linear-gradient(135deg, #4A7E72 0%, #F4B942 100%);
  background-size: 180% 180%;
  background-position: 0% 50%;
  border: 1px solid rgba(244, 185, 66, 0.45);
  text-decoration: none;
  cursor: pointer;
  box-shadow: 0 8px 22px -10px rgba(74, 126, 114, 0.55);
  transition: transform 220ms cubic-bezier(0.22, 1, 0.36, 1),
              box-shadow 220ms ease,
              background-position 360ms ease;
}

.btn-sacred-gold:hover {
  transform: translateY(-1px);
  background-position: 100% 50%;
  box-shadow:
    0 14px 34px -10px rgba(244, 185, 66, 0.55),
    0 0 0 1px rgba(244, 185, 66, 0.55);
}

.btn-sacred-gold:active {
  transform: translateY(1px);
  box-shadow: 0 4px 10px -6px rgba(74, 126, 114, 0.45);
  transition-duration: 90ms;
}

.btn-sacred-gold:focus-visible {
  outline: 3px solid #F4B942;
  outline-offset: 3px;
}

/* ── Universal button micro-interaction (additive, palette-safe) ─────── */
button:not([disabled]):not(.no-mi),
.btn-mi {
  transition: transform 220ms cubic-bezier(0.22, 1, 0.36, 1),
              box-shadow 220ms ease;
}

button:not([disabled]):not(.no-mi):hover,
.btn-mi:hover {
  transform: translateY(-1px);
  box-shadow: 0 8px 22px -10px rgba(74, 126, 114, 0.35);
}

button:not([disabled]):not(.no-mi):active,
.btn-mi:active {
  transform: translateY(1px);
  box-shadow: 0 3px 8px -5px rgba(74, 126, 114, 0.30);
  transition-duration: 90ms;
}

/* ── Reduced motion blanket (everything pinned to end state) ──────────── */
@media (prefers-reduced-motion: reduce) {
  .visual-benefits-polish .vb-header,
  .visual-benefits-polish .vb-header.revealed,
  .visual-benefits-polish .vb-row,
  .visual-benefits-polish .vb-row.revealed {
    opacity: 1 !important;
    transform: none !important;
    transition: none !important;
  }
  .visual-benefits-polish .vb-image,
  .visual-benefits-polish .vb-image-frame,
  .visual-benefits-polish .vb-cta,
  .visual-benefits-polish .vb-cta-arrow,
  .visual-benefits-polish .vb-avatar-overlay {
    animation: none !important;
    transition: none !important;
    transform: none !important;
  }
  .visual-benefits-polish .vb-image-wrap:hover .vb-image,
  .visual-benefits-polish .vb-image-wrap:hover .vb-image-frame,
  .visual-benefits-polish .vb-cta:hover,
  .visual-benefits-polish .vb-cta:hover .vb-cta-arrow {
    transform: none !important;
  }

  .btn-sacred-gold,
  button:not([disabled]):not(.no-mi),
  .btn-mi {
    transition: none !important;
  }
  .btn-sacred-gold:hover,
  .btn-sacred-gold:active,
  button:not([disabled]):not(.no-mi):hover,
  button:not([disabled]):not(.no-mi):active,
  .btn-mi:hover,
  .btn-mi:active {
    transform: none !important;
  }
}

/* ────────────────────────────────────────────────────────────────────────
   wellness-shell.css — Sanctuary Depth for Inner Wellness Surfaces
   Applies to JournalPage, MoodPage, AIChatPage, StatePage and any other
   surface wrapped in <WellnessPageShell>.  All effects are SCOPED to
   `.wellness-shell` so they never leak to other pages.

   Honors prefers-reduced-motion.
   ──────────────────────────────────────────────────────────────────────── */

/* ── Root container — soft sanctuary backdrop ──────────────────────────── */
.wellness-shell {
  position: relative;
}

.wellness-shell::before {
  content: '';
  position: fixed;
  inset: 0;
  z-index: -1;
  background:
    radial-gradient(ellipse 60% 40% at 50% 0%,
      rgba(190, 134, 34, 0.04) 0%,
      transparent 60%),
    radial-gradient(ellipse 80% 60% at 50% 100%,
      rgba(30, 200, 144, 0.045) 0%,
      transparent 70%);
  pointer-events: none;
}

/* ── Quick-nav pills — refined hover with sage tint ─────────────────────── */
.wellness-shell [data-testid='wellness-quicknav'] a {
  background:
    linear-gradient(180deg,
      rgba(255, 255, 255, 0.95) 0%,
      rgba(252, 246, 234, 0.40) 100%);
  transition: all 0.3s cubic-bezier(0.23, 1, 0.32, 1);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 1px 2px rgba(6, 42, 42, 0.04);
}

.wellness-shell [data-testid='wellness-quicknav'] a:hover {
  transform: translateY(-1px);
  background:
    linear-gradient(180deg,
      rgba(255, 255, 255, 1) 0%,
      rgba(252, 246, 234, 0.65) 100%);
  border-color: rgba(30, 200, 144, 0.40);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 4px 10px rgba(6, 42, 42, 0.06),
    0 0 0 1px rgba(190, 134, 34, 0.12);
}

/* ── Main content section — sanctuary card ─────────────────────────────── */
.wellness-shell > section {
  position: relative;
  overflow: hidden;
  background:
    linear-gradient(180deg,
      rgba(255, 255, 255, 1) 0%,
      rgba(252, 246, 234, 0.30) 100%) !important;
  border-color: rgba(30, 200, 144, 0.20) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 2px 8px rgba(6, 42, 42, 0.04),
    0 14px 32px rgba(6, 42, 42, 0.05);
  transition: box-shadow 0.4s ease, border-color 0.4s ease;
}

/* Animated top accent bar */
.wellness-shell > section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg,
    transparent 0%,
    rgba(190, 134, 34, 0.5) 25%,
    rgba(30, 200, 144, 0.6) 50%,
    rgba(190, 134, 34, 0.5) 75%,
    transparent 100%);
  opacity: 0.55;
  transition: opacity 0.5s ease;
}

.wellness-shell > section:hover {
  border-color: rgba(30, 200, 144, 0.30) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 4px 14px rgba(6, 42, 42, 0.06),
    0 22px 48px rgba(6, 42, 42, 0.08);
}

.wellness-shell > section:hover::before {
  opacity: 0.95;
}

/* ── Info accordion (Learn more about this tool) — match sanctuary ────── */
.wellness-shell > div[class*='border-border'][class*='bg-card'] {
  background:
    linear-gradient(180deg,
      rgba(255, 255, 255, 0.97) 0%,
      rgba(252, 246, 234, 0.25) 100%) !important;
  border-color: rgba(30, 200, 144, 0.18) !important;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    0 1px 3px rgba(6, 42, 42, 0.03);
}

/* ── Title heading — soft serif emphasis ───────────────────────────────── */
.wellness-shell > header h1 {
  background: linear-gradient(135deg,
    var(--glp-sage-deep, #062a2a) 0%,
    #0d4a3d 50%,
    var(--glp-sage-deep, #062a2a) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  letter-spacing: -0.01em;
}

/* ── Reduced-motion compliance ─────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  .wellness-shell [data-testid='wellness-quicknav'] a,
  .wellness-shell [data-testid='wellness-quicknav'] a:hover,
  .wellness-shell > section,
  .wellness-shell > section::before,
  .wellness-shell > section:hover {
    transition: none;
    transform: none;
  }
}

